def _require_env(key: str) -> str:
    val = os.environ.get(key)
    if not val:
        raise SystemExit(
            f"[FATAL] متغیر محیطی «{key}» تنظیم نشده. "
            f"فایل .env را کنار bot.py بگذار یا env سرور را چک کن."
        )
    return val

