# همهٔ سرویس‌هایی که کلید دارند (چت + ویس + هر سرویس آیندهٔ EXTRA_API_SERVICES)
API_SERVICES = {**AI_PROVIDERS, **EXTRA_API_SERVICES}

# envهایی که ممکن است کلید داخلشان باشد (به‌خاطر اشتباه رایج، مثلاً کلید در فیلد مدل)
_AI_KEY_ENV_NAMES = {
    "groq": ["GROQ_API_KEYS", "GROQ_API_KEY", "GROQ_MODEL", "GROQ_MODEL_FALLBACKS"],
    "gemini": ["GEMINI_API_KEYS", "GEMINI_API_KEY", "GEMINI_MODEL", "GEMINI_MODEL_FALLBACKS"],
    "openrouter": ["OPENROUTER_API_KEYS", "OPENROUTER_API_KEY", "OPENROUTER_MODEL", "OPENROUTER_MODEL_FALLBACKS"],
    "elevenlabs": ["ELEVENLABS_API_KEYS", "ELEVENLABS_API_KEY"],
}


def _clean_groq_key(raw: str) -> str:
    """فاصله، کوتیشن و = اضافی اول کلید را پاک می‌کند (اشتباه رایج در .env)."""
    k = (raw or "").strip().strip('"').strip("'").strip()
    while k.startswith("="):
        k = k[1:].strip()
    return k


def _split_env_list(raw: str) -> list:
    """جداسازی با ویرگول / نقطه‌ویرگول / فاصله / خط‌جدید."""
    if not raw:
        return []
    return [p for p in re.split(r"[,;\s]+", raw) if p.strip()]


def _mask_key(k: str) -> str:
    n = 8
    for p in API_SERVICES.values():
        if k.startswith(p["prefix"]):
            n = len(p["prefix"]) + 8
            break
    return (k[:n] + "…" + k[-4:]) if len(k) > n + 6 else (k[:8] + "…")


def _env_get(name: str) -> str:
    """مقدار تازه: اول فایل .env (تا بدون ری‌استارت هم تغییر دیده شود)، بعد os.environ."""
    try:
        vals = dotenv_values(_ENV_FILE_PATH)
        if name in vals and vals[name] is not None:
            return vals[name] or ""
    except Exception:
        pass
    return os.environ.get(name, "") or ""


def _ai_prefixes(provider: str) -> tuple:
    p = API_SERVICES[provider]
    return tuple(p.get("prefixes") or (p["prefix"],))


def _ai_prefix_label(provider: str) -> str:
    p = API_SERVICES[provider]
    return p.get("key_hint") or " یا ".join(_ai_prefixes(provider))


def _ai_key_ok(provider: str, k: str) -> bool:
    """قالب کلید معتبر است؟ (سرویس‌هایی با key_re مثل الون‌لبز با regex، بقیه با پیشوند)"""
    rx = API_SERVICES[provider].get("key_re")
    if rx:
        return re.fullmatch(rx, k or "") is not None
    return (k or "").startswith(_ai_prefixes(provider))


def _err_brief(text: str, n: int = 110) -> str:
    """متن کوتاه و خوانا از بدنهٔ خطا (JSON گوگل/گروک) برای نمایش در پنل."""
    try:
        d = _json_loads(text)
        e = d.get("error") if isinstance(d, dict) else None
        if isinstance(e, dict):
            msg = e.get("message") or e.get("status") or ""
            if msg:
                return str(msg).replace("\n", " ")[:n]
    except Exception:
        pass
    return (text or "").replace("\n", " ").replace("<", "")[:n]


def _extract_ai_keys(provider: str, with_report: bool = False):
    """همهٔ کلیدهای یک سرویس. با with_report=True دلیل ردشدن‌ها هم برمی‌گردد."""
    out, seen, skipped = [], set(), []
    for name in _AI_KEY_ENV_NAMES[provider]:
        is_key_field = name.endswith("KEYS") or name.endswith("KEY")
        for part in _split_env_list(_env_get(name)):
            k = _clean_groq_key(part)
            if not k:
                continue
            if not _ai_key_ok(provider, k):
                if is_key_field:
                    skipped.append((_mask_key(k), f"شروع با {_ai_prefix_label(provider)} نیست"))
                continue
            if k in seen:
                skipped.append((_mask_key(k), "تکراری"))
                continue
            seen.add(k)
            out.append(k)
    return (out, skipped) if with_report else out


def _parse_groq_keys_env() -> list:
    return _extract_ai_keys("groq")


def _parse_model_list(primary_name: str, fallbacks_name: str, default_csv: str, bad_prefixes: tuple) -> list:
    models, seen = [], set()
    raw = _env_get(fallbacks_name) or default_csv
    for part in _split_env_list(raw):
        m = part.strip().strip('"').strip("'")
        if not m or m.startswith(bad_prefixes) or m in seen:
            continue
        seen.add(m)
        models.append(m)
    primary = _env_get(primary_name).strip().strip('"').strip("'")
    if primary and not primary.startswith(bad_prefixes):
        if primary in models:
            models.remove(primary)
        models.insert(0, primary)
    if not models:
        models = [default_csv.split(",")[0]]
    return models


def _parse_groq_models_env() -> list:
    """فقط نام مدل‌های واقعی — هر کلیدی که اشتباه در فیلد مدل باشد حذف می‌شود."""
    return _parse_model_list(
        "GROQ_MODEL", "GROQ_MODEL_FALLBACKS",
        "qwen/qwen3.8-27b,openai/gpt-oss-120b",
        ("gsk_", "sk-or-"),
    )


def _parse_groq_web_models_env() -> list:
    """مدل‌های گروک با جستجوی وب داخلی (compound) — فقط برای مسیر «بازار/اینترنت»."""
    return _parse_model_list(
        "GROQ_WEB_MODEL", "GROQ_WEB_MODEL_FALLBACKS",
        "groq/compound,groq/compound-mini",
        ("gsk_", "sk-or-"),
    )


def _parse_gemini_keys_env() -> list:
    return _extract_ai_keys("gemini")


def _parse_gemini_models_env() -> list:
    """مدل‌های جمینی به ترتیب اولویت. اگر نامی در دسترس نباشد (404/400) خودکار مدل بعدی امتحان می‌شود.
    برای عوض‌کردن: GEMINI_MODEL و/یا GEMINI_MODEL_FALLBACKS را در .env بگذار."""
    return _parse_model_list(
        "GEMINI_MODEL", "GEMINI_MODEL_FALLBACKS",
        "gemini-3.5-flash-lite,gemini-3.1-flash-lite,gemini-3.6-flash,gemini-3.5-flash",
        ("gsk_", "sk-or-", "AIza", "AQ."),
    )


def _parse_openrouter_models_env() -> list:
    """مدل‌های اوپن‌روتر برای چت متنی (به ترتیب اولویت؛ اگر مدلی حذف/شلوغ شد خودکار بعدی)."""
    return _parse_model_list(
        "OPENROUTER_MODEL", "OPENROUTER_MODEL_FALLBACKS",
        "thinkingmachines/inkling:free,nvidia/nemotron-3-super-120b-a12b:free",
        ("gsk_", "AIza", "AQ.", "sk-"),
    )


def _parse_openrouter_vision_models_env() -> list:
    """مدل‌های اوپن‌روتر که ورودی عکس را می‌پذیرند (برای تحلیل عکس). OPENROUTER_VISION_MODELS در .env."""
    raw = (_env_get("OPENROUTER_VISION_MODELS") or "").strip()
    ms = [m.strip().strip('"').strip("'") for m in _split_env_list(raw)]
    ms = [m for m in ms if m and not m.startswith(("gsk_", "AIza", "AQ.", "sk-"))]
    return ms or ["thinkingmachines/inkling:free"]


GROQ_API_KEYS: list = []
GEMINI_API_KEYS: list = []
OPENROUTER_API_KEYS: list = []
OPENROUTER_MODELS: list = []
OPENROUTER_VISION_MODELS: list = []
ELEVENLABS_API_KEYS: list = []
GEMINI_MODELS: list = []
GROQ_MODEL_FALLBACKS: list = []
GROQ_MODEL = "qwen/qwen3.8-27b"
GROQ_WEB_MODELS: list = []

_AI_KEYS_LOCK = threading.RLock()
_ai_env_sig = "unset"
_ai_slot_index = 0
_ai_slot_index_by_provider = {"groq": 0, "gemini": 0, "openrouter": 0, "elevenlabs": 0}


def _ai_env_signature():
    try:
        st_ = os.stat(_ENV_FILE_PATH)
        return (st_.st_mtime_ns, st_.st_size)
    except OSError:
        return None


def reload_ai_keys(force: bool = False) -> bool:
    """کلیدها و مدل‌ها را دوباره از .env می‌خواند (فقط اگر فایل عوض شده باشد یا force).
    برمی‌گرداند: True اگر بارگذاری مجدد انجام شد."""
    global GROQ_API_KEYS, GROQ_MODEL_FALLBACKS, GROQ_MODEL
    global GROQ_WEB_MODELS, _ai_env_sig
    global GEMINI_API_KEYS, GEMINI_MODELS
    global OPENROUTER_API_KEYS, OPENROUTER_MODELS, OPENROUTER_VISION_MODELS
    global ELEVENLABS_API_KEYS
    sig = _ai_env_signature()
    with _AI_KEYS_LOCK:
        if not force and sig == _ai_env_sig:
            return False
        GROQ_API_KEYS = _parse_groq_keys_env()
        GROQ_MODEL_FALLBACKS = _parse_groq_models_env()
        GROQ_MODEL = GROQ_MODEL_FALLBACKS[0] if GROQ_MODEL_FALLBACKS else "qwen/qwen3.8-27b"
        GROQ_WEB_MODELS = _parse_groq_web_models_env()
        GEMINI_API_KEYS = _parse_gemini_keys_env()
        GEMINI_MODELS = _parse_gemini_models_env()
        OPENROUTER_API_KEYS = _extract_ai_keys("openrouter")
        OPENROUTER_MODELS = _parse_openrouter_models_env()
        OPENROUTER_VISION_MODELS = _parse_openrouter_vision_models_env()
        ELEVENLABS_API_KEYS = _extract_ai_keys("elevenlabs")
        _ai_env_sig = sig
        return True


def _env_file_set(name: str, value: str) -> None:
    """مقدار NAME را در فایل .env عوض/اضافه می‌کند (بقیهٔ خطوط دست‌نخورده)."""
    try:
        with open(_ENV_FILE_PATH, encoding="utf-8") as f:
            lines = f.read().splitlines(keepends=True)
    except FileNotFoundError:
        lines = []
    pat = re.compile(r"^\s*(?:export\s+)?" + re.escape(name) + r"\s*=")
    out, replaced, i = [], False, 0
    while i < len(lines):
        ln = lines[i]
        if pat.match(ln):
            rhs = ln.split("=", 1)[1].lstrip()
            if rhs[:1] in ("'", '"'):
                q = rhs[0]
                closed = q in rhs[1:]
                while not closed and i + 1 < len(lines):  # مقدار چندخطی
                    i += 1
                    closed = q in lines[i]
            if not replaced:
                out.append(f"{name}={value}\n")
                replaced = True
            i += 1
            continue
        out.append(ln)
        i += 1
    if not replaced:
        if out and not out[-1].endswith("\n"):
            out[-1] += "\n"
        out.append(f"{name}={value}\n")
    data = "".join(out)
    tmp = _ENV_FILE_PATH + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(data)
        try:
            os.chmod(tmp, stat.S_IMODE(os.stat(_ENV_FILE_PATH).st_mode))
        except OSError:
            pass
        os.replace(tmp, _ENV_FILE_PATH)
    except OSError:
        # مثلاً .env به‌صورت فایل مستقیم در داکر mount شده — مستقیم روی همان فایل بنویس
        try:
            os.remove(tmp)
        except OSError:
            pass
        with open(_ENV_FILE_PATH, "w", encoding="utf-8") as f:
            f.write(data)
    os.environ[name] = value


def add_ai_key(provider: str, key: str) -> bool:
    """کلید را به .env اضافه می‌کند و بلافاصله وارد چرخه می‌شود. False اگر تکراری بود."""
    with _AI_KEYS_LOCK:
        cur = _extract_ai_keys(provider)
        if key in cur:
            return False
        cur.append(key)
        _env_file_set(API_SERVICES[provider]["env"], ",".join(cur))
        reload_ai_keys(force=True)
        return True


def remove_ai_keys(keys) -> int:
    """کلیدها را از همهٔ متغیرهای .env حذف می‌کند و چرخه را تازه می‌کند."""
    keys = set(keys)
    changed = 0
    with _AI_KEYS_LOCK:
        for names in _AI_KEY_ENV_NAMES.values():
            for name in names:
                parts = _split_env_list(_env_get(name))
                keep = [p for p in parts if _clean_groq_key(p) not in keys]
                if len(keep) != len(parts):
                    _env_file_set(name, ",".join(keep))
                    changed += len(parts) - len(keep)
        reload_ai_keys(force=True)
    return changed


class _NormResp:
    """پاسخ بومی جمینی را به شکل پاسخ OpenAI درمی‌آورد تا بقیهٔ کد بدون تغییر کار کند."""

    def __init__(self, status_code, text, payload=None):
        self.status_code, self.text, self._payload = status_code, text, payload

    def json(self):
        return self._payload


# سطح تفکر هر سرویس از پنل ادمین (🧠 سطح تفکر) تنظیم می‌شود و در دیتابیس می‌ماند؛ بدون ری‌استارت اعمال می‌شود.
# default = هیچ پارامتری نفرست و پیش‌فرض خود مدل را بگیر.
_AI_THINK_PROVIDERS = ("gemini", "groq")
_AI_THINK_LEVELS = ("off", "minimal", "low", "medium", "high", "default")
_AI_THINK_LABELS = {
    "off": "خاموش",
    "minimal": "خیلی کم",
    "low": "کم",
    "medium": "متوسط",
    "high": "زیاد",
    "default": "پیش‌فرض مدل",
}
_AI_THINK_HINTS = {
    "gemini": "جمینی: کمتر = سریع‌تر. برای چت تلگرام «کم» بهترین است. مدل‌هایی که «خاموش» را قبول نکنند خودکار روی «خیلی کم» می‌روند.",
    "groq": "گروک: فقط مدل‌های استدلالی اثر می‌گیرند (qwen و gpt-oss). gpt-oss خاموش‌شدن ندارد و روی «کم» می‌رود. مدل‌های compound (جستجوی وب) دست‌نخورده می‌مانند.",
}
# مدلی که پارامتر تفکر را رد کرده (400) — دیگر برایش نفرست تا هر بار دو درخواست نشود
_AI_NO_THINK_MODELS: set = set()


def _ai_think_level(provider: str) -> str:
    try:
        v = (get_setting(f"ai_think_{provider}", "") or "").strip().lower()
    except Exception:
        v = ""
    if v not in _AI_THINK_LEVELS:
        v = ""
    if not v and provider == "gemini":
        v = (os.environ.get("GEMINI_THINKING_LEVEL", "") or "").strip().lower()
        if v not in _AI_THINK_LEVELS:
            v = "minimal"  # چت تلگرام: کمترین تفکر = سریع‌ترین جواب
    return v or "default"


def _gemini_thinking_cfg(model: str, override=None):
    lvl = override if override in _AI_THINK_LEVELS else _ai_think_level("gemini")
    if lvl == "default":
        lvl = "minimal"   # «پیش‌فرض» مدل = medium و کند (۱۰۰۰+ توکن فکر برای جواب کوتاه)؛ برای چت تلگرام کمترین سطح
    m = (model or "").lower()
    if "gemini-2.5" in m:
        budget = {"off": 0, "minimal": 128, "low": 512, "medium": 2048, "high": 8192}[lvl]
        if "pro" in m:
            budget = max(budget, 128)  # پرو خاموش‌شدن ندارد
        return {"thinkingBudget": budget}
    if "gemini-3" in m:
        # سری 3 «خاموش» ندارد؛ کمترین سطح minimal است
        return {"thinkingLevel": "minimal" if lvl == "off" else lvl}
    return None


def _groq_reasoning_effort(model: str, override=None):
    lvl = override if override in _AI_THINK_LEVELS else _ai_think_level("groq")
    if lvl == "default":
        return None
    m = (model or "").lower()
    if "compound" in m:
        return None
    if "gpt-oss" in m:
        return {"off": "low", "minimal": "low", "low": "low", "medium": "medium", "high": "high"}[lvl]
    if "qwen" in m:
        return "none" if lvl in ("off", "minimal") else "default"
    return None


# سشن مشترک برای تماس با Groq/Gemini: Keep-Alive + retry خودکار روی خطاهای اتصال/TLS.
# قبلاً هر درخواست یک اتصال TLS تازه می‌ساخت و روی شبکه‌های ناپایدار «Max retries exceeded» می‌داد.
# پروکسی اختیاری (وقتی سرور مستقیم به api.groq.com / googleapis.com دسترسی ندارد):
#   .env →  AI_PROXY=http://127.0.0.1:8118   یا   socks5h://127.0.0.1:1080  (برای socks: pip install "requests[socks]")
_ai_session = requests.Session()
_ai_session.mount("https://", requests.adapters.HTTPAdapter(
    pool_connections=16, pool_maxsize=64,   # = بزرگ‌تر از ۴۸ ترد _AI_CALL_POOL؛ با ۱۶ تا اتصال‌های اضافه دور ریخته و هر بار TLS تازه ساخته می‌شد
    max_retries=requests.adapters.Retry(
        # read=False (نه 0): تایم‌اوتِ خواندن همان‌جا به‌صورت requests.exceptions.ReadTimeout بالا می‌آید.
        # با read=0، urllib3 آن را در MaxRetryError می‌پیچید و requests به‌شکل ConnectionError («خطای شبکه») گزارش می‌کرد؛
        # در نتیجه یک جواب کندِ جمینی (read timeout=20) کل جمینی را کنار می‌گذاشت و مستقیم به گروک می‌رفت
        # (به‌جای امتحان مدل/کلید بعدیِ همان جمینی). حالا شاخهٔ Timeout (مدل بعدی) درست کار می‌کند.
        total=2, connect=1, read=False, other=1, backoff_factor=0.3,
        allowed_methods=frozenset(["GET", "POST"]),
    ),
))
_AI_PROXY = (os.environ.get("AI_PROXY", "") or "").strip()
if _AI_PROXY:
    _ai_session.trust_env = False   # وگرنه HTTPS_PROXY سیستم روی پروکسی اختصاصی اولویت می‌گیرد
    _ai_session.proxies.update({"http": _AI_PROXY, "https": _AI_PROXY})


def _err_cause(e, n: int = 110) -> str:
    """علت واقعی خطای شبکه. پیام requests فقط «Max retries exceeded» است و ریشهٔ مشکل
    (DNS / timeout / reset / TLS) را قطع می‌کند؛ اینجا تا ریشه پایین می‌رویم."""
    cur = e
    for _ in range(8):
        nxt = getattr(cur, "reason", None)
        if nxt is None and getattr(cur, "args", None) and isinstance(cur.args[0], BaseException):
            nxt = cur.args[0]
        if nxt is None or nxt is cur:
            break
        cur = nxt
    msg = str(cur)
    low = msg.lower()
    if "name or service not known" in low or "name resolution" in low or "getaddrinfo" in low:
        hint = "DNS جواب نمی‌دهد"
    elif "timed out" in low or "timeout" in low:
        hint = "تایم‌اوت؛ معمولاً یعنی مسیر فیلتر/بلاک است"
    elif "reset" in low or "remotedisconnected" in low or "eof" in low or "aborted" in low:
        hint = "اتصال از وسط قطع شد (Reset)؛ معمولاً فیلترینگ یا شبکهٔ ناپایدار"
    elif "certificate" in low or "ssl" in low:
        hint = "خطای TLS/گواهی"
    elif "proxy" in low:
        hint = "خطای پروکسی"
    elif "refused" in low or "unreachable" in low:
        hint = "اتصال رد شد/مسیر در دسترس نیست"
    else:
        hint = ""
    out = f"{type(cur).__name__}: {msg[:n]}"
    return f"{hint} — {out}" if hint else out


from concurrent.futures import TimeoutError as _FutTimeout
AI_BUILD = "2026-10-27-r14-agent"   # برای اطمینان از اینکه نسخهٔ جدید روی سرور آمده؛ در لاگ [AI] start و [STARTUP] چاپ می‌شود
_AI_CALL_POOL = ThreadPoolExecutor(max_workers=48, thread_name_prefix="ai-call")


def _ai_http_post(provider, key, model, messages, max_tokens, temperature, timeout, vision: bool = False,
                  search_web: bool = False, think=None):
    """پوشش با سقف زمانیِ واقعی (wall-clock). timeout در requests فقط «بین دو دریافت بایت» است؛
    اگر سرور/پروکسی کند و قطره‌قطره جواب بدهد یا اتصال گیر کند، یک تلاش می‌تواند ده‌ها ثانیه طول بکشد.
    اینجا بعد از connect+read (+۲ ثانیه) صبر را رها می‌کنیم و Timeout می‌دهیم تا مدل بعدی امتحان شود."""
    try:
        if isinstance(timeout, (tuple, list)):
            cap = float(timeout[0]) + float(timeout[1]) + 2.0
        else:
            cap = float(timeout) + 2.0
    except Exception:
        cap = 30.0
    _t0 = time.time()
    if vision:
        _think = f"img:{IMG_THINK_LEVEL}"
    elif provider in _AI_THINK_PROVIDERS:
        _think = think if think in _AI_THINK_LEVELS else _ai_think_level(provider)
        if provider == "gemini" and _think == "default":
            _think = "minimal(default)"
        if think in _AI_THINK_LEVELS:
            _think += "(forced)"
    else:
        _think = "-"
    fut = _AI_CALL_POOL.submit(_ai_http_post_raw, provider, key, model, messages, max_tokens, temperature,
                               timeout, vision, search_web, think)
    try:
        r = fut.result(timeout=cap)
    except _FutTimeout:
        logger.warning(f"[AI-CALL] {provider}/{model} HARD-CAP after {time.time() - _t0:.1f}s (cap={cap:.0f}s "
                       f"timeout={timeout} think={_think})")
        raise requests.exceptions.ReadTimeout(f"hard cap {cap:.0f}s exceeded ({provider}/{model})")
    except Exception as e:
        logger.warning(f"[AI-CALL] {provider}/{model} EXC {type(e).__name__} after {time.time() - _t0:.1f}s "
                       f"(cap={cap:.0f}s timeout={timeout} think={_think}) :: {str(e)[:160]}")
        raise
    try:
        _hdr = r.elapsed.total_seconds()     # زمان تا رسیدن هدر پاسخ (اتصال + پردازش مدل؛ بدون دانلود بدنه)
    except Exception:
        _hdr = -1
    _ln = logger.info if r.status_code == 200 else logger.warning
    _ln(f"[AI-CALL] {provider}/{model} status={r.status_code} wall={time.time() - _t0:.1f}s hdr={_hdr:.1f}s "
        f"cap={cap:.0f}s think={_think} in_msgs={len(messages)} max_tok={max_tokens}"
        + ("" if r.status_code == 200 else f" :: {_err_brief(r.text)}"))
    return r


def _or_messages(messages: list) -> list:
    """پیام‌های داخلی ربات → قالب OpenAI برای اوپن‌روتر: کلید «images» به بخش‌های image_url (data URL) تبدیل می‌شود."""
    out = []
    for m in messages:
        imgs = m.get("images") or []
        base = {k: v for k, v in m.items() if k != "images"}
        if imgs:
            parts = []
            for i, im in enumerate(imgs, 1):
                if len(imgs) > 1:
                    parts.append({"type": "text", "text": f"[عکس {i}]"})
                parts.append({"type": "image_url",
                              "image_url": {"url": f"data:{im['mime']};base64,{im['b64']}"}})
            parts.append({"type": "text", "text": base.get("content") or ""})
            base["content"] = parts
        out.append(base)
    return out


def _ai_http_post_raw(provider, key, model, messages, max_tokens, temperature, timeout, vision: bool = False,
                      search_web: bool = False, think=None):
    """یک درخواست چت. گروک: OpenAI-style. جمینی: generateContent بومی.
    vision=True (فقط جمینی): پیام‌های کاربر می‌توانند کلید "images" داشته باشند ([{"mime","b64"}, …]).
    search_web=True (فقط جمینی): جستجوی زندهٔ گوگل (Grounding) برای درخواست متنی هم فعال می‌شود."""
    if provider != "gemini":
        _msgs = _or_messages(messages) if provider == "openrouter" else messages
        payload = {"model": model, "messages": _msgs, "max_tokens": max_tokens, "temperature": temperature}
        _hdrs = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
        if provider == "openrouter":
            _hdrs["HTTP-Referer"] = os.environ.get("OPENROUTER_REFERER", "https://t.me")
            _hdrs["X-Title"] = os.environ.get("OPENROUTER_TITLE", "Telegram Bot")
        effort = None
        if provider == "groq" and ("groq", model) not in _AI_NO_THINK_MODELS:
            effort = _groq_reasoning_effort(model, think)
            if effort:
                payload["reasoning_effort"] = effort
        if search_web and provider == "groq" and "gpt-oss" in (model or "").lower():
            payload["tools"] = [{"type": "browser_search"}]      # جستجوی وب داخلی گروک (سمت سرور خودشان اجرا می‌شود)
            effort = "low"                                       # توصیهٔ خود گروک: کیفیت/سرعت متعادل
            payload["reasoning_effort"] = "low"

        def _post(pl):
            return _ai_session.post(
                AI_PROVIDERS[provider]["url"],
                headers=_hdrs,
                json=pl, timeout=timeout,
            )

        r = _post(payload)
        if r.status_code == 400 and effort and "reasoning" in (r.text or "").lower():
            _AI_NO_THINK_MODELS.add(("groq", model))
            payload.pop("reasoning_effort", None)
            r = _post(payload)
        return r
    system_parts = [m.get("content") or "" for m in messages if m.get("role") == "system"]
    contents = []
    for m in messages:
        if m.get("role") == "system":
            continue
        parts = []
        imgs = m.get("images") or []
        for i, im in enumerate(imgs, 1):
            if len(imgs) > 1:
                parts.append({"text": f"[عکس {i}]"})
            parts.append({"inlineData": {"mimeType": im["mime"], "data": im["b64"]}})
        parts.append({"text": m.get("content") or ""})
        contents.append({"role": "model" if m.get("role") == "assistant" else "user", "parts": parts})
    body = {
    "contents": contents,
    "generationConfig": {
        "maxOutputTokens": max_tokens,
        "temperature": temperature,
    },
    "safetySettings": [
        {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
        {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
        {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
        {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
        {"category": "HARM_CATEGORY_CIVIC_INTEGRITY", "threshold": "BLOCK_NONE"}
    ]
}

    if vision:
        # دقت بیشتر روی جزئیات ریز عکس (متن کوچک، عدد، نمودار)
        body["generationConfig"]["mediaResolution"] = "MEDIA_RESOLUTION_HIGH"
    # جستجوی زندهٔ گوگل برای جمینی: هم تحلیل عکس (با handoff فعال، جستجو را گروک انجام می‌دهد)
    # هم درخواست‌های متنی که search_web=True بگیرند (شناسایی آهنگ/شعر/فیلم/کتاب/دیالوگ)
    if search_web or (vision and IMG_AI_SEARCH and not _img_handoff_active()):
        body["tools"] = [{"google_search": {}}]
    if system_parts:
        body["systemInstruction"] = {"parts": [{"text": "\n\n".join(system_parts)}]}

    def _gpost(b):
        return _ai_session.post(
            AI_PROVIDERS["gemini"]["url"].format(model=model),
            headers={"x-goog-api-key": key, "Content-Type": "application/json"},
            json=b, timeout=timeout,
        )

    # مدل‌های جدید جمینی پیش‌فرض «فکر می‌کنند» (3.5 flash = medium) و همین ۱۰ تا ۲۰ ثانیه تأخیر می‌سازد.
    # برای چت کوتاه تلگرام سطح تفکر را پایین می‌آوریم. با GEMINI_THINKING_LEVEL در .env قابل‌تغییر است
    # (minimal | low | medium | high | off = دست‌نزن).
    tcfg = _img_thinking_cfg(model) if vision else _gemini_thinking_cfg(model, think)
    if tcfg:
        body["generationConfig"]["thinkingConfig"] = tcfg
    r = _gpost(body)
    if (vision or search_web) and r.status_code != 200:
        # جستجو فقط امتیاز اضافه است: اگر این مدل/کلید/سهمیه آن را رد کرد (400/403/404/429) بدون جستجو دوباره امتحان کن
        if "tools" in body and r.status_code in (400, 403, 404, 429):
            logger.warning(f"[IMG] gemini/{model} {r.status_code} با جستجو رد شد — بدون جستجو :: {_err_brief(r.text)}")
            body.pop("tools", None)
            r = _gpost(body)
        # بعد mediaResolution (برخی مدل‌ها نمی‌شناسند)؛ خودِ عکس همچنان می‌رود
        if r.status_code == 400 and "mediaResolution" in body["generationConfig"]:
            logger.warning(f"[IMG] gemini/{model} 400 — بدون mediaResolution :: {_err_brief(r.text)}")
            body["generationConfig"].pop("mediaResolution", None)
            r = _gpost(body)
    if r.status_code == 400 and tcfg and "think" in (r.text or "").lower():
        # این مدل آن مقدار تفکر را قبول نکرد — اگر «off/minimal» بود یک پله بالاتر، وگرنه بدون آن
        alt = None
        if "thinkingLevel" in tcfg and tcfg["thinkingLevel"] == "minimal":
            alt = {"thinkingLevel": "low"}
        body["generationConfig"].pop("thinkingConfig", None)
        if alt:
            body["generationConfig"]["thinkingConfig"] = alt
        r = _gpost(body)
        if r.status_code == 400 and alt and "think" in (r.text or "").lower():
            body["generationConfig"].pop("thinkingConfig", None)
            r = _gpost(body)
    if r.status_code != 200:
        return r
    try:
        d = r.json()
    except Exception:
        return _NormResp(502, (r.text or "")[:200])
    cand = ((d.get("candidates") or [{}])[0]) or {}
    parts = (cand.get("content") or {}).get("parts") or []
    text = "".join(p.get("text", "") for p in parts if isinstance(p, dict) and not p.get("thought"))
    fin = "length" if cand.get("finishReason") == "MAX_TOKENS" else "stop"
    um = d.get("usageMetadata") or {}
    if vision and not text.strip():
        logger.warning(f"[IMG] gemini/{model} جواب خالی داد finish={cand.get('finishReason')} "
                       f"block={(d.get('promptFeedback') or {}).get('blockReason')} think={um.get('thoughtsTokenCount')}")
    return _NormResp(200, r.text, {
        "choices": [{"message": {"content": text}, "finish_reason": fin}],
        "_usage": {"think": um.get("thoughtsTokenCount"), "out": um.get("candidatesTokenCount"),
                   "in": um.get("promptTokenCount")},
        "_grounded": bool(cand.get("groundingMetadata")),
    })


def _ai_keys_of(provider: str) -> list:
    return {
        "groq": GROQ_API_KEYS,
        "gemini": GEMINI_API_KEYS,
        "openrouter": OPENROUTER_API_KEYS,
        "elevenlabs": ELEVENLABS_API_KEYS,
    }.get(provider, [])


def _ai_total_keys() -> int:
    return sum(len(_ai_keys_of(p)) for p in API_SERVICES)


def _ai_counts_inline(sep: str = " | ") -> str:
    """«گروک 3 | جمینی 2 | الون‌لبز 2» — برای پیام‌های پنل (HTML)."""
    return sep.join(f"{API_SERVICES[p]['short']} <b>{len(_ai_keys_of(p))}</b>" for p in API_SERVICES)


# گوگل برای کلید نامعتبر/منقضی/لو‌رفته «400 یا 403» برمی‌گرداند (نه 401)؛ بدنهٔ پاسخ تعیین‌کننده است.
# فقط این نشانه‌های قطعی «مرده» حساب می‌شوند — خطای منطقه/شبکه/سهمیه هرگز.
_AI_BADKEY_MARKERS = (
    "api key not valid", "api_key_invalid", "api key expired",
    "api key not found", "reported as leaked",
    "no auth credentials", "user not found",   # اوپن‌روتر: کلید نامعتبر/حذف‌شده (401)
    "organization has been restricted",   # گروک: اکانت/سازمانِ آن کلید محدود شده؛ فقط همان کلید کنار برود، نه کل مدل برای همهٔ کلیدها
)


def _body_says_bad_key(text: str) -> bool:
    t = (text or "").lower()
    return any(m in t for m in _AI_BADKEY_MARKERS)


def _next_ai_slot(provider: str | None = None):
    """نوبت بعدی چرخه: (provider, key).
    اگر provider داده شود فقط بین کلیدهای همان سرویس می‌چرخد (مسیریابی گروک/جمینی)؛
    بدون آرگومان مثل قبل هر دو سرویس در یک صف مشترک‌اند."""
    global _ai_slot_index
    with _AI_KEYS_LOCK:
        if provider in API_SERVICES:
            keys = _ai_keys_of(provider)
            if not keys:
                return None
            i = _ai_slot_index_by_provider.get(provider, 0)
            key = keys[i % len(keys)]
            _ai_slot_index_by_provider[provider] = (i + 1) % len(keys)
            return (provider, key)
        pool = [(p, k) for p in AI_PROVIDERS for k in _ai_keys_of(p)]
        if not pool:
            return None
        slot = pool[_ai_slot_index % len(pool)]
        _ai_slot_index = (_ai_slot_index + 1) % len(pool)
        return slot


