# ============================================================
# منطقه زمانی تهران
# — ایران از سال ۱۴۰۱ (۲۰۲۲) دیگر تغییر ساعت تابستانی/زمستانی ندارد و همیشه
#   UTC+03:30 است؛ افست ثابت هم دقیق‌تر است و هم نیازی به دیتابیس tzdata سیستم ندارد.
# — همهٔ تایم‌استمپ‌های ذخیره‌شده در ارز.txt (فیلد ts) با UTC هستند (پسوند Z)،
#   پس هر جا زمانی برای نمایش به کاربر فرمت می‌شود، باید از این تابع عبور کند.
# ============================================================
TEHRAN_TZ = timezone(timedelta(hours=3, minutes=30))


def _to_tehran(dt: datetime) -> datetime | None:
    """datetime را (اگر بدون tzinfo بود، با فرض UTC) به وقت محلی تهران تبدیل می‌کند."""
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(TEHRAN_TZ)


def _now_tehran() -> datetime:
    return datetime.now(TEHRAN_TZ)


# ============================================================
# تقویم شمسی ↔ میلادی (کاملاً محاسباتی؛ جدول دستی ندارد و هر سال خودکار درست می‌شود)
# ============================================================
# الگوریتم: جدول «شکستگی‌های» ۳۳ساله (مثل jalaali-js) که روز ۱ فروردین هر سال را به‌صورت
# تاریخ میلادی می‌دهد؛ بقیهٔ سال با حساب روز ساخته می‌شود. طول هر سال (۳۶۵/۳۶۶) از فاصلهٔ
# ۱ فروردین دو سال پشت‌سرهم درمی‌آید، پس کبیسه‌ها هم خودکار هستند.
# تاریخ امروز همیشه از ساعت سرور (وقت تهران) خوانده می‌شود، نه از حافظهٔ مدل.
from datetime import date as _date

_JAL_BREAKS = (-61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210,
               1635, 2060, 2097, 2192, 2262, 2324, 2394, 2456, 3178)
_JAL_MONTHS = ("فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
               "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند")
_GREG_MONTHS_FA = ("ژانویه", "فوریه", "مارس", "آوریل", "مه", "ژوئن",
                   "ژوئیه", "اوت", "سپتامبر", "اکتبر", "نوامبر", "دسامبر")
_WEEKDAYS_FA = ("شنبه", "یکشنبه", "دوشنبه", "سه‌شنبه", "چهارشنبه", "پنجشنبه", "جمعه")


def _jal_new_year(jy: int) -> _date:
    """تاریخ میلادیِ ۱ فروردین سال شمسی jy."""
    if jy < _JAL_BREAKS[0] or jy >= _JAL_BREAKS[-1]:
        raise ValueError(f"سال شمسی خارج از بازهٔ پشتیبانی‌شده: {jy}")
    gy = jy + 621
    leap_j = -14
    jp = _JAL_BREAKS[0]
    jump = 0
    for jm in _JAL_BREAKS[1:]:
        jump = jm - jp
        if jy < jm:
            break
        leap_j += (jump // 33) * 8 + (jump % 33) // 4
        jp = jm
    n = jy - jp
    leap_j += (n // 33) * 8 + ((n % 33) + 3) // 4
    if jump % 33 == 4 and jump - n == 4:
        leap_j += 1
    leap_g = gy // 4 - ((gy // 100 + 1) * 3) // 4 - 150
    return _date(gy, 3, 20 + leap_j - leap_g)


def jalali_year_length(jy: int) -> int:
    """۳۶۵ یا ۳۶۶ (کبیسه)."""
    return (_jal_new_year(jy + 1) - _jal_new_year(jy)).days


def jalali_month_length(jy: int, jm: int) -> int:
    if jm <= 6:
        return 31
    if jm <= 11:
        return 30
    return 30 if jalali_year_length(jy) == 366 else 29


def gregorian_to_jalali(d: _date) -> tuple:
    """(سال، ماه، روز) شمسی از یک date میلادی."""
    jy = d.year - 621
    if d < _jal_new_year(jy):
        jy -= 1
    k = (d - _jal_new_year(jy)).days
    if k <= 185:
        return jy, 1 + k // 31, k % 31 + 1
    k -= 186
    return jy, 7 + k // 30, k % 30 + 1


def jalali_to_gregorian(jy: int, jm: int, jd: int) -> _date:
    """date میلادی از تاریخ شمسی؛ تاریخ نامعتبر (مثلاً ۳۰ اسفند سال غیرکبیسه) ValueError می‌دهد."""
    if not (1 <= jm <= 12) or not (1 <= jd <= jalali_month_length(jy, jm)):
        raise ValueError(f"تاریخ شمسی نامعتبر: {jy}/{jm}/{jd}")
    off = (jm - 1) * 31 if jm <= 6 else 186 + (jm - 7) * 30
    return _jal_new_year(jy) + timedelta(days=off + jd - 1)


def _weekday_fa(d: _date) -> str:
    return _WEEKDAYS_FA[(d.weekday() + 2) % 7]


def format_both(d: _date) -> str:
    """مثلاً «شنبه 28 تیر 1404 (19 ژوئیه 2025)»."""
    jy, jm, jd = gregorian_to_jalali(d)
    return (f"{_weekday_fa(d)} {jd} {_JAL_MONTHS[jm - 1]} {jy} "
            f"({d.day} {_GREG_MONTHS_FA[d.month - 1]} {d.year})")


def calendar_today_line() -> str:
    """یک خط کوتاه برای هر پرامپت: امروز به هر دو تقویم + ساعت تهران."""
    now = _now_tehran()
    return f"امروز: {format_both(now.date())} — ساعت {now:%H:%M} به وقت تهران"


def calendar_year_map(d: _date | None = None) -> str:
    """نقشهٔ کامل سال شمسیِ جاری (و آغاز سال بعد) برای تبدیل هر تاریخ بین دو تقویم.
    هر سطر ۱ام یک ماه + روز هفته‌اش را می‌دهد؛ مدل بقیه را با شمارش حساب می‌کند."""
    d = d or _now_tehran().date()
    jy = gregorian_to_jalali(d)[0]
    ylen = jalali_year_length(jy)
    start, nxt = _jal_new_year(jy), _jal_new_year(jy + 1)
    out = [f"تقویم کامل سال شمسی {jy} ({ylen} روزه{'، کبیسه' if ylen == 366 else ''}؛ "
           f"از {format_both(start)} تا {format_both(nxt - timedelta(days=1))}):"]
    out.append("شمسی → میلادی (روز اول هر ماه):")
    for m in range(1, 13):
        g = jalali_to_gregorian(jy, m, 1)
        out.append(f"1 {_JAL_MONTHS[m - 1]} ({jalali_month_length(jy, m)} روز) = "
                   f"{g.day} {_GREG_MONTHS_FA[g.month - 1]} {g.year}، {_weekday_fa(g)}")
    out.append("میلادی → شمسی (روز اول هر ماه):")
    y, m = start.year, start.month
    while _date(y, m, 1) <= nxt:
        g = _date(y, m, 1)
        if g >= start:
            jy2, jm2, jd2 = gregorian_to_jalali(g)
            out.append(f"1 {_GREG_MONTHS_FA[m - 1]} {y} = {jd2} {_JAL_MONTHS[jm2 - 1]} {jy2}، {_weekday_fa(g)}")
        m += 1
        if m == 13:
            y, m = y + 1, 1
    out.append(f"سال بعد: {format_both(nxt)}")
    return "\n".join(out)


# ============================================================
# تعطیلات رسمی ایران
# ============================================================
# قبلاً ربات فقط «تبدیل تاریخ» بلد بود و جدول تعطیلات نداشت؛ برای همین جواب «روز تعطیل بعدی کیه؟» را مدل از حافظه
# حدس می‌زد (مثلاً مبعث را ۴ اسفند گفته بود). حالا جدول داخلی دارد و مدل فقط از همین جواب می‌دهد.
# • تعطیلات شمسی (نوروز، ۱۲ و ۱۳ فروردین، ۱۴ و ۱۵ خرداد، ۲۲ بهمن، ۲۹ اسفند) هر سال ثابت‌اند و خودکار حساب می‌شوند.
# • تعطیلات قمری (تاسوعا، عاشورا، اربعین، مبعث، ...) با تقویم هجریِ «جدولی» حساب می‌شوند. تقویم رسمی کشور به رؤیت هلال
#   وابسته است؛ پس این تاریخ‌ها ممکن است ±۱ روز با اعلام رسمی فرق کنند و در جواب «تقریبی» گفته می‌شوند.
# • اصلاح بدون تغییر کد (.env یا Environment پنل Render):
#     HOLIDAY_OVERRIDES="1405/08/22=شهادت حضرت فاطمه (س); 1405/08/23=-"
#        «تاریخ شمسی=نام» → تعطیلیِ قطعیِ آن روز (جایگزین محاسبه) | «تاریخ شمسی=-» → حذف تعطیلی آن روز
#     HIJRI_OFFSET_DAYS=1   → همهٔ تعطیلات قمریِ محاسبه‌شده یک روز جلو می‌روند (-1 = یک روز عقب)
# • جمعه‌ها تعطیل هفتگی‌اند و جزو جدول نیستند؛ مناسبتی که روی جمعه بیفتد با برچسب «جمعه» در فهرست می‌آید.
_JAL_FIXED_HOLIDAYS = (
    (1, 1, "عید نوروز"), (1, 2, "عید نوروز"), (1, 3, "عید نوروز"), (1, 4, "عید نوروز"),
    (1, 12, "روز جمهوری اسلامی"), (1, 13, "روز طبیعت (سیزده‌بدر)"),
    (3, 14, "رحلت امام خمینی (ره)"), (3, 15, "قیام ۱۵ خرداد"),
    (11, 22, "پیروزی انقلاب اسلامی"), (12, 29, "ملی شدن صنعت نفت ایران"),
)
# (ماه هجری، روز، نام)؛ روز 0 = آخرین روز ماه (۲۹ یا ۳۰ صفر)
_HIJRI_HOLIDAYS = (
    (1, 9, "تاسوعای حسینی"), (1, 10, "عاشورای حسینی"), (2, 20, "اربعین حسینی"),
    (2, 28, "رحلت پیامبر اکرم (ص) و شهادت امام حسن مجتبی (ع)"), (2, 0, "شهادت امام رضا (ع)"),
    (3, 8, "شهادت امام حسن عسکری (ع)"), (3, 17, "میلاد پیامبر اکرم (ص) و امام جعفر صادق (ع)"),
    (6, 3, "شهادت حضرت فاطمه زهرا (س)"), (7, 13, "ولادت امام علی (ع) و روز پدر"),
    (7, 27, "مبعث پیامبر اکرم (ص)"), (8, 15, "ولادت امام زمان (عج) و نیمه شعبان"),
    (9, 21, "شهادت امام علی (ع)"), (10, 1, "عید سعید فطر"), (10, 2, "تعطیل به مناسبت عید فطر"),
    (10, 25, "شهادت امام جعفر صادق (ع)"), (12, 10, "عید سعید قربان"), (12, 18, "عید سعید غدیر خم"),
)
try:
    _HIJRI_OFFSET_DAYS = int(float(os.environ.get("HIJRI_OFFSET_DAYS", "0") or 0))
except ValueError:
    _HIJRI_OFFSET_DAYS = 0
_HOLIDAY_CACHE: dict = {}
_HOL_DIGITS = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")


def _hijri_to_gregorian(hy: int, hm: int, hd: int) -> _date:
    """تقویم هجری قمری «جدولی» (محاسباتی) → date میلادی. با رؤیت هلال تا ±۱ روز فرق دارد."""
    jdn = hd + (59 * (hm - 1) + 1) // 2 + (hy - 1) * 354 + (3 + 11 * hy) // 30 + 1948439
    return _date.fromordinal(jdn - 1721425)


# تاریخ‌های قطعی که با تقویم رسمی (time.ir) تطبیق داده شده و با محاسبهٔ هجری فرق داشت؛ روی محاسبه ارجحیت دارند.
# (فرمت مثل HOLIDAY_OVERRIDES) — برای ۳ جمادی‌الثانیه ۱۴۴۸ تقویم رسمی ۲۲ آبان ۱۴۰۵ را تعطیل نشان می‌دهد، نه ۲۳ آبان.
_HOLIDAY_CONFIRMED = (
    (1405, 8, 22, "شهادت حضرت فاطمه زهرا (س)"),
    (1405, 8, 23, "-"),
)


def _holiday_overrides() -> dict:
    """تاریخ‌های قطعی داخلی + HOLIDAY_OVERRIDES از env → {date میلادی: نام یا "-"}؛ env ارجحیت دارد؛ ورودی خراب نادیده گرفته می‌شود."""
    out: dict = {}
    for jy, jm, jd, name in _HOLIDAY_CONFIRMED:
        out[jalali_to_gregorian(jy, jm, jd)] = name
    raw = (os.environ.get("HOLIDAY_OVERRIDES", "") or "").translate(_HOL_DIGITS)
    for part in re.split(r"[;\n؛]+", raw):
        m = re.match(r"\s*(\d{4})\s*[/\-.]\s*(\d{1,2})\s*[/\-.]\s*(\d{1,2})\s*=\s*(.+?)\s*$", part)
        if not m:
            continue
        try:
            out[jalali_to_gregorian(int(m.group(1)), int(m.group(2)), int(m.group(3)))] = m.group(4).strip()
        except ValueError:
            continue
    return out


def _holidays_rules(jy: int) -> dict:
    """فقط محاسبه (تعطیلات ثابت شمسی + قمریِ جدولی)؛ بدون داده‌ی رسمیِ همگام‌شده و بدون اصلاحیه‌ها."""
    start, end = _jal_new_year(jy), _jal_new_year(jy + 1)
    out: dict = {}

    def add(d: _date, name: str, lunar: bool) -> None:
        if start <= d < end and all(name != n for n, _ in out.get(d, [])):
            out.setdefault(d, []).append((name, lunar))

    for m, d, name in _JAL_FIXED_HOLIDAYS:
        add(jalali_to_gregorian(jy, m, d), name, False)
    shift = timedelta(days=_HIJRI_OFFSET_DAYS)
    hy0 = int((start.year - 622) * 1.030684)
    for hy in range(hy0 - 1, hy0 + 4):
        for hm, hd, name in _HIJRI_HOLIDAYS:
            if hd == 0:      # آخرین روز ماه = یک روز قبل از اول ماه بعد
                g = _hijri_to_gregorian(hy + (1 if hm == 12 else 0), hm % 12 + 1, 1) - timedelta(days=1)
            else:
                g = _hijri_to_gregorian(hy, hm, hd)
            add(g + shift, name, True)
    return out


def _holidays_in_year(jy: int) -> dict:
    """{date میلادی: [(نام، قمریِ‌محاسبه‌ای؟), ...]} همهٔ تعطیلات رسمی سال شمسی jy (به‌جز جمعه‌های معمولی).
    ترتیب اولویت (ضعیف → قوی): محاسبه ← تقویم رسمیِ همگام‌شده (خودکار) ← _HOLIDAY_CONFIRMED / HOLIDAY_OVERRIDES."""
    hit = _HOLIDAY_CACHE.get(jy)
    if hit is not None:
        return hit
    start, end = _jal_new_year(jy), _jal_new_year(jy + 1)
    out = _holidays_rules(jy)
    try:
        _apply_official_holidays(out, start, end)
    except Exception as e:      # همگام‌سازی هیچ‌وقت نباید جدول محاسباتی را خراب کند
        logger.warning(f"[HOLIDAY-SYNC] اعمال داده‌ی رسمی ناموفق: {e}")
    for g, name in _holiday_overrides().items():
        if start <= g < end:
            if name == "-":
                out.pop(g, None)
            else:
                out[g] = [(name, False)]
    _HOLIDAY_CACHE[jy] = out
    return out


# ------------------------------------------------------------
# همگام‌سازی خودکار با تقویم رسمی (برای اینکه دیگر نیاز به اصلاح دستیِ ماه‌به‌ماه نباشد)
# ------------------------------------------------------------
# مشکل: تعطیلات قمری با رؤیت هلال تعیین می‌شوند و محاسبه ممکن است ±۱ روز با تقویم رسمی فرق کند (مثل ۲۲/۲۳ آبان ۱۴۰۵).
# راه‌حل: یک کار پس‌زمینه هر چند ساعت وضعیت تعطیلیِ روزهای پیش‌رو (پیش‌فرض ۴۰۰ روز) را از یک منبع رسمی می‌گیرد،
# در دیتابیس (جدول settings، کلید holiday_official_cache) نگه می‌دارد و روی جدول محاسباتی اعمال می‌کند.
# • منبع پیش‌فرض: holidayapi.ir (دادهٔ تقویم رسمی؛ هر روز یک درخواست). با HOLIDAY_SYNC_URL عوض می‌شود؛
#   قالب آدرس باید {y} {m} {d} (شمسی) داشته باشد، و پاسخ JSON با کلیدهای is_holiday و events[].{description,is_holiday}.
# • خاموش‌کردن: HOLIDAY_SYNC=0
# • اگر منبع در دسترس نباشد یا پاسخ نامعتبر باشد، چیزی عوض نمی‌شود و همان جدول محاسباتی کار می‌کند.
# • داده‌ی رسمی فقط برای سال شمسیِ جاری اجازه‌ی «حذف» تعطیلیِ محاسباتی دارد (برای سال بعد که هنوز اعلام نشده باشد
#   پاسخ «تعطیل نیست» نباید تعطیلی‌ها را پاک کند)؛ اضافه/جایگزین‌کردن برای هر سال مجاز است.
_HOLIDAY_SYNC_ON = os.environ.get("HOLIDAY_SYNC", "1").strip().lower() not in ("0", "false", "no", "off")
_HOLIDAY_SYNC_URL = (os.environ.get("HOLIDAY_SYNC_URL") or "https://holidayapi.ir/jalali/{y}/{m:02d}/{d:02d}").strip()
try:
    _HOLIDAY_SYNC_HORIZON = max(30, min(800, int(os.environ.get("HOLIDAY_SYNC_HORIZON_DAYS") or 400)))
except ValueError:
    _HOLIDAY_SYNC_HORIZON = 400
_HOLIDAY_SYNC_MAX_PER_RUN = 500
_HOLIDAY_SYNC_KEY = "holiday_official_cache"
_OFFICIAL: dict = {}            # {"2026-11-13": {"n": [نام‌ها], "t": زمان دریافت}}؛ n خالی = تعطیل نیست
_OFFICIAL_LOADED = False
_OFFICIAL_LOCK = threading.Lock()
_HOLIDAY_SYNC_RUN_LOCK = threading.Lock()


def _official_load(force: bool = False) -> None:
    """کش دیتابیس را یک‌بار در حافظه می‌خواند (خطا → نادیده؛ جدول محاسباتی کار می‌کند)."""
    global _OFFICIAL, _OFFICIAL_LOADED
    with _OFFICIAL_LOCK:
        if _OFFICIAL_LOADED and not force:
            return
        _OFFICIAL_LOADED = True
    try:
        with db_cursor() as c:
            c.execute("SELECT setting_value FROM settings WHERE setting_key=%s", (_HOLIDAY_SYNC_KEY,))
            row = c.fetchone()
        data = _json_loads(row["setting_value"]) if row and row.get("setting_value") else {}
        days = data.get("days") if isinstance(data, dict) else None
        if isinstance(days, dict):
            clean = {k: v for k, v in days.items()
                     if isinstance(v, dict) and isinstance(v.get("n"), list) and isinstance(v.get("t"), (int, float))}
            with _OFFICIAL_LOCK:
                _OFFICIAL = clean
    except Exception as e:
        logger.warning(f"[HOLIDAY-SYNC] خواندن کش از دیتابیس ناموفق: {type(e).__name__}: {e}")


def _official_save(days: dict) -> None:
    payload = _json_dumps({"v": 1, "days": days}, ensure_ascii=False, separators=(",", ":"))
    with db_cursor() as c:
        c.execute(
            "INSERT INTO settings (setting_key, setting_value) VALUES (%s, %s) "
            "ON CONFLICT (setting_key) DO UPDATE SET setting_value=%s",
            (_HOLIDAY_SYNC_KEY, payload, payload),
        )


def _apply_official_holidays(out: dict, start: _date, end: _date) -> None:
    """داده‌ی رسمیِ همگام‌شده را روی جدول محاسباتی همان سال می‌نشاند (جایگزین/اضافه؛ حذف فقط در سال جاری)."""
    if not _HOLIDAY_SYNC_ON:
        return
    _official_load()
    with _OFFICIAL_LOCK:
        snap = dict(_OFFICIAL)
    if not snap:
        return
    cur_end = _jal_new_year(gregorian_to_jalali(_now_tehran().date())[0] + 1)
    for iso, rec in snap.items():
        try:
            g = _date.fromisoformat(iso)
        except ValueError:
            continue
        if not (start <= g < end):
            continue
        names = [str(n) for n in (rec.get("n") or []) if str(n).strip()]
        if names:
            out[g] = [(n, False) for n in names]      # رسمی = قطعی، نه «تقریبی»
        elif g < cur_end:
            out.pop(g, None)


def _parse_official_day(data, g: _date):
    """پاسخ JSON یک روز → فهرست نام تعطیلی‌ها ([] = تعطیل نیست)؛ ساختار ناشناخته → None."""
    if not isinstance(data, dict) or not isinstance(data.get("is_holiday"), bool):
        return None
    events = data.get("events")
    if events is None:
        events = []
    if not isinstance(events, list):
        return None
    names: list = []
    for e in events:
        if isinstance(e, dict) and e.get("is_holiday") is True:
            n = re.sub(r"\s+", " ", str(e.get("description") or "")).strip()
            if n and n not in names:
                names.append(n)
    # روز تعطیل اعلام شده ولی رویدادِ تعطیلِ نام‌دار ندارد: جمعه‌ی معمولی نادیده؛ غیرجمعه «تعطیل رسمی»
    if data["is_holiday"] and not names and g.weekday() != 4:
        first = next((str(e.get("description")).strip() for e in events
                      if isinstance(e, dict) and e.get("description")), "")
        names.append(first or "تعطیل رسمی")
    return names


def _fetch_official_day(g: _date):
    """(names | None، علت خطا). None یعنی نتوانستیم جواب معتبر بگیریم."""
    jy, jm, jd = gregorian_to_jalali(g)
    try:
        url = _HOLIDAY_SYNC_URL.format(y=jy, m=jm, d=jd)
    except (KeyError, IndexError, ValueError):
        return None, "HOLIDAY_SYNC_URL قالب نامعتبر دارد ({y} {m} {d})"
    try:
        r = _FAST_HTTP.get(url, timeout=(4, 8), headers={"User-Agent": "Mozilla/5.0", "Accept": "application/json"})
    except Exception as e:
        return None, f"{type(e).__name__}"
    if r.status_code != 200:
        return None, f"HTTP {r.status_code}"
    try:
        names = _parse_official_day(r.json(), g)
    except ValueError:
        return None, "پاسخ JSON نیست"
    if names is None:
        return None, "ساختار پاسخ ناشناخته"
    return names, ""


def holiday_sync_job() -> None:
    """هر چند ساعت: روزهای جدید و روزهای کهنه را از منبع رسمی می‌گیرد. روزهای ۶۰ روز آینده هر ۱۲ ساعت،
    دورتر هفته‌ای یک‌بار تازه می‌شوند (چون اعلام رسمیِ رؤیت هلال نزدیک خودِ مناسبت عوض می‌شود)."""
    if not _HOLIDAY_SYNC_ON or not _HOLIDAY_SYNC_RUN_LOCK.acquire(blocking=False):
        return
    try:
        _official_load(force=True)
        today = _now_tehran().date()
        now_ts = time.time()
        with _OFFICIAL_LOCK:
            cache = dict(_OFFICIAL)
        todo = []
        for i in range(_HOLIDAY_SYNC_HORIZON):
            g = today + timedelta(days=i)
            rec = cache.get(g.isoformat())
            if rec is None:
                prio = 0
            else:
                age = now_ts - rec["t"]
                if i <= 60 and age > 12 * 3600:
                    prio = 1
                elif i > 60 and age > 7 * 86400:
                    prio = 2
                else:
                    continue
            todo.append((prio, i, g))
        if not todo:
            return
        todo.sort()
        todo = todo[:_HOLIDAY_SYNC_MAX_PER_RUN]

        got: dict = {}
        fails = 0
        last_err = ""
        for _, _, g in todo:
            names, err = _fetch_official_day(g)
            if names is None:
                fails += 1
                last_err = err
                if fails >= 6:      # منبع قطع/مسدود است؛ بی‌خود فشار نیاور
                    break
                continue
            fails = 0
            got[g.isoformat()] = {"n": names, "t": now_ts}
            time.sleep(0.05)
        if fails >= 6 and not got:
            logger.warning(f"[HOLIDAY-SYNC] منبع در دسترس نیست ({last_err}) — جدول محاسباتی استفاده می‌شود. "
                           f"آدرس: {_HOLIDAY_SYNC_URL}")
            return

        # اعتبارسنجی: اگر ≥30 روز گرفتیم و هیچ تعطیلِ غیرجمعه‌ای نبود ولی محاسبه انتظارش را داشت، پاسخ مشکوک است
        # (اختلاف ±۱ روز در تعطیلات قمری عادی است؛ ولی اگر کمتر از نصفِ تعطیلی‌های محاسباتی در ±۱ روز
        #  با داده‌ی رسمی جور شد، یعنی منبع خراب/نامرتبط است و چیزی اعمال نمی‌شود)
        rules_cache: dict = {}
        diffs = []
        off_days = {_date.fromisoformat(k) for k, v in got.items() if v["n"]}
        rule_days = []
        for iso, rec in got.items():
            g = _date.fromisoformat(iso)
            jy = gregorian_to_jalali(g)[0]
            rules = rules_cache.setdefault(jy, _holidays_rules(jy))
            rule_names = [n for n, _ in rules.get(g, [])]
            if rule_names:
                rule_days.append(g)
            if bool(rec["n"]) != bool(rule_names) and g.weekday() != 4:
                jyy, jm, jd = gregorian_to_jalali(g)
                diffs.append(f"{jyy}/{jm:02d}/{jd:02d}: رسمی={rec['n'] or '—'} | محاسبه={rule_names or '—'}")
        if len(rule_days) >= 3:
            matched = sum(1 for r in rule_days
                          if any((r + timedelta(days=k)) in off_days for k in (-1, 0, 1)))
            if matched / len(rule_days) < 0.5:
                logger.warning(f"[HOLIDAY-SYNC] پاسخ منبع مشکوک است (فقط {matched} از {len(rule_days)} تعطیلیِ محاسباتی "
                               f"در داده‌ی رسمی دیده شد) — اعمال نشد")
                return

        cache.update(got)
        cutoff = today - timedelta(days=45)
        cache = {k: v for k, v in cache.items() if k >= cutoff.isoformat()}
        with _OFFICIAL_LOCK:
            _OFFICIAL.clear()
            _OFFICIAL.update(cache)
        _HOLIDAY_CACHE.clear()
        try:
            _official_save(cache)
        except Exception as e:
            logger.warning(f"[HOLIDAY-SYNC] ذخیره در دیتابیس ناموفق (فقط در حافظه): {type(e).__name__}: {e}")
        logger.info(f"[HOLIDAY-SYNC] {len(got)} روز به‌روز شد (کل کش: {len(cache)}؛ خطا: {fails})"
                    + (f" | اختلاف با محاسبه ({len(diffs)}): " + " ; ".join(diffs[:8]) if diffs else ""))
    except Exception as e:
        logger.warning(f"[HOLIDAY-SYNC] خطا: {type(e).__name__}: {e}")
    finally:
        _HOLIDAY_SYNC_RUN_LOCK.release()


def upcoming_holidays(from_d: _date | None = None, limit: int = 8, horizon_days: int = 400) -> list:
    """[(date، [(نام، قمری؟)])] تعطیلات رسمیِ از from_d (خودِ روز هم حساب می‌شود) به بعد، مرتب."""
    from_d = from_d or _now_tehran().date()
    jy = gregorian_to_jalali(from_d)[0]
    last = from_d + timedelta(days=horizon_days)
    items = []
    for y in (jy, jy + 1, jy + 2):
        for d, names in _holidays_in_year(y).items():
            if from_d <= d <= last:
                items.append((d, names))
    items.sort(key=lambda x: x[0])
    return items[:limit]


def holiday_block(today: _date | None = None, limit: int = 8) -> str:
    """بلوک تعطیلات پیش‌رو برای پرامپت سیستم (مرجع قطعیِ «تعطیل بعدی کیه؟»)."""
    today = today or _now_tehran().date()
    items = upcoming_holidays(today, limit)
    fri = today + timedelta(days=(4 - today.weekday()) % 7)
    lines = ["تعطیلات رسمی ایران (جدول داخلی ربات؛ مرجع قطعی برای «تعطیل بعدی؟/فلان مناسبت کی است؟»):",
             f"جمعه‌ها تعطیل هفتگی‌اند؛ جمعهٔ {'امروز' if fri == today else 'بعدی'}: {format_both(fri)}."]
    first_work = None
    for i, (d, names) in enumerate(items, 1):
        delta = (d - today).days
        when = "امروز" if delta == 0 else "فردا" if delta == 1 else f"{delta} روز دیگر"
        label = " + ".join(n for n, _ in names)
        notes = []
        if d.weekday() == 4:
            notes.append("روز جمعه است؛ تعطیل اضافه‌ای نمی‌سازد")
        elif first_work is None:
            first_work = (d, label, when)
        if any(lunar for _, lunar in names):
            notes.append("تقریبی؛ قمری، ±1 روز")
        lines.append(f"{i}. {format_both(d)} — {label} — {when}" + (f" [{'؛ '.join(notes)}]" if notes else ""))
    if first_work:
        lines.append(f"نزدیک‌ترین تعطیلی رسمی که یک روز کاری (غیرجمعه) را تعطیل می‌کند: "
                     f"{format_both(first_work[0])} — {first_work[1]} ({first_work[2]}).")
    lines.append("قواعد: برای «تعطیل بعدی» از همین فهرست جواب بده (اول نزدیک‌ترین تعطیل غیرجمعه، و اگر خواست بقیه). "
                 "تعطیلیِ قمری را «حدوداً/طبق تقویم» بگو و اگر مهم است پیشنهاد بده تاریخ دقیق را از تقویم رسمی هم ببیند. "
                 "این جدول تعطیلی‌های موردی و اعلامی (آلودگی هوا، برف، سوگواری، پل بین دو تعطیلی، تعطیلی استانی) را ندارد؛ "
                 "اگر دربارهٔ آن‌ها پرسید صادقانه بگو در جدول نیست. هیچ تعطیلی یا تاریخ قمری از حافظه نساز.")
    return "\n".join(lines)


_HOLIDAY_ASK_RE = re.compile(
    r"تعطیل|مناسبت|(?<![؀-ۿ])عید|مبعث|عاشورا|تاسوعا|اربعین|نوروز|سیزده[\s‌]?بدر|غدیر|قربان|فطر|"
    r"نیمه[\s‌]?شعبان|ولادت|شهادت|رحلت|(?<![a-z])holidays?(?![a-z])", re.I)
# مناسبت مشخص یا خواستن فهرست → فهرست بلندتر (تا مناسبتِ دورتر هم در بلوک باشد)
_HOLIDAY_SPECIFIC_RE = re.compile(
    r"مبعث|عاشورا|تاسوعا|اربعین|نوروز|سیزده[\s‌]?بدر|غدیر|قربان|فطر|نیمه[\s‌]?شعبان|ولادت|شهادت|رحلت|"
    r"انقلاب|نفت|خرداد|همه|تمام|لیست|فهرست|کل|امسال|سال", re.I)
# «روز تعطیل بعدی کیه؟»: جدول داخلی دقیق‌تر و سریع‌تر از جستجوی وب است؛ پس برای همین سؤال وب خاموش می‌شود
_HOLIDAY_NEXT_RE = re.compile(
    r"تعطیل(?:ی|ات)?\s*(?:رسمی\s*)?(?:بعدی|آینده|پیش\s*رو|بعد)"
    r"|(?:بعدی|آینده|پیش\s*رو).{0,15}تعطیل"
    r"|(?:کی|کِی|چه\s*روزی|کدوم\s*روز).{0,15}تعطیل"
    r"|روز\s*تعطیل"
    # مناسبت رسمیِ نام‌دار + «کی/چه روزی/چندم» («مبعث کی هست؟»، «عاشورا چندمه؟»): جدول داخلی جواب می‌دهد، نه وب
    r"|(?:مبعث|عاشورا|تاسوعا|اربعین|نوروز|سیزده\s*بدر|غدیر|عید\s*(?:فطر|قربان)|نیمه\s*شعبان)"
    r".{0,25}(?:کی|کِی|چه\s*روزی|چندم|کدوم\s*روز)"
    r"|(?:کی|کِی|چه\s*روزی|چندم|کدوم\s*روز).{0,25}"
    r"(?:مبعث|عاشورا|تاسوعا|اربعین|نوروز|سیزده\s*بدر|غدیر|عید\s*(?:فطر|قربان)|نیمه\s*شعبان)")


_CAL_WORDS = (
    "تاریخ", "چندم", "چنده", "چندمه", "شمسی", "میلادی", "هجری", "قمری", "تقویم", "نوروز", "تعطیل",
    "فردا", "دیروز", "پس[\u200c ]?فردا", "پریروز",
    "(?:هفته|ماه|سال)[\u200c ]?(?:بعد|آینده|پیش|قبل|گذشته)", "سال[\u200c ]?نو",
    "روز\\s*(?:چنده|چندمه|چه\\s*روزی)",
)
_CAL_NAMES = _JAL_MONTHS + _GREG_MONTHS_FA + _WEEKDAYS_FA + ("پنج‌شنبه",)
_CAL_TRIGGER_RE = re.compile(
    "|".join(_CAL_WORDS)
    + r"|(?<![\u0600-\u06FF])(?:" + "|".join(_CAL_NAMES) + r")(?![\u0600-\u06FF])"
    + r"|\b(?:date|today|tomorrow|yesterday|calendar|weekday|jalali|solar hijri|january|february|march|april|"
      r"june|july|august|september|october|november|december)\b",
    re.I,
)


def calendar_context(user_text: str = "") -> str:
    """بلوک تاریخ برای پرامپت سیستم هوش مصنوعی. همیشه یک خط «امروز» دارد؛ اگر پیام دربارهٔ
    تاریخ/تبدیل تقویم/روز هفته به نظر برسد، نقشهٔ کامل سال هم اضافه می‌شود (تا توکن بی‌خود خرج نشود)."""
    try:
        txt = (user_text or "").replace("ي", "ی").replace("ك", "ک")
        block = ("تاریخ و زمان (از ساعت سرور؛ مرجع قطعی است):\n" + calendar_today_line() + "\n"
                 "برای هر سؤال دربارهٔ امروز/فردا/دیروز، تاریخ، روز هفته و تبدیل شمسی↔میلادی فقط از همین بلوک "
                 "استفاده کن و از حافظه‌ات تاریخ حدس نزن. تاریخ‌ها را به هر دو تقویم و با ارقام انگلیسی بگو.")
        if _CAL_TRIGGER_RE.search(txt):
            block += "\n" + calendar_year_map()
        if _HOLIDAY_ASK_RE.search(txt):
            try:
                block += "\n\n" + holiday_block(limit=30 if _HOLIDAY_SPECIFIC_RE.search(txt) else 8)
            except Exception as e:      # جدول تعطیلات خراب شد؟ فقط همین بخش حذف شود
                logger.warning(f"[CAL] holiday block failed: {e}")
        return block
    except Exception as e:  # هیچ‌وقت نباید جواب ربات را خراب کند
        try:
            logger.warning(f"[CAL] context failed: {e}")
        except Exception:
            pass
        return ""


def _now_stamp() -> str:
    """«2025-07-19 14:30 (شنبه 28 تیر 1404)» — برای سرتیتر بلوک‌های بازار و هوا."""
    n = _now_tehran()
    jy, jm, jd = gregorian_to_jalali(n.date())
    return f"{n:%Y-%m-%d %H:%M} ({_weekday_fa(n.date())} {jd} {_JAL_MONTHS[jm - 1]} {jy})"



# ============================================================
# Logger
# ============================================================
# قبلاً فقط روی stdout نوشته می‌شد؛ یعنی اگر وب‌ساکت کنسول زنده‌ی پنل قطع
# می‌شد (یا رفرش صفحه کمکی نمی‌کرد)، هیچ راه دومی برای دیدن لاگ‌ها نبود —
# نه لاگ گذشته، نه [SLOW-GROUP-CMD] لحظه‌ی کندی. حالا یک فایل چرخشی
# (rotating) هم اضافه شده تا لاگ‌ها همیشه، مستقل از وضعیت داشبورد، روی
# دیسک بمانند و از فایل‌منیجر پنل قابل دانلود/grep باشند.
_LOG_DIR = Path(__file__).resolve().parent / "logs"
try:
    _LOG_DIR.mkdir(parents=True, exist_ok=True)
except Exception:
    pass

# توکن ربات داخل URL درخواست‌های تلگرام است و urllib3/telebot موقع Retry کل URL را (با توکن) لاگ می‌کنند.
# این فرمتر قبل از نوشتن روی کنسول و فایل، توکن و کلیدهای API را پنهان و خط‌های غول‌پیکر را کوتاه می‌کند.
_LOG_SECRET_RE = re.compile(
    r"(?:bot\d{6,}:[A-Za-z0-9_-]{30,})"
    r"|(?:(?<![A-Za-z0-9])\d{8,}:[A-Za-z0-9_-]{35}(?![A-Za-z0-9_-]))"
    r"|(?:gsk_[A-Za-z0-9]{20,})|(?:sk-or-[A-Za-z0-9_-]{20,})|(?:AIza[A-Za-z0-9_-]{30,})"
)
_LOG_MAX_LINE = 900


class _RedactFormatter(logging.Formatter):
    def format(self, record):
        out = super().format(record)
        try:
            out = _LOG_SECRET_RE.sub(
                lambda m: "bot<REDACTED>" if m.group(0).startswith("bot") else "<REDACTED>", out
            )
            if len(out) > _LOG_MAX_LINE:
                out = "\n".join(
                    (ln[:_LOG_MAX_LINE] + f"…[{len(ln) - _LOG_MAX_LINE} کاراکتر حذف شد]") if len(ln) > _LOG_MAX_LINE else ln
                    for ln in out.split("\n")
                )
        except Exception:
            pass
        return out


_log_handlers = [logging.StreamHandler(sys.stdout)]
try:
    from logging.handlers import RotatingFileHandler
    _file_handler = RotatingFileHandler(
        _LOG_DIR / "bot.log",
        maxBytes=10 * 1024 * 1024,  # ۱۰ مگابایت هر فایل
        backupCount=5,               # مجموعاً حداکثر ~۶۰ مگابایت لاگ نگه‌داشته می‌شود
        encoding="utf-8",
    )
    _log_handlers.append(_file_handler)
except Exception as _e:
    print(f"[LOG] file handler راه‌اندازی نشد (ادامه فقط با stdout): {_e}", file=sys.stderr)

_log_formatter = _RedactFormatter("%(asctime)s [%(levelname)s] %(message)s")
# ساعت لاگ باید با ساعت تهران (و زمان‌بند) یکی باشد؛ قبلاً با ساعت سیستم‌عامل کانتینر ~۸.۵ ساعت اختلاف داشت
_log_formatter.converter = lambda ts: datetime.fromtimestamp(ts, TEHRAN_TZ).timetuple()
for _h in _log_handlers:
    _h.setFormatter(_log_formatter)
logging.basicConfig(
    level=logging.INFO,
    handlers=_log_handlers,
    force=True,
)
logger = logging.getLogger("ChandBot")
logger.info(f"[LOG] لاگ روی فایل هم نوشته می‌شود: {_LOG_DIR / 'bot.log'}")


# ============================================================
