logger.info("[PINLINK] دانلود از لینک پینترست فعال است (pinterest_link)" if _HAS_PINLINK else "[PINLINK] دانلود از لینک غیرفعال است (pinterest_link.py کنار bot.py نیست یا خطا داد)")

# تایم‌اوت صریح برای همهٔ تماس‌های HTTP به تلگرام (بجز خودِ getUpdates که تایم‌اوت
# طولانی‌ترش را از long_polling_timeout می‌گیرد) — روی هاستی که مسیر شبکه‌اش به
# تلگرام گاهی هنگ/کند می‌شود (خیلی رایج برای سرورهای داخل ایران)، بدون این
# مقدار صریح، یک تک‌کانکشن آویزان می‌تواند برای مدت نامعلوم یکی از تردهای
# کارگر بالا را قفل کند و همان چیزی شود که باعث تاخیر لحظه‌به‌لحظهٔ رشدیابنده
# در پاسخ‌های گروه می‌شود؛ این‌طور، بدترین حالت هر تماس حداکثر ~۱۳ ثانیه
# (اتصال ۵ + خواندن ۸) طول می‌کشد، نه بی‌نهایت.
telebot.apihelper.CONNECT_TIMEOUT = 5
telebot.apihelper.READ_TIMEOUT = 8

# سشن پایدار و استخر اتصال بزرگ‌تر برای تماس‌های HTTP به api.telegram.org —
# بدون این، telebot به‌صورت پیش‌فرض هم سشن را حفظ می‌کند (SESSION_TIME_TO_LIVE)
# ولی با استخر کوچک‌تر؛ اسم درست هوک سراسری کتابخانه CUSTOM_REQUEST_SENDER است
# (نه CUSTOM_REQUEST — آن اسم توسط apihelper خوانده نمی‌شود و بی‌اثر می‌ماند).
# هدف: وقتی چند ترد هم‌زمان (حذف پیام قدیمی، حذف نمودار، ارسال منو) به تلگرام
# وصل می‌شوند، همه از یک استخر کانکشن گرم/Keep-Alive استفاده کنند تا مجبور به
# هندشیک TLS جدید و کند (به‌خصوص روی هاست‌هایی با مسیر شبکهٔ کند به تلگرام) نشوند.
_telegram_session = requests.Session()
_telegram_adapter = requests.adapters.HTTPAdapter(
    pool_connections=20, pool_maxsize=30, max_retries=2
)
_telegram_session.mount("https://", _telegram_adapter)
telebot.apihelper.CUSTOM_REQUEST_SENDER = _telegram_session.request


# ============================================================
# سرور لوکال Bot API تلگرام (اختیاری — LOCAL_API_URL یا AUTO_LOCAL_SERVER=1)
# ============================================================
# در حالت لوکال: همه‌ی تماس‌ها به سرور لوکال می‌رود، getFile فایل را روی دیسک می‌گذارد و یک مسیر مطلق
# برمی‌گرداند (نه URL)؛ پس فایل‌ها مستقیم از دیسک خوانده و بعدش پاک می‌شوند تا دیسک پر نشود.
if LOCAL_API_URL:
    telebot.apihelper.API_URL = f"{LOCAL_API_URL}/bot{{0}}/{{1}}"
    telebot.apihelper.FILE_URL = f"{LOCAL_API_URL}/file/bot{{0}}/{{1}}"
    # ترافیک localhost نباید از پروکسی محیطی (HTTP_PROXY/...) رد شود
    _np_list = [x.strip() for x in os.environ.get("NO_PROXY", os.environ.get("no_proxy", "")).split(",") if x.strip()]
    for _nph in ("127.0.0.1", "localhost"):
        if _nph not in _np_list:
            _np_list.append(_nph)
    os.environ["NO_PROXY"] = os.environ["no_proxy"] = ",".join(_np_list)
    # getFile روی سرور لوکال کل فایل را دانلود می‌کند و بعد جواب می‌دهد؛ تایم‌اوت ۸ ثانیه برایش کم است.
    # (مسیر شبکه به سرور لوکال داخلی است؛ مشکل هنگ‌کردن مسیر تلگرام که آن عدد برایش بود اینجا نیست.)
    telebot.apihelper.READ_TIMEOUT = max(8, _ls_int("LOCAL_READ_TIMEOUT", 120))

_LS_PROC: "subprocess.Popen | None" = None


def _ls_stop_server() -> None:
    if _LS_PROC is not None and _LS_PROC.poll() is None:
        _LS_PROC.terminate()
        try:
            _LS_PROC.wait(timeout=10)
        except subprocess.TimeoutExpired:
            _LS_PROC.kill()


def _ls_http_json(url: str, timeout: float = 15) -> dict:
    """GET و برگرداندن JSON؛ جواب خطای HTTP (مثل 401) هم جواب معتبر حساب می‌شود. URL را لاگ نکن (توکن دارد)."""
    try:
        with urllib.request.urlopen(url, timeout=timeout) as r:
            return _json_loads(r.read())
    except urllib.error.HTTPError as e:
        try:
            return _json_loads(e.read())
        except Exception:
            return {"ok": False, "error_code": e.code, "description": f"HTTP {e.code}"}


def _ls_ensure_binary() -> Path:
    import shutil as _sh
    LOCAL_SERVER_DIR.mkdir(parents=True, exist_ok=True)
    binp = LOCAL_SERVER_DIR / "telegram-bot-api"
    # اگر آدرس باینری در .env عوض شده باشد، فایل قبلی خودکار پاک و فایل جدید دانلود می‌شود
    # (دیگر لازم نیست ./tgapi/telegram-bot-api را دستی پاک کنی).
    url_marker = LOCAL_SERVER_DIR / ".bin_url"
    try:
        _prev_url = url_marker.read_text().strip() if url_marker.exists() else ""
    except OSError:
        _prev_url = ""
    if binp.exists() and _prev_url != LOCAL_SERVER_BIN_URL:
        logger.info("[LOCAL-API] آدرس باینری تغییر کرده → فایل قبلی حذف و نسخهٔ جدید دانلود می‌شود.")
        binp.unlink(missing_ok=True)
    if not binp.exists():
        logger.info(f"[LOCAL-API] دانلود telegram-bot-api از {LOCAL_SERVER_BIN_URL} ...")
        part = LOCAL_SERVER_DIR / "telegram-bot-api.part"
        req = urllib.request.Request(LOCAL_SERVER_BIN_URL, headers={"User-Agent": "Mozilla/5.0"})
        try:
            with urllib.request.urlopen(req, timeout=120) as r, part.open("wb") as f:
                _sh.copyfileobj(r, f)
        except Exception as e:
            part.unlink(missing_ok=True)
            raise SystemExit(f"[FATAL] دانلود فایل اجرایی سرور لوکال ناموفق بود: {e}") from e
        part.chmod(0o755)
        part.replace(binp)
        try:
            url_marker.write_text(LOCAL_SERVER_BIN_URL)
        except OSError:
            pass
        h = hashlib.sha256()
        with binp.open("rb") as f:
            for chunk in iter(lambda: f.read(1 << 20), b""):
                h.update(chunk)
        logger.info(f"[LOCAL-API] دانلود شد ({binp.stat().st_size / 1048576:.1f} مگ) sha256={h.hexdigest()}")
    binp.chmod(0o755)
    try:
        out = subprocess.run([str(binp), "--version"], capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired) as e:
        binp.unlink(missing_ok=True)
        raise SystemExit(f"[FATAL] فایل اجرایی سرور لوکال روی این هاست اجرا نمی‌شود: {e}") from e
    if out.returncode != 0:
        raise SystemExit(
            f"[FATAL] telegram-bot-api اجرا نشد (کد {out.returncode}): {(out.stderr or out.stdout).strip()[:500]}\n"
            "احتمالاً کتابخانه‌ی سیستمی (libssl/zlib/glibc) روی هاست سازگار نیست."
        )
    logger.info(f"[LOCAL-API] telegram-bot-api: {(out.stdout or out.stderr).strip()[:200]}")
    return binp


def _ls_cloud_logout_once() -> None:
    """ربات باید قبل از رفتن به سرور لوکال از سرور ابری logOut شود (فقط یک‌بار برای هر توکن)."""
    marker = LOCAL_SERVER_DIR / f".cloud_logged_out_{hashlib.sha1(TOKEN.encode()).hexdigest()[:10]}"
    if marker.exists():
        return
    logger.info("[LOCAL-API] logOut از سرور ابری تلگرام (فقط یک‌بار)...")
    try:
        res = _ls_http_json(f"https://api.telegram.org/bot{TOKEN}/logOut", timeout=30)
    except Exception as e:
        logger.warning(f"[LOCAL-API] logOut انجام نشد ({type(e).__name__}). اگر سرور لوکال Unauthorized داد، ربات را دوباره اجرا کن.")
        return
    if res.get("ok") or res.get("error_code") == 401:
        marker.write_text(str(time.time()))
    logger.info(f"[LOCAL-API] logOut: {'ok' if res.get('ok') else res.get('description', res)}")


def start_local_server() -> None:
    """فقط وقتی AUTO_LOCAL_SERVER=1 باشد سرور را بالا می‌آورد؛ با LOCAL_API_URL فقط سلامتش چک می‌شود."""
    global _LS_PROC
    if not LOCAL_API_URL:
        logger.info("[LOCAL-API] غیرفعال (api.telegram.org)")
        return
    getme = f"{LOCAL_API_URL}/bot{TOKEN}/getMe"
    if START_LOCAL_SERVER:
        if not (TELEGRAM_API_ID and TELEGRAM_API_HASH):
            raise SystemExit("[FATAL] TELEGRAM_API_ID و TELEGRAM_API_HASH در .env تنظیم نشده.")
        if not TELEGRAM_API_ID.isdigit():
            raise SystemExit(
                f"[FATAL] TELEGRAM_API_ID باید فقط عدد باشد (طول مقدار فعلی: {len(TELEGRAM_API_ID)}). "
                "احتمالاً مقدار اشتباه یا جابه‌جا با API_HASH وارد شده؛ از my.telegram.org بگیر."
            )
        if not re.fullmatch(r"[0-9a-fA-F]{32}", TELEGRAM_API_HASH):
            raise SystemExit(
                f"[FATAL] TELEGRAM_API_HASH باید ۳۲ کاراکتر (حروف a-f و عدد) باشد (طول مقدار فعلی: {len(TELEGRAM_API_HASH)}). "
                "دوباره از my.telegram.org کپی کن."
            )
        binp = _ls_ensure_binary()
        _ls_cloud_logout_once()
        LOCAL_FILES_DIR.mkdir(parents=True, exist_ok=True)
        tmpd = LOCAL_SERVER_DIR / "tmp"
        tmpd.mkdir(parents=True, exist_ok=True)

        alive = False
        try:  # اگر از اجرای قبلی هنوز سروری روی همین پورت زنده است، همان را استفاده کن
            _ls_http_json(getme, timeout=3)
            alive = True
            logger.info(f"[LOCAL-API] سرور لوکال از قبل روی پورت {LOCAL_SERVER_PORT} بالاست.")
        except Exception:
            pass

        if not alive:
            base = [
                str(binp), f"--api-id={TELEGRAM_API_ID}", f"--api-hash={TELEGRAM_API_HASH}", "--local",
                f"--http-port={LOCAL_SERVER_PORT}", f"--dir={LOCAL_FILES_DIR}", f"--temp-dir={tmpd}",
            ]
            logp = LOCAL_SERVER_DIR / "server.log"
            logf = logp.open("ab")
            proc = None
            heads = []
            for extra in (["--http-ip-address=127.0.0.1"], []):  # اول فقط روی localhost؛ اگر نسخه نشناخت بدون آن
                off = logp.stat().st_size if logp.exists() else 0
                proc = subprocess.Popen(base + extra, stdout=logf, stderr=subprocess.STDOUT)
                time.sleep(2)
                if proc.poll() is None:
                    break
                logf.flush()
                # خطای واقعی ابتدای خروجی است (ته لاگ فقط لیست راهنمای آپشن‌هاست)
                with logp.open("rb") as _lf:
                    _lf.seek(off)
                    heads.append(_lf.read(600).decode("utf-8", "ignore"))
            else:
                _safe = lambda t: t.replace(TELEGRAM_API_HASH, "<hash>").replace(TOKEN, "<token>")
                msg = "\n--- تلاش بعدی ---\n".join(_safe(h) for h in heads)
                raise SystemExit(f"[FATAL] سرور لوکال بالا نیامد. ابتدای خروجی سرور:\n{msg}")
            _LS_PROC = proc
            import atexit as _ls_atexit
            _ls_atexit.register(_ls_stop_server)

            deadline = time.time() + 90
            while True:
                if proc.poll() is not None:
                    tail = logp.read_text(errors="ignore")[-800:].replace(TELEGRAM_API_HASH, "<hash>")
                    raise SystemExit(f"[FATAL] سرور لوکال وسط راه‌اندازی بسته شد. آخر server.log:\n{tail}")
                try:
                    _ls_http_json(getme, timeout=10)
                    break
                except Exception:
                    if time.time() > deadline:
                        raise SystemExit("[FATAL] سرور لوکال تا ۹۰ ثانیه جواب نداد (server.log را ببین).") from None
                    time.sleep(1.5)

    res = _ls_http_json(getme, timeout=20)
    if res.get("ok"):
        logger.info(f"[LOCAL-API] ✅ سرور لوکال سالم است | bot=@{res['result'].get('username')} | files dir={LOCAL_FILES_DIR}")
    else:
        logger.warning(f"[LOCAL-API] سرور لوکال بالاست ولی getMe خطا داد: {res.get('description')} (چند دقیقه بعد دوباره امتحان کن)")
    if not LOCAL_FILES_DIR.is_dir():
        logger.warning(f"[LOCAL-API] پوشه {LOCAL_FILES_DIR} وجود ندارد؛ Volume مشترک با سرور لوکال mount نشده.")


def _ls_is_local_path(fpath) -> bool:
    """در حالت لوکال، file_path برگشتی از getFile یک مسیر مطلق روی دیسک است (نه مسیر نسبی API)."""
    return bool(LOCAL_API_URL) and bool(fpath) and os.path.isabs(str(fpath))


def _ls_drop(fpath) -> None:
    try:
        Path(fpath).unlink()
    except OSError:
        pass


def _ls_check(fpath) -> Path:
    src = Path(fpath)
    if not src.is_file():
        raise FileNotFoundError(f"{fpath} روی دیسکِ ربات پیدا نشد؛ Volume مشترک بین سرور لوکال و ربات را چک کن.")
    return src


def _ls_take_bytes(fpath) -> bytes:
    """کل فایل را می‌خواند و نسخه‌ی سرور را پاک می‌کند."""
    src = _ls_check(fpath)
    try:
        return src.read_bytes()
    finally:
        _ls_drop(src)


def _ls_read_head(fpath, n: int) -> bytes:
    """n بایت اول فایل؛ بعدش نسخه‌ی سرور پاک می‌شود (دیسک پر نشود)."""
    src = _ls_check(fpath)
    try:
        with src.open("rb") as f:
            return f.read(n)
    finally:
        _ls_drop(src)


def _ls_take_tempfile(fpath, max_bytes: int):
    """فایل را به یک TemporaryFile (seek(0) شده) منتقل می‌کند و نسخه‌ی سرور را پاک می‌کند."""
    import shutil as _sh
    import tempfile as _tf
    src = _ls_check(fpath)
    try:
        if src.stat().st_size > max_bytes:
            raise ValueError("فایل بزرگ یا دانلود کند است")
        tf = _tf.TemporaryFile()
        try:
            with src.open("rb") as f:
                _sh.copyfileobj(f, tf, 1 << 20)
            tf.seek(0)
            return tf
        except Exception:
            tf.close()
            raise
    finally:
        _ls_drop(src)


if LOCAL_API_URL:
    _orig_bot_download_file = bot.download_file

    def _bot_download_file_local(file_path):
        if _ls_is_local_path(file_path):
            return _ls_take_bytes(file_path)
        return _orig_bot_download_file(file_path)

    bot.download_file = _bot_download_file_local


# ============================================================
# DB — context-manager based
# ============================================================

_db_pool = None
_db_pool_lock = threading.Lock()


# bool پایتون → 0/1 تا روی ستون‌های SMALLINT (جایگزین TINYINT(1) قدیمی) خطای نوع نده
psycopg2.extensions.register_adapter(
    bool, lambda b: psycopg2.extensions.AsIs("1" if b else "0")
)

_DB_TIMEZONE = os.environ.get("DB_TIMEZONE", "Asia/Tehran")


class _AutoCommitConnection(psycopg2.extensions.connection):
    """اتصال با autocommit (مثل رفتار قبلی) و ساعت سشن = تهران (برای NOW() و DEFAULT CURRENT_TIMESTAMP)."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.autocommit = True
        with self.cursor() as _c:
            _c.execute("SET TIME ZONE %s", (_DB_TIMEZONE,))


def _get_db_pool() -> PooledDB:
    """استخر اتصال PostgreSQL — mincached=2 تا همیشه چند کانکشن گرم و آماده باشد."""
    global _db_pool
    if _db_pool is None:
        with _db_pool_lock:
            if _db_pool is None:
                logger.info(
                    "[DB] connecting to PostgreSQL (%s) ...", DB_NAME,
                )
                try:
                    _db_pool = PooledDB(
                        creator=psycopg2,
                        maxconnections=30,
                        mincached=2,
                        maxcached=10,
                        maxshared=0,
                        blocking=True,
                        dsn=DATABASE_URL,
                        connection_factory=_AutoCommitConnection,
                        cursor_factory=psycopg2.extras.RealDictCursor,
                        connect_timeout=10,
                        keepalives=1,
                        keepalives_idle=30,
                        keepalives_interval=10,
                        keepalives_count=3,
                    )
                    _test = _db_pool.connection()
                    _test.close()
                    logger.info(
                        "[DB] connection pool OK (mincached=2, maxconnections=30)"
                    )
                except Exception as e:
                    logger.critical(
                        "[DB] FAILED PostgreSQL connect db=%s | error=%s | "
                        "check .env DATABASE_URL and network",
                        DB_NAME, e,
                    )
                    raise
    return _db_pool

@contextmanager
def db_conn():
    pool = _get_db_pool()
    conn = pool.connection()
    try:
        yield conn
    finally:
        try:
            conn.close()  # برگرداندن به استخر
        except Exception:
            pass


@contextmanager
def db_cursor():
    with db_conn() as conn:
        with conn.cursor() as c:
            yield c


# جدول‌های خودِ ربات — هر جدولِ دیگری در دیتابیس «اضافه» حساب می‌شود (بازماندهٔ ربات قبلی).
# فقط برای پاکسازی یک‌باره‌ی پایین استفاده می‌شود.
_BOT_OWN_TABLES = frozenset({
    "users", "groups_list", "settings", "force_join_channels", "fj_users", "fj_groups", "price_targets",
    "user_favorites",
    "pred_users", "pred_daily", "pred_groups", "pred_bonus", "posted_news",   # جدول‌های قدیمی (دیگر ساخته نمی‌شوند؛ فقط از پاکسازی خودکار محافظت می‌شوند)
    "daily_checkin", "user_states", "user_portfolio", "shock_subscribers",
    "shock_state", "api_clients",
    "bot_meta", "help_buttons",
    "user_personality", "personality_activity",     # جدول‌های قدیمیِ قابلیت حذف‌شدهٔ /شخصیت (دیگر استفاده نمی‌شوند؛ فقط از پاکسازی خودکار محافظت می‌شوند)
    "user_ai_profile",                              # قابلیت «تنظیم پرامپت شخصی»
    "group_messages",                               # حافظهٔ ۲۴ ساعتهٔ گروه‌ها برای هوش مصنوعی
    "group_seen_users", "group_pp_nudge",           # منشن روزانهٔ «تنظیم پرامپت شخصی» در گروه‌ها
    "enf_allow", "enf_events", "enf_chat_cfg",      # کنترلر اجرایی امنیت (فایل‌های تأییدشده / رویدادها / تنظیم گروه)
})
_FIRST_CLEANUP_KEY = "first_db_cleanup_done"


def _first_run_db_cleanup():
    """پاکسازی یک‌باره — **پیش‌فرض خاموش**. روی دیتابیس مشترک/Neon خطرناک است چون هر جدولِ
    ناشناس را DROP و دادهٔ جدول‌های ربات را TRUNCATE می‌کند. فقط اگر در .env صریحاً
    DB_FIRST_CLEANUP=1 بگذاری اجرا می‌شود؛ بعدش در bot_meta نشانه ثبت می‌شود و دیگر تکرار نمی‌شود."""
    if os.environ.get("DB_FIRST_CLEANUP", "0").strip().lower() not in ("1", "true", "yes", "on"):
        return
    with db_conn() as conn:
        with conn.cursor() as c:
            c.execute(
                "CREATE TABLE IF NOT EXISTS bot_meta ("
                "meta_key VARCHAR(64) PRIMARY KEY, meta_value VARCHAR(255), "
                "updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)"
            )
            c.execute("SELECT meta_value FROM bot_meta WHERE meta_key=%s", (_FIRST_CLEANUP_KEY,))
            if c.fetchone():
                return  # قبلاً انجام شده
            logger.warning("[DB-CLEANUP] اولین اجرا — حذف جدول‌های اضافه و پاک‌کردن داده‌ها ...")
            c.execute(
                "SELECT table_name AS t, table_type AS ty FROM information_schema.tables "
                "WHERE table_schema = current_schema()"
            )
            rows = c.fetchall() or []
            dropped, wiped, failed = [], [], []
            for r in rows:
                name = r["t"]
                qname = '"' + str(name).replace('"', '""') + '"'
                is_view = (r["ty"] or "").upper() == "VIEW"
                try:
                    if name not in _BOT_OWN_TABLES:
                        c.execute(f"DROP {'VIEW' if is_view else 'TABLE'} IF EXISTS {qname} CASCADE")
                        dropped.append(name)
                    elif name != "bot_meta" and not is_view:
                        c.execute(f"TRUNCATE TABLE {qname} CASCADE")
                        wiped.append(name)
                except Exception as e:
                    failed.append(f"{name}: {e}")
            # نشانه حتی با خطای جزئی ثبت می‌شود تا در استارت‌های بعد دادهٔ تازه هرگز پاک نشود
            c.execute(
                "INSERT INTO bot_meta (meta_key, meta_value) VALUES (%s, %s) "
                "ON CONFLICT (meta_key) DO UPDATE SET meta_value=EXCLUDED.meta_value",
                (_FIRST_CLEANUP_KEY, datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
            )
            logger.warning(
                f"[DB-CLEANUP] تمام شد — جدول اضافهٔ حذف‌شده ({len(dropped)}): {', '.join(dropped) or '—'} | "
                f"جدول خالی‌شده ({len(wiped)}): {', '.join(wiped) or '—'}"
            )
            for f in failed:
                logger.error(f"[DB-CLEANUP] خطا: {f}")


def init_db():
    try:
        _first_run_db_cleanup()
    except Exception as e:
        # شکست پاکسازی نباید ربات را از کار بیندازد؛ نشانه ثبت نشده پس استارت بعد دوباره تلاش می‌کند
        logger.error(f"[DB-CLEANUP] اجرا نشد: {e}", exc_info=True)
    with db_cursor() as c:
        c.execute("""
            CREATE TABLE IF NOT EXISTS users (
                user_id BIGINT PRIMARY KEY,
                username VARCHAR(255),
                first_name VARCHAR(255),
                joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                active_mid BIGINT DEFAULT NULL,
                is_blocked SMALLINT DEFAULT 0,
                captcha_ok SMALLINT DEFAULT 0,
                captcha_lock_until DOUBLE PRECISION DEFAULT NULL
            )
        """)
        # مهاجرت ستون‌های کپچا برای دیتابیس‌های قدیمی
        try:
            c.execute("ALTER TABLE users ADD COLUMN captcha_ok SMALLINT DEFAULT 0")
            # کاربران قبلی بدون کپچا عبور داده شوند
            c.execute("UPDATE users SET captcha_ok=1")
        except Exception:
            pass
        try:
            c.execute("ALTER TABLE users ADD COLUMN captcha_lock_until DOUBLE PRECISION DEFAULT NULL")
        except Exception:
            pass
        # شهر هواشناسی هر کاربر (/هوا و سؤال‌های هوا) — به‌جای جدول جدا، روی خود users
        for _col_ddl in (
            "ALTER TABLE users ADD COLUMN weather_city VARCHAR(64) DEFAULT NULL",
            "ALTER TABLE users ADD COLUMN weather_lat DOUBLE PRECISION DEFAULT NULL",
            "ALTER TABLE users ADD COLUMN weather_lon DOUBLE PRECISION DEFAULT NULL",
            "ALTER TABLE users ADD COLUMN ai_choice VARCHAR(16) DEFAULT NULL",     # /مدل: هوش مصنوعیِ دلخواه کاربر (NULL = خودکار/فالبک)
            "ALTER TABLE users ADD COLUMN img_choice VARCHAR(32) DEFAULT NULL",    # /مدل ← تصویر: مدل ساخت عکسِ دلخواه کاربر (NULL = پیش‌فرض)
            "ALTER TABLE users ADD COLUMN img_size VARCHAR(8) DEFAULT NULL",       # /مدل ← تصویر: سایز پیش‌فرض عکس (NULL = خودکار)
        ):
            try:
                c.execute(_col_ddl)
            except Exception:
                pass   # ستون از قبل هست
        try:
            c.execute("ALTER TABLE users ADD COLUMN chart_bg VARCHAR(16) DEFAULT 'dark'")
        except Exception:
            pass
        # سیستم دعوت دوستان: هر کاربر می‌تواند توسط یک نفر دعوت شده باشد
        try:
            c.execute("ALTER TABLE users ADD COLUMN referred_by BIGINT DEFAULT NULL")
        except Exception:
            pass
        try:
            c.execute("CREATE INDEX IF NOT EXISTS idx_users_referred_by ON users (referred_by)")
        except Exception:
            pass
        try:
            c.execute(
                "ALTER TABLE price_targets ADD COLUMN near_notified SMALLINT DEFAULT 0"
            )
        except Exception:
            pass
        c.execute("""
            CREATE TABLE IF NOT EXISTS groups_list (
                group_id BIGINT PRIMARY KEY,
                group_title VARCHAR(255),
                group_username VARCHAR(255),
                added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                is_active SMALLINT DEFAULT 1
            )
        """)
        c.execute("""
            CREATE TABLE IF NOT EXISTS settings (
                setting_key VARCHAR(100) PRIMARY KEY,
                setting_value TEXT
            )
        """)
        # دکمه‌های «راهنما گروه» — از پنل ادمین مدیریت می‌شوند
        c.execute("""
            CREATE TABLE IF NOT EXISTS help_buttons (
                id SERIAL PRIMARY KEY,
                title VARCHAR(64) NOT NULL,
                body TEXT,
                row_no INT NOT NULL DEFAULT 0,
                pos_no INT NOT NULL DEFAULT 0,
                parent_id INT NOT NULL DEFAULT 0,
                is_folder SMALLINT NOT NULL DEFAULT 0
            )
        """)
        # دیتابیس‌های قدیمی: ستون‌های «زیرمنو» (parent_id = 0 یعنی منوی اصلی؛ is_folder = 1 یعنی پوشه/زیرمنو)
        for _col, _ddl in (
            ("parent_id", "ALTER TABLE help_buttons ADD COLUMN parent_id INT NOT NULL DEFAULT 0"),
            ("is_folder", "ALTER TABLE help_buttons ADD COLUMN is_folder SMALLINT NOT NULL DEFAULT 0"),
        ):
            try:
                c.execute(
                    "SELECT 1 FROM information_schema.columns "
                    "WHERE table_schema = current_schema() AND table_name = 'help_buttons' AND column_name = %s",
                    (_col,),
                )
                if not c.fetchone():
                    c.execute(_ddl)
            except Exception as _e:
                logger.warning(f"[DB] افزودن ستون help_buttons.{_col} ناموفق: {_e}")
        # جدول کانال‌های عضویت اجباری — چند کانال قابل تعریف است
        c.execute("""
            CREATE TABLE IF NOT EXISTS force_join_channels (
                channel_id VARCHAR(64) PRIMARY KEY,
                channel_title VARCHAR(255),
                added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        try:
            c.execute("ALTER TABLE force_join_channels ADD COLUMN channel_link VARCHAR(255) DEFAULT NULL")
        except Exception:
            pass
        # وضعیت عضویت اجباری هر کاربر در پیوی (status: 1 = تأییدشده، 0 = تأییدنشده/خارج‌شده)
        c.execute("""
            CREATE TABLE IF NOT EXISTS fj_users (
                user_id BIGINT PRIMARY KEY,
                status SMALLINT NOT NULL DEFAULT 0,
                gate_mid BIGINT DEFAULT NULL,
                last_check TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_fj_users_status ON fj_users (status, last_check)")
        # وضعیت گروه‌ها: کسی که ربات را اضافه کرده + قفل/فعال (status: 1 = فعال، 0 = قفل)
        c.execute("""
            CREATE TABLE IF NOT EXISTS fj_groups (
                group_id BIGINT PRIMARY KEY,
                adder_id BIGINT NOT NULL DEFAULT 0,
                adder_name VARCHAR(255) DEFAULT NULL,
                status SMALLINT NOT NULL DEFAULT 0,
                gate_mid BIGINT DEFAULT NULL,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_fj_groups_adder ON fj_groups (adder_id, status)")
        c.execute("""
            CREATE TABLE IF NOT EXISTS price_targets (
                id BIGSERIAL PRIMARY KEY,
                user_id BIGINT NOT NULL,
                ab VARCHAR(32) NOT NULL,
                target_price DOUBLE PRECISION NOT NULL,
                baseline_price DOUBLE PRECISION NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                is_active SMALLINT DEFAULT 1
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_targets_user ON price_targets (user_id)")
        c.execute("CREATE INDEX IF NOT EXISTS idx_targets_active ON price_targets (is_active, ab)")
        c.execute("""
            CREATE TABLE IF NOT EXISTS user_favorites (
                user_id BIGINT NOT NULL,
                ab VARCHAR(32) NOT NULL,
                sort_order INT DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (user_id, ab)
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_fav_user ON user_favorites (user_id)")
        c.execute("""
            CREATE TABLE IF NOT EXISTS daily_checkin (
                user_id BIGINT PRIMARY KEY,
                last_date DATE NOT NULL,
                streak INT NOT NULL DEFAULT 0,
                total_days INT NOT NULL DEFAULT 0
            )
        """)
        # استیت پایدار کاربران (ثبت‌نام / تارگت / سبد و …)
        c.execute("""
            CREATE TABLE IF NOT EXISTS user_states (
                user_id BIGINT PRIMARY KEY,
                state_name VARCHAR(64) NOT NULL,
                state_data TEXT,
                updated_at DOUBLE PRECISION NOT NULL
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_user_states_ts ON user_states (updated_at)")
        # سبد دارایی شخصی
        c.execute("""
            CREATE TABLE IF NOT EXISTS user_portfolio (
                user_id BIGINT NOT NULL,
                ab VARCHAR(32) NOT NULL,
                amount DOUBLE PRECISION NOT NULL DEFAULT 0,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (user_id, ab)
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_portfolio_user ON user_portfolio (user_id)")
        # آلارم جهش قیمت — کاربران/گروه‌های مشترک
        c.execute("""
            CREATE TABLE IF NOT EXISTS shock_subscribers (
                chat_id BIGINT PRIMARY KEY,
                is_group SMALLINT DEFAULT 0,
                enabled SMALLINT DEFAULT 1,
                threshold_pct DOUBLE PRECISION DEFAULT 2.0,
                subscribed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        # حافظهٔ ضدِاسپمِ آلارم جهش (آخرین اعلان هر نماد) — قبلاً فقط در RAM
        # (دیکشنری پایتون) نگه داشته می‌شد، یعنی با هر ری‌استارت سرویس
        # (کرش/دیپلوی/ری‌استارت سیستمی) کاملاً خالی می‌شد و کول‌داون ۴۵دقیقه‌ای
        # از صفر شروع می‌شد — دقیقاً همان چیزی که باعث می‌شد یک «جهش» که کمی
        # قبل از ری‌استارت اعلام شده بود، بلافاصله بعد از بالا آمدن دوباره
        # (مثلاً فقط ۱۰ دقیقه بعد) دوباره اعلام شود، با همان درصد/قیمت تقریباً
        # ثابت. حالا در دیتابیس هم نگه داشته می‌شود تا با ری‌استارت از دست نرود.
        c.execute("""
            CREATE TABLE IF NOT EXISTS shock_state (
                ab VARCHAR(32) PRIMARY KEY,
                last_notify_ts DOUBLE PRECISION NOT NULL,
                last_price DOUBLE PRECISION DEFAULT NULL,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        # حافظهٔ مشترک گروه‌ها برای هوش مصنوعی (آخرین ۱۰۰ پیام هر گروه، حداکثر ۲۴ ساعت)
        c.execute("""
            CREATE TABLE IF NOT EXISTS group_messages (
                chat_id BIGINT NOT NULL,
                message_id BIGINT NOT NULL,
                ts DOUBLE PRECISION NOT NULL,
                author VARCHAR(255) NOT NULL,
                body VARCHAR(1000) NOT NULL,
                reply_to BIGINT NULL,
                is_bot SMALLINT NOT NULL DEFAULT 0,
                PRIMARY KEY (chat_id, message_id)
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_gm_ts ON group_messages (ts)")
        # پرامپت شخصی کاربر برای هوش مصنوعی (از پیوی ربات ثبت می‌شود؛ در همهٔ گروه‌ها اعمال می‌شود)
        c.execute("""
            CREATE TABLE IF NOT EXISTS user_ai_profile (
                user_id BIGINT PRIMARY KEY,
                profile TEXT NOT NULL,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        # کلاینت‌های وب‌سرویس قیمت (لایسنس API)
        c.execute("""
            CREATE TABLE IF NOT EXISTS api_clients (
                id SERIAL PRIMARY KEY,
                client_name VARCHAR(100) NOT NULL,
                api_key VARCHAR(64) UNIQUE NOT NULL,
                expire_at TIMESTAMP NOT NULL,
                is_active SMALLINT DEFAULT 1,
                note VARCHAR(255) DEFAULT NULL,
                allowed_symbols TEXT DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                CONSTRAINT uq_api_client_name UNIQUE (client_name)
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_api_key ON api_clients (api_key)")
        c.execute("CREATE INDEX IF NOT EXISTS idx_api_active ON api_clients (is_active, expire_at)")
        try:
            c.execute(
                "ALTER TABLE api_clients ADD COLUMN allowed_symbols TEXT DEFAULT NULL"
            )
        except Exception:
            pass
        # ساعت ارسال گزارش روزانه گروه (۹ تا ۱۴) — ستون قدیمی، فقط برای مهاجرت نگه داشته شده
        try:
            c.execute(
                "ALTER TABLE groups_list ADD COLUMN schedule_hour SMALLINT DEFAULT 12"
            )
        except Exception:
            pass
        try:
            # انتقال پیش‌فرض قدیمی ۱۱ → ۱۲
            c.execute(
                "UPDATE groups_list SET schedule_hour=12 WHERE schedule_hour=11 OR schedule_hour IS NULL"
            )
        except Exception:
            pass
        # زمان‌های ارسال «پیام زمان‌بندی‌شده» گروه — پنل جدید /پنل (چند زمان هم‌زمان، نیم‌ساعته)
        try:
            c.execute(
                "ALTER TABLE groups_list ADD COLUMN schedule_times VARCHAR(64) DEFAULT '12:00'"
            )
        except Exception:
            pass
        try:
            # حفظ سفارشی‌سازی قبلیِ سازگار با بازه‌های جدید (۱۰، ۱۱، ۱۲) در اولین مهاجرت
            c.execute(
                "UPDATE groups_list SET schedule_times=CONCAT(LPAD(schedule_hour::text,2,'0'),':00') "
                "WHERE schedule_hour IN (10,11,12) AND schedule_times='12:00'"
            )
        except Exception:
            pass
        # حالت «دستور قیمت» گروه — پنل /پنل ← دستور قیمت: با/بدون/هر دو
        # (اسلش) پیش‌فرض 'slash' یعنی دقیقاً همان رفتار قبلی، بدون تغییر برای گروه‌هایی
        # که این تنظیم را دست نزده‌اند.
        try:
            c.execute(
                "ALTER TABLE groups_list ADD COLUMN price_cmd_mode VARCHAR(16) DEFAULT 'slash'"
            )
        except Exception:
            pass
        # دسترسی ادمین‌های گروه به /پنل — پنل /پنل ← سوییچ «ادمین مجاز/غیرمجاز»
        # پیش‌فرض ۰ یعنی فقط صاحب گروه (creator)، دقیقاً رفتار قبلی، بدون تغییر
        # برای گروه‌هایی که این تنظیم را دست نزده‌اند.
        try:
            c.execute(
                "ALTER TABLE groups_list ADD COLUMN panel_admin_allowed SMALLINT DEFAULT 0"
            )
        except Exception:
            pass
        # پین قیمت گروه — پنل /پنل ← پین قیمت: به‌جای «پیام زمان‌بندی‌شده»، یک
        # پیام قیمت به‌صورت دائمی در گروه پین و هر دقیقه بروزرسانی می‌شود.
        # پیش‌فرض خاموش. وقتی فعال است، «پیام زمان‌بندی‌شده» غیرفعال می‌ماند.
        try:
            c.execute(
                "ALTER TABLE groups_list ADD COLUMN pin_price_enabled SMALLINT DEFAULT 0"
            )
        except Exception:
            pass
        try:
            c.execute(
                "ALTER TABLE groups_list ADD COLUMN pin_price_message_id BIGINT DEFAULT NULL"
            )
        except Exception:
            pass
        # --- اعلان عضو جدید به صاحب ربات + تشخیص دقیق‌تر بلاک/حذف ---
        try:
            c.execute("ALTER TABLE users ADD COLUMN owner_notified SMALLINT DEFAULT 0")
            # کاربران قبلی (که ربات را استارت کرده‌اند) دوباره به‌عنوان «عضو جدید» اعلان نشوند
            c.execute("UPDATE users SET owner_notified=1 WHERE captcha_ok=1")
        except Exception:
            pass
        try:
            c.execute("ALTER TABLE users ADD COLUMN alive_checked_at TIMESTAMP DEFAULT NULL")
        except Exception:
            pass
        try:
            c.execute("ALTER TABLE groups_list ADD COLUMN alive_checked_at TIMESTAMP DEFAULT NULL")
        except Exception:
            pass
        # اعضای دیده‌شده در هر گروه (برای منشن روزانهٔ «تنظیم پرامپت شخصی»)
        c.execute("""
            CREATE TABLE IF NOT EXISTS group_seen_users (
                group_id BIGINT NOT NULL,
                user_id BIGINT NOT NULL,
                first_name VARCHAR(64) DEFAULT NULL,
                username VARCHAR(64) DEFAULT NULL,
                last_seen DOUBLE PRECISION NOT NULL,
                last_nudged DOUBLE PRECISION DEFAULT NULL,
                PRIMARY KEY (group_id, user_id)
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_gseen_last ON group_seen_users (group_id, last_seen)")
        c.execute("""
            CREATE TABLE IF NOT EXISTS group_pp_nudge (
                group_id BIGINT PRIMARY KEY,
                last_date DATE NOT NULL
            )
        """)
        # کنترلر اجرایی امنیت: فایل‌های تأییدشدهٔ ادمین، گزارش رویدادها (پلکان تخلف)، روشن/خاموش هر گروه
        c.execute("""
            CREATE TABLE IF NOT EXISTS enf_allow (
                chat_id BIGINT NOT NULL,
                file_unique_id VARCHAR(64) NOT NULL,
                approved_by BIGINT DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (chat_id, file_unique_id)
            )
        """)
        c.execute("""
            CREATE TABLE IF NOT EXISTS enf_events (
                id BIGSERIAL PRIMARY KEY,
                chat_id BIGINT NOT NULL,
                user_id BIGINT NOT NULL,
                file_unique_id VARCHAR(64) DEFAULT NULL,
                file_name VARCHAR(200) DEFAULT NULL,
                score INTEGER NOT NULL DEFAULT 0,
                threat VARCHAR(200) DEFAULT NULL,
                deleted BOOLEAN NOT NULL DEFAULT FALSE,
                muted BOOLEAN NOT NULL DEFAULT FALSE,
                mute_seconds INTEGER NOT NULL DEFAULT 0,
                false_positive BOOLEAN NOT NULL DEFAULT FALSE,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_enf_ev_user ON enf_events (chat_id, user_id, created_at)")
        c.execute("""
            CREATE TABLE IF NOT EXISTS enf_chat_cfg (
                chat_id BIGINT PRIMARY KEY,
                enabled BOOLEAN NOT NULL DEFAULT TRUE
            )
        """)
    logger.info("DB initialized")
    _insert_default_settings()
    _load_settings_cache(force=True)


