def _insert_default_settings():
    defaults = [(k, meta["default"]) for k, meta in TEXT_SETTING_META.items()]
    with db_cursor() as c:
        c.executemany(
            "INSERT INTO settings (setting_key, setting_value) VALUES (%s, %s) ON CONFLICT (setting_key) DO NOTHING",
            defaults,
        )


def render_text(key: str, **kwargs) -> str:
    """متن تنظیم‌شده را با متغیرها رندر می‌کند.

    اگر ادمین عمداً مقدار را «خالی» کرده باشد، رشتهٔ خالی برمی‌گردد
    (دیگر به default برنمی‌گردد). فقط وقتی کلید اصلاً در تنظیمات نباشد
    از default استفاده می‌شود.
    """
    meta = TEXT_SETTING_META.get(key) or {}
    if not _settings_loaded:
        _load_settings_cache()
    with _settings_cache_lock:
        if key in _settings_cache:
            template = _settings_cache[key]
            if template is None:
                template = ""
        else:
            template = meta.get("default", "")
    if not template:
        return ""
    safe = {k: ("" if v is None else v) for k, v in kwargs.items()}

    class _SafeDict(dict):
        def __missing__(self, missing_key):
            logger.warning(
                f"[render_text] متغیر ناشناخته «{{{missing_key}}}» در قالب «{key}» "
                f"— این متغیر برای این پیام پشتیبانی نمی‌شود و خالی جایگزین شد."
            )
            return ""

    try:
        return template.format_map(_SafeDict(safe))
    except Exception as e:
        logger.error(f"[render_text] خطای فرمت در قالب «{key}»: {e}")
        return template


class _SafeFmt(dict):
    def __missing__(self, k):
        return ""


def render_text_or_default(key: str, **kwargs) -> str:
    """مثل render_text؛ ولی اگر ادمین متن را خالی کرده باشد، متن پیش‌فرض برمی‌گردد.
    برای متن‌هایی که نباید خالی شوند (بدنهٔ پیام، عنوان، برچسب دکمه)."""
    t = render_text(key, **kwargs)
    if t.strip():
        return t
    default = (TEXT_SETTING_META.get(key) or {}).get("default", "")
    safe = {k: ("" if v is None else v) for k, v in kwargs.items()}
    try:
        return default.format_map(_SafeFmt(safe))
    except Exception:
        return default


def _lbl(key: str, **kwargs) -> str:
    """برچسب دکمه از تنظیمات (همیشه غیرخالی)."""
    return render_text_or_default(key, **kwargs)[:64]


def _empty_hint(meta: dict) -> str:
    mode = (meta or {}).get("empty", "")
    if mode == "default":
        return "خالی = متن پیش‌فرض استفاده می‌شود"
    if mode == "silent":
        return "خالی = غیرفعال (چیزی نشان داده نمی‌شود)"
    return "خالی = هیچی ذخیره نشود"


def _register_service_texts(mod) -> int:
    """متن‌های قابل‌ویرایشِ یک ماژول جانبی (مثل weather_service) را به
    TEXT_SETTING_META اضافه می‌کند تا در پنل ادمین ← ✏️ ویرایش پیام‌ها دیده شوند، و
    render_text_or_default را به‌عنوان تأمین‌کنندهٔ متن به ماژول می‌دهد. باید قبل از init_db صدا زده شود
    (مقدار پیش‌فرض هر کلید همان‌جا در جدول settings ثبت می‌شود). تعداد کلیدهای جدید را برمی‌گرداند."""
    if mod is None:
        return 0
    added = 0
    for key, meta in (getattr(mod, "TEXT_DEFAULTS", None) or {}).items():
        if key not in TEXT_SETTING_META:
            TEXT_SETTING_META[key] = dict(meta)
            added += 1
    setter = getattr(mod, "set_text_provider", None)
    if callable(setter):
        setter(render_text_or_default)
    return added


try:
    _n_wx_texts = _register_service_texts(_wx_mod)
    if _n_wx_texts:
        logger.info(f"[TEXTS] {_n_wx_texts} متن هواشناسی به بخش ویرایش پیام‌ها اضافه شد")
except Exception as _e_wx_txt:  # pragma: no cover
    logger.warning(f"[TEXTS] ثبت متن‌های هواشناسی ناموفق: {_e_wx_txt}")


# --- کش رم برای جدول settings ---
# تنظیمات فقط از پنل ادمین تغییر می‌کنند (خیلی به‌ندرت)، اما در هر /start و هر رندر منو
# خوانده می‌شوند (خیلی زیاد). به همین دلیل کل جدول یک‌بار در رم نگه داشته می‌شود و get_setting
# دیگر هیچ کوئری‌ای به دیتابیس نمی‌زند؛ فقط set_setting هم دیتابیس و هم کش را آپدیت می‌کند.
_settings_cache: dict = {}
_settings_cache_lock = threading.Lock()
_settings_loaded = False


def _load_settings_cache(force: bool = False):
    global _settings_loaded
    if _settings_loaded and not force:
        return
    try:
        with db_cursor() as c:
            c.execute("SELECT setting_key, setting_value FROM settings")
            rows = c.fetchall()
        with _settings_cache_lock:
            _settings_cache.clear()
            for row in rows:
                _settings_cache[row["setting_key"]] = row["setting_value"]
            _settings_loaded = True
        logger.info(f"[SETTINGS] {len(rows)} تنظیم در رم کش شد")
    except Exception as e:
        logger.error(f"[SETTINGS] بارگذاری کش تنظیمات شکست خورد: {e}")


def get_setting(key: str, default: str = "") -> str:
    if not _settings_loaded:
        # فقط یک‌بار در کل عمر پروسه (اولین فراخوانی) به دیتابیس می‌رود؛ پس از آن همیشه از رم می‌آید
        _load_settings_cache()
    with _settings_cache_lock:
        val = _settings_cache.get(key)
    return val if val is not None else default


def set_setting(key: str, value: str):
    with db_cursor() as c:
        c.execute(
            "INSERT INTO settings (setting_key, setting_value) VALUES (%s, %s) ON CONFLICT (setting_key) DO UPDATE SET setting_value=%s",
            (key, value, value)
        )
    with _settings_cache_lock:
        _settings_cache[key] = value


