def set_user_blocked(uid: int, blocked: bool = True):
    with db_cursor() as c:
        c.execute("UPDATE users SET is_blocked=%s WHERE user_id=%s", (1 if blocked else 0, uid))


def get_all_users():
    with db_cursor() as c:
        c.execute("SELECT user_id, username, first_name FROM users WHERE is_blocked=0")
        rows = c.fetchall()
    return rows


def get_user_count():
    """تعداد کاربران «فعال» — کسانی که ربات را بلاک نکرده‌اند (مثل get_group_count که فقط گروه‌های فعال را می‌شمارد)."""
    with db_cursor() as c:
        c.execute("SELECT COUNT(*) as cnt FROM users WHERE is_blocked=0")
        row = c.fetchone()
    return row["cnt"] if row else 0


def get_blocked_user_count():
    """تعداد کاربرانی که ربات را بلاک کرده‌اند (یا حسابشان حذف شده)."""
    with db_cursor() as c:
        c.execute("SELECT COUNT(*) as cnt FROM users WHERE is_blocked=1")
        row = c.fetchone()
    return row["cnt"] if row else 0


