# ============================================================
# پین قیمت گروه — پنل /پنل ← پین قیمت: به‌جای «پیام زمان‌بندی‌شده»، یک پیام
# قیمت به‌صورت دائمی در گروه پین و هر دقیقه بروزرسانی می‌شود. پیش‌فرض خاموش —
# تا وقتی کاربر از پنل صراحتاً فعالش نکند هیچ تغییری در رفتار قبلی گروه نیست.
# ============================================================


def resolve_group_link(group_id: int, username: str | None = None) -> str | None:
    """لینک واقعی و قابل‌باز شدن:
    یوزرنیم عمومی یا لینک دعوت ربات.
    t.me/c/... عمداً برنمی‌گردد — در مرورگر خالی می‌ماند و گمراه‌کننده است.
    """
    uname = (username or "").strip().lstrip("@")
    if uname:
        return f"https://t.me/{uname}"

    try:
        link = bot.export_chat_invite_link(group_id)
        if link and str(link).startswith("https://"):
            return link
    except Exception:
        pass
    try:
        inv = bot.create_chat_invite_link(group_id, name="nokhod-admin")
        link = getattr(inv, "invite_link", None)
        if link and str(link).startswith("https://"):
            return link
    except Exception:
        pass

    return None


def refresh_group_info(group_id: int) -> dict | None:
    """از تلگرام title/username را تازه می‌کند و در DB می‌نویسد."""
    try:
        chat = bot.get_chat(group_id)
    except Exception as e:
        logger.warning(f"[GROUP] get_chat {group_id} failed: {e}")
        return None
    title = getattr(chat, "title", None) or str(group_id)
    uname = getattr(chat, "username", None)
    try:
        with db_cursor() as c:
            c.execute(
                """UPDATE groups_list
                   SET group_title=%s, group_username=%s, is_active=1
                   WHERE group_id=%s""",
                (title, uname, group_id),
            )
    except Exception as e:
        logger.warning(f"[GROUP] refresh db failed: {e}")
    return {"group_id": group_id, "group_title": title, "group_username": uname}


def format_group_list_line(g: dict) -> str:
    """یک ردیف خوانا با لینک واقعی برای پنل ادمین."""
    title = g.get("group_title") or "بدون‌نام"
    title = (
        str(title)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )
    gid = g.get("group_id")
    uname = (g.get("group_username") or "").strip().lstrip("@")
    if uname:
        link_html = f'<a href="https://t.me/{uname}">@{uname}</a>'
    else:
        link = resolve_group_link(gid, None) or ""
        if link.startswith("https://") and "t.me/c/" not in link:
            label = "لینک دعوت" if ("+" in link or "joinchat" in link) else "لینک گروه"
            link_html = f'<a href="{link}">{label}</a>'
        else:
            link_html = "خصوصی — لینک دعوت در دسترس نیست"
    return "• <b>%s</b>\n  %s — <code>%s</code>" % (title, link_html, gid)


def get_group_count():
    with db_cursor() as c:
        c.execute("SELECT COUNT(*) as cnt FROM groups_list WHERE is_active=1")
        row = c.fetchone()
    return row["cnt"] if row else 0


# ============================================================
# Spam protection
# ============================================================

_spam_tracker = {}
SPAM_WINDOW = 5
SPAM_LIMIT = 5

# محدودیت درخواست نمودار — جلوگیری از اسپم عکس
_chart_spam_tracker = {}  # chat_id -> [timestamps]
CHART_SPAM_WINDOW = 20          # ثانیه
CHART_SPAM_LIMIT_PV = 4         # حداکثر ۴ نمودار در ۲۰ثانیه در پیوی
CHART_SPAM_LIMIT_GROUP = 2      # حداکثر ۲ نمودار در ۲۰ثانیه در گروه


def is_spam(chat_id: int) -> bool:
    if chat_id == ADMIN_ID:
        return False
    now = time.time()
    times = _spam_tracker.get(chat_id, [])
    times = [t for t in times if now - t < SPAM_WINDOW]
    times.append(now)
    _spam_tracker[chat_id] = times
    return len(times) > SPAM_LIMIT


def is_chart_spam(chat_id: int, is_group: bool = False) -> bool:
    """True اگر درخواست نمودار بیش از حد باشد (ادمین معاف)."""
    if chat_id == ADMIN_ID:
        return False
    limit = CHART_SPAM_LIMIT_GROUP if is_group else CHART_SPAM_LIMIT_PV
    now = time.time()
    times = _chart_spam_tracker.get(chat_id, [])
    times = [t for t in times if now - t < CHART_SPAM_WINDOW]
    if len(times) >= limit:
        _chart_spam_tracker[chat_id] = times
        return True
    times.append(now)
    _chart_spam_tracker[chat_id] = times
    return False


def cleanup_spam_tracker():
    """جاب زمان‌بندی‌شده — رکوردهای منقضی‌شدهٔ آنتی‌اسپم را پاک می‌کند تا دیکشنری برای همیشه رشد نکند (نشت حافظه)."""
    now = time.time()
    expired_keys = []
    for chat_id, times in list(_spam_tracker.items()):
        fresh = [t for t in times if now - t < SPAM_WINDOW]
        if fresh:
            _spam_tracker[chat_id] = fresh
        else:
            expired_keys.append(chat_id)
    for k in expired_keys:
        _spam_tracker.pop(k, None)

    # پاکسازی ترکر اسپم نمودار
    chart_expired = []
    for chat_id, times in list(_chart_spam_tracker.items()):
        fresh = [t for t in times if now - t < CHART_SPAM_WINDOW]
        if fresh:
            _chart_spam_tracker[chat_id] = fresh
        else:
            chart_expired.append(chat_id)
    for k in chart_expired:
        _chart_spam_tracker.pop(k, None)

    total = len(expired_keys) + len(chart_expired)
    if total:
        logger.info(f"[SPAM] {total} رکورد منقضی‌شده از حافظه پاک شد")

    # پاکسازی کش مکالمه AI و محدودیت نرخ
    try:
        _ai_cache_cleanup_expired()
    except Exception:
        pass
    try:
        _ai_rate_cleanup()
    except Exception:
        pass
    try:
        group_mem_cleanup()
    except Exception:
        pass


def _malloc_trim():
    """آزادسازی حافظهٔ خالیِ heapِ گلیبک به سیستم‌عامل.

    gc.collect فقط آبجکت‌های پایتون را آزاد می‌کند؛ خودِ حافظهٔ آزادشده معمولاً
    داخل heap پروسه نگه داشته می‌شود (برای استفادهٔ بعدی پایتون) و به سیستم‌عامل
    برنمی‌گردد — به همین دلیل RSS گزارش‌شده در پنل هاست معمولاً بیشتر از حجم
    واقعی آبجکت‌های زندهٔ پایتون است، مخصوصاً بعد از رسم چند نمودار سنگین
    matplotlib پشت‌سرهم. malloc_trim(0) از خودِ glibc می‌خواهد این حافظهٔ آزاد را
    به سیستم‌عامل پس بدهد. کاملاً اختیاری و بی‌خطر: اگر روی سیستمی غیر از
    glibc/Linux اجرا شود (مثلاً musl/Alpine یا ویندوز) فقط بی‌صدا رد می‌شود و
    هیچ اثری روی رفتار ربات ندارد."""
    try:
        libc = ctypes.CDLL(ctypes.util.find_library("c") or "libc.so.6")
        libc.malloc_trim(0)
        return True
    except Exception:
        return False


def memory_housekeeping():
    """جاب زمان‌بندی‌شدهٔ ساعتی — gc.collect صریح را اجرا می‌کند (چرخه‌های
    ارجاعیِ آبجکت‌های matplotlib/numpy را زودتر از موعد خودکار GC آزاد می‌کند)،
    سپس malloc_trim حافظهٔ آزادشده را واقعاً به سیستم‌عامل پس می‌دهد (وگرنه RSS
    در پنل هاست بالا می‌ماند حتی وقتی آبجکت‌های پایتون آزاد شده‌اند)، و اگر
    psutil نصب باشد، مصرف واقعی RAM پروسه (RSS) را لاگ می‌کند تا بشود فهمید
    بعد از این بهینه‌سازی‌ها، رم واقعاً پایدار مانده یا نه."""
    try:
        collected = gc.collect()
    except Exception as e:
        collected = None
        logger.warning(f"[MEM] gc.collect failed: {e}")

    _malloc_trim()

    if _HAS_PSUTIL:
        try:
            rss_mb = psutil.Process(os.getpid()).memory_info().rss / (1024 * 1024)
            _gm_groups, _gm_msgs = group_mem_stats()
            logger.info(
                f"[MEM] RSS={rss_mb:.1f}MB gc_collected={collected} "
                f"chart_cache={len(_chart_cache)} group_mem={_gm_groups}groups/{_gm_msgs}msgs"
            )
        except Exception as e:
            logger.warning(f"[MEM] psutil read failed: {e}")
    elif collected is not None:
        logger.info(f"[MEM] gc_collected={collected} (نصب psutil برای لاگ RSS: pip install psutil)")


# ============================================================
# Price data — ساختار فایل ارز.txt
# ============================================================
#
# هر آیتم:
#   ab  : کد (usd, eur, gram, emami, ...)
#   av  : ایموجی
#   en  : نام انگلیسی
#   fa  : نام فارسی
#   ty  : cu | go | cc | co
#   ps  : لیست اسنپ‌شات‌ها (جدیدترین اول)
#         هر اسنپ: {bp?, sp?, ts}
#
# cu=ارز فیات، go=طلا (گرم/مثقال)، co=سکه، cc=رمزارز
#

_price_items = []          # list of dicts (full items)
_price_by_ab = {}          # ab -> item
_price_cache_time = 0
try:
    _PRICE_REFRESH_ENV = max(2, int(os.environ.get("PRICE_API_REFRESH_SEC", "5") or 5))
except ValueError:
    _PRICE_REFRESH_ENV = 5
CACHE_TTL = min(30, _PRICE_REFRESH_ENV)   # ثانیه — هم‌گام با بروزرسانی API
_price_lock = threading.Lock()  # جلوگیری از خواندن نصفه/ناسازگار دیکشنری‌های سراسری زیر بار موازی


def _resolve_price_path() -> Path:
    p = Path(PRICE_DATA_PATH)
    if p.is_file():
        return p
    for fp in _FALLBACK_PRICE_PATHS:
        if fp.is_file():
            return fp
    return p  # ممکن است بعداً ظاهر شود


def _snap_price(snap: dict) -> float | None:
    """قیمت نمایشی از یک اسنپ‌شات: ترجیح sp، در غیر این صورت bp، در غیر این صورت میانگین."""
    if not snap:
        return None
    sp = snap.get("sp")
    bp = snap.get("bp")
    if sp is not None and bp is not None:
        try:
            return float(sp)  # فروش به‌عنوان قیمت رایج
        except (TypeError, ValueError):
            pass
    for key in ("sp", "bp"):
        if snap.get(key) is not None:
            try:
                return float(snap[key])
            except (TypeError, ValueError):
                continue
    return None


def _load_price_file(force: bool = False) -> list:
    global _price_items, _price_by_ab, _price_cache_time
    now = time.time()
    if not force and _price_items and (now - _price_cache_time) < CACHE_TTL:
        return _price_items

    with _price_lock:
        # بررسی مجدد پس از گرفتن قفل (Double-checked locking) — ممکن است ترد دیگری
        # دقیقاً بین بررسی بالا و رسیدن نوبت این ترد به قفل، از قبل فایل را تازه
        # بارگذاری کرده باشد؛ در این صورت نیازی به خواندن دوبارهٔ دیسک نیست.
        if not force and _price_items and (now - _price_cache_time) < CACHE_TTL:
            return _price_items

        path = _resolve_price_path()
        last_err = None
        # حداکثر ۲ تلاش: اگر اسکریپت دیگری دقیقاً همین لحظه در حال بازنویسی فایل باشد،
        # ممکن است یک بار فایل خالی/نصفه‌نویسی‌شده بخوانیم — با یک تاخیر کوتاه دوباره امتحان می‌کنیم
        # به‌جای کرش کردن یا از دست دادن آخرین دادهٔ سالم موجود در حافظه.
        for attempt in range(2):
            try:
                with open(path, "r", encoding="utf-8") as f:
                    raw_text = f.read()
                if not raw_text.strip():
                    raise ValueError("price file is empty (probably mid-write)")
                data = _json_loads(raw_text)
                if not isinstance(data, list):
                    raise ValueError("root of price file must be a list")
                items = []
                by_ab = {}
                for raw in data:
                    if not isinstance(raw, dict) or "ab" not in raw:
                        continue
                    ab = str(raw["ab"]).strip().lower()
                    item = {
                        "ab": ab,
                        "av": raw.get("av") or "•",
                        "en": raw.get("en") or ab,
                        "fa": raw.get("fa") or ab,
                        "ty": raw.get("ty") or "cu",
                        "ps": raw.get("ps") or [],
                    }
                    items.append(item)
                    by_ab[ab] = item
                if not items:
                    raise ValueError("parsed price file contains 0 valid items")
                _price_items = items
                _price_by_ab = by_ab
                _price_cache_time = now
                logger.info(f"[PRICE] loaded {len(items)} items from {path}")
                return items
            except (json.JSONDecodeError, ValueError) as e:
                last_err = e
                if attempt == 0:
                    time.sleep(0.15)
                    continue
            except Exception as e:
                last_err = e
                break

        logger.error(f"[PRICE] load failed from {path}: {last_err} — نگه‌داشتن آخرین دادهٔ سالم در حافظه")
        return _price_items or []


def fetch_prices(force: bool = False, skip_oil: bool = False) -> list:
    """خواندن سریع از فایل محلی + نفت.txt — هیچ ریکوئست شبکه‌ای نمی‌زند."""
    _load_price_file(force=force)
    _merge_oil_items(force=force)
    return _price_items


# ============================================================
# نفت و گاز — دریافت مستقیم از API اپ oilprice.com (سرویس priceChart)
# هر بار فقط یک درخواست برای هر نماد (برنت، WTI، گاز طبیعی) زده می‌شود و کل
# نمودار درون‌روزی همان لحظه از پاسخ ساخته می‌شود؛ پس دیگر لازم نیست ساعت‌ها
# صبر کنی تا نمودار پر شود و به فایل نفت.txt هم وابسته نیست.
# فایل نفت.txt فقط یک «آخرین اسنپ‌شات سالم» برای استارت وقتی API در دسترس نیست.
# هیچ ریکوئست نفتی روی /start یا کلیک کاربر زده نمی‌شود (فقط جاب پس‌زمینه).
#
# متغیرهای محیطی (همان‌هایی که در پنل هاست گذاشته‌ای):
#   OIL_API_URL             آدرس اندپوینت اپ                          — الزامی
#   OIL_DEVICE_TOKEN        deviceToken اپ (داخل بدنهٔ درخواست)        — الزامی
#   OIL_ACCESS_TOKEN        توکن دسترسی (داخل هدر درخواست)            — اگر API لازم دارد
#   OIL_ACCESS_HEADER       نام هدر توکن؛ پیش‌فرض Authorization
#   OIL_ACCESS_SCHEME       پیشوند مقدار هدر؛ پیش‌فرض Bearer (برای ارسال خام خالی بگذار: OIL_ACCESS_SCHEME=none)
#   OIL_CHART_PERIOD        پیش‌فرض 2 (همان period نمودار روزانه)
#   OIL_BODY_FORMAT         json (پیش‌فرض) یا form
#   OIL_USER_AGENT          اختیاری؛ همان User-Agent کپچر
# ============================================================
OIL_DATA_PATH = os.environ.get(
    "OIL_DATA_PATH",
    str(Path(__file__).resolve().parent / "نفت.txt"),
)

_OIL_FALLBACK_PATHS = [
    Path("/home/workdir/attachments/نفت.txt"),
    Path(__file__).resolve().parent.parent / "attachments" / "نفت.txt",
]

_OIL_SYMBOLS = [
    ("brent", "🛢️", "Brent Crude", "نفت برنت"),
    ("wti", "⛽", "WTI Crude", "نفت WTI"),
    ("ng", "🔥", "Natural Gas", "گاز طبیعی"),
]

# blendId در oilprice.com (از globalVariables → blend_codes)
_OILPRICE_BLEND_IDS = {"brent": 46, "wti": 45, "ng": 51}

OILPRICE_API_URL = os.environ.get("OIL_API_URL", "").strip()
OILPRICE_DEVICE_TOKEN = os.environ.get("OIL_DEVICE_TOKEN", "").strip()
OILPRICE_ACCESS_TOKEN = os.environ.get("OIL_ACCESS_TOKEN", "").strip()
OILPRICE_ACCESS_HEADER = (os.environ.get("OIL_ACCESS_HEADER", "Authorization") or "Authorization").strip()
_scheme_raw = os.environ.get("OIL_ACCESS_SCHEME")
OILPRICE_ACCESS_SCHEME = "Bearer" if _scheme_raw is None else _scheme_raw.strip()
if OILPRICE_ACCESS_SCHEME.lower() in ("none", "raw", "-"):
    OILPRICE_ACCESS_SCHEME = ""
OILPRICE_CHART_PERIOD = (os.environ.get("OIL_CHART_PERIOD", "2") or "2").strip()
OILPRICE_BODY_FORMAT = (os.environ.get("OIL_BODY_FORMAT", "json") or "json").strip().lower()
_OILPRICE_HEADERS = {
    "Accept": "*/*",
    "User-Agent": os.environ.get("OIL_USER_AGENT", "OilPrice/1 CFNetwork Darwin"),
}
# اگر نه هدر و نه scheme دستی تنظیم نشده باشند، در صورت 401/403 چند حالت رایج
# یک‌بار امتحان می‌شود و حالتی که جواب داد در حافظه می‌ماند (در لاگ فقط نام هدر می‌آید).
_OIL_AUTH_AUTOPROBE = (
    os.environ.get("OIL_ACCESS_HEADER") is None and _scheme_raw is None
)
_OIL_AUTH_CANDIDATES = [
    ("Authorization", "Bearer"),
    ("Authorization", ""),
    ("X-Api-Key", ""),
    ("X-Access-Token", ""),
    ("Access-Token", ""),
    ("accesstoken", ""),
    ("accessToken", ""),
    ("token", ""),
    ("X-Auth-Token", ""),
    ("Auth-Token", ""),
    ("apikey", ""),
    ("api-key", ""),
    ("body:accessToken", ""),
    ("body:access_token", ""),
    ("body:accesstoken", ""),
    ("body:token", ""),
]
_oil_auth_choice = (OILPRICE_ACCESS_HEADER, OILPRICE_ACCESS_SCHEME)
_oil_auth_probe_next = 0.0     # زمان مجاز بعدی برای امتحان دوباره (بعد از شکست همهٔ حالت‌ها)
OIL_AUTH_PROBE_COOLDOWN = 6 * 3600


_oil_cache_time = 0.0
_oil_items_cache: list = []
OIL_CACHE_TTL = 60
try:
    OIL_REFRESH_SEC = max(30, int(os.environ.get("OIL_REFRESH_SEC", "60")))
except ValueError:
    OIL_REFRESH_SEC = 60
_oil_lock = threading.Lock()
_oil_probe_lock = threading.Lock()


def _resolve_oil_path() -> Path:
    p = Path(OIL_DATA_PATH)
    if p.is_file():
        return p
    for fp in _OIL_FALLBACK_PATHS:
        if fp.is_file():
            return fp
    return p


def _load_oil_file() -> list:
    """خواندن آخرین اسنپ‌شات ذخیره‌شده (فقط برای استارت وقتی هنوز چیزی در حافظه نیست)."""
    path = _resolve_oil_path()
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = f.read()
        if not raw.strip():
            return []
        data = _json_loads(raw)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def _write_oil_file(items: list) -> bool:
    """ذخیره اتمیک آخرین اسنپ‌شات؛ فقط پشتوانهٔ استارت است، نمودار از آن ساخته نمی‌شود."""
    path = _resolve_oil_path()
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(path.suffix + ".tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(_json_dumps(items, ensure_ascii=False))
        tmp.replace(path)
        return True
    except Exception as e:
        logger.error(f"[OIL] write file failed: {e}")
        return False


OIL_HISTORY_KEEP_SEC = 30 * 3600   # تاریخچهٔ نگه‌داری‌شده در حافظه (نمودار ۲۴ ساعته + حاشیه)
OIL_MIN_SNAP_GAP_SEC = 300         # حداقل فاصلهٔ دو نقطه در نمودار (دادهٔ API حدود هر ۱ دقیقه است)
OIL_MAX_SNAPS = 300


def _oil_apply_auth(choice, body: dict):
    """(headers, body) با توکن دسترسی به‌شکل انتخاب‌شده. حالت «body:xxx» توکن را داخل بدنه می‌گذارد."""
    h = dict(_OILPRICE_HEADERS)
    b = dict(body)
    if OILPRICE_ACCESS_TOKEN:
        name, scheme = choice
        if name.startswith("body:"):
            b[name[5:]] = OILPRICE_ACCESS_TOKEN
        else:
            h[name] = f"{scheme} {OILPRICE_ACCESS_TOKEN}" if scheme else OILPRICE_ACCESS_TOKEN
    return h, b


def _oilprice_post(body: dict, choice):
    """درخواست + JSON پاسخ. برمی‌گرداند (status_code, data|None, text)."""
    hdrs, bdy = _oil_apply_auth(choice, body)
    if OILPRICE_BODY_FORMAT == "form":
        r = _FAST_HTTP.post(OILPRICE_API_URL, data=bdy, headers=hdrs, timeout=10)
    else:
        r = _FAST_HTTP.post(OILPRICE_API_URL, json=bdy, headers=hdrs, timeout=10)
    try:
        data = r.json()
    except Exception:
        data = None
    return r.status_code, data, (r.text or "")


def _oil_is_auth_fail(code: int, data) -> bool:
    """سرور اپ گاهی خطای احراز را با HTTP 200 و errorCode=401 داخل JSON برمی‌گرداند."""
    if code in (401, 403):
        return True
    if isinstance(data, dict) and str(data.get("status", "")).lower() == "error":
        try:
            return int(data.get("errorCode") or data.get("statusCode") or 0) in (401, 403)
        except (TypeError, ValueError):
            return False
    return False


def _oilprice_fetch_chart(blend_id: int, period: str | None = None, allow_empty: bool = False) -> dict:
    """یک درخواست priceChart برای یک blend؛ پاسخ خام (dict) را برمی‌گرداند.
    period: اگر داده نشود OIL_CHART_PERIOD (نمودار روزانه). allow_empty=True → پاسخ بدون prices
    (آخر هفته/بازار بسته) خطا نمی‌دهد و prices=[] برمی‌گردد تا فراخواننده سراغ تاریخچه برود."""
    global _oil_auth_choice, _oil_auth_probe_next
    if not OILPRICE_API_URL or not OILPRICE_DEVICE_TOKEN:
        raise RuntimeError("OIL_API_URL / OIL_DEVICE_TOKEN تنظیم نشده")
    body = {
        "deviceToken": OILPRICE_DEVICE_TOKEN,
        "blendId": str(blend_id),
        "dayTrend": "y",
        "period": str(period or OILPRICE_CHART_PERIOD),
        "service": "priceChart",
        "deviceType": "i",
    }
    code, data, text = _oilprice_post(body, _oil_auth_choice)
    if (_oil_is_auth_fail(code, data) and OILPRICE_ACCESS_TOKEN and _OIL_AUTH_AUTOPROBE
            and time.time() >= _oil_auth_probe_next):
        found = False
        with _oil_probe_lock:
            if _oil_is_auth_fail(code, data):  # شاید تردِ دیگری همین حالا حل کرده
                for cand in _OIL_AUTH_CANDIDATES:
                    if cand == _oil_auth_choice:
                        continue
                    c2, d2, t2 = _oilprice_post(body, cand)
                    if not _oil_is_auth_fail(c2, d2) and c2 < 400:
                        _oil_auth_choice = cand
                        logger.info(
                            f"[OIL] auth OK با «{cand[0]}»"
                            f"{' (scheme ' + cand[1] + ')' if cand[1] else ' (خام)'} — برای ثابت‌کردن در پنل: "
                            f"OIL_ACCESS_HEADER={cand[0]} OIL_ACCESS_SCHEME={cand[1] or 'none'}")
                        code, data, text = c2, d2, t2
                        found = True
                        break
                if not found:
                    _oil_auth_probe_next = time.time() + OIL_AUTH_PROBE_COOLDOWN
                    logger.error(
                        f"[OIL] هیچ‌کدام از {len(_OIL_AUTH_CANDIDATES)} حالت احراز جواب نداد — "
                        f"اسم واقعی هدر/فیلد توکن را از کپچر اپ بگیر و در OIL_ACCESS_HEADER بگذار "
                        f"(تا {OIL_AUTH_PROBE_COOLDOWN // 3600} ساعت دیگر دوباره امتحان نمی‌شود)")
            else:
                code, data, text = _oilprice_post(body, _oil_auth_choice)
    if code >= 400:
        raise RuntimeError(f"HTTP {code}: {text[:150]!r}")
    if not isinstance(data, dict) or str(data.get("status", "")).lower() != "success":
        raise ValueError(f"unexpected oilprice status: {str(data)[:120]}")
    if not isinstance(data.get("prices"), list) or not data["prices"]:
        if not allow_empty:
            raise ValueError("oilprice payload has no prices")
        data = dict(data)
        data["prices"] = []
    return data


# ------------------------------------------------------------
# تاریخچهٔ نفت/گاز برای محور زمان نمودار
# نمودار روزانهٔ API (OIL_CHART_PERIOD) فقط سشن جاری را می‌دهد؛ آخر هفته/بازار بسته خالی است و
# بعد از باز شدن بازار یا ری‌استارت فقط چند ساعت دارد. نتیجه: نمودار ۲ نقطه‌ای با ۵ دقیقه بازه و
# فقط یک برچسب «04:18» زیرش. برای همین وقتی پوشش داده کمتر از OIL_MIN_COVER_SEC است، یک دورهٔ
# بلندتر (۵ روز/۱ هفته با نقاط ۵ دقیقه‌ای) گرفته می‌شود و ۲۴ ساعت آخرِ همان داده رسم می‌شود —
# دقیقاً مثل بقیهٔ آیتم‌ها (برچسب ساعت‌ها هر ۳ ساعت).
#   OIL_HIST_PERIODS  لیست دوره‌های امتحانی به ترتیب (پیش‌فرض "3,4,5")؛ اولین دوره‌ای که نقاط ریز
#                     (حداقل ۲۴ نقطه در ۲۰+ ساعت آخر) بدهد انتخاب و در حافظه نگه داشته می‌شود.
# ------------------------------------------------------------
OIL_HIST_PERIODS = [
    p.strip() for p in (os.environ.get("OIL_HIST_PERIODS", "3,4,5") or "").split(",") if p.strip()
]
OIL_MIN_COVER_SEC = 20 * 3600       # کمتر از این پوشش در نمودار روزانه → تاریخچه لازم است
OIL_HIST_TTL = 300                  # تاریخچه هر ۵ دقیقه یک‌بار تازه می‌شود (نه با هر آپدیت ۶۰ ثانیه‌ای)
OIL_HIST_RETRY_SEC = 180            # بعد از شکست کامل، تا این مدت دوباره تلاش نمی‌شود
_oil_hist_cache: dict = {}          # blend_id -> (زمان, پاسخ)
_oil_hist_retry_at: dict = {}       # blend_id -> زمان مجاز تلاش بعدی
_oil_hist_period_ok = None          # دوره‌ای که قبلاً جواب درست داده
_oil_hist_lock = threading.Lock()


def _oil_hist_usable(data: dict) -> bool:
    """تاریخچه وقتی قابل‌استفاده است که ۲۴ ساعت آخرش حداقل ۲۴ نقطه و ≥۲۰ ساعت پوشش داشته باشد
    (دورهٔ ماهانه/سالانه نقاط روزانه می‌دهد و رد می‌شود)."""
    pts = _oilprice_points(data or {})
    if len(pts) < 24:
        return False
    last_t = pts[-1][0]
    win = [p for p in pts if (last_t - p[0]).total_seconds() <= 86400]
    return len(win) >= 24 and (last_t - win[0][0]).total_seconds() >= 20 * 3600


def _oil_fetch_history(blend_id: int):
    """پاسخ priceChart با دورهٔ بلند (کش‌شده) یا None. هرگز استثنا پرتاب نمی‌کند."""
    global _oil_hist_period_ok
    now = time.time()
    with _oil_hist_lock:
        ent = _oil_hist_cache.get(blend_id)
        if ent and now - ent[0] < OIL_HIST_TTL:
            return ent[1]
        if now < _oil_hist_retry_at.get(blend_id, 0.0):
            return ent[1] if ent else None
        periods = list(OIL_HIST_PERIODS)
        if _oil_hist_period_ok in periods:
            periods.remove(_oil_hist_period_ok)
            periods.insert(0, _oil_hist_period_ok)
    for per in periods:
        try:
            d = _oilprice_fetch_chart(blend_id, period=per, allow_empty=True)
        except Exception as e:
            logger.warning(f"[OIL] history blend={blend_id} period={per} failed: {e}")
            continue
        if _oil_hist_usable(d):
            if _oil_hist_period_ok != per:
                _pts = _oilprice_points(d)
                logger.info(f"[OIL] history period={per} انتخاب شد (blend={blend_id}, {len(_pts)} نقطه, "
                            f"{_pts[0][0]:%m-%d %H:%M} → {_pts[-1][0]:%m-%d %H:%M} UTC) — برای ثابت‌کردن: OIL_HIST_PERIODS={per}")
            with _oil_hist_lock:
                _oil_hist_period_ok = per
                _oil_hist_cache[blend_id] = (time.time(), d)
                _oil_hist_retry_at.pop(blend_id, None)
            return d
        logger.info(f"[OIL] history blend={blend_id} period={per}: نقاط کافی/ریز نیست "
                    f"({len(_oilprice_points(d))} نقطه) — دوره بعدی")
    with _oil_hist_lock:
        _oil_hist_retry_at[blend_id] = time.time() + OIL_HIST_RETRY_SEC
        ent = _oil_hist_cache.get(blend_id)
    return ent[1] if ent else None


def _oil_last_valid(data: dict) -> bool:
    """آیا خود پاسخ lastPrice و lastTime معتبر دارد (آخر هفته برنت: هر دو صفرند)."""
    try:
        return float(str(data.get("lastPrice")).replace(",", "")) > 0 and int(float(data.get("lastTime"))) > 0
    except (TypeError, ValueError):
        return False


def _oil_merge_chart(primary: dict | None, hist: dict) -> dict:
    """نقاط تاریخچه (قدیمی‌تر از اولین نقطهٔ نمودار روزانه) + نقاط روزانه؛ سربرگ (lastPrice، lastTime،
    lastClosePrice، change…) از پاسخی که lastPrice معتبر دارد (ترجیحاً روزانه)."""
    h_pts = _oilprice_points(hist)
    p_pts = _oilprice_points(primary) if primary else []
    if p_pts:
        first = p_pts[0][0]
        pts = [p for p in h_pts if p[0] < first] + p_pts
    else:
        pts = h_pts
    base = primary if (primary and p_pts and _oil_last_valid(primary)) else hist
    merged = dict(base)
    merged["prices"] = [{"price": p, "timestamp": int(t.timestamp())} for t, p in pts]
    return merged


def _oilprice_get_chart(blend_id: int) -> dict:
    """پاسخ نمودار برای ساخت آیتم: روزانه، و اگر پوشش کم/خالی بود همراه تاریخچه."""
    primary, err = None, None
    try:
        primary = _oilprice_fetch_chart(blend_id, allow_empty=True)
    except Exception as e:
        err = e
    pts = _oilprice_points(primary) if primary else []
    cover = (pts[-1][0] - pts[0][0]).total_seconds() if len(pts) >= 2 else 0.0
    if cover >= OIL_MIN_COVER_SEC:
        return primary
    hist = _oil_fetch_history(blend_id) if OIL_HIST_PERIODS else None
    if hist is not None:
        return _oil_merge_chart(primary, hist)
    if primary is None:
        raise err or RuntimeError("oilprice: no data")
    if not primary.get("prices"):
        raise ValueError("oilprice payload has no prices")
    return primary


def _oilprice_points(data: dict) -> list:
    """[(datetime UTC, price)] مرتب قدیم → جدید از فیلد prices.
    تحمل‌پذیر: timestamp ثانیه/میلی‌ثانیه، کلیدهای جایگزین، قیمت رشته‌ای با کاما."""
    pts = []
    for row in data.get("prices") or []:
        if not isinstance(row, dict):
            continue
        try:
            raw_t = next((row[k] for k in ("timestamp", "time", "ts", "t", "date") if row.get(k) not in (None, "")), None)
            raw_p = next((row[k] for k in ("price", "p", "close", "value", "lastPrice") if row.get(k) not in (None, "")), None)
            if raw_t is None or raw_p is None:
                continue
            ts = int(float(raw_t))
            if ts > 10**11:          # میلی‌ثانیه
                ts //= 1000
            t = datetime.fromtimestamp(ts, timezone.utc)
            p = float(str(raw_p).replace(",", "").strip())
        except (KeyError, ValueError, TypeError, OverflowError, OSError):
            continue
        if p > 0:
            pts.append((t, p))
    pts.sort(key=lambda x: x[0])
    return pts


def _oil_iso(t: datetime) -> str:
    return t.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _oilprice_build_item(ab: str, av: str, en: str, fa: str, data: dict, prev_ps) -> dict:
    """ساخت آیتم نفت با ps (جدید → قدیم) از پاسخ priceChart.

    - نقاط درون‌روزیِ خود API فوراً کل نمودار را می‌سازند.
    - چون API فقط سشن جاری را می‌دهد (از ۰۰:۰۰ UTC)، نقاط قدیمی‌تر همان نماد که
      قبلاً در حافظهٔ همین پروسه بوده‌اند برای پنجرهٔ ۲۴ ساعته نگه داشته می‌شوند.
    - اگر هنوز پوشش ~۲۴ ساعت نیست، قیمت بستهٔ قبلی (lastClosePrice) به‌عنوان نقطهٔ
      آغاز (seed) گذاشته می‌شود تا نمودار از قیمت بستهٔ دیروز شروع شود.
    """
    pts = _oilprice_points(data)
    if not pts:
        # نقاط درون‌روزی خالی/نامعتبر است (مثلاً آخر هفته که بازار بسته است) —
        # به‌جای شکست کامل، از lastPrice/lastTime خود پاسخ یک نقطه می‌سازیم.
        _rows = data.get("prices") or []
        logger.warning(
            f"[OIL] {ab}: نقطهٔ معتبر نیست؛ keys={list(data.keys())[:15]} "
            f"rows={len(_rows)} sample={str(_rows[:2])[:200]} "
            f"lastPrice={data.get('lastPrice')!r} lastTime={data.get('lastTime')!r} "
            f"lastClosePrice={data.get('lastClosePrice')!r} "
            f"change={data.get('change')!r} pct={data.get('changePercent')!r} "
            f"dir={data.get('changeDirection')!r}"
        )
        try:
            _lp = float(str(data.get("lastPrice")).replace(",", ""))
        except (TypeError, ValueError):
            _lp = 0.0
        if _lp <= 0:
            # بازار بسته/بدون سشن امروز: lastPrice صفر است ولی lastClosePrice (بستهٔ قبلی) و change
            # (تغییر آخرین معامله نسبت به آن) پر هستند → آخرین قیمت واقعی = بسته + تغییر
            # (مثلاً برنت: 113.17 + 3.55 = 116.72، دقیقاً همان عدد اپ oilprice).
            def _fnum(k):
                try:
                    return float(str(data.get(k)).replace(",", "").replace("%", "").strip())
                except (TypeError, ValueError):
                    return None
            _pc, _ch, _chp = _fnum("lastClosePrice"), _fnum("change"), _fnum("changePercent")
            _lp = _pc if (_pc and _pc > 0) else 0.0
            # ⚠️ وقتی lastPrice=0 است، فیلد change خود API هم خراب است (= −lastClosePrice؛ مثلاً برنت: −113.17) و فقط
            # changePercent سالم می‌ماند (لاگ: lastClose=113.17 pct=3.14 ← 113.17×1.0314 = 116.72 = عدد اپ). پس اول از «درصد» حساب می‌کنیم؛
            # «change» فقط وقتی درصد نبود و عدد متناسب بود استفاده می‌شود.
            if _lp > 0:
                _dir = str(data.get("changeDirection") or "").strip().lower()
                if _chp:
                    _p = abs(_chp) if _dir in ("up", "rise", "increase", "+") else (-abs(_chp) if _dir in ("down", "fall", "decrease", "-") else _chp)
                    if abs(_p) < 30:          # درصد منطقی روزانه؛ بیشتر از این = داده خراب
                        _lp = _lp * (1.0 + _p / 100.0)
                elif _ch:
                    if abs(_ch) < 0.3 * _lp:      # عدد نامتناسب را قبول نکن
                        _lp = _lp + _ch
        if _lp <= 0:
            raise ValueError("no valid points")
        try:
            _lt = int(float(data.get("lastTime")))
            if _lt > 10**11:
                _lt //= 1000
            if _lt <= 0:
                raise ValueError("lastTime is 0")   # بازار بسته: زمان صفر = ۱۹۷۰، نه زمان واقعی
            _lt_dt = datetime.fromtimestamp(_lt, timezone.utc)
        except (TypeError, ValueError, OverflowError, OSError):
            _lt_dt = datetime.now(timezone.utc)
        pts = [(_lt_dt, _lp)]

    nd = lambda v: round(v, 4 if v < 20 else 2)

    last_price = None
    try:
        last_price = float(data.get("lastPrice"))
    except (TypeError, ValueError):
        pass
    if not last_price or last_price <= 0:
        last_price = pts[-1][1]

    last_t = pts[-1][0]
    try:
        lt = int(data.get("lastTime"))
        last_t = datetime.fromtimestamp(lt, timezone.utc)
    except (TypeError, ValueError, OverflowError, OSError):
        pass
    if last_t >= pts[-1][0]:
        pts = [p for p in pts if p[0] < last_t] + [(last_t, last_price)]
    else:
        pts[-1] = (pts[-1][0], last_price)

    now_dt = datetime.now(timezone.utc)
    first_fresh = pts[0][0]

    entries = list(pts)
    for sn in prev_ps or []:
        if not isinstance(sn, dict) or sn.get("seed"):
            continue
        t = _parse_snap_time(sn)
        pr = _snap_price(sn)
        if t is None or pr is None:
            continue
        if t.tzinfo is None:
            t = t.replace(tzinfo=timezone.utc)
        if t >= first_fresh:
            continue  # دادهٔ تازهٔ API جایگزین آن است
        if (now_dt - t).total_seconds() > OIL_HISTORY_KEEP_SEC:
            continue
        if abs(pr - last_price) / last_price > 0.5:
            continue  # عدد نامتناسب — دور بریز
        entries.append((t, float(pr)))
    entries.sort(key=lambda x: x[0])

    # نقطهٔ آغاز از قیمت بستهٔ قبلی — فقط اگر سشن تازه شروع شده و کمتر از ۱۲ نقطه داریم،
    # و دقیقاً یک گام (۵ دقیقه) قبل از اولین نقطه (نه ساعت‌ها قبل: فاصلهٔ زیادِ بین دو نقطه
    # باعث می‌شد اسپلاین درجه‌سه از قاب پایین نمودار بیرون بزند و L نمودار هم اشتباه شود).
    seed = None
    if len(entries) < 12:
        try:
            prev_close = float(data.get("lastClosePrice"))
            if prev_close > 0 and abs(prev_close - last_price) / last_price < 0.5:
                seed = {"sp": nd(prev_close), "ts": _oil_iso(entries[0][0] - timedelta(seconds=OIL_MIN_SNAP_GAP_SEC)), "seed": 1}
        except (TypeError, ValueError):
            pass

    # کاهش تراکم: جدید → قدیم با حداقل فاصلهٔ OIL_MIN_SNAP_GAP_SEC
    ps = []
    last_kept = None
    for t, pr in reversed(entries):
        if last_kept is not None and (last_kept - t).total_seconds() < OIL_MIN_SNAP_GAP_SEC:
            continue
        ps.append({"sp": nd(pr), "ts": _oil_iso(t)})
        last_kept = t
        if len(ps) >= OIL_MAX_SNAPS:
            break
    if seed and len(ps) < OIL_MAX_SNAPS:
        ps.append(seed)

    item = {"ab": ab, "av": av, "en": en, "fa": fa, "ty": "oi", "ps": ps}
    # نوسان: مقدار خام API را فقط وقتی قبول می‌کنیم که با قیمت و هم‌دیگر سازگار باشد
    # (قبلاً diff≈قیمت با علامت منفی و درصد مثبت نمایش داده می‌شد: ▼ 113 (+3.1%))
    def _fl(k):
        try:
            return float(str(data.get(k)).replace(",", "").replace("%", "").strip())
        except (TypeError, ValueError):
            return None
    raw_chg, raw_pct, prev_close = _fl("change"), _fl("changePercent"), _fl("lastClosePrice")
    chg = chg_pct = None
    if prev_close and prev_close > 0 and abs(prev_close - last_price) / last_price < 0.5:
        chg = last_price - prev_close
        chg_pct = chg / prev_close * 100.0
    elif raw_chg is not None and raw_pct is not None:
        if abs(raw_chg) < 0.5 * last_price and raw_chg * raw_pct >= 0:
            chg, chg_pct = raw_chg, raw_pct
    if chg is None and raw_chg is not None and raw_pct is not None:
        logger.warning(f"[OIL] {ab}: change/percent خام API نامعتبر — chg={raw_chg} pct={raw_pct} "
                       f"price={last_price} prevClose={prev_close}")
    if chg is not None:
        item["chg"] = round(chg, 4)
        item["chg_pct"] = round(chg_pct, 4)
    return item


def _fetch_live_oil_widget() -> list:
    """دریافت زندهٔ همهٔ نمادها. اگر یک نماد خطا بدهد، آیتم قبلی‌اش نگه داشته می‌شود؛
    اگر هیچ نمادی تازه نشد، خطا پرتاب می‌شود."""
    prev_by_ab = {
        it.get("ab"): it
        for it in (_oil_items_cache or _load_oil_file())
        if isinstance(it, dict) and it.get("ab")
    }
    built, fresh_count = [], 0
    for ab, av, en, fa in _OIL_SYMBOLS:
        try:
            data = _oilprice_get_chart(_OILPRICE_BLEND_IDS[ab])
            prev = prev_by_ab.get(ab) or {}
            built.append(_oilprice_build_item(ab, av, en, fa, data, prev.get("ps")))
            fresh_count += 1
        except Exception as e:
            logger.warning(f"[OIL] {ab} update failed: {e}")
            if prev_by_ab.get(ab):
                built.append(prev_by_ab[ab])
    if fresh_count == 0:
        raise ValueError("oilprice: هیچ نمادی به‌روز نشد")
    return built


def _build_oil_items(force: bool = False) -> list:
    global _oil_cache_time, _oil_items_cache
    now = time.time()
    if not force and _oil_items_cache and (now - _oil_cache_time) < OIL_CACHE_TTL:
        return _oil_items_cache

    with _oil_lock:
        if not force and _oil_items_cache and (now - _oil_cache_time) < OIL_CACHE_TTL:
            return _oil_items_cache
        try:
            fresh = _fetch_live_oil_widget()
            if fresh:
                _oil_items_cache = fresh
                _oil_cache_time = time.time()
                _write_oil_file(fresh)
                return _oil_items_cache
        except Exception as e:
            logger.warning(f"[OIL] API update failed, keeping last data: {e}")
        if not _oil_items_cache:
            items = _load_oil_file()
            if items:
                _oil_items_cache = items
        return _oil_items_cache or []


def _merge_oil_items(force: bool = False):
    global _price_items, _price_by_ab, _oil_items_cache, _oil_cache_time
    if force or not _oil_items_cache:
        items = _load_oil_file()
        if items:
            _oil_items_cache = items
            _oil_cache_time = time.time()
    items = _oil_items_cache
    if not items:
        return
    with _price_lock:
        oil_abs = {it["ab"] for it in items}
        _price_items = [it for it in _price_items if it.get("ab") not in oil_abs]
        for it in items:
            _price_items.append(it)
            _price_by_ab[it["ab"]] = it


def background_update_oil():
    """بروزرسانی در پس‌زمینه — قیمت و نمودار مستقیم از API اپ oilprice.com."""
    try:
        items = _build_oil_items(force=True)
        _merge_oil_items()
        _desc = []
        for _it in items or []:
            try:
                _ps0 = (_it.get("ps") or [{}])[0]
                _t = _parse_snap_time(_ps0)
                if _t is not None and _t.tzinfo is None:
                    _t = _t.replace(tzinfo=timezone.utc)
                _age = (datetime.now(timezone.utc) - _t).total_seconds() / 60 if _t else -1
                _desc.append(f"{_it.get('ab')}={_snap_price(_ps0)} age={_age:.0f}m")
            except Exception:
                pass
        logger.info(f"[OIL] background OK ({len(items or [])} items) " + " | ".join(_desc))
    except Exception as e:
        logger.warning(f"[OIL] background failed: {e}")

