def update_prices_from_api() -> bool:
    """از API برنامهٔ چند قیمت‌ها را می‌گیرد و در فایل ارز.txt ذخیره می‌کند،
    سپس کش حافظه را با force=True تازه می‌کند."""
    global _last_api_hash, _last_api_trim
    # اگر بروزرسانی قبلی هنوز در جریان است (مثلاً API کند بود)، این نوبت رد می‌شود
    if not _api_update_lock.acquire(blocking=False):
        logger.info("[API] بروزرسانی قبلی هنوز در جریان است — این نوبت رد شد")
        return False
    try:
        response = _FAST_HTTP.get(API_URL, headers=_API_HEADERS, timeout=15)
        if response.status_code == 200:
            _new_hash = hashlib.md5(response.content).hexdigest()
            if _new_hash == _last_api_hash and _price_items:
                # داده دقیقاً مثل دفعهٔ قبل است (مثلاً بازار بسته) — نوشتن فایل،
                # پاک‌کردن کش نمودار، پیش‌گرمایش و چک تارگت/جهش لازم نیست
                return True
            data = response.json()
            # خروجی API مستقیم لیست آیتم‌هاست (همان ساختار ارز.txt)
            if not isinstance(data, list):
                logger.warning(f"[API] ساختار غیرمنتظره: {type(data)}")
                return False
            path = _resolve_price_path()
            # نوشتن اتمیک: ابتدا در فایل موقت، سپس rename — تا _load_price_file
            # وسط نوشتن فایل نیمه‌کاره نخواند.
            tmp_path = path.with_suffix(path.suffix + ".tmp")
            # بایت‌های خام پاسخ (که همین الان معتبر بودنشان پارس شد) مستقیم نوشته می‌شوند —
            # بدون سریالایز مجدد با indent=2 که هر بار حافظهٔ موقت اضافه می‌خواست
            tmp_path.write_bytes(response.content)
            tmp_path.replace(path)
            _n_items = len(data)
            del data, response
            # فقط فایل ارز را دوباره بخوان؛ نفت جاب/کش مخصوص خودش را دارد و
            # با بروزرسانی ۳۰ثانیه‌ای نباید هر بار فایلش از دیسک پارس شود
            _load_price_file(force=True)
            _merge_oil_items()
            # نمودارهای کش‌شده با اسنپ‌شات قبلی دیگر معتبر نیستند
            _clear_chart_cache()
            _last_api_hash = _new_hash
            logger.info(
                f"[API] قیمت‌ها با موفقیت از سرور چند دریافت و ذخیره شدند "
                f"({_n_items} آیتم + نفت)."
            )
            # بازگرداندن حافظهٔ آزاد به سیستم‌عامل (حداکثر هر ۵ دقیقه) تا RSS بالا نماند
            if time.time() - _last_api_trim > 300:
                _last_api_trim = time.time()
                gc.collect()
                _malloc_trim()
            return True
        else:
            logger.warning(f"[API] خطا در دریافت قیمت: کد {response.status_code}")
            return False
    except Exception as e:
        logger.error(f"[API] خطا در برقراری ارتباط با سرور: {e}")
        return False
    finally:
        _api_update_lock.release()


def get_item_by_ab(ab: str) -> dict | None:
    fetch_prices()
    return _price_by_ab.get((ab or "").lower())


def item_is_usd_unit(item: dict | None) -> bool:
    """فقط نفت (ty=oi) به دلار است؛ بقیهٔ آیتم‌های ربات به تومان‌اند."""
    if not item:
        return False
    return (item.get("ty") or "") == "oi"


def fmt_price(val) -> str:
    """فرمت عمومی — اعداد کوچک را دلاری فرض می‌کند (سازگاری عقب‌رو)."""
    try:
        f_val = float(val)
        if f_val < 1000:
            return f"{f_val:.2f} $"
        num = int(round(f_val))
        return f"{num:,}"
    except Exception:
        return str(val) if val is not None else "—"


def fmt_item_price(val, item: dict | None = None) -> str:
    """فرمت قیمت بر اساس نوع آیتم: نفت → دلار، بقیه → تومان با جداکننده هزارگان."""
    if val is None:
        return "—"
    try:
        f_val = float(val)
    except (TypeError, ValueError):
        return str(val)
    if item_is_usd_unit(item):
        return f"{f_val:.2f} $"
    # تومان — همیشه عدد صحیح با کاما (حتی اگر زیر ۱۰۰۰ باشد مثل بعضی سکه‌های خاص)
    return f"{int(round(f_val)):,}"


def item_price_unit(item: dict | None) -> str:
    return "دلار" if item_is_usd_unit(item) else "تومان"


def item_latest_snap(item: dict) -> dict | None:
    ps = item.get("ps") or []
    return ps[0] if ps else None


def item_last_update_str(item: dict) -> str:
    snap = item_latest_snap(item)
    if not snap or not snap.get("ts"):
        return _now_tehran().strftime("%H:%M")
    try:
        # ts مثل 2026-09-21T23:19:13Z (UTC) — به وقت محلی تهران (+03:30) تبدیل می‌شود
        ts = snap["ts"].replace("Z", "+00:00")
        dt = datetime.fromisoformat(ts)
        return _to_tehran(dt).strftime("%H:%M")
    except Exception:
        return _now_tehran().strftime("%H:%M")


def item_current_price(item: dict) -> float | None:
    return _snap_price(item_latest_snap(item))


def item_fluctuation(item: dict) -> tuple[float | None, float | None]:
    """
    نوسان نسبت به قدیمی‌ترین اسنپ‌شات موجود در لیست (تقریباً ۲۴ ساعت).
    اگر قیمت‌های متوالی یکسان باشند، باز هم تغییر واقعی روز مشخص می‌شود.

    برای نفت (chg/chg_pct روی خود آیتم ذخیره شده): همان نوسان منبع مستقیماً
    استفاده می‌شود به‌جای بازسازی از ps[0] در برابر ps[-1].
    """
    if item.get("chg") is not None or item.get("chg_pct") is not None:
        return item.get("chg"), item.get("chg_pct")

    ps = item.get("ps") or []
    if len(ps) < 2:
        return None, None

    curr = _snap_price(ps[0])
    prev = _snap_price(ps[-1])  # ابتدای بازه / قدیمی‌ترین

    if curr is None or prev is None or prev == 0:
        return None, None

    diff = curr - prev
    pct = (diff / prev) * 100.0
    return diff, pct


def _compact_num(ad: float) -> str:
    """عدد فشرده با K / M / B — مثلاً 4,350,000 → 4.35M ، 250,000 → 250K.
    فقط برای دکمه‌ها استفاده می‌شود تا نوسان در نیم‌عرض موبایل با «…» بریده نشود."""
    def _t(v: float, nd: int) -> str:
        s_ = f"{v:.{nd}f}"
        if "." in s_:
            s_ = s_.rstrip("0").rstrip(".")
        return s_
    if ad >= 999_500_000:
        return _t(ad / 1e9, 2) + "B"
    if ad >= 999_500:
        return _t(ad / 1e6, 2) + "M"
    if ad >= 100_000:
        return _t(ad / 1e3, 0) + "K"
    return _t(ad / 1e3, 1) + "K"


def fmt_fluctuation(diff: float | None, pct: float | None, compact: bool = False) -> str:
    """فرمت فشرده برای دکمهٔ شیشه‌ای — تا در عرض نیم‌صفحه موبایل بریده نشود.
    مثال: ▲ 35 (+0.7%)  |  ▼ 1,300 (−0.6%)  |  • 0 (0%)
    compact=True (مخصوص دکمه‌ها): اعداد ≥ 10,000 با K/M/B کوتاه می‌شوند → ▲ 4.35M (+4.1%)
    """
    if diff is None:
        return "—"
    sign = "▲" if diff > 0 else ("▼" if diff < 0 else "•")
    ad = abs(diff)
    if ad < 1:
        abs_diff = f"{ad:.2f}"
    elif ad < 100:
        # بدون صفرهای انتهایی: 35.00 → 35 ، 35.50 → 35.5
        abs_diff = f"{ad:.1f}".rstrip("0").rstrip(".")
    elif compact and ad >= 10_000:
        abs_diff = _compact_num(ad)
    else:
        abs_diff = f"{int(round(ad)):,}"
    if pct is not None:
        # درصد فشرده: یک رقم اعشار کافی است و جا می‌گیرد
        pct_s = f"{pct:+.1f}%"
        return f"{sign} {abs_diff} ({pct_s})"
    return f"{sign} {abs_diff}"


