# فضای‌نام SVG برای پارس با ElementTree
_SVG_NS = "http://www.w3.org/2000/svg"
ET.register_namespace("", _SVG_NS)


def _parse_svg_length(value: str | None) -> float | None:
    """
    یک مقدار طول SVG مثل '24', '24px', '24pt', '24mm' و... را به عدد float
    (بر حسب px، با تبدیل تقریبی واحدها) تبدیل می‌کند.
    برای واحدهای نسبی/غیرقابل‌اتکا (%، em، ex یا هر واحد ناشناخته) عمداً
    None برمی‌گرداند، چون تبدیل نادرست همین‌ها بود که باعث می‌شد فقط گوشهٔ
    بسیار کوچکی از تصویر (مثلاً ۲ ستاره از پرچم) با بزرگ‌نمایی وحشتناک دیده شود:
    وقتی width="1em" اشتباهاً برابر با «۱ واحد» در نظر گرفته می‌شد، viewBox
    ساخته‌شده «0 0 1 1» می‌شد و بقیهٔ پرچم که در مختصات ۰ تا چند صد قرار داشت
    عملاً بیرون از کادر می‌افتاد.
    """
    if not value:
        return None
    value = value.strip()
    m = re.match(r"^([0-9]*\.?[0-9]+)\s*([a-z%]*)$", value, re.IGNORECASE)
    if not m:
        return None
    num = float(m.group(1))
    unit = (m.group(2) or "").lower()
    # فقط واحدهای طول مطلق (قابل تبدیل قطعی به پیکسل) پذیرفته می‌شوند
    absolute_unit_to_px = {
        "": 1.0, "px": 1.0, "pt": 96.0 / 72.0, "pc": 16.0,
        "in": 96.0, "cm": 96.0 / 2.54, "mm": 96.0 / 25.4,
    }
    if unit not in absolute_unit_to_px:
        return None  # %، em، ex یا هر چیز نسبی/ناشناختهٔ دیگر
    return num * absolute_unit_to_px[unit]


def _ensure_svg_has_valid_frame(svg_path: "Path") -> bytes:
    """
    فایل SVG را می‌خواند و *فقط* در صورتی دست‌کاری می‌کند که به هیچ‌وجه یک
    قاب مختصاتی قابل‌اتکا (نه viewBox معتبر، نه width/height عددیِ مطلق) نداشته
    باشد؛ در آن حالت یک viewBox/width/height پیش‌فرض مربعی روی تگ ریشه می‌گذارد
    تا CairoSVG به‌جای بومِ پیش‌فرضِ عجیب یا واحدهای نسبیِ گمراه‌کننده، یک قاب
    معتبر برای رندر داشته باشد.
    اگر فایل از قبل viewBox یا width/height عددی مطلق سالم دارد، بدون هیچ
    تغییری همان بایت‌های خام برگردانده می‌شود — چون این فایل‌ها معمولاً درست
    هستند و مشکل واقعی جای دیگری (نحوهٔ crop/fit در PIL) حل می‌شود.
    در صورت خطای پارس هم، بایت‌های خام بدون تغییر برگردانده می‌شود.
    """
    raw_bytes = svg_path.read_bytes()
    try:
        root = ET.fromstring(raw_bytes)
    except ET.ParseError as e:
        logger.warning(f"[CHART] SVG parse failed for {svg_path.name}, using raw bytes: {e}")
        return raw_bytes

    view_box = root.get("viewBox")
    has_valid_viewbox = bool(view_box and len(view_box.split()) == 4)

    w = _parse_svg_length(root.get("width"))
    h = _parse_svg_length(root.get("height"))
    has_valid_size = bool(w and h and w > 0 and h > 0)

    if has_valid_viewbox or has_valid_size:
        return raw_bytes

    logger.warning(
        f"[CHART] SVG '{svg_path.name}' فاقد viewBox/اندازهٔ مطلق معتبر است؛ "
        f"قاب پیش‌فرض ۵۱۲×۵۱۲ اعمال می‌شود."
    )
    root.set("viewBox", "0 0 512 512")
    root.set("width", "512")
    root.set("height", "512")
    return ET.tostring(root, encoding="utf-8")


def _render_svg_cover(svg_path: "Path", size: int) -> "Image.Image":
    """
    SVG را با نسبت ابعاد طبیعیِ خودش (بدون هیچ تغییر شکل/کشیدگی) در وضوح بالا
    رندر می‌کند و سپس با PIL دقیقاً مثل `object-fit: cover` در CSS:
      ۱. تصویر را طوری Resize می‌کند که کوچک‌ترین بعدش برابر با size شود،
      ۲. از وسط، مربع size×size را از آن Crop می‌کند.
    این روش کاملاً مستقل از پیاده‌سازی preserveAspectRatio در خود CairoSVG عمل
    می‌کند (که منبع اصلی باگ «فقط گوشهٔ تصویر با بزرگ‌نمایی دیده می‌شود» بود)
    و تضمین می‌کند کل گرافیک به‌صورت متناسب و بدون برش ناقص در کادر مربعی جا
    بگیرد.
    """
    from PIL import Image

    fixed_bytes = _ensure_svg_has_valid_frame(svg_path)

    # رندر در وضوح بالا (۴ برابر اندازهٔ هدف) برای لبه‌های تیز پس از downscale؛
    # عمداً output_width/output_height ست نمی‌کنیم تا نسبت ابعاد طبیعی SVG
    # دست‌نخورده بماند و به شکل اشتباه به یک مربع کِش داده نشود.
    render_scale = max(1.0, (size * 4) / 100.0)
    png_bytes = cairosvg.svg2png(bytestring=fixed_bytes, scale=render_scale)
    raw = Image.open(io.BytesIO(png_bytes)).convert("RGBA")

    rw, rh = raw.size
    if rw <= 0 or rh <= 0:
        raise ValueError(f"رندر SVG ابعاد نامعتبر داشت: {rw}x{rh}")

    # گام ۱: Resize با حفظ نسبت ابعاد طوری که کوچک‌ترین بعد دقیقاً size شود
    cover_scale = size / min(rw, rh)
    new_w = max(size, round(rw * cover_scale))
    new_h = max(size, round(rh * cover_scale))
    resized = raw.resize((new_w, new_h), Image.Resampling.LANCZOS)

    # گام ۲: کراپ مرکزی به مربع size×size (بعد بزرگ‌تر از وسط برش می‌خورد)
    left = (new_w - size) // 2
    top = (new_h - size) // 2
    return resized.crop((left, top, left + size, top + size))


def _initials_for(item: dict) -> str:
    ab = (item.get("ab") or "").strip()
    return (ab[:2] or "?").upper()


_icon_url_fail: dict[str, float] = {}   # ab -> زمان آخرین شکست دانلود (برای جلوگیری از تلاش مکرر)

# ریپوی آیکون‌های SVG (فایل‌ها به‌صورت {ab}.svg در ریشه). با env به اسم ICON_REPO_BASE_URL عوض می‌شود؛
# خالی‌کردنش (مقدار "-") این منبع را غیرفعال می‌کند.
_ICON_REPO_DEFAULT = "https://cdn.jsdelivr.net/gh/feizimohsen555-bit/iconn@main"
ICON_REPO_BASE_URL = (os.environ.get("ICON_REPO_BASE_URL") or _ICON_REPO_DEFAULT).strip().rstrip("/")
if ICON_REPO_BASE_URL == "-":
    ICON_REPO_BASE_URL = ""


def _wsrv_url(src_url: str, size: int, fmt: str = "png") -> str:
    """تبدیل SVG به PNG مربعی با سرویس wsrv.nl (بدون نیاز به cairosvg روی سرور)."""
    from urllib.parse import quote as _q
    return f"https://wsrv.nl/?url={_q(src_url, safe='')}&w={size}&h={size}&fit=cover&output={fmt}"


def _http_get_bytes(url: str, max_bytes: int = 2_000_000) -> bytes:
    r = _FAST_HTTP.get(url, timeout=(3, 8), headers={"User-Agent": "Mozilla/5.0"})
    if r.status_code != 200 or not r.content or len(r.content) > max_bytes:
        raise RuntimeError(f"HTTP {r.status_code}, {len(r.content or b'')} bytes")
    return r.content


def _fetch_icon_from_url(ab: str, size: int):
    """
    آیکون از اینترنت، به ترتیب:
      ۱) {ICON_REPO_BASE_URL}/{ab}.svg با cairosvg (اگر نصب باشد)
      ۲) همان SVG تبدیل‌شده به PNG با wsrv.nl
    در هر خطایی None (۱۰ دقیقه دوباره تلاش نمی‌کند).
    """
    if not ab or not re.fullmatch(r"[A-Za-z0-9_.\-]+", ab):
        return None
    now = time.time()
    with _icon_cache_lock:
        failed_at = _icon_url_fail.get(ab)
    if failed_at and now - failed_at < 600:
        return None

    from PIL import Image, ImageOps
    errors = []

    def _fit(raw: bytes):
        img = Image.open(io.BytesIO(raw)).convert("RGBA")
        return ImageOps.fit(img, (size, size), Image.Resampling.LANCZOS)

    if ICON_REPO_BASE_URL:
        svg_url = f"{ICON_REPO_BASE_URL}/{ab}.svg"
        if _HAS_CAIROSVG:
            try:
                import tempfile
                raw = _http_get_bytes(svg_url)
                with tempfile.NamedTemporaryFile(suffix=".svg") as tf:
                    tf.write(raw)
                    tf.flush()
                    return _render_svg_cover(Path(tf.name), size)
            except Exception as e:
                errors.append(f"svg: {e}")
        try:
            return _fit(_http_get_bytes(_wsrv_url(svg_url, size, "png")))
        except Exception as e:
            errors.append(f"wsrv: {e}")

    with _icon_cache_lock:
        _icon_url_fail[ab] = now
    logger.warning(f"[CHART] icon url fetch failed for {ab}: {' | '.join(errors) or 'no source configured'}")
    return None


_icon_remote_img: dict[str, "Image.Image"] = {}   # "ab:size" -> آیکون دانلودشده (مربع RGBA، قبل از ماسک دایره)
_icon_inflight: set = set()


def _icon_remote_prefetch(ab: str, size: int):
    """دانلود آیکون در ترد پس‌زمینه — مسیر ساخت کارت هرگز منتظر شبکه نمی‌ماند."""
    key = f"{ab}:{size}"
    with _icon_cache_lock:
        if key in _icon_remote_img or key in _icon_inflight:
            return
        _icon_inflight.add(key)

    def _work():
        try:
            img = _fetch_icon_from_url(ab, size)
            if img is not None:
                with _icon_cache_lock:
                    _icon_remote_img[key] = img
        except Exception as e:
            logger.warning(f"[CHART] icon prefetch failed for {ab}: {e}")
        finally:
            with _icon_cache_lock:
                _icon_inflight.discard(key)

    threading.Thread(target=_work, name=f"icon-{ab}", daemon=True).start()


def warm_remote_icons(size: int = 240):
    """هنگام استارت: آیکون همهٔ آیتم‌ها را آهسته و پشت‌سرهم بگیر تا اولین نمودار کاربر بدون تأخیر ساخته شود."""
    if not ICON_REPO_BASE_URL:
        return
    try:
        items = list(fetch_prices() or [])
    except Exception as e:
        logger.warning(f"[CHART] warm icons: price list unavailable: {e}")
        return
    n = 0
    for it in items:
        ab = (it.get("ab") or "").strip().lower()
        if not ab:
            continue
        key = f"{ab}:{size}"
        with _icon_cache_lock:
            have = key in _icon_remote_img
        if have:
            continue
        try:
            img = _fetch_icon_from_url(ab, size)
            if img is not None:
                with _icon_cache_lock:
                    _icon_remote_img[key] = img
                n += 1
        except Exception:
            pass
        time.sleep(0.25)
    logger.info(f"[CHART] warm icons done: {n}/{len(items)} loaded")


# ------------------------------------------------------------
# آیکون‌های داخلی نفت و گاز (PNG ۱۶۰×۱۶۰ شفاف؛ همان طرح brent.svg / wti.svg / ng.svg در ریپوی iconn).
# چرا؟ آیکون بقیهٔ آیتم‌ها از پوشهٔ ICONS_DIR یا پیش‌دانلود استارت می‌آید؛ نفت و گاز نه (در فهرست
