def _builtin_icon(ab: str, size: int):
    """آیکون داخلی (مربع RGBA، قبل از ماسک دایره) یا None اگر برای این آیتم داخلی نداریم."""
    b64 = _BUILTIN_ICON_PNG_B64.get((ab or "").lower())
    if not b64:
        return None
    try:
        import base64
        from PIL import Image, ImageOps
        img = Image.open(io.BytesIO(base64.b64decode(b64))).convert("RGBA")
        return ImageOps.fit(img, (size, size), Image.Resampling.LANCZOS)
    except Exception as e:
        logger.warning(f"[CHART] builtin icon failed for {ab}: {e}")
        return None


def _render_icon_circle(item: dict, size: int = 240) -> "Image.Image":
    """
    آیکون دایره‌ای پرچم/کوین برای هدر — ابتدا SVG واقعی از پوشهٔ ICONS_DIR با
    نسبت ابعاد طبیعی‌اش رندر شده و سپس با روش cover (مشابه CSS
    object-fit: cover) به مربع size×size کراپ می‌شود (نگاه کنید به
    _render_svg_cover)؛ اگر cairosvg نصب نبود یا فایل SVG موجود نبود یا رندر
    با خطا مواجه شد، به یک بج دایره‌ای با حروف اول کد ارز سقوط می‌کند (بدون
    کرش در هیچ حالتی).
    """
    from PIL import Image, ImageDraw, ImageChops

    ab = (item.get("ab") or "item").lower()
    cache_key = f"{ab}:{size}"
    with _icon_cache_lock:
        cached = _icon_cache.get(cache_key)
    if cached is not None:
        return cached.copy()

    icon = None
    svg_path = ICONS_DIR / f"{ab}.svg"
    if _HAS_CAIROSVG and svg_path.is_file():
        try:
            icon = _render_svg_cover(svg_path, size)
        except Exception as e:
            logger.warning(f"[CHART] svg icon render failed for {ab}: {e}")
            icon = None

    if icon is None and ICON_REPO_BASE_URL:
        with _icon_cache_lock:
            _remote = _icon_remote_img.get(f"{ab}:{size}")
        if _remote is not None:
            icon = _remote.copy()
        else:
            _icon_remote_prefetch(ab, size)   # بدون انتظار؛ این بار بج حروف اول، دفعهٔ بعد آیکون واقعی

    _is_fallback = False
    if icon is None:
        # نفت/گاز: آیکون داخلی (بدون شبکه). کش نمی‌شود تا اگر آیکون ریپو آماده شد جایگزینش شود.
        icon = _builtin_icon(ab, size)
        if icon is not None:
            _is_fallback = True
    if icon is None:
        _is_fallback = True
        # سقوط ایمن: دایرهٔ رنگی با حروف اول کد ارز — هرگز باعث کرش نمی‌شود
        icon = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(icon)
        draw.ellipse((0, 0, size - 1, size - 1), fill=(52, 52, 58, 255))
        font = _load_font(_FONT_BOLD_PATH, int(size * 0.36))
        text = _initials_for(item)
        bb = draw.textbbox((0, 0), text, font=font)
        tw, th = bb[2] - bb[0], bb[3] - bb[1]
        draw.text(
            ((size - tw) / 2 - bb[0], (size - th) / 2 - bb[1]),
            text, font=font, fill=(230, 230, 235, 255),
        )

    # برش دایره‌ای اجباری روی خروجی نهایی — حتی وقتی آیکون از SVG واقعی می‌آید،
    # چون خیلی از فایل‌های SVG دقیقاً مربع/دایره‌ی کامل نیستند و بدون این ماسک
    # ممکن است لبه‌شان از کادر گرد بیرون بزند (دقیقاً همان چیزی که «از کادر خارج»
    # به نظر می‌رسید). این کار روی هر دو حالت (SVG و بج حروف اول) یکسان اجرا می‌شود.
    if icon.size != (size, size):
        icon = icon.resize((size, size), Image.Resampling.LANCZOS)
    circle_mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(circle_mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    icon.putalpha(ImageChops.darker(icon.split()[-1], circle_mask))

    # اگر آدرس آیکون تنظیم است، بج حروف اول را کش نمی‌کنیم تا بعد از رفع خطای شبکه آیکون واقعی بیاید
    if not (_is_fallback and ICON_REPO_BASE_URL):
        with _icon_cache_lock:
            _icon_cache[cache_key] = icon.copy()
    return icon


def _parse_snap_time(snap: dict):
    """زمان یک اسنپ‌شات را از فیلد ts (مثل 2026-09-21T23:19:13Z) می‌خواند."""
    if not snap:
        return None
    ts = snap.get("ts")
    if not ts:
        return None
    try:
        return datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
    except Exception:
        return None


def _extract_price_series(item: dict):
    """
    برمی‌گرداند (times, prices) به ترتیب قدیم → جدید. اسنپ‌شات‌های ps در جدول از
    جدید به قدیم ذخیره می‌شوند، پس برای رسم باید معکوس شوند.
    """
    ps = item.get("ps") or []
    times, prices = [], []
    for snap in reversed(ps):
        p = _snap_price(snap)
        if p is None:
            continue
        prices.append(p)
        times.append(_parse_snap_time(snap))
    return times, prices


def _catmull_rom_smooth(x, y, points_per_segment: int = 24):
    """
    منحنی نرم Catmull-Rom که دقیقاً از همهٔ نقاط داده واقعی عبور می‌کند — بر خلاف
    میانگین متحرک، هیچ قله/درهٔ واقعی قیمت را صاف/گم نمی‌کند؛ فقط به‌جای خط شکسته،
    بین نقاط منحنی نرم رسم می‌شود (دقیقاً همان جلوه‌ای که در اپ‌های مالی می‌بینیم).
    """
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    n = len(x)
    if n < 3:
        return x, y

    xs = np.concatenate(([x[0]], x, [x[-1]]))
    ys = np.concatenate(([y[0]], y, [y[-1]]))

    out_x = [x[0]]
    out_y = [y[0]]
    for i in range(1, n):
        p0x, p1x, p2x, p3x = xs[i - 1], xs[i], xs[i + 1], xs[i + 2]
        p0y, p1y, p2y, p3y = ys[i - 1], ys[i], ys[i + 1], ys[i + 2]
        t = np.linspace(0, 1, points_per_segment, endpoint=True)[1:]
        t2 = t * t
        t3 = t2 * t
        seg_x = 0.5 * ((2 * p1x) + (-p0x + p2x) * t +
                        (2 * p0x - 5 * p1x + 4 * p2x - p3x) * t2 +
                        (-p0x + 3 * p1x - 3 * p2x + p3x) * t3)
        seg_y = 0.5 * ((2 * p1y) + (-p0y + p2y) * t +
                        (2 * p0y - 5 * p1y + 4 * p2y - p3y) * t2 +
                        (-p0y + 3 * p1y - 3 * p2y + p3y) * t3)
        out_x.extend(seg_x.tolist())
        out_y.extend(seg_y.tolist())
    return np.array(out_x), np.array(out_y)


def _chart_x_ticks(t_start_ts: float, t_end_ts: float, x_margin: float, width_px: int,
                   fontsize: float = 15, dpi: int = CHART_DPI) -> list:
    """برچسب‌های محور X → لیست (timestamp, متن).

    • اگر بازهٔ داده به‌اندازهٔ کافی بلند باشد (≥۳ تیک روی شبکهٔ ۳ساعتهٔ معمول): همان منطق قبلی
      (۱۲ساعته، فقط ساعت: 10 01 04 07 …).
    • اگر بازه کوتاه باشد (مثلاً نفت/گاز بعد از باز شدن بازار یا ری‌استارت که فقط چند دقیقه/ساعت
      داده داریم): قبلاً هیچ تیکی نمی‌ماند و فقط دو برچسب «ساعت شروع/پایان» دقیقاً روی لبهٔ تصویر
      گذاشته می‌شد و نصفه بریده می‌شد. حالا گام مناسب (۵ تا ۱۸۰ دقیقه، روی ساعت رُند) انتخاب می‌شود،
      حداکثر ۶ برچسب و همیشه با فاصلهٔ امن از لبه‌ها؛ برای گام‌های زیر ۱ ساعت به‌صورت HH:MM.
    """
    t_start = _to_tehran(datetime.fromtimestamp(t_start_ts, tz=timezone.utc))
    t_end = _to_tehran(datetime.fromtimestamp(t_end_ts, tz=timezone.utc))

    def _lbl(tt, with_minutes: bool) -> str:
        h12 = tt.hour % 12 or 12
        return f"{h12:02d}:{tt.minute:02d}" if with_minutes else f"{h12:02d}"

    # ۱) شبکهٔ ۳ساعتهٔ معمول (بدون تغییر)
    last_tick = (t_end - timedelta(hours=2)).replace(minute=0, second=0, microsecond=0)
    ticks = [last_tick - timedelta(hours=3 * i) for i in range(6, -1, -1)]
    ticks = [tt for tt in ticks if tt.timestamp() >= t_start_ts]
    if len(ticks) >= 3:
        return [(tt.timestamp(), _lbl(tt, False)) for tt in ticks]

    # ۲) بازهٔ کوتاه: گام تطبیقی روی ساعت رُند
    span = max(t_end_ts - t_start_ts, 1.0)
    px_per_sec = width_px / (span + 2 * x_margin)
    em_px = fontsize * dpi / 72.0

    def _half_w(with_minutes: bool) -> float:
        # عرض تقریبی ارقام DejaVu Sans ≈ ۰٫۶۳۶ em و «:» ≈ ۰٫۳۳۷ em؛ + حاشیهٔ امن ۱۴px
        w = (4 * 0.636 + 0.337 if with_minutes else 2 * 0.636) * em_px
        return w / 2 + 14

    day0 = t_start.replace(hour=0, minute=0, second=0, microsecond=0).timestamp()
    for step_min in (5, 10, 15, 20, 30, 60, 120, 180):
        with_min = step_min < 60
        margin_sec = _half_w(with_min) / px_per_sec
        lo, hi = t_start_ts + margin_sec, t_end_ts - margin_sec
        if hi <= lo:
            continue
        step = step_min * 60
        k0 = int(np.ceil((lo - day0) / step))
        k1 = int(np.floor((hi - day0) / step))
        if 2 <= (k1 - k0 + 1) <= 6:
            out = []
            for k in range(k0, k1 + 1):
                tt = _to_tehran(datetime.fromtimestamp(day0 + k * step, tz=timezone.utc))
                out.append((tt.timestamp(), _lbl(tt, with_min)))
            return out

    # بازهٔ بسیار کوتاه (چند دقیقه): فقط یک برچسب وسط
    mid = (t_start_ts + t_end_ts) / 2.0
    return [(mid, _lbl(_to_tehran(datetime.fromtimestamp(mid, tz=timezone.utc)), True))]


# ------------------------------------------------------------
# ظاهر کارت (نسخهٔ جدید): پس‌زمینهٔ گرادیانتی با درخشش رنگی، آیکون با حلقه و گلو،
# بج تغییر قیمت، چیپ‌های H/L، منحنی با گلو + نقطهٔ پایانی. ابعاد خروجی همان قبلی است.
# ------------------------------------------------------------
CHART_BRAND = (os.environ.get("CHART_BRAND", "@nokhudbot") or "").strip()   # خالی = بدون برند


def _hex_rgb(c) -> tuple:
    from PIL import ImageColor
    return tuple(ImageColor.getrgb(c)[:3])


def _mix_rgb(c1, c2, t: float) -> tuple:
    a, b = _hex_rgb(c1), _hex_rgb(c2)
    return tuple(int(round(a[i] + (b[i] - a[i]) * t)) for i in range(3))


def _make_card_background(w: int, h: int, theme: str, accent: str):
    """گرادیانت عمودی ملایم + درخشش رنگی (سبز/قرمز) گوشهٔ بالا-راست. در ۱/۴ اندازه محاسبه
    و بزرگ می‌شود تا RAM مصرف نشود (گرادیانت نرم است و تفاوتی دیده نمی‌شود)."""
    from PIL import Image
    th = _chart_theme(theme)
    is_dark = th is CHART_DARK
    sw, sh = max(w // 4, 8), max(h // 4, 8)
    if is_dark:
        top = np.array(_mix_rgb(th["bg"], "#FFFFFF", 0.07), dtype=np.float32)
        bot = np.array(_mix_rgb(th["bg"], "#000000", 0.30), dtype=np.float32)
    else:
        top = np.array((255, 255, 255), dtype=np.float32)
        bot = np.array(_mix_rgb(th["bg"], "#E3E3E8", 0.55), dtype=np.float32)
    yy = np.linspace(0.0, 1.0, sh, dtype=np.float32)[:, None, None]
    arr = np.repeat(top * (1 - yy) + bot * yy, sw, axis=1)            # (sh, sw, 3)
    ys = np.linspace(0.0, 1.0, sh, dtype=np.float32)[:, None] * (h / float(w))
    xs = np.linspace(0.0, 1.0, sw, dtype=np.float32)[None, :]
    d = np.sqrt((xs - 0.93) ** 2 + ys ** 2) / 0.80
    g = (np.clip(1.0 - d, 0.0, 1.0) ** 2) * (0.22 if is_dark else 0.14)
    acc = np.array(_hex_rgb(accent), dtype=np.float32)
    arr = arr * (1 - g[..., None]) + acc * g[..., None]
    small = Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8), "RGB")
    return small.resize((w, h), Image.Resampling.BICUBIC).convert("RGBA")


def _draw_chart_panel(p_unique, ts_unique, dt_unique, x, y, line_color: str, theme: str = "dark"):
    """
    پنل نمودار (منحنی با گلو + گرادیانت زیرش + گرید خط‌چین + نقطهٔ پایانی + برچسب ساعت‌ها)
    با matplotlib و زمینهٔ شفاف؛ پس‌زمینهٔ گرادیانتی کارت در generate_chart_image زیرش قرار می‌گیرد.
    """
    from PIL import Image

    th = _chart_theme(theme)
    bg = th["bg"]
    grid_c = tuple(v / 255.0 for v in _mix_rgb(bg, th["text"], 0.11))
    label_c = th["label"]

    fig = None
    try:
        fig, ax = plt.subplots(
            figsize=(CHART_IMG_WIDTH / CHART_DPI, CHART_IMG_HEIGHT / CHART_DPI),
            dpi=CHART_DPI,
        )
        fig.patch.set_alpha(0.0)
        ax.patch.set_alpha(0.0)

        y_min, y_max = float(p_unique.min()), float(p_unique.max())
        span = (y_max - y_min) if y_max > y_min else max(abs(y_max) * 0.02, 1.0)
        pad = span * 0.15
        fill_baseline = y_min - pad
        label_pad = span * 0.55
        ylim_bottom = fill_baseline - label_pad
        ylim_top = y_max + pad * 1.3

        # گرید خط‌چین ظریف
        for gy in np.linspace(y_min, y_max, 4):
            ax.axhline(gy, color=grid_c, linewidth=1.0, linestyle=(0, (5, 7)), zorder=1)

        # گرادیانت زیر منحنی (بالا پررنگ، پایین کاملاً محو)
        verts = np.column_stack([
            np.concatenate([[x[0]], x, [x[-1]]]),
            np.concatenate([[fill_baseline], y, [fill_baseline]]),
        ])
        clip_poly = Polygon(verts, closed=True, facecolor="none", edgecolor="none")
        ax.add_patch(clip_poly)

        rgb = to_rgb(line_color)
        grad = np.zeros((256, 1, 4))
        grad[:, 0, 0] = rgb[0]
        grad[:, 0, 1] = rgb[1]
        grad[:, 0, 2] = rgb[2]
        grad[:, 0, 3] = 0.46 * np.linspace(0.0, 1.0, 256) ** 1.35
        im = ax.imshow(
            grad, extent=[x[0], x[-1], fill_baseline, ylim_top],
            origin="lower", aspect="auto", zorder=2,
        )
        im.set_clip_path(clip_poly)

        # خط قیمت فعلی (خط‌چین رنگی تا نقطهٔ پایانی) و راهنمای عمودی
        ex, ey = float(x[-1]), float(y[-1])
        ax.plot([x[0], ex], [ey, ey], color=line_color, alpha=0.35, linewidth=1.2,
                linestyle=(0, (4, 6)), zorder=2)
        ax.plot([ex, ex], [fill_baseline, ey], color=line_color, alpha=0.28, linewidth=1.2,
                linestyle=(0, (3, 5)), zorder=2)

        # منحنی با هالهٔ نورانی
        for lw, al in ((12, 0.045), (7.5, 0.09)):
            ax.plot(x, y, color=line_color, linewidth=lw, alpha=al,
                    solid_capstyle="round", solid_joinstyle="round", zorder=3)
        ax.plot(x, y, color=line_color, linewidth=3.3, solid_capstyle="round",
                solid_joinstyle="round", antialiased=True, zorder=4)

        # نقطهٔ پایانی (قیمت فعلی) با هالهٔ چندلایه
        core_c = tuple(v / 255.0 for v in (_mix_rgb(bg, "#000000", 0.2) if th is CHART_DARK else (255, 255, 255)))
        for s_, a_ in ((520, 0.13), (190, 0.30)):
            ax.scatter([ex], [ey], s=s_, color=line_color, alpha=a_, linewidths=0,
                       zorder=5, clip_on=False)
        ax.scatter([ex], [ey], s=72, color=line_color, linewidths=0, zorder=6, clip_on=False)
        ax.scatter([ex], [ey], s=20, color=core_c, linewidths=0, zorder=7, clip_on=False)

        # حاشیهٔ چپ/راست: جا برای هالهٔ نقطهٔ پایانی که بریده نشود
        x_span = ts_unique[-1] - ts_unique[0]
        x_margin = max(x_span * 0.03, 30.0)
        ax.set_xlim(ts_unique[0] - x_margin, ts_unique[-1] + x_margin)
        ax.set_ylim(ylim_bottom, ylim_top)

        t_start_ts = float(ts_unique[0])
        t_end_ts = float(ts_unique[-1])
        tick_list = _chart_x_ticks(t_start_ts, t_end_ts, x_margin, CHART_IMG_WIDTH)

        label_y = fill_baseline - label_pad * 0.5
        for x_pos, lbl in tick_list:
            ax.text(
                x_pos, label_y, lbl,
                color=label_c, fontsize=15,
                ha="center", va="center", family="DejaVu Sans", zorder=4,
            )

        for spine in ax.spines.values():
            spine.set_visible(False)
        ax.set_xticks([])
        ax.set_yticks([])
        ax.margins(0)
        plt.subplots_adjust(left=0.0, right=1.0, top=1.0, bottom=0.0)

        buf = io.BytesIO()
        plt.savefig(
            buf, format="png",
            transparent=True,
            dpi=CHART_DPI,
            bbox_inches=None,
            pad_inches=0,
        )
        buf.seek(0)
        return Image.open(buf).convert("RGBA")
    finally:
        if fig is not None:
            fig.clf()
            plt.close(fig)
        plt.close('all')


def _draw_header_panel(item: dict, price: float | None, diff: float | None,
                        pct: float | None, hi: float | None, lo: float | None,
                        theme: str = "dark", bg_top=None) -> "Image.Image":
    """
    هدر کارت: آیکون با حلقه و گلوی رنگی، نام + چیپ کد، چیپ 24H و برند، بج تغییر قیمت
    (مثلث + مقدار + درصد)، قیمت بزرگ و چیپ‌های HIGH/LOW. با ۲× سوپرسمپل رسم و کوچک می‌شود
    تا لبه‌ها صاف باشند. bg_top = برش بالای پس‌زمینهٔ گرادیانتی (اختیاری).
    """
    from PIL import Image, ImageDraw, ImageFilter

    S = 2
    th = _chart_theme(theme)
    is_dark = th is CHART_DARK
    is_up = (diff or 0) >= 0
    accent = CHART_UP_COLOR if is_up else CHART_DOWN_COLOR
    acc_rgb = _hex_rgb(accent)
    txt_rgb = _hex_rgb(th["text"])
    chip_a = 30 if is_dark else 22          # شفافیت چیپ‌های خنثی
    badge_a = 48 if is_dark else 36         # شفافیت بج تغییر قیمت

    def s(v):
        return int(round(v * S))

    W, H = s(HEADER_WIDTH), s(HEADER_HEIGHT)
    if bg_top is None:
        bg_top = _make_card_background(
            HEADER_WIDTH, HEADER_HEIGHT + CHART_IMG_HEIGHT, theme, accent
        ).crop((0, 0, HEADER_WIDTH, HEADER_HEIGHT))
    base = bg_top.convert("RGBA").resize((W, H), Image.Resampling.BICUBIC)

    f_name = _load_font(_FONT_BOLD_PATH, s(48))
    f_code = _load_font(_FONT_REGULAR_PATH, s(27))
    f_chip = _load_font(_FONT_BOLD_PATH, s(25))
    f_brand = _load_font(_FONT_REGULAR_PATH, s(26))
    f_diff = _load_font(_FONT_BOLD_PATH, s(38))
    f_pct = _load_font(_FONT_BOLD_PATH, s(30))
    f_price = _load_font(_FONT_BOLD_PATH, s(104))
    f_hl_lab = _load_font(_FONT_REGULAR_PATH, s(22))
    f_hl_val = _load_font(_FONT_BOLD_PATH, s(30))

    meas = ImageDraw.Draw(Image.new("L", (1, 1)))

    def tw(text, font):
        return meas.textlength(text, font=font) / S

    shapes = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    sd = ImageDraw.Draw(shapes)
    texts = []      # (x, cy, text, font, fill, anchor)
    tris = []       # (points در مختصات ۱×, رنگ)

    def pill(x0, y0, x1, y1, rgb, alpha):
        sd.rounded_rectangle((s(x0), s(y0), s(x1), s(y1)),
                             radius=s((y1 - y0) / 2.0), fill=tuple(rgb) + (alpha,))

    def tri(x0, cy, w, h, up, color):
        if up:
            pts = [(x0 + w / 2.0, cy - h / 2.0), (x0, cy + h / 2.0), (x0 + w, cy + h / 2.0)]
        else:
            pts = [(x0, cy - h / 2.0), (x0 + w, cy - h / 2.0), (x0 + w / 2.0, cy + h / 2.0)]
        tris.append((pts, color))

    pad_x, top_y, icon_size = 56, 52, 120
    right_x = HEADER_WIDTH - pad_x

    # --- آیکون: گلو + حلقه ---
    cx, cy_i = pad_x + icon_size / 2.0, top_y + icon_size / 2.0
    gr = icon_size / 2.0 + 30
    patch = Image.new("RGBA", (s(gr * 2), s(gr * 2)), tuple(acc_rgb) + (0,))
    ImageDraw.Draw(patch).ellipse((s(30), s(30), s(gr * 2 - 30), s(gr * 2 - 30)),
                                  fill=tuple(acc_rgb) + (120,))
    patch = patch.filter(ImageFilter.GaussianBlur(s(16)))
    base.alpha_composite(patch, (s(cx - gr), s(cy_i - gr)))
    sd.ellipse((s(pad_x - 7), s(top_y - 7), s(pad_x + icon_size + 7), s(top_y + icon_size + 7)),
               outline=tuple(acc_rgb) + (255,), width=s(3))

    # --- نام + چیپ کد ---
    text_x = pad_x + icon_size + 32
    name_text = item.get("en") or item.get("fa") or (item.get("ab") or "").upper()
    code_text = (item.get("ab") or "").upper()
    texts.append((text_x, top_y + 36, name_text, f_name, th["text"], "lm"))
    if code_text:
        cw = tw(code_text, f_code) + 36
        pill(text_x, top_y + 62, text_x + cw, top_y + 106, txt_rgb, chip_a)
        texts.append((text_x + 18, top_y + 84, code_text, f_code, th["subtle"], "lm"))

    # --- بالا-راست: چیپ 24H + برند ---
    lab = "24H"
    lw_ = tw(lab, f_chip) + 36
    pill(right_x - lw_, top_y + 4, right_x, top_y + 48, txt_rgb, chip_a)
    texts.append((right_x - lw_ + 18, top_y + 26, lab, f_chip, th["subtle"], "lm"))
    if CHART_BRAND:
        texts.append((right_x, top_y + 78, CHART_BRAND, f_brand, th["subtle"], "rm"))

    # --- بج تغییر قیمت ---
    b_y0, b_h = 202, 64
    b_cy = b_y0 + b_h / 2.0
    if diff is None:
        diff_s = "—"
    else:
        ad = abs(diff)
        if ad < 1:
            diff_s = f"{ad:.2f}"
        elif ad < 100:
            diff_s = f"{ad:.1f}".rstrip("0").rstrip(".")
        else:
            diff_s = f"{int(round(ad)):,}"
    pct_s = f"{abs(pct):.2f}%" if (pct is not None and diff is not None) else ""
    pad_b = 26
    cur = pad_x + pad_b
    b_w = pad_b * 2 + (24 + 14 if diff is not None else 0) + tw(diff_s, f_diff)
    if pct_s:
        b_w += 22 + tw(pct_s, f_pct)
    pill(pad_x, b_y0, pad_x + b_w, b_y0 + b_h, acc_rgb, badge_a)
    if diff is not None:
        tri(cur, b_cy, 24, 20, is_up, accent)
        cur += 24 + 14
    texts.append((cur, b_cy, diff_s, f_diff, accent, "lm"))
    cur += tw(diff_s, f_diff)
    if pct_s:
        texts.append((cur + 22, b_cy + 1, pct_s, f_pct, accent, "lm"))

    # --- قیمت بزرگ ---
    price_str = fmt_item_price(price, item) if price is not None else "—"
    texts.append((pad_x, 340, price_str, f_price, th["text"], "lm"))

    # --- چیپ‌های HIGH / LOW ---
    hl_y0, hl_h = 404, 54
    hl_cy = hl_y0 + hl_h / 2.0
    hx = pad_x
    for label, val, is_hi in (("HIGH", hi, True), ("LOW", lo, False)):
        vs = fmt_item_price(val, item) if val is not None else "—"
        w_ = 22 + 14 + 10 + tw(label, f_hl_lab) + 14 + tw(vs, f_hl_val) + 24
        pill(hx, hl_y0, hx + w_, hl_y0 + hl_h, txt_rgb, chip_a)
        c_ = hx + 22
        tri(c_, hl_cy, 14, 12, is_hi, CHART_UP_COLOR if is_hi else CHART_DOWN_COLOR)
        c_ += 14 + 10
        texts.append((c_, hl_cy, label, f_hl_lab, th["subtle"], "lm"))
        c_ += tw(label, f_hl_lab) + 14
        texts.append((c_, hl_cy, vs, f_hl_val, th["text"], "lm"))
        hx += w_ + 18

    # --- ترکیب: شکل‌های نیمه‌شفاف → آیکون → متن و مثلث‌ها ---
    img = Image.alpha_composite(base, shapes)
    icon = _render_icon_circle(item, size=s(icon_size))
    img.paste(icon, (s(pad_x), s(top_y)), icon)

    draw = ImageDraw.Draw(img)
    for pts, color in tris:
        draw.polygon([(s(px), s(py)) for px, py in pts], fill=color)
    for tx, tcy, text, font, fill, anchor in texts:
        try:
            draw.text((s(tx), s(tcy)), text, font=font, fill=fill, anchor=anchor)
        except Exception:
            draw.text((s(tx), s(tcy) - s(14)), text, font=font, fill=fill)

    return img.resize((HEADER_WIDTH, HEADER_HEIGHT), Image.Resampling.LANCZOS)


_chart_render_lock = threading.Lock()  # رابط pyplot Thread-safe نیست؛ رندر همزمان دو نمودار در دو ترد را جدی می‌گیریم


def generate_chart_image(item: dict, theme: str = "dark"):
    """
    تصویر کامل مطابق طرح مرجع می‌سازد: هدر بالا (آیکون، نام/کد، ضربدر، فلش+تغییر،
    قیمت بزرگ، H/L) روی زمینهٔ تم انتخابی، و پنل نمودار (اسپلاین/Catmull-Rom + گرادیانت
    واقعی + برچسب ساعت ۰۶/۰۹/۱۲…) در پایین همان تصویر — همه در یک PNG واحد در
    حافظه (io.BytesIO)، چیزی روی دیسک نوشته نمی‌شود. اگر داده کافی برای رسم نباشد
    None برمی‌گردد.
    theme: "dark" (مشکی) یا "light" (سفید).

    محور X پنل نمودار بر اساس تایم‌استمپ واقعی هر اسنپ‌شات رسم می‌شود، نه شمارهٔ
    ردیف — چون فاصلهٔ زمانی بین اسنپ‌شات‌ها ثابت نیست (مثلاً شب‌ها آپدیت کمتری
    ثبت می‌شود)؛ رسم بر اساس ایندکس ردیف باعث کِش‌آمدن/فشرده‌شدن مصنوعی منحنی و
    جابه‌جایی برچسب‌های ساعت می‌شد.

    کل بدنهٔ تابع زیر یک قفل سراسری (_chart_render_lock) اجرا می‌شود چون رابط
    pyplot یک state machine سراسری و غیر Thread-safe دارد؛ اگر دو ترد همزمان
    وارد plt.subplots/plt.savefig شوند ممکن است نمودار یکدیگر را خراب کنند یا
    خطای رندرینگ بدهند. صف شدن پشت این قفل مشکلی ایجاد نمی‌کند چون کش تصویر
    (get_cached_chart_image) از قبل جلوی رندرهای تکراری برای یک اسنپ‌شات را
    می‌گیرد؛ این تابع فقط برای اسنپ‌شات‌های واقعاً جدید صدا زده می‌شود.
    """
    from PIL import Image

    with _chart_render_lock:
        times, prices = _extract_price_series(item)
        if len(prices) < 2:
            return None

        # فقط اسنپ‌شات‌های دارای زمان معتبر، و مرتب‌شده بر اساس تایم‌استمپ واقعی
        # (نه صرفاً بر ترتیب ps تکیه می‌کنیم؛ این یک لایهٔ ایمنی اضافه است)
        valid_data = [(t.timestamp(), p, t) for t, p in zip(times, prices) if t is not None]
        if len(valid_data) < 2:
            return None
        valid_data.sort(key=lambda v: v[0])

        # امتداد تا لحظهٔ حال (اگر آخرین اسنپ‌شات واقعی هنوز به‌روزتر از ۲۴ ساعت
        # قبل است) — این باید قبل از برش ۲۴ ساعته انجام شود؛ وگرنه برش بر اساس
        # آخرین اسنپ‌شاتِ واقعی (مثلاً ساعت ۱۹ دیروز، وقتی بازار شب آپدیت نشده)
        # انجام می‌شد و بعد امتداد تا الان (مثلاً ۰۶:۲۰ امروز) کل بازهٔ نمودار را
        # به‌جای ۲۴ ساعت به چیزی حدود ۳۵ ساعت می‌کشید و فاصلهٔ ساعت‌ها را به‌هم می‌ریخت.
        now_dt = _now_tehran()
        last_dt = _to_tehran(valid_data[-1][2])
        if 0 < (now_dt - last_dt).total_seconds() < 86400:
            valid_data.append((now_dt.timestamp(), valid_data[-1][1], now_dt))

        # فقط ۲۴ ساعت آخرِ همین بازهٔ (احتمالاً امتدادیافته تا الان) — تا محور
        # شلوغ نشود و دقیقاً شبیه تب 1D اپ چند بماند. اگر دقیقاً روی لحظهٔ cutoff
        # اسنپ‌شاتی ثبت نشده باشد (مثلاً اولین اسنپ‌شاتِ بعد از آن برای ۲۲ ساعت
        # قبل باشد)، یک نقطهٔ مرزی روی خودِ cutoff با قیمتِ آخرین اسنپ‌شاتِ قبل
        # از آن اضافه می‌شود تا خط از همان ثانیهٔ اولِ کادر (لبهٔ چپ) پیوسته
        # شروع شود، نه از وسط کادر.
        last_ts = valid_data[-1][0]
        cutoff = last_ts - 86400
        past_points = [v for v in valid_data if v[0] < cutoff]
        future_points = [v for v in valid_data if v[0] >= cutoff]
        if past_points and future_points:
            boundary = (
                cutoff, past_points[-1][1],
                _to_tehran(datetime.fromtimestamp(cutoff, tz=timezone.utc)),
            )
            candidate = [boundary] + future_points
        else:
            candidate = future_points
        if len(candidate) >= 2:
            valid_data = candidate

        ts_arr = np.array([v[0] for v in valid_data], dtype=float)
        p_arr = np.array([v[1] for v in valid_data], dtype=float)
        dt_arr = [v[2] for v in valid_data]

        # حذف تایم‌استمپ‌های تکراری (اگر باشند) — وگرنه اسپلاین/Catmull-Rom خطا می‌دهد
        ts_unique, uniq_idx = np.unique(ts_arr, return_index=True)
        p_unique = p_arr[uniq_idx]
        dt_unique = [dt_arr[i] for i in uniq_idx]
        if len(ts_unique) < 2:
            return None

        # H / L بازهٔ ۲۴ ساعت همان دادهٔ رسم‌شده (بعد از trim به ۲۴س بالا)
        hi_val = float(p_unique.max())
        lo_val = float(p_unique.min())

        is_up = p_unique[-1] >= p_unique[0]
        line_color = CHART_UP_COLOR if is_up else CHART_DOWN_COLOR

        # نرم‌سازی روی محور زمان واقعی (نه ایندکس ردیف) — اگر scipy نصب باشد از اسپلاین
        # درجه‌سه استفاده می‌شود، وگرنه به همان Catmull-Rom داخلی سقوط می‌کند (بدون کرش)
        x = y = None
        if _HAS_SCIPY and len(ts_unique) >= 4:
            try:
                x = np.linspace(ts_unique[0], ts_unique[-1], 180)
                if (item.get("ty") or "") == "oi":
                    # نفت: نقاط API فاصلهٔ نامساوی دارند (مثلاً وقفهٔ ۱ ساعتهٔ بین دو سشن)؛
                    # اسپلاین درجه‌سه در چنین جاهایی دره/قلهٔ ساختگی می‌سازد. PCHIP هرگز
                    # از محدودهٔ قیمت‌های واقعی بیرون نمی‌زند و باز هم نرم است.
                    from scipy.interpolate import PchipInterpolator
                    y = PchipInterpolator(ts_unique, p_unique)(x)
                else:
                    spl = make_interp_spline(ts_unique, p_unique, k=3)
                    y = spl(x)
            except Exception:
                x = y = None
        if x is None:
            x, y = _catmull_rom_smooth(ts_unique, p_unique, points_per_segment=12)
        # اسپلاین بین نقاطِ با فاصلهٔ نامساوی می‌تواند بیرون از محدودهٔ واقعی قیمت بزند
        # (دره/قلهٔ ساختگی و بیرون‌زدن از قاب) — همیشه داخل [کف، سقف] دادهٔ واقعی نگه دار
        y = np.clip(y, lo_val, hi_val)

        try:
            price = item_current_price(item)
            diff, pct = item_fluctuation(item)

            total_h = HEADER_HEIGHT + CHART_IMG_HEIGHT
            # رنگ درخشش پس‌زمینه = همان رنگ تغییر قیمت هدر (سبز/قرمز)
            _hdr_accent = CHART_UP_COLOR if (diff or 0) >= 0 else CHART_DOWN_COLOR
            composite = _make_card_background(HEADER_WIDTH, total_h, theme, _hdr_accent)
            header_img = _draw_header_panel(
                item, price, diff, pct, hi_val, lo_val, theme=theme,
                bg_top=composite.crop((0, 0, HEADER_WIDTH, HEADER_HEIGHT)),
            )
            chart_img = _draw_chart_panel(p_unique, ts_unique, dt_unique, x, y, line_color, theme=theme)
            composite.alpha_composite(header_img, (0, 0))
            composite.alpha_composite(chart_img, (0, HEADER_HEIGHT))

            buf = io.BytesIO()
            buf.name = f"chart_{item.get('ab', 'item')}.png"
            _rgb = composite.convert("RGB")
            _rgb.save(buf, format="PNG", compress_level=3)
            buf.seek(0)
            for _im in (_rgb, composite, header_img, chart_img):
                try:
                    _im.close()
                except Exception:
                    pass
            return buf
        except Exception as e:
            logger.error(f"[CHART] generation failed for {item.get('ab')}: {e}", exc_info=True)
            return None


_chart_cache = {}          # (ab, theme) -> (زمان رندر, بایت‌های PNG)
_chart_cache_lock = threading.Lock()
_chart_inflight = {}       # (ab, theme) -> Event؛ چند درخواستِ هم‌زمان برای یک نمودار فقط یک رندر می‌سازند
try:
    _CHART_FRESH_SEC = float(os.environ.get("CHART_CACHE_FRESH_SEC", "45") or 45)    # تا این سن همان تصویر بدون رندر
    _CHART_STALE_SEC = float(os.environ.get("CHART_CACHE_STALE_SEC", "180") or 180)  # تا این سن: فوراً بده + پشت‌صحنه تازه کن
except ValueError:
    _CHART_FRESH_SEC, _CHART_STALE_SEC = 45.0, 180.0


def _clear_chart_cache():
    """قبلاً با هر آپدیت قیمت (هر ۳۰ ثانیه) کل کش پاک می‌شد و کلید کش هم دقیقه‌ای بود؛ نتیجه: تقریباً هر کلیک یک رندر سرد
    و چند ثانیه‌ای و تلگرام منتظرش نمی‌ماند. حالا کش با «سن» خودش منقضی می‌شود (_CHART_FRESH_SEC/_CHART_STALE_SEC)
    و این تابع عمداً کاری نمی‌کند (فقط برای سازگاری با فراخوانی‌های قبلی)."""
    return


# کش «قیمت‌محور»: عدد قیمت/تغییر داخل خودِ تصویر نمودار چاپ می‌شود. اگر فقط به سنِ کش تکیه کنیم، تا ۳ دقیقه قیمتِ قدیمی نشان
# داده می‌شد. پس هر تصویر با «امضای قیمت» ذخیره می‌شود و فقط وقتی قیمت/تغییر همان است از کش داده می‌شود.
# CHART_STRICT_PRICE=0 → رفتار قبلی (فقط سنِ کش). CHART_SAME_PRICE_MAX_SEC: حتی با قیمت ثابت، بعد از این مدت دوباره رندر.
_CHART_STRICT = os.environ.get("CHART_STRICT_PRICE", "1").strip().lower() not in ("0", "false", "off", "no")
try:
    _CHART_SAME_MAX_SEC = float(os.environ.get("CHART_SAME_PRICE_MAX_SEC", "600") or 600)
except ValueError:
    _CHART_SAME_MAX_SEC = 600.0


def _chart_sig(item: dict):
    try:
        p = item_current_price(item)
        d, _pct = item_fluctuation(item)
        return (None if p is None else round(float(p), 6), None if d is None else round(float(d), 6))
    except Exception:
        return None


def _chart_buf(ab, data: bytes) -> io.BytesIO:
    buf = io.BytesIO(data)
    buf.name = f"chart_{ab or 'item'}.png"
    return buf


def _chart_render_store(item: dict, theme: str, key: tuple):
    """رندر واقعی + ذخیره در کش، با جلوگیری از رندر تکراریِ هم‌زمان. برمی‌گرداند BytesIO یا None."""
    with _chart_cache_lock:
        ev = _chart_inflight.get(key)
        owner = ev is None
        if owner:
            ev = _chart_inflight[key] = threading.Event()
    if not owner:
        ev.wait(timeout=25)                       # کسِ دیگری همین نمودار را می‌سازد؛ منتظرش می‌مانیم
        with _chart_cache_lock:
            ent = _chart_cache.get(key)
        if ent:
            return _chart_buf(key[0], ent[1])
        if ev.is_set():
            return None                           # رندرِ آن یکی شکست خورد
    try:
        _t0 = time.time()
        _sig = _chart_sig(item)
        buf = generate_chart_image(item, theme=theme)
        logger.info(f"[CHART] rendered {key[0]} in {time.time() - _t0:.2f}s ok={bool(buf)}")
        if not buf:
            return None
        data = buf.getvalue()
        with _chart_cache_lock:
            _chart_cache[key] = (time.time(), data, _sig)
            # سقف سخت برای جلوگیری از رشد RAM — قدیمی‌ترین ورودی حذف شود
            while len(_chart_cache) > 64:
                _chart_cache.pop(next(iter(_chart_cache)))
        return _chart_buf(key[0], data)
    finally:
        if owner:
            with _chart_cache_lock:
                _chart_inflight.pop(key, None)
            ev.set()


def _chart_refresh_async(ab, theme: str, key: tuple):
    """کش کهنه (ولی هنوز قابل‌قبول) را پشت‌صحنه تازه می‌کند تا کلیک بعدی هم سریع باشد."""
    with _chart_cache_lock:
        if key in _chart_inflight:
            return

    def _job():
        try:
            it = get_item_by_ab(ab)
            if it:
                _chart_render_store(it, theme, key)
        except Exception as e:
            logger.warning(f"[CHART] refresh failed for {ab}: {e}")

    threading.Thread(target=_job, name="chart-refresh", daemon=True).start()


def get_cached_chart_image(item: dict, theme: str = "dark", strict: bool = True) -> io.BytesIO | None:
    """نمودار از کش (سریع) یا رندر تازه. سن کش: کمتر از _CHART_FRESH_SEC → همان؛ تا _CHART_STALE_SEC → همان را فوراً
    بده و پشت‌صحنه تازه کن؛ بیشتر → رندر هم‌زمان (با جلوگیری از رندر تکراری). theme: dark/light."""
    theme = "light" if (theme or "").lower() == "light" else "dark"
    ab = item.get("ab")
    key = (ab, theme)
    with _chart_cache_lock:
        ent = _chart_cache.get(key)
    if ent:
        age = time.time() - ent[0]
        if _CHART_STRICT and strict:
            # قیمت/تغییر همان است → تصویر همان است؛ عوض شده → رندر تازه (دکمه قبلش اعلان «در حال ساخت» می‌دهد)
            if age < _CHART_SAME_MAX_SEC and len(ent) > 2 and ent[2] == _chart_sig(item):
                return _chart_buf(ab, ent[1])
        else:
            # strict=False: آدرس عکسی که تلگرام می‌گیرد؛ هرچه آماده است بده تا تلگرام منتظر رندر جدید نماند
            if age < _CHART_FRESH_SEC:
                return _chart_buf(ab, ent[1])
            if age < _CHART_STALE_SEC:
                _chart_refresh_async(ab, theme, key)
                return _chart_buf(ab, ent[1])
    return _chart_render_store(item, theme, key)


def _chart_prewarm(ab: str, theme: str = "dark") -> bool:
    """قبل از ادیت پیام با لینک‌پریویو، نمودار را همین‌جا رندر/کش می‌کنیم. تلگرام عکس را چند ثانیه بعد از ادیت از URL می‌گیرد
    و اگر آن لحظه رندر هنوز تمام نشده باشد پیش‌نمایش را بی‌صدا رها می‌کند («ارسال نمی‌شود»). با این کار درخواست تلگرام
    همیشه از کش جواب می‌گیرد؛ و اگر داده‌ی نمودار نباشد کاربر پیام خطا می‌بیند، نه پیامِ بدون عکس."""
    try:
        _t0 = time.time()
        _chart_mark_hot(ab)          # این نمودار «داغ» است: کار پس‌زمینه تا چند دقیقه آمادهٔ آن نگهش می‌دارد
        item = get_item_by_ab((ab or "").strip().lower())
        ok = bool(item and get_cached_chart_image(item, theme=theme))
        logger.info(f"[CHART] prewarm {ab} ok={ok} took={time.time() - _t0:.2f}s")
        return ok
    except Exception as e:
        logger.warning(f"[CHART] prewarm failed for {ab}: {e}")
        return False


# ---- نمودار «همیشه گرم» ----
# رندر یک نمودار روی CPU ضعیف هاست (مثل Render رایگان) حدود ۱۰ ثانیه طول می‌کشد. قبلاً این رندر وقتی شروع می‌شد که کاربر
# دکمه را می‌زد، پس هر کلیکِ «سرد» ~۱۰ ثانیه حالت لودینگ داشت. حالا یک کار زمان‌بندی‌شده نمودارهای پرمصرف را از قبل
# تازه نگه می‌دارد: همیشه usd (یا هر چه در CHART_HOT_ABS باشد) + چند نمودار آخری که کاربرها باز کرده‌اند یا دکمه‌اش را دیده‌اند.
# کلیک روی این‌ها فوری جواب می‌گیرد (کش «تازه یا کهنهٔ قابل‌قبول» است). .env:
#   CHART_HOT_MAX=0 خاموش | CHART_HOT_MAX=3 تعداد کل نمودارهای گرم | CHART_HOT_ABS=usd,gram | CHART_HOT_TTL_SEC=1800
def _chart_env_num(key: str, default: float) -> float:
    try:
        return float(os.environ.get(key, "") or default)
    except ValueError:
        return default


_CHART_HOT_MAX = int(_chart_env_num("CHART_HOT_MAX", 3))
_CHART_HOT_TTL = _chart_env_num("CHART_HOT_TTL_SEC", 1800.0)
_CHART_HOT_REFRESH_SEC = _chart_env_num("CHART_HOT_REFRESH_SEC", 80.0)
_CHART_HOT_DEFAULT = tuple(x.strip().lower() for x in (os.environ.get("CHART_HOT_ABS", "usd") or "").split(",") if x.strip())
_chart_hot: dict = {}                  # ab -> زمان آخرین درخواست/نمایش دکمهٔ نمودار
_chart_hot_lock = threading.Lock()


def _chart_mark_hot(ab) -> None:
    ab = (ab or "").strip().lower()
    if not ab or _CHART_HOT_MAX <= 0:
        return
    with _chart_hot_lock:
        _chart_hot[ab] = time.time()
        if len(_chart_hot) > 60:
            for k_ in sorted(_chart_hot, key=_chart_hot.get)[:20]:
                _chart_hot.pop(k_, None)


def _chart_cache_ready(ab: str, theme: str = "dark") -> bool:
    """نمودار آماده (تازه یا کهنهٔ قابل‌قبول) همین الان در کش هست؟ آن‌وقت کلیک بدون رندر جواب می‌گیرد."""
    try:
        theme = "light" if (theme or "").lower() == "light" else "dark"
        it = get_item_by_ab((ab or "").strip().lower())
        if not it:
            return False
        with _chart_cache_lock:
            ent = _chart_cache.get((it.get("ab"), theme))
        if not ent:
            return False
        age = time.time() - ent[0]
        if _CHART_STRICT:
            return bool(age < _CHART_SAME_MAX_SEC and len(ent) > 2 and ent[2] == _chart_sig(it))
        return bool(age < _CHART_STALE_SEC)
    except Exception:
        return False


def chart_hot_refresh_job() -> None:
    """کار زمان‌بندی‌شده: نمودار آیتم‌های گرم را پشت‌صحنه (یکی‌یکی) تازه نگه می‌دارد."""
    if _CHART_HOT_MAX <= 0:
        return
    now = time.time()
    with _chart_hot_lock:
        recent = [ab for _, ab in sorted(((t, a) for a, t in _chart_hot.items() if now - t < _CHART_HOT_TTL), reverse=True)]
    abs_ = list(_CHART_HOT_DEFAULT)
    for ab in recent:
        if ab not in abs_:
            abs_.append(ab)
    for ab in abs_[:_CHART_HOT_MAX]:
        try:
            it = get_item_by_ab(ab)
            if not it:
                continue
            key = (it.get("ab"), "dark")
            with _chart_cache_lock:
                ent = _chart_cache.get(key)
            if ent:
                _age = time.time() - ent[0]
                if _CHART_STRICT:
                    if _age < _CHART_SAME_MAX_SEC and len(ent) > 2 and ent[2] == _chart_sig(it):
                        continue
                elif _age < _CHART_HOT_REFRESH_SEC:
                    continue
            _chart_render_store(it, "dark", key)
        except Exception as e:
            logger.warning(f"[CHART] hot refresh failed for {ab}: {e}")


