def _oil_abs_from_file() -> list:
    """هر نمادی که در نفت.txt / کش نفت باشد."""
    abs_list = []
    for it in (_oil_items_cache or _load_oil_file() or []):
        ab = (it.get("ab") or "").strip().lower()
        if ab and ab not in abs_list:
            abs_list.append(ab)
    if not abs_list:
        abs_list = ["brent", "wti"]
    return abs_list


