def _env_int_simple(name: str, default: int, lo: int, hi: int) -> int:
    try:
        v = int(os.environ.get(name, "") or default)
    except ValueError:
        v = default
    return max(lo, min(hi, v))


_GROQ_MARKET_MAXTOK = _env_int_simple("AI_GROQ_MARKET_MAX_TOKENS", 1400, 300, 4000)
_MARKET_MAX_ROWS = _env_int_simple("AI_MARKET_MAX_ROWS", 8, 2, 22)

