import urllib.parse

# زمان‌بندی جستجوی وب (ثانیه): هر درخواست حداکثر _WEB_HTTP_TIMEOUT؛ کل جستجو حداکثر _WEB_TOTAL_TIMEOUT.
# اگر بینگ زودتر جواب داد، به DuckDuckGo (دقیق‌تر) حداکثر _WEB_DDG_GRACE فرصت می‌دهیم و نتایج ترکیب می‌شوند.
def _env_float(key: str, default: float) -> float:
    try:
        return float(os.environ.get(key, "") or default)
    except ValueError:
        return default


_WEB_HTTP_TIMEOUT = _env_float("WEB_HTTP_TIMEOUT_SEC", 6.0)
_WEB_TOTAL_TIMEOUT = _env_float("WEB_TOTAL_TIMEOUT_SEC", 7.0)
_WEB_DDG_GRACE = _env_float("WEB_DDG_GRACE_SEC", 1.5)
_WEB_POOL = ThreadPoolExecutor(max_workers=max(16, int(_env_float("WEB_POOL_WORKERS", 32))), thread_name_prefix="web-search")        # درخواست‌های شبکه
_WEB_OUTER_POOL = ThreadPoolExecutor(max_workers=4, thread_name_prefix="web-multi")   # چند جستجوی هم‌زمان (جدا از بالا تا deadlock نشود)

_BING_HEADERS = {
    "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
                   "Chrome/124.0.0.0 Safari/537.36"),
    "Accept-Language": "fa-IR,fa;q=0.9,en-US;q=0.8,en;q=0.7",
}


def _bing_unwrap_href(href: str) -> str:
    """لینک‌های بینگ گاهی redirect هستند (bing.com/ck/a?...&u=a1<base64>)؛ آدرس واقعی را درمی‌آورد."""
    try:
        if "bing.com/ck/a" in href:
            u = (urllib.parse.parse_qs(urllib.parse.urlparse(href).query).get("u") or [""])[0]
            if u.startswith("a1"):
                u = u[2:]
                return _b64.urlsafe_b64decode(u + "=" * (-len(u) % 4)).decode("utf-8", "ignore") or href
    except Exception:
        pass
    return href


def _search_bing_html(query: str, max_results: int = 5) -> list:
    """پشتیبانِ RSS: صفحهٔ نتایج بینگ (رایگان و بی‌کلید) → [{title, body, href}]؛ هر خطا → لیست خالی.
    توجه: این اسکرپ HTML است، نه API رسمی؛ ممکن است بینگ از آی‌پی سرور کپچا بدهد (آن‌وقت لیست خالی برمی‌گردد)."""
    if not _HAS_BS4:
        return []
    results = []
    try:
        r = _ai_session.get("https://www.bing.com/search", params={"q": query, "setlang": "fa"},
                            headers=_BING_HEADERS, timeout=_WEB_HTTP_TIMEOUT)
        if r.status_code != 200:
            logger.warning(f"[WEB-BING-HTML] status={r.status_code}")
            return []
        soup = BeautifulSoup(r.text, "html.parser")
        for item in soup.find_all("li", class_="b_algo", limit=max_results):
            h2 = item.find("h2")
            title = h2.get_text(" ", strip=True) if h2 else ""
            a_tag = h2.find("a") if h2 else None
            href = _bing_unwrap_href(a_tag.get("href", "")) if a_tag else ""
            cap = item.find("p") or item.find("div", class_="b_caption")
            body = cap.get_text(" ", strip=True) if cap else ""
            if title or body:
                results.append({"title": title, "body": body[:350], "href": href})
        if not results:
            logger.info("[WEB-BING-HTML] نتیجه‌ای استخراج نشد (احتمالاً کپچا/تغییر ساختار صفحه)")
    except Exception as e:
        logger.warning(f"[WEB-BING-HTML] خطا در جستجو: {_err_cause(e)}")
    return results


def _search_bing_rss(query: str, max_results: int = 5) -> list:
    """منبع دوم جستجو: فید RSS بینگ (format=rss) — سبک و مستقل از قالب HTML، بدون نیاز به BeautifulSoup.
    اندپوینت رسمی/مستند نیست؛ اگر بینگ آن را ببندد یا خالی بدهد، _search_bing به اسکرپ HTML می‌رود."""
    results = []
    try:
        r = _ai_session.get("https://www.bing.com/search", params={"q": query, "format": "rss", "setlang": "fa"},
                            headers={**_BING_HEADERS,
                                     "Accept": "application/rss+xml, application/xml;q=0.9, text/xml;q=0.8, */*;q=0.7"},
                            timeout=_WEB_HTTP_TIMEOUT)
        if r.status_code != 200 or not r.content:
            logger.warning(f"[WEB-BING-RSS] status={r.status_code}")
            return []
        root = ET.fromstring(r.content[:600_000])
        channel = root.find("channel")
        if channel is None:
            logger.info("[WEB-BING-RSS] پاسخ RSS نبود (احتمالاً صفحهٔ HTML/کپچا)")
            return []
        for item in channel.findall("item")[:max_results]:
            title = (item.findtext("title") or "").strip()
            link = (item.findtext("link") or "").strip()
            desc = html.unescape(re.sub(r"<[^>]+>", "", item.findtext("description") or "")).strip()
            if title or desc:
                results.append({"title": title, "body": desc[:350], "href": link,
                                "date": _web_fmt_date(item.findtext("pubDate") or "")})
    except Exception as e:
        logger.warning(f"[WEB-BING-RSS] خطا در خواندن فید: {_err_cause(e)}")
    return results


def _search_bing(query: str, max_results: int = 5) -> list:
    """بینگ: اول فید RSS، اگر خالی بود اسکرپ HTML."""
    return _search_bing_rss(query, max_results) or _search_bing_html(query, max_results)


_WEB_FRESH_RE = re.compile(
    r"(?:آخرین|اخرین|جدیدترین|جدید ترین|تازه ?ترین|اخیر|الان|اکنون|امروز|دیشب|دیروز|این (?:هفته|ماه)|همین حالا|فعلی|"
    r"فعلا|تازه|جدید|"
    # خبر و رویداد: «کی فوت کرد؟»، «چی شد؟»، «اخبار ...» → جستجوی خبر (تاریخ‌دار) نه صفحه‌های قدیمی
    r"فوت" + _AI_FA_RIGHT + r"|درگذشت|به ?درک|واصل ?شد|کشته|ترور|انفجار|زلزله|سقوط|استعفا|اخبار|چی ?شد|چه ?شد|"
    r"latest|newest|recent|currently|today|tonight|yesterday|breaking|\bnow\b|\bnew\b|\bdied\b|\bdeath\b|\bkilled\b)", re.I)
_DDG_WARNED = False


def _web_is_fresh(text: str) -> bool:
    """سؤال «تازه‌ترین/آخرین/الان» است؟ آن‌وقت خبر و نتایج تاریخ‌دار در اولویت‌اند (نه صفحه‌های قدیمیِ پربازدید)."""
    return bool(_WEB_FRESH_RE.search(_ai_norm_fa(text or "")))


def _web_fmt_date(s: str) -> str:
    """تاریخ RSS (RFC822) → YYYY-MM-DD؛ هر خطا → رشتهٔ خالی."""
    s = (s or "").strip()
    if not s:
        return ""
    try:
        from email.utils import parsedate_to_datetime
        return parsedate_to_datetime(s).strftime("%Y-%m-%d")
    except Exception:
        m = re.search(r"\d{4}-\d{2}-\d{2}", s)
        return m.group(0) if m else ""


def _search_ddg(query: str, max_results: int = 5, news: bool = False) -> list:
    """DuckDuckGo (رایگان، بی‌کلید) → [{title, body, href, date}]؛ news=True → بخش خبر (تاریخ‌دار و تازه)؛
    هر خطا (مثل rate-limit) → لیست خالی."""
    global _DDG_WARNED
    if _DDGS is None:
        if not _DDG_WARNED:
            _DDG_WARNED = True
            logger.warning("[WEB-DDG] پکیج ddgs نصب نیست (pip install ddgs در requirements.txt) — فقط بینگ/گوگل‌نیوز کار می‌کنند")
        return []
    out = []
    try:
        with _DDGS(timeout=_WEB_HTTP_TIMEOUT) as ddgs:
            rows = (ddgs.news(query, max_results=max_results) if news
                    else ddgs.text(query, max_results=max_results)) or []
            for r in rows:
                title = (r.get("title") or "").strip()
                body = (r.get("body") or "").strip()
                if title or body:
                    out.append({"title": title, "body": body[:350],
                                "href": (r.get("href") or r.get("url") or "").strip(),
                                "date": _web_fmt_date(r.get("date") or ""), "src": (r.get("source") or "").strip()})
    except Exception as e:
        logger.warning(f"[WEB-DDG{'-NEWS' if news else ''}] خطا در جستجو: {_err_cause(e)}")
    return out


def _search_gnews(query: str, max_results: int = 5) -> list:
    """Google News RSS (رایگان، بی‌کلید، به‌روز) → [{title, body, href, date, src}] مرتب از تازه به قدیمی.
    برای سؤال‌های «آخرین/جدیدترین/خبر» که موتورهای عادی نتایج قدیمی می‌دهند."""
    results = []
    try:
        latin = not re.search(r"[؀-ۿ]", query)
        params = ({"q": query, "hl": "en-US", "gl": "US", "ceid": "US:en"} if latin
                  else {"q": query, "hl": "fa", "gl": "IR", "ceid": "IR:fa"})
        r = _ai_session.get("https://news.google.com/rss/search", params=params, headers=_BING_HEADERS,
                            timeout=_WEB_HTTP_TIMEOUT)
        if r.status_code != 200 or not r.content:
            logger.warning(f"[WEB-GNEWS] status={r.status_code}")
            return []
        channel = ET.fromstring(r.content[:900_000]).find("channel")
        if channel is None:
            return []
        for item in channel.findall("item")[:20]:
            title = (item.findtext("title") or "").strip()
            src = (item.findtext("source") or "").strip()
            if src and title.endswith(" - " + src):
                title = title[: -len(src) - 3].strip()
            if title:
                results.append({"title": title, "body": f"خبر از {src}" if src else "",
                                "href": (item.findtext("link") or "").strip(),
                                "date": _web_fmt_date(item.findtext("pubDate") or ""), "src": src})
        results.sort(key=lambda x: x.get("date") or "", reverse=True)       # تازه‌ترین اول
    except Exception as e:
        logger.warning(f"[WEB-GNEWS] خطا در خواندن فید: {_err_cause(e)}")
    return results[:max_results]


# ============================================================
# موتورهای جستجوی اضافه + مدار قطع‌کن + رتبه‌بندی نتایج (برای «همهٔ» جستجوهای ربات، نه فقط آهنگ)
# ------------------------------------------------------------
# مشکل قبلی: فقط DDG و بینگ-RSS بودند؛ به محض اینکه یکی از آن‌ها چیزی برمی‌گرداند بقیه فقط ۱٫۵ ثانیه فرصت داشتند، و اگر هر دو
# نتیجهٔ بی‌ربط می‌دادند (بینگ-RSS برای فارسی اغلب همین‌طور است) ربات «پیدا نشد» می‌گفت. حالا:
#   • Yahoo، Mojeek (و DDG-HTML وقتی ddgs نصب نیست یا خالی داد) هم‌زمان جستجو می‌کنند؛ تا دو موتور جواب ندهند کمی بیشتر صبر می‌شود.
#   • هر موتوری که پشت‌سرهم ۳ بار خراب شود (کپچا/۴۰۳/۴۲۹) ۵ دقیقه کنار گذاشته می‌شود؛ نتیجه در لاگ [WEB-...] معلوم است.
#   • نتایج بر اساس «چند کلمهٔ سؤال در عنوان/متن/لینک دیده شد» مرتب می‌شوند (نتیجهٔ بی‌ربط ته لیست می‌رود).
#   • تکراری‌ها با «آدرس نرمال‌شده» حذف می‌شوند (www/m/amp و پارامترهای utm).
# .env:  WEB_EXTRA_ENGINES=0 → فقط DDG/بینگ مثل قبل
# ============================================================
_WEB_EXTRA_ON = os.environ.get("WEB_EXTRA_ENGINES", "1").strip().lower() not in ("0", "false", "off", "no")
_WEB_PLAIN_GRACE = _env_float("WEB_PLAIN_GRACE_SEC", 2.5)       # بعد از اولین موتورِ جواب‌داده، برای موتور دوم این‌قدر صبر کن
_WEB_ENG_STATE: dict = {}
_WEB_ENG_LOCK = threading.Lock()


def _web_eng_ok(name: str) -> bool:
    st = _WEB_ENG_STATE.get(name)
    return not st or st["until"] <= time.time()


def _web_eng_report(name: str, ok: bool, why: str = "") -> None:
    with _WEB_ENG_LOCK:
        st = _WEB_ENG_STATE.setdefault(name, {"fails": 0, "until": 0.0})
        if ok:
            st["fails"] = 0
            return
        st["fails"] += 1
        if st["fails"] >= 3:
            st["until"] = time.time() + 300
            st["fails"] = 0
            logger.warning(f"[WEB-{name.upper()}] ۳ بار پشت‌سرهم نتیجه نداد ({why}) ← ۵ دقیقه کنار گذاشته شد")


def _web_get_html(name: str, url: str, params=None, data=None):
    """درخواست به یک موتور جستجو → متن HTML یا None (خطا/وضعیت غیر ۲۰۰)."""
    try:
        if data is not None:
            r = _ai_session.post(url, data=data, headers=_BING_HEADERS, timeout=_WEB_HTTP_TIMEOUT)
        else:
            r = _ai_session.get(url, params=params, headers=_BING_HEADERS, timeout=_WEB_HTTP_TIMEOUT)
    except Exception as e:
        _web_eng_report(name, False, type(e).__name__)
        logger.warning(f"[WEB-{name.upper()}] خطا :: {_err_cause(e)}")
        return None
    if r.status_code != 200:
        _web_eng_report(name, False, f"HTTP {r.status_code}")
        logger.warning(f"[WEB-{name.upper()}] status={r.status_code}")
        return None
    return r.text or ""


_WEB_CAPTCHA_RE = re.compile(r"captcha|unusual traffic|are you a (?:robot|human)|verify you are|automated (?:queries|requests)", re.I)


def _yahoo_unwrap(href: str) -> str:
    """لینک‌های یاهو redirect هستند (r.search.yahoo.com/.../RU=<آدرس-انکودشده>/RK=...)."""
    m = re.search(r"/RU=([^/&]+)", href or "")
    if m:
        try:
            return urllib.parse.unquote(m.group(1))
        except Exception:
            pass
    return href or ""


def _search_yahoo(query: str, max_results: int = 5) -> list:
    """Yahoo (اسکرپ HTML، بی‌کلید) → [{title, body, href}]؛ هر خطا/کپچا → []."""
    if not (_HAS_BS4 and _WEB_EXTRA_ON and _web_eng_ok("yahoo")):
        return []
    txt = _web_get_html("yahoo", "https://search.yahoo.com/search", params={"p": query, "ei": "UTF-8", "n": 10})
    if txt is None:
        return []
    out, seen = [], set()
    try:
        soup = BeautifulSoup(txt, "html.parser")
        for item in soup.select("div.algo"):
            a = item.select_one("h3 a") or item.select_one("a[href]")
            if not a:
                continue
            href = _yahoo_unwrap(a.get("href", ""))
            if not href.startswith("http") or href in seen:
                continue
            seen.add(href)
            full = a.get_text(" ", strip=True)
            title = full
            for sp in a.select("span"):                  # «دامنه › مسیر» که یاهو قبل از عنوان می‌گذارد
                t = sp.get_text(" ", strip=True)
                if t and full.startswith(t) and len(full) > len(t) + 2:
                    title = full[len(t):].strip()
                    break
            p = item.select_one("div.compText p") or item.select_one("p")
            body = p.get_text(" ", strip=True) if p else ""
            if title or body:
                out.append({"title": title, "body": body[:350], "href": href})
            if len(out) >= max_results:
                break
    except Exception as e:
        logger.warning(f"[WEB-YAHOO] پارس خطا :: {_err_cause(e)}")
    _web_eng_report("yahoo", bool(out), "کپچا/تغییر ساختار" if _WEB_CAPTCHA_RE.search(txt[:20000]) else "نتیجه‌ای استخراج نشد")
    return out


def _search_mojeek(query: str, max_results: int = 5) -> list:
    """Mojeek (ایندکس مستقل، اسکرپ‌پسند) → [{title, body, href}]."""
    if not (_HAS_BS4 and _WEB_EXTRA_ON and _web_eng_ok("mojeek")):
        return []
    txt = _web_get_html("mojeek", "https://www.mojeek.com/search", params={"q": query})
    if txt is None:
        return []
    out = []
    try:
        soup = BeautifulSoup(txt, "html.parser")
        for li in soup.select("ul.results-standard > li, ul.results > li"):
            a = li.select_one("a.title") or li.select_one("h2 a")
            if not a or not (a.get("href") or "").startswith("http"):
                continue
            p = li.select_one("p.s") or li.select_one("p")
            out.append({"title": a.get_text(" ", strip=True), "body": (p.get_text(" ", strip=True) if p else "")[:350],
                        "href": a["href"]})
            if len(out) >= max_results:
                break
    except Exception as e:
        logger.warning(f"[WEB-MOJEEK] پارس خطا :: {_err_cause(e)}")
    _web_eng_report("mojeek", bool(out), "کپچا/تغییر ساختار" if _WEB_CAPTCHA_RE.search(txt[:20000]) else "نتیجه‌ای استخراج نشد")
    return out


def _search_ddg_html(query: str, max_results: int = 5) -> list:
    """DuckDuckGo نسخهٔ HTML — فالبکِ وقتی پکیج ddgs نصب نیست یا ریت‌لیمیت شده."""
    if not (_HAS_BS4 and _WEB_EXTRA_ON and _web_eng_ok("ddg-html")):
        return []
    txt = _web_get_html("ddg-html", "https://html.duckduckgo.com/html/", data={"q": query, "kl": "wt-wt"})
    if txt is None:
        return []
    out = []
    try:
        soup = BeautifulSoup(txt, "html.parser")
        for item in soup.select("div.result, div.web-result"):
            a = item.select_one("a.result__a")
            if not a:
                continue
            href = a.get("href", "")
            if "uddg=" in href:
                href = (urllib.parse.parse_qs(urllib.parse.urlparse(href).query).get("uddg") or [""])[0]
            elif href.startswith("//"):
                href = "https:" + href
            if not href.startswith("http"):
                continue
            sn = item.select_one(".result__snippet")
            out.append({"title": a.get_text(" ", strip=True), "body": (sn.get_text(" ", strip=True) if sn else "")[:350],
                        "href": href})
            if len(out) >= max_results:
                break
    except Exception as e:
        logger.warning(f"[WEB-DDG-HTML] پارس خطا :: {_err_cause(e)}")
    _web_eng_report("ddg-html", bool(out), "کپچا/تغییر ساختار" if _WEB_CAPTCHA_RE.search(txt[:20000]) else "نتیجه‌ای استخراج نشد")
    return out


_WEB_TRACK_PARAM_RE = re.compile(r"^(?:utm_.*|fbclid|gclid|ref|spm|igshid)$", re.I)


def _web_canon_url(u: str) -> str:
    """آدرس نرمال‌شده برای حذف تکراری‌ها (www/m/amp، اسلش آخر، پارامترهای ردیابی)."""
    u = (u or "").strip()
    if not u:
        return ""
    try:
        p = urllib.parse.urlsplit(u)
        host = re.sub(r"^(?:www\.|m\.|amp\.)", "", p.netloc.lower())
        q = [(k, v) for k, v in urllib.parse.parse_qsl(p.query) if not _WEB_TRACK_PARAM_RE.match(k)]
        return host + urllib.parse.unquote(p.path).rstrip("/") + (("?" + urllib.parse.urlencode(q)) if q else "")
    except Exception:
        return u.lower()


_WEB_RANK_STOP = frozenset(
    "و در به از که را رو با برای این آن اون اینو یه یک چی چیه کیه کی چه هم تا یا اما ولی the of and a an in on for to is are".split())


def _web_rank_tokens(s: str) -> list:
    s = urllib.parse.unquote(s or "").lower().replace("\u200c", " ").replace("ي", "ی").replace("ك", "ک")
    s = re.sub(r"site:\S+", " ", s)
    return [w for w in re.findall(r"\w+", s) if len(w) >= 2 and w not in _WEB_RANK_STOP]


def _web_rerank(query: str, res: list) -> list:
    """نتایجی که کلمه‌های بیشتری از سؤال را در عنوان/متن/لینک دارند بالا می‌آیند؛ ترتیبِ موتورها داخل هر سطح حفظ می‌شود (پایدار)."""
    qt = list(dict.fromkeys(_web_rank_tokens(query)))
    if len(qt) < 2 or len(res) < 2:
        return res
    return [r for _l, r in sorted(((_web_rel_level(qt, r), r) for r in res), key=lambda x: -x[0])]


def _web_rel_level(qt: list, r: dict) -> int:
    """۰..۴: چند چهارم کلمه‌های سؤال در عنوان/متن/لینک این نتیجه دیده شد."""
    blob = " ".join(_web_rank_tokens(f"{r.get('title') or ''} {r.get('body') or ''} {r.get('href') or ''}"))
    words = set(blob.split())
    hit = sum(1 for t in qt if t in words or (len(t) >= 4 and t in blob))
    return int(hit * 4 / max(1, len(qt)))


def _web_good_count(query: str, results: list) -> int:
    """چند نتیجهٔ «واقعاً مرتبط» (≥۳/۴ کلمه‌های سؤال) تا حالا رسیده؛ برای قطع زودهنگام انتظار."""
    qt = list(dict.fromkeys(_web_rank_tokens(query)))
    if len(qt) < 2:
        return 0
    return sum(1 for r in results if _web_rel_level(qt, r) >= 3)


def _web_relax_query(q: str) -> str:
    """گیومه و عملگرها را برمی‌دارد (وقتی جستجوی دقیق هیچ نتیجه‌ای نداد)."""
    q = re.sub(r"site:\S+", " ", q or "")
    q = re.sub(r"[\"“”«»]", " ", q)
    return re.sub(r"\s+", " ", q).strip()


def _web_search_available() -> bool:
    return True      # بینگ RSS فقط به requests/ET نیاز دارد (همیشه موجود)


def _web_interleave(lists: list, limit: int) -> list:
    """نتایج منابع مختلف را نوبتی (به ترتیب اولویت) ترکیب می‌کند تا یک منبع همهٔ جاها را پر نکند؛ تکراری‌ها حذف."""
    seen, out = set(), []
    for i in range(max((len(x) for x in lists), default=0)):
        for lst in lists:
            if i < len(lst):
                r = lst[i]
                k = (_web_canon_url(r.get("href") or "") or (r.get("title") or "")).strip().lower()
                if k and k not in seen:
                    seen.add(k)
                    out.append(r)
                    if len(out) >= limit:
                        return out
    return out


# --- تاریخِ نتایج بی‌تاریخ ---
# سایت‌های آهنگ فارسی (نتایج متنیِ DDG/بینگ) فیلد تاریخ ندارند ولی در عنوان/متن «24 مهر 1405» یا «1405/07/24» می‌نویسند.
# قبلاً نتایج بی‌تاریخ ته لیست می‌افتادند و خبرِ تاریخ‌دارِ قدیمی (مثلاً ۲۰۲۵) «تازه‌ترین» حساب می‌شد.
_FA_DIGIT_TABLE = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
_WEB_JAL_MONTH_IDX = {_ai_norm_fa(m_): i_ + 1 for i_, m_ in enumerate(_JAL_MONTHS)}
_WEB_JAL_DMY_RE = re.compile(
    r"(?<!\d)(\d{1,2})\s+(" + "|".join(sorted(_WEB_JAL_MONTH_IDX, key=len, reverse=True)) + r")\s+(1[34]\d{2})(?!\d)")
_WEB_JAL_NUM_RE = re.compile(r"(?<!\d)(1[34]\d{2})\s*[/\-.]\s*(\d{1,2})\s*[/\-.]\s*(\d{1,2})(?!\d)")
_WEB_ISO_RE = re.compile(r"(?<!\d)(20\d{2})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{1,2})(?!\d)")


def _web_guess_date(*texts) -> str:
    """تاریخ را از عنوان/خلاصه/لینک بیرون می‌کشد (شمسی «24 مهر 1405» یا «1405/07/24»، میلادی «2026-10-16») → YYYY-MM-DD
    یا رشتهٔ خالی. تاریخ‌های بعد از امروز (بیش از ۲ روز) نادیده گرفته می‌شوند."""
    t = _ai_norm_fa(" ".join(x or "" for x in texts)).translate(_FA_DIGIT_TABLE)
    cands = []
    for m in _WEB_JAL_DMY_RE.finditer(t):
        try:
            cands.append(jalali_to_gregorian(int(m.group(3)), _WEB_JAL_MONTH_IDX[m.group(2)], int(m.group(1))))
        except Exception:
            pass
    for m in _WEB_JAL_NUM_RE.finditer(t):
        try:
            cands.append(jalali_to_gregorian(int(m.group(1)), int(m.group(2)), int(m.group(3))))
        except Exception:
            pass
    for m in _WEB_ISO_RE.finditer(t):
        try:
            cands.append(_date(int(m.group(1)), int(m.group(2)), int(m.group(3))))
        except Exception:
            pass
    try:
        limit = _now_tehran().date() + timedelta(days=2)
        cands = [d for d in cands if d <= limit]
    except Exception:
        pass
    return max(cands).isoformat() if cands else ""


def _web_fill_dates(results: list) -> list:
    for r in results or []:
        if not r.get("date"):
            d = _web_guess_date(r.get("title"), r.get("body"), r.get("href"))
            if d:
                r["date"] = d
    return results


# --- موسیقی: «آخرین آهنگ تتلو» → «دانلود آهنگ جدید تتلو» ---
# عنوان تقریباً همهٔ سایت‌های دانلود آهنگ فارسی همین قالب است («دانلود آهنگ جدید امیر تتلو به نام ...») و تازه‌ترین
# انتشارها همان‌جا زودتر از خبر و ویکی‌پدیا پیدا می‌شوند. نتایجش کنار نتایج عادی ترکیب می‌شود.
_WEB_MUSIC_RE = re.compile(r"(?:آهنگ|اهنگ|موزیک|ترانه|آلبوم|البوم|سینگل|song|music|track|album|single)", re.I)
_WEB_MUSIC_STRIP_RE = re.compile(
    r"(?<![\u0600-\u06FF])(?:آخرین|اخرین|جدیدترین|جدید ?ترین|تازه ?ترین|جدید|تازه|اخیر|آهنگی?|اهنگی?|موزیک|ترانه|"
    r"آلبوم|البوم|تک ?آهنگ|سینگل|که|رو|را|داده|بیرون|منتشر(?: ?شده| ?کرده)?|ریلیز(?: ?شده| ?کرده)?|داد|چیه|چیست|چی|بود|هست|"
    r"بعد از|از|برای)(?![\u0600-\u06FF])"
    r"|\b(?:latest|newest|new|song|music|track|album|single|released?)\b", re.I)


def _web_music_query(query: str) -> str:
    """کوئری مخصوص سایت‌های آهنگ؛ رشتهٔ خالی = سؤال موسیقی نیست یا نام خواننده/اثر پیدا نشد."""
    q = _ai_norm_fa(query)
    if not _WEB_MUSIC_RE.search(q):
        return ""
    name = _WEB_MUSIC_STRIP_RE.sub(" ", q)
    name = re.sub(r"[«»\"'؟?!.,،:؛\-]", " ", name)
    name = re.sub(r"\s+", " ", name).strip()
    if len(name) < 2:
        return ""
    if re.search(r"[\u0600-\u06FF]", name):
        return f"دانلود آهنگ جدید {name}"[:120]
    return f"{name} new song"[:120]


def _web_clean_q(q: str) -> str:
    """نیم‌فاصله/کنترل‌کاراکترهای جهت را به فاصله تبدیل می‌کند؛ احتمالاً بینگ/گوگل‌نیوز نام‌هایی مثل «خامنه‌ای» را با نیم‌فاصله خوب مچ نمی‌کنند
    (در لاگ، نتایج بینگ فقط روی «علی» مچ شده بودند)؛ این نسخهٔ تمیز بی‌ضرر است."""
    q = re.sub(r"[\u200c\u200d\u200e\u200f\u202a-\u202e]", " ", q or "")
    return re.sub(r"\s+", " ", q).strip()


def _web_is_event_hit(r: dict) -> bool:
    """آیا عنوان/متن این نتیجه کلمهٔ رویداد (فوت/کشته‌شدن…) دارد؟"""
    t = f"{r.get('title') or ''} {r.get('body') or ''}".lower()
    return any(w in t for w in _WEB_DEATH_HIT)



# ============================================================
# منابع خبری ثابت (RSS مستقیم) — برای سؤال‌های «خبر/فوت/آخرین …»
# ------------------------------------------------------------
# DDG/بینگ/گوگل از آی‌پی رندر گاهی ۱۰+ ثانیه طول می‌کشند یا ۴۲۹ می‌دهند و نتیجهٔ بی‌ربط برمی‌گردانند. فید خبرگزاری‌ها سبک و سریع است:
# همهٔ فیدها هم‌زمان خوانده می‌شوند، ۲ دقیقه کش می‌شوند (سؤال‌های بعدی بدون شبکه) و عنوان/خلاصهٔ هر خبر با کوئری مچ می‌شود.
# لیست پایین را ویرایش کن یا در ENV این‌ها را بگذار:
#   NEWS_FEEDS_EXTRA = آدرس‌های اضافه، جداشده با فاصله/کاما/خط جدید      NEWS_FEEDS=0 → خاموش‌کردن کامل
# فقط آدرس‌هایی که وجودشان تأیید شده پیش‌فرض‌اند؛ بقیه (ایسنا، ایرنا، رادیو فردا، یورونیوز، ایران‌وایر…) را بعد از تست
# از رندر (curl) به NEWS_FEEDS_EXTRA اضافه کن؛ بعضی سایت‌های داخلی ممکن است آی‌پی خارجی را ببندند.
# ============================================================
_NEWS_FEEDS_DEFAULT = (
    "https://feeds.bbci.co.uk/persian/rss.xml",      # BBC فارسی
    "https://rss.dw.com/rdf/rss-per-all",            # DW فارسی
)
_NEWS_FEEDS_ON = os.environ.get("NEWS_FEEDS", "1").strip().lower() not in ("0", "false", "off", "no")
_NEWS_FEED_CACHE = TTLCache(maxsize=64, ttl=120)
_NEWS_POOL = ThreadPoolExecutor(max_workers=8, thread_name_prefix="news-feed")
_NEWS_AR_MAP = str.maketrans({"ي": "ی", "ك": "ک", "ۀ": "ه", "ة": "ه", "أ": "ا", "إ": "ا", "ؤ": "و", "آ": "ا"})
_NEWS_STOP = frozenset((
    "درگذشت", "فوت", "کشته", "مرگ", "رحلت", "death", "died", "dies", "dead", "news", "خبر", "اخبار", "آخرین", "اخرین",
    "جدید", "جدیدترین", "کی", "چه", "ساعتی", "روزی", "و", "به", "از", "در", "که", "را", "رو", "چی", "چیه", "شد", "بود",
    "است", "هست", "کرد", "رفت", "درک", "the", "of", "and", "in", "on", "is", "was", "when", "did", "who",
))


def _news_feed_urls() -> tuple:
    extra = [u.strip() for u in re.split(r"[\s,]+", os.environ.get("NEWS_FEEDS_EXTRA", "")) if u.strip().startswith("http")]
    return tuple(dict.fromkeys(_NEWS_FEEDS_DEFAULT + tuple(extra)))


def _news_key(t: str) -> str:
    """متن را برای مچ «بدون فاصله و نیم‌فاصله» یکدست می‌کند (خامنه‌ای = خامنه ای = خامنهای)."""
    t = (t or "").lower().translate(_NEWS_AR_MAP)
    t = re.sub(r"[\u200c\u200d\u200e\u200f\u064b-\u065f\u0640]", "", t)
    return re.sub(r"[\W_]+", "", t)


def _news_src_name(url: str) -> str:
    d = re.sub(r"^https?://(?:www\.)?", "", url).split("/")[0]
    return {"feeds.bbci.co.uk": "BBC فارسی", "rss.dw.com": "DW فارسی"}.get(d, d)


def _news_xml_text(el, *names) -> str:
    for ch in el:
        t = ch.tag.rsplit("}", 1)[-1] if isinstance(ch.tag, str) else ""
        if t in names:
            if t == "link" and not (ch.text or "").strip():
                return (ch.get("href") or "").strip()
            return (ch.text or "").strip()
    return ""


def _news_fetch_feed(url: str, force: bool = False) -> list:
    """یک فید RSS/RDF/Atom → [{title, body, href, date, src}] (با کش ۲ دقیقه‌ای؛ شکست هم کش می‌شود تا فید خراب هر بار معطل نکند)."""
    if not force and url in _NEWS_FEED_CACHE:
        return _NEWS_FEED_CACHE[url]
    items = []
    t0 = time.time()
    try:
        r = _ai_session.get(url, headers={**_BING_HEADERS, "Accept": "application/rss+xml, application/xml, text/xml, */*;q=0.5"},
                            timeout=4)
        if r.status_code != 200 or not r.content:
            raise RuntimeError(f"HTTP {r.status_code}")
        root = ET.fromstring(r.content[:1_500_000])
        src = _news_src_name(url)
        for it in root.iter():
            tag = it.tag.rsplit("}", 1)[-1] if isinstance(it.tag, str) else ""
            if tag not in ("item", "entry"):
                continue
            title = html.unescape(_news_xml_text(it, "title"))
            body = html.unescape(re.sub(r"<[^>]+>", " ", _news_xml_text(it, "description", "summary", "encoded", "content")))
            body = re.sub(r"\s+", " ", body).strip()
            if title or body:
                items.append({"title": title, "body": body[:350], "href": _news_xml_text(it, "link"),
                              "date": _web_fmt_date(_news_xml_text(it, "pubDate", "date", "published", "updated")), "src": src})
        logger.info(f"[NEWS] {src}: {len(items)} خبر ({time.time() - t0:.1f}s)")
    except Exception as e:
        logger.warning(f"[NEWS] فید {url[:60]} خوانده نشد: {_err_cause(e)}")
    _NEWS_FEED_CACHE[url] = items
    return items


_NEWS_WARM_LOCK = threading.Lock()
_NEWS_WARM_STARTED = False


def _news_warm_loop() -> None:
    """هر ۹۰ ثانیه فیدها را از قبل تازه می‌کند تا کش (۱۲۰ ثانیه) همیشه گرم باشد؛ اولین خواندنِ سرد از رندر ۳٫۵–۴٫۵ ثانیه طول می‌کشید."""
    while True:
        time.sleep(90)
        for u in _news_feed_urls():
            try:
                _news_fetch_feed(u, force=True)
            except Exception:
                pass


def _news_warm_start() -> None:
    global _NEWS_WARM_STARTED
    with _NEWS_WARM_LOCK:
        if _NEWS_WARM_STARTED:
            return
        _NEWS_WARM_STARTED = True
    threading.Thread(target=_news_warm_loop, name="news-warm", daemon=True).start()


def _search_news_feeds(query: str, max_results: int = 5) -> list:
    """خبرهای فیدهای ثابت که با کوئری مچ می‌شوند؛ تازه‌ترین اول. خالی = مچ نشد یا فید در دسترس نبود."""
    if not _NEWS_FEEDS_ON:
        return []
    _news_warm_start()
    from concurrent.futures import wait as _wait
    toks = [_news_key(w) for w in re.findall(r"[\w\u200c]+", query or "")]
    toks = [k for k in toks if len(k) >= 3 and k not in {_news_key(x) for x in _NEWS_STOP}]
    if not toks:
        return []
    fa = "".join(k for k in toks if re.search(r"[\u0600-\u06FF]", k))
    la = "".join(k for k in toks if not re.search(r"[\u0600-\u06FF]", k))
    need = max(1, -(-len(toks) * 3 // 5))           # ceil(0.6 * n)
    futs = [_NEWS_POOL.submit(_news_fetch_feed, u) for u in _news_feed_urls()]
    _wait(futs, timeout=5)
    scored = []
    for f in futs:
        try:
            rows = f.result(timeout=0) if f.done() else []
        except Exception:
            rows = []
        for r in rows:
            key = _news_key(f"{r['title']} {r['body']}")
            phrase = (len(fa) >= 5 and fa in key) or (len(la) >= 5 and la in key)
            hits = sum(1 for k in toks if k in key)
            if phrase or hits >= need:
                scored.append((2 if phrase else 1, r.get("date") or "", r))
    scored.sort(key=lambda x: (x[0], x[1]), reverse=True)
    out = [x[2] for x in scored[:max_results]]
    logger.info(f"[NEWS] کوئری={query[:40]!r} مچ={len(scored)} برگشتی={len(out)}")
    return out


def _search_web(query: str, max_results: int = 5, fresh=None, event: bool = False, _relaxed: bool = False) -> list:
    """موتور جستجوی ربات: چند منبع هم‌زمان (نه پشت‌سرهم).
    • سؤال معمولی: DuckDuckGo + بینگ RSS + Yahoo + Mojeek (+ DDG-HTML اگر ddgs نبود/خالی داد)؛ نتایج ترکیب، بی‌تکرار و بر اساس
      ربط به سؤال مرتب می‌شوند.
    • سؤال «آخرین/جدیدترین/الان» (fresh): اول خبرِ DuckDuckGo و Google News (تاریخ‌دار، مرتب از تازه)، بعد متن و بقیه.
    تا «دو» موتور جواب ندهند (یا _total تمام نشود) کمی بیشتر صبر می‌کنیم؛ قبلاً بعد از اولین جواب فقط ۱٫۵ ثانیه بود و نتیجهٔ بی‌ربطِ
    اولین موتور تنها چیزی می‌شد که ربات می‌دید.
    خروجی: [{title, body, href, date, src}]؛ هیچ‌کدام جواب ندادند → جستجوی بدون گیومه/عملگر، بعد اسکرپ HTML بینگ."""
    from concurrent.futures import wait, FIRST_COMPLETED
    t0 = time.time()
    if fresh is None:
        fresh = _web_is_fresh(query)
    qc = _web_clean_q(query)          # نسخهٔ بدون نیم‌فاصله برای بینگ/گوگل‌نیوز/یاهو
    fetch_n = max(max_results, 8)     # از هر موتور بیشتر می‌گیریم؛ بعد از رتبه‌بندی به max_results بریده می‌شود
    jobs = {}
    # event=True (فوت/کشته‌شدن…): منبع‌های خبر هم اجرا می‌شوند ولی مرتب‌سازی بر اساس تاریخ نه (مقالات تازهٔ بی‌ربط بالا نیایند)
    if fresh or event:
        jobs["feeds"] = _WEB_POOL.submit(_search_news_feeds, query, max_results)      # فید خبرگزاری‌ها: سریع و مستقیم، اول لیست
        jobs["ddg-news"] = _WEB_POOL.submit(_search_ddg, query, max_results, True)
        jobs["gnews"] = _WEB_POOL.submit(_search_gnews, qc, max_results)
    jobs["ddg"] = _WEB_POOL.submit(_search_ddg, query, fetch_n)
    jobs["bing"] = _WEB_POOL.submit(_search_bing_rss, qc, fetch_n)
    if _WEB_EXTRA_ON:
        jobs["yahoo"] = _WEB_POOL.submit(_search_yahoo, qc, fetch_n)
        if not (fresh or event):
            jobs["mojeek"] = _WEB_POOL.submit(_search_mojeek, qc, fetch_n)
        if _DDGS is None:                                    # ddgs نصب نیست: نسخهٔ HTML جایگزین است
            jobs["ddg-html"] = _WEB_POOL.submit(_search_ddg_html, query, fetch_n)
    if event:
        _lat = re.findall(r"[A-Za-z][A-Za-z.\-']*", query)
        qen = " ".join(_lat)
        if len(_lat) >= 2 and qen.lower() != qc.lower() and re.search(r"[\u0600-\u06FF]", qc):
            jobs["bing-en"] = _WEB_POOL.submit(_search_bing_rss, qen, max_results)       # فقط بخش لاتینِ کوئری (Ali Khamenei death)
            jobs["gnews-en"] = _WEB_POOL.submit(_search_gnews, qen, max_results)
    music_q = _web_music_query(query) if fresh else ""
    if music_q:
        jobs["ddg-music"] = _WEB_POOL.submit(_search_ddg, music_q, max_results)
        jobs["bing-music"] = _WEB_POOL.submit(_search_bing_rss, music_q, max_results)
    _plain = not (fresh or event)
    _grace = max(_WEB_DDG_GRACE, 3.0) if music_q else (max(_WEB_DDG_GRACE, _WEB_PLAIN_GRACE) if _plain else _WEB_DDG_GRACE)
    _grace2 = 1.5                    # بعد از موتور دوم هم کمی صبر می‌کنیم (موتور سوم ممکن است همان نتیجهٔ مرتبط را داشته باشد)
    _total = _WEB_TOTAL_TIMEOUT      # (برای رویداد بیشتر صبر نمی‌کنیم: فیدهای خبری سریع‌اند و DDG روی رندر گاهی ۱۰+ ثانیه طول می‌کشد)

    def _is_hit(lst) -> bool:
        # در حالت رویداد، فقط نتیجهٔ مرتبط (دارای کلمهٔ فوت/کشته…) «اولین نتیجه» حساب می‌شود، نه هر نتیجهٔ بی‌ربط
        return any(_web_is_event_hit(r) for r in lst) if event else bool(lst)

    def _res(f) -> list:
        try:
            return (f.result(timeout=0) if f.done() else []) or []
        except Exception:
            return []

    pending = set(jobs.values())
    hits, first_hit, second_hit = 0, None, None
    try:
        while pending:
            now = time.time()
            left = _total - (now - t0)
            if second_hit is not None and _plain:
                left = min(left, _grace2 - (now - second_hit))
            elif first_hit is not None:
                left = min(left, _grace - (now - first_hit))
            if left <= 0:
                break
            done, pending = wait(pending, timeout=left, return_when=FIRST_COMPLETED)
            if not done:
                break
            for f in done:
                if f is jobs.get("ddg") and not _res(f) and _WEB_EXTRA_ON and "ddg-html" not in jobs and _web_eng_ok("ddg-html"):
                    jobs["ddg-html"] = _WEB_POOL.submit(_search_ddg_html, query, fetch_n)      # DDG خالی/ریت‌لیمیت ← نسخهٔ HTML
                    pending.add(jobs["ddg-html"])
                if _is_hit(_res(f)):
                    hits += 1
                    if first_hit is None:
                        first_hit = time.time()
                    if hits >= 2 and second_hit is None:
                        second_hit = time.time()
            if _plain and pending and _web_good_count(qc, [r for ff in jobs.values() for r in _res(ff)]) >= 3:
                break                # ≥۳ نتیجهٔ واقعاً مرتبط رسید؛ منتظر بقیه نمی‌مانیم
    except Exception as e:
        logger.warning(f"[WEB] خطا در انتظار نتایج: {_err_cause(e)}")
    limit = max_results + 2 if fresh else max_results
    if fresh:
        # تازه‌ترین تاریخ اول (نتایج بی‌تاریخ آخر)؛ سقف بعد از مرتب‌سازی اعمال می‌شود تا خبر تازه حذف نشود.
        # نتایج بی‌تاریخ اول از روی متنشان تاریخ می‌گیرند (شمسی هم) تا بالاتر از خبر قدیمی بنشینند.
        res = sorted(_web_interleave([_web_fill_dates(_res(f)) for f in jobs.values()], limit * (3 if music_q else 2)),
                     key=lambda x: x.get("date") or "", reverse=True)[:limit]
    elif event:
        res = _web_interleave([_res(f) for f in jobs.values()], limit * 2)
        res = sorted(res, key=lambda r: not _web_is_event_hit(r))[:limit]      # مرتبط‌ها اول (مرتب‌سازی پایدار)
    else:
        res = _web_rerank(qc, _web_interleave([_res(f) for f in jobs.values()], limit * 3))[:limit]
    logger.info("[WEB] fresh=%s event=%s %s %.1fs -> %d | top: %s" % (
        fresh, event, " ".join(f"{k}={len(_res(f)) if f.done() else 'pending'}" for k, f in jobs.items()), time.time() - t0, len(res),
        " || ".join(f"{r.get('date') or '-'} {(r.get('title') or '')[:40]}" for r in res[:3])))
    if res:
        return res
    if time.time() - t0 < _total - 2:      # همه زود و خالی برگشتند (نه تایم‌اوت): اسکرپ HTML بینگ
        r2 = _search_bing_html(qc, max_results)
        if r2:
            return r2
    if not _relaxed:                       # جستجوی دقیق (گیومه/عملگر) هیچ نداد ← یک بار بدون گیومه
        rq = _web_relax_query(qc)
        if rq and rq != qc and len(rq) >= 3:
            logger.info(f"[WEB] بدون نتیجه؛ تلاش دوباره بدون گیومه/عملگر: {rq[:60]!r}")
            return _search_web(rq, max_results, fresh=fresh, event=event, _relaxed=True)
    return []


def _web_results_text(results: list) -> str:
    """نتایج وب → متن برای مدل؛ دامنهٔ منبع و تاریخ (اگر دارد) هم نوشته می‌شود (متن‌ترانه ≠ کپشن اینستاگرام)."""
    parts = []
    for r in results:
        dom = re.sub(r"^https?://(?:www\.)?", "", r.get("href") or "").split("/")[0]
        if "news.google.com" in dom:
            dom = ""
        p = f"منبع: {r.get('src') or dom}"
        if r.get("date"):
            p += f"\nتاریخ: {r['date']}"
        _href = (r.get("href") or "").strip()
        _lnk = f"\nلینک: {_href[:200]}" if (_href.startswith("http") and "news.google.com" not in _href) else ""
        parts.append(f"{p}\nعنوان: {r['title']}\nمتن: {r['body']}{_lnk}")
    return "\n---\n".join(parts)[:6000]


def _web_merge(*lists) -> list:
    seen, out = set(), []
    for lst in lists:
        for r in lst:
            k = _web_canon_url(r.get("href") or "") or r["title"]
            if k not in seen:
                seen.add(k)
                out.append(r)
    return out


# ---- جستجوی وب برای «هر پیامی که به اینترنت نیاز دارد» (نه فقط آهنگ) ----
# وقتی تشخیص نیت (intent["web"]) بگوید پیام به وب نیاز دارد، پایتون با DuckDuckGo جستجو می‌کند و نتایج به پرامپت سیستم
# اضافه می‌شود؛ هر مدلی (گروک یا جمینی، حتی بدون ابزار وب خودش) از همین نتایج جواب می‌دهد.
# .env: WEB_SEARCH_DDG=0 → خاموش
_WEB_DDG_ON = os.environ.get("WEB_SEARCH_DDG", "1").strip().lower() not in ("0", "false", "off", "no")
# جستجوی وب برای گپ و محاوره (خبر، ورزش، «آخرین/جدیدترین ...»، اطلاعات عمومی، ...). پیش‌فرض روشن است؛ وقتی خاموش بود
# مدل سؤال‌های تازه («آخرین آهنگ فلانی») را از حافظهٔ قدیمی خودش جواب می‌داد. خاموش‌کردن: WEB_SEARCH_CHAT=0 در .env
# (اگر در پنل Render این متغیر را قبلاً روی 0 گذاشته‌ای، حذفش کن یا روی 1 بگذار.)
_WEB_CHAT_SEARCH = os.environ.get("WEB_SEARCH_CHAT", "1").strip().lower() in ("1", "true", "on", "yes")
_WEB_CTX_CACHE = TTLCache(maxsize=200, ttl=300)
_WEB_FAIL_NOTE = """توجه: جستجوی وب ربات همین حالا نتیجه‌ای برنگرداند. اگر ابزار جستجوی خودت داری با آن جستجو کن.
اگر نداری، دربارهٔ چیزهای تازه (آخرین آهنگ/خبر/نتیجه/قیمت یا کارهای جدید یک آدم) از حافظه جواب نده و حدس نزن؛ کوتاه و صادقانه بگو
الان نتونستم اطلاعات تازه‌اش رو پیدا کنم و پیشنهاد بده کمی بعد دوباره بپرسد یا اسم دقیق‌تری بنویسد.
نگو «کاری نکرده/چیزی منتشر نکرده»؛ نبودنِ اطلاعات در حافظهٔ تو دلیل نبودنِ اتفاق نیست."""
_WEB_CTX_RULES = """نتایج جستجوی زندهٔ وب برای همین پیام (چند لحظه پیش گرفته شده):
{results}

{today}

قواعد استفاده: اگر نتایج به سؤال کاربر مربوط است، جواب را از همین‌ها بساز و عدد و نام را فقط از همین‌ها بگو.
بعضی نتایج «تاریخ» دارند (تاریخ شمسی سایت‌ها به میلادی تبدیل شده؛ مثلاً 1405 شمسی = 2026 میلادی). برای سؤال‌های
«آخرین/جدیدترین/الان» نتیجه‌ای را مبنا بگیر که تاریخ‌اش از همه تازه‌تر است و کوتاه بگو مربوط به کی است. چیزی را که
قدیمی‌تر از نتیجهٔ تازه‌تر است «آخرین» نخوان. اگر نتایج چیزی تازه‌تر از دانستهٔ قدیمی خودت نشان می‌دهد، همان را بگو و
حرف حافظه‌ات («فلانی دیگه کار جدید نداده» یا «آخرینش فلان سال بود») را تکرار نکن.
عنوان صفحه‌های دانلود آهنگ معمولاً «دانلود آهنگ جدید <خواننده> به نام <آهنگ>» است؛ نام آهنگ و خواننده را از همین عنوان بگیر.
اگر نتایج بی‌ربط یا ناکافی بود صادقانه بگو دقیق پیدا نکردی؛ از حافظه عدد و اسم نساز. لینک نده."""


_WEB_Q_LEAD_RE = re.compile(
    r"^(?:(?:ببین(?:ید)?|بگو(?:ید)?|بگین|لطفا|لطفاً|میشه|می‌شه|می ?خوام(?: بدونم)?|بدونم|بهم|برام|یه|یک|راستی|خب|خوب|عالیم عالی)\s+)+")
_WEB_Q_TAIL_RE = re.compile(r"(?:\s+(?:چیه|چیست|چی بود|چی هست|چی شد|کیه|کیست|چطوره|چطور است|هست|هستش|بگو|بده))+$")


# موتورهای جستجو و خبرگزاری‌ها «درگذشت/فوت» می‌نویسند، نه «به درک رفت»؛ با کوئری محاوره‌ای فقط ویدیوهای قدیمی می‌آمد.
_WEB_SLANG = (
    (re.compile(_AI_FA_LEFT + r"(?:به ?درک ?(?:رفت|واصل ?شد)|رفت ?به ?درک|واصل ?(?:شد|شده)|رفت ?پی ?کارش)"
                r"" + _AI_FA_RIGHT + r""), "درگذشت فوت"),
    (re.compile(_AI_FA_LEFT + r"(?:کی|چه ?روزی) و چه ?ساعتی" + _AI_FA_RIGHT + r""), "تاریخ و ساعت"),
)


# رویداد «فوت/کشته‌شدن»: کلمه‌های کوئری و کلمه‌هایی که یک نتیجهٔ مرتبط باید در عنوان/متنش داشته باشد (فارسی + انگلیسی)
_WEB_DEATH_Q_RE = re.compile(r"درگذشت|فوت|مرگ|رحلت|به ?درک|کشته|ترور|شهادت|شهید|اعدام")
_WEB_DEATH_HIT = ("درگذشت", "فوت", "مرگ", "رحلت", "کشته", "ترور", "شهادت", "شهید", "اعدام",
                  "killed", "dead", "death", "dies", "died", "assassinat", "funeral")


def _web_query_from(user_text: str, reply_ctx: str = "") -> str:
    t = _ai_norm_fa(user_text or "")
    t = re.sub(r"@\w+", " ", t)
    t = re.sub(r"(?:^|\s)نخود(?=\s|$|[،,:])", " ", t)
    t = re.sub(r"\s+", " ", t).strip(" \t\n،,:؛;؟?!.-«»\"'")
    t = t.replace("اخرین", "آخرین").replace("اهنگ", "آهنگ")
    for _slang_re, _slang_to in _WEB_SLANG:      # محاوره‌ای → عبارتی که خبرگزاری‌ها می‌نویسند («به درک رفت» → «درگذشت»)
        t = _slang_re.sub(_slang_to, t)
    for _ in range(2):      # فعل‌های اضافه‌ی ابتدا و «چیه؟» آخر جمله، کوئری جستجو را خراب می‌کنند
        t2 = _WEB_Q_LEAD_RE.sub("", t).strip()
        t2 = _WEB_Q_TAIL_RE.sub("", t2).strip(" \t\n،,:؛;؟?!.-")
        t2 = re.sub(r"\s+که\s+", " ", t2)
        t = t2 if len(t2.split()) >= 2 else t
    if len(t.split()) < 4 and reply_ctx:       # «این چیه؟» روی یک پیام ریپلای → متن پیام ریپلای‌شده هم در سرچ بیاید
        m = re.search(r"«(.+?)»", reply_ctx, re.S)
        if m:
            t = (re.sub(r"\s+", " ", m.group(1)).strip()[:120] + " " + t).strip()
    return t[:200]


def _build_web_context(user_text: str, reply_ctx: str = "", q_hint: str = "", fresh=None) -> str:
    """نتایج جستجوی وب → بلوک متنی برای پرامپت سیستم (رشتهٔ خالی = چیزی پیدا نشد/خاموش).
    q_hint = کوئریِ جستجوی ساخته‌شده توسط مدل تشخیص نیت (کوتاه و هدفمند؛ بهتر از جملهٔ خام کاربر)،
    fresh = سؤال «آخرین/جدیدترین/الان» است (None → با regex از متن تشخیص می‌دهد)."""
    if not (_WEB_DDG_ON and _web_search_available()):
        return ""
    q = re.sub(r"\s+", " ", (q_hint or "")).strip(" \t\n،,:؛;؟?!.-«»\"'")[:160]
    if len(q) < 3:
        q = _web_query_from(user_text, reply_ctx)
    if len(q) < 3:
        return ""
    fresh = bool(fresh) or _web_is_fresh(user_text)
    # «فلانی کی/چه ساعتی فوت کرد؟»: مدل تشخیص نیت گاهی فقط اسم را به‌عنوان کوئری می‌دهد («علی خامنه ای») و جستجوی «تازه‌ترین اول»
    # مقالات جدیدِ بی‌ربط (تولد، بیوگرافی) را بالا می‌آورد و خبر اصلی (ماه‌ها قبل) کنار می‌رود. پس: کلمهٔ رویداد از پیام خود کاربر
    # به کوئری اضافه می‌شود، ترتیب تاریخ برای این رویداد یک‌باره خاموش می‌شود و نتایج بی‌ربط به رویداد کنار گذاشته می‌شوند.
    death = False
    try:
        _uq = _web_query_from(user_text, reply_ctx)
        death = bool(_WEB_DEATH_Q_RE.search(_uq) or _WEB_DEATH_Q_RE.search(q))
        if death and not _WEB_DEATH_Q_RE.search(q):
            q = (q + " درگذشت").strip()[:160]
    except Exception as e:
        logger.warning(f"[WEB-DDG] event-guard failed: {_err_cause(e)}")
    if death:
        fresh = False
    ck = _song_norm(q) + ("|f" if fresh else "") + ("|e" if death else "")
    if ck in _WEB_CTX_CACHE:
        return _WEB_CTX_CACHE[ck]
    t0 = time.time()
    res = _search_web(q, 5, fresh=fresh, event=death)
    if death and res:
        # قبلاً اگر هیچ نتیجه‌ای کلمهٔ رویداد نداشت همان نتایج بی‌ربط (علی/بلیط علی‌بابا…) به مدل داده می‌شد.
        # حالا خالی می‌شود تا مسیر فالبک (گروک با وب خودش) فعال شود، نه اینکه مدل با آشغال «پیدا نکردم» بگوید.
        _n_all = len(res)
        res = [r for r in res if _web_is_event_hit(r)]
        if not res:
            logger.info(f"[WEB-DDG] رویداد: از {_n_all} نتیجه هیچ‌کدام مرتبط نبود؛ نتایج دور ریخته شد")
    try:
        _today = calendar_today_line()
    except Exception:
        _today = ""
    block = (_WEB_CTX_RULES.replace("{results}", _web_results_text(res)).replace("{today}", _today)
             if res else "")
    logger.info(f"[WEB-DDG] q={q[:50]!r} fresh={fresh} results={len(res)} took={time.time() - t0:.1f}s")
    if block:
        _WEB_CTX_CACHE[ck] = block      # شکست را کش نکن (rate-limit موقتی است)
    return block


_SONG_SNIPPET_PROMPT = """You extract song information ONLY from the web search results below. Never use your memory.

LINE: «{phrase}»
{hint}
SEARCH RESULTS:
{web}

Rules:
1. A result is evidence only if its text contains the LINE (at most 2 words different). Copy that wording EXACTLY from the
   results into "matched_text" (max 14 words). If no result contains it -> found=false.
2. "song_title" = ONLY the bare song name, taken from a result's title/heading/track list. Page titles are often wrapped
   like «متن آهنگ X از Y» or «دانلود آهنگ X - Y»: return just X. Never include the singer's name or words like آهنگ / متن آهنگ /
   دانلود / موزیک inside song_title. The lyric LINE itself is NEVER a title. If no result states the title -> null.
   IMPORTANT: Persian lyric sites often use the OPENING WORDS of the lyrics as the page title (e.g. «متن آهنگ <first line> از Y»).
   The real song title is usually SHORT (1-3 words) and appears next to the singer in other results ("Y - X", "Y _ X + متن",
   Latin spelling in parentheses, track lists). When a short title like that exists, return it instead of the long opening-words title.
3. "singer" only if a result says who sings/performed the song. Hashtags, video captions, comments, challenge/reel
   posts and "used with" mentions are NOT evidence -> null.
4. A line can be a poem (poet) AND a song at the same time. Never invent singer, lyricist, composer or title.

Output ONE JSON object only (no markdown, no other text):
{{"found":true|false,"song_title":null,"singer":null,"poem_title":null,"poet_or_lyricist":null,"composer":null,
"matched_text":null,"line_differs_from_source":null,"others":[],"confidence":"high|medium|low"}}"""

_SONG_GEMINI_PROMPT = """با استفاده از ابزار Google Search عبارت زیر را دقیقاً در وب (به‌ویژه سایت‌های متن ترانه فارسی، گنجور، سینما و ادبیات) جستجو کن:
"{phrase}"

وظیفه تو:
1. اگر ترانه/آهنگ است: نام آهنگ، نام خواننده و در صورت مشخص بودن نام ترانه‌سرا را مشخص کن.
2. اگر شعر کهن است (حافظ، سعدی، مولانا و...): نام شاعر و مطلع شعر را بگو، و اگر خواننده‌ای آن را اجرا کرده نامش را ذکر کن.
3. اگر دیالوگ، کتاب یا فیلم است: نام اثر و صاحب اثر یا شخصیت گوینده را مشخص کن.
4. هرگز از حافظه حدس نزن. فقط در صورتی که این متن دقیقاً در منبع یافت شد جواب بده. اگر پیدا نشد فقط بگو «پیدا نشد».

پاسخ را بسیار مرتب، صمیمی، بدون مقدمه‌چینی و حداکثر در ۳ یا ۴ خط به این فرمت بنویس:
🎵 اثر: [نام آهنگ/شعر/فیلم/کتاب]
👤 صاحب اثر / خواننده: [نام خواننده یا نویسنده یا شاعر]
📝 توضیحات کوتاه: [یک خط توضیح یا تفاوت املایی متن اگر وجود داشت]"""


def _song_gemini_ask(prompt: str, search_web: bool = False, max_tokens: int = 600):
    """یک سؤال به جمینی با چرخش کلید/مدل. search_web=True → Google Search (فقط جواب «گراندینگ‌شده» قبول می‌شود).
    برمی‌گرداند: متن جواب، یا None اگر هیچ کلید/مدلی جواب نداد."""
    keys = _ai_keys_of("gemini")
    if not keys:
        return None
    messages = [{"role": "user", "content": prompt}]
    models = list(GEMINI_MODELS) or ["gemini-2.5-flash", "gemini-1.5-flash"]
    deadline = time.time() + _SONG_GEMINI_BUDGET
    _cdp = "gemini-search" if search_web else "gemini-song"     # کول‌دان جدا از چت عادی
    for _ in range(len(keys)):
        slot = _next_ai_slot("gemini")
        if not slot:
            break
        _, key = slot
        if _AI_DEAD_KEYS.get(key, 0) > time.time():
            continue
        for model in models:
            if time.time() > deadline:
                logger.warning("[SONG-GEMINI] بودجهٔ زمانی تمام شد")
                return None
            if max(_AI_MODEL_COOLDOWN.get((_cdp, model), 0), _AI_MODEL_COOLDOWN.get((_cdp, model, key), 0)) > time.time():
                continue
            try:
                r = _ai_http_post("gemini", key, model, messages, max_tokens, 0.1,   # دمای پایین = کمتر توهم
                                  (10, max(_AI_GEMINI_TIMEOUT, 25)), vision=False, search_web=search_web)
                if r.status_code == 200:
                    data = r.json() or {}
                    content = (((data.get("choices") or [{}])[0].get("message") or {}).get("content") or "").strip()
                    content = _ai_strip_think(content)
                    if not content:
                        continue
                    if search_web and not data.get("_grounded"):
                        logger.warning(f"[SONG-GEMINI] {model} بدون گراندینگ جواب داد — رد شد")
                        continue
                    return content
                if r.status_code in (400, 401, 403) and _body_says_bad_key(r.text):
                    _AI_DEAD_KEYS[key] = time.time() + _AI_DEADKEY_SEC
                    logger.warning(f"[SONG-GEMINI] key rejected ({_mask_key(key)}) — skipped for 1h")
                    break
                if r.status_code in (400, 404):
                    _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_MODELGONE_SEC
                elif r.status_code == 429:
                    _AI_MODEL_COOLDOWN[(_cdp, model, key)] = time.time() + _AI_RATELIMIT_SEC
                else:
                    _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_BUSY_SEC
                logger.warning(f"[SONG-GEMINI] {model} {r.status_code} :: {_err_brief(r.text, 300)}")
            except requests.exceptions.ConnectionError as e:
                logger.warning(f"[SONG-GEMINI] خطای شبکه :: {_err_cause(e)}")
                return None
            except requests.exceptions.Timeout:
                _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_BUSY_SEC
                logger.warning(f"[SONG-GEMINI] {model} timeout")
            except Exception as e:
                logger.warning(f"[SONG-GEMINI] خطا روی مدل {model}: {_err_cause(e)}")
    return None


def _song_clean_answer(content):
    """جواب جمینی → متن نهایی، یا None اگر «پیدا نشد»/خیلی کوتاه بود."""
    if not content or ("پیدا نشد" in content and "🎵" not in content) or len(content) <= 15:
        return None
    return _ai_strip_markdown(_force_latin_digits(content))


# ---------------------------------------------------------------------------
# تأیید با «متن واقعی آهنگ» (lyrics_service.py) — جلوی اسم‌های ساختگیِ وب/مدل را می‌گیرد
#   SONG_LYRIC_SEARCH=0   جستجوی تمام‌متن (Genius) خاموش
#   SONG_LYRIC_VERIFY=0   تأیید/اصلاح اسم آهنگ با متن آهنگ‌های خواننده (LRCLIB) خاموش
# ---------------------------------------------------------------------------
_SONG_LYSEARCH_ON = os.environ.get("SONG_LYRIC_SEARCH", "1").strip().lower() not in ("0", "false", "off", "no")
_SONG_VERIFY_ON = os.environ.get("SONG_LYRIC_VERIFY", "1").strip().lower() not in ("0", "false", "off", "no")
_LYS_ARTIST_CACHE = TTLCache(maxsize=300, ttl=24 * 3600)
_LYS_ARTIST_PROMPT = (
    "Give the spellings under which this singer/band name is published on Spotify / Genius / lyrics databases.\n"
    "NAME: {n}\n"
    "Return up to 3 spellings: the standard Latin/English one and the original-script (e.g. Persian) one, "
    "different from the NAME itself. If unsure, return an empty list. Reply ONLY with JSON: {{\"names\": [\"...\"]}}"
)


def _lys_artist_names(name: str) -> list:
    """املاهای دیگر اسم خواننده (فارسی ↔ لاتین) برای جستجو در پایگاه متن آهنگ؛ خطا/نبودن کلید ← []."""
    key = _song_norm(name)
    if not key or not _ai_keys_of("gemini"):
        return []
    if key in _LYS_ARTIST_CACHE:
        return _LYS_ARTIST_CACHE[key]
    out = []
    try:
        raw = _song_gemini_ask(_LYS_ARTIST_PROMPT.format(n=(name or "")[:80].replace("{", "").replace("}", "")), False, 150)
        d = _song_json(raw or "") or {}
        names = d.get("names") if isinstance(d.get("names"), list) else []
        out = [x.strip()[:60] for x in names if isinstance(x, str) and x.strip()][:3]
        _LYS_ARTIST_CACHE[key] = out
    except Exception as _e:
        logger.warning(f"[SONG-LYR] artist names خطا :: {_err_cause(_e)}")
    return out


# ---- نتیجهٔ آهنگ‌یاب همیشه لاتین/فینگلیش (تا جستجوی لینک اسپاتیفای/اپل/ساوندکلود با متن فارسی انجام نشود) ----
_SONG_FA_RE = re.compile(r"[\u0600-\u06FF\u0750-\u077F\uFB50-\uFDFF\uFE70-\uFEFF]")
_SONG_LATIN_CACHE = TTLCache(maxsize=800, ttl=6 * 3600)
_SONG_LATIN_PROMPT = (
    "A Telegram bot found a song. The text below may be Persian/Arabic, and the title and the singer may be MERGED "
    "in one string (e.g. a web page title).\n"
    "TITLE: {t}\nARTIST: {a}\n\n"
    "Split them into the real song title and the real singer, and write BOTH in Latin letters exactly the way "
    "Spotify / Apple Music list them (official English spelling if you know it; otherwise the common Finglish "
    "transliteration, e.g. Persian letters -> Latin). Use ONLY the given text, never invent a singer. "
    "Example: TITLE=\"متن آهنگ تیمار امیر تتلو\" -> {{\"title\": \"Timar\", \"artist\": \"Amir Tataloo\"}}.\n"
    "Reply ONLY with JSON: {{\"title\": \"...\", \"artist\": \"...\"}} (artist may be empty only if it is truly absent)."
)


def _song_latinize(title: str, artist: str = ""):
    """(اسم آهنگ، خواننده) را به نوشتار لاتین تبدیل می‌کند و اگر هر دو در یک رشته بودند («نصف شب علی یاسینی») جدا می‌کند.
    قبلاً لاتین بود ← بدون تغییر؛ خطا/نبودن کلید ← ورودی همان‌طور برمی‌گردد."""
    title, artist = (title or "").strip(), (artist or "").strip()
    if title and artist and not _SONG_FA_RE.search(title + artist):
        return title, artist
    if not title or not _ai_keys_of("gemini"):
        return title, artist
    ck = _song_norm(f"{artist} | {title}")
    if ck in _SONG_LATIN_CACHE:
        return _SONG_LATIN_CACHE[ck]
    res = (title, artist)
    try:
        raw = _song_gemini_ask(_SONG_LATIN_PROMPT.format(t=title[:120].replace("{", "").replace("}", ""),
                                                          a=artist[:80].replace("{", "").replace("}", "")), False, 200)
        d = _song_json(raw or "") or {}
        t2, a2 = _song_s(d.get("title")), _song_s(d.get("artist"))
        if t2 and not _SONG_FA_RE.search(t2) and not _SONG_FA_RE.search(a2):
            res = (t2[:80], a2[:80])
            _SONG_LATIN_CACHE[ck] = res
    except Exception as _e:
        logger.warning(f"[SONG] لاتین‌سازی خطا :: {_err_cause(_e)}")
    return res


def _song_head(title: str, artist: str = "", sure: bool = True) -> str:
    """قالب یکدستِ جواب: «Title» از Artist  (هیچ‌وقت «از» خالی نمی‌ماند؛ همیشه لاتین)."""
    title, artist = _song_latinize(title, artist)
    base = f"«{title}» از {artist}" if artist else f"«{title}»"
    return base if sure else f"فکر کنم {base} باشه (مطمئن نیستم)"



def _song_lyrics_identify(phrase: str):
    """جستجوی تمام‌متن (Genius) که بیت را در خودِ متن آهنگ‌ها می‌گردد؛ فقط اگر «تأیید با متن» شد جواب می‌دهد، وگرنه None."""
    if not (_HAS_LYRSVC and _SONG_LYSEARCH_ON and _ls_identify and phrase):
        return None
    r = _ls_identify(phrase, name_fn=_lys_artist_names)
    if not r:
        return None
    _rt = str(r.get("title") or "")
    if len(_rt.split()) >= 4 and _song_phrase_hit(phrase, _rt, 0.7):
        logger.warning(f"[SONG-LYR] عنوانِ پیشنهادی خودِ مصرع است ← رد شد: {_rt[:50]!r}")
        return None
    logger.info(f"[SONG-LYR] تأیید با متن: {r.get('artist')} - {r.get('title')} ({r.get('source')} {r.get('score', 0):.2f} "
                f"conf={r.get('confidence', 'high')})")
    return _song_head(r.get("title"), r.get("artist"), sure=(r.get("confidence") != "low"))   # low = فقط یک سایت اسم را داده


# منبع وبِ lyrics_service (صفحه‌های واقعی متن ترانه) از همان موتور جستجو و جمینیِ خودِ ربات استفاده می‌کند
if _HAS_LYRSVC and _ls_set_hooks:
    try:
        _ls_set_hooks(search_fn=lambda _q, _n=6: _search_web(_q, max(_n, 8), fresh=False),
                      llm_fn=lambda _p: _song_gemini_ask(_p, False, 300))
        _lw_mod = getattr(sys.modules.get("lyrics_service"), "_lweb", None)
        logger.info(f"[SONG-LYR] lyrics_web={'بارگذاری شد' if _lw_mod else 'بارگذاری نشد (lyrics_web.py کنار bot.py نیست یا خطا دارد)'}")
    except Exception as _hk_e:
        logger.warning(f"[SONG-LYR] ثبت هوک وب شکست خورد :: {_err_cause(_hk_e)}")


_SONG_OVERRIDE_MIN = 0.985      # حداقل امتیاز اسکن متن برای عوض‌کردنِ اسمی که از عنوان نتایج وب تأیید شده


def _song_verify_with_lyrics(d: dict, phrase: str) -> dict:
    """نتیجهٔ وب/مدل (خواننده + اسم آهنگ) را با متن واقعی آهنگ‌های همان خواننده می‌سنجد:
    بیت در آهنگِ دیگری بود ← اسم اصلاح می‌شود؛ در هیچ‌کدام نبود (و چندین متن بررسی شد) ← علامت «مطمئن نیستم»."""
    if not (_HAS_LYRSVC and _SONG_VERIFY_ON and _ls_scan):
        return d
    singer, song = _song_s(d.get("singer")), _song_s(d.get("song_title"))
    if not singer:
        return d
    try:
        r = _ls_scan(singer, phrase, titles=[song] if song else [], name_fn=_lys_artist_names)
    except Exception as _e:
        logger.warning(f"[SONG-LYR] scan خطا :: {_err_cause(_e)}")
        return d
    best, scanned = r.get("best"), int(r.get("scanned") or 0)
    need = 0.78 if len(_song_norm(phrase).split()) >= 4 else 0.9
    d = dict(d)
    if best and best["score"] >= need:
        t = best["title"]
        same = bool(song) and (_song_norm(t) == _song_norm(song)
                               or difflib.SequenceMatcher(None, _song_norm(t), _song_norm(song)).ratio() >= 0.7)
        if not same and song and best["score"] < _SONG_OVERRIDE_MIN:
            # اسمِ وب در عنوان نتایج دیده شده؛ اسکن متن آهنگ دیگری را پیشنهاد می‌دهد ولی قطعی نیست ← اسم وب می‌ماند،
            # فقط با «مطمئن نیستم» (قبلاً اسم درست «دو پنجره» با یک تطبیق ۰.۹۶ اشتباه عوض می‌شد)
            logger.info(f"[SONG-LYR] اسم وب حفظ شد: {song!r} (اسکن: {t!r} {best['score']:.2f} < {_SONG_OVERRIDE_MIN})")
            d["_unverified"] = True
            return d
        if not same:
            logger.info(f"[SONG-LYR] اسم اصلاح شد: {song!r} → {t!r} (امتیاز {best['score']:.2f})")
            d["song_title"] = t
        d["confidence"] = "high"
        d["_verified"] = True
    elif scanned >= 8:
        logger.info(f"[SONG-LYR] بیت در {scanned} آهنگ {singer!r} پیدا نشد ← بدون تأیید")
        d["_unverified"] = True
    return d


_SONG_SEG_SPLIT_RE = re.compile(r"\s*[_\-–—|+/:()\[\]،,·•]\s*")
_SONG_SEG_NOISE = {"متن", "آهنگ", "اهنگ", "ترانه", "دانلود", "موزیک", "ویدیو", "کلیپ", "جدید", "کامل", "lyrics", "lyric", "mp3",
                   "و", "با", "صدای", "از"}


def _song_shorten_title(song: str, singer: str, titles: list) -> str:
    """سایت‌های متن ترانه معمولاً مصرع اول را عنوان صفحه می‌کنند («متن آهنگ باران میبارد امشب از امید»)، در حالی که اسم واقعی
    آهنگ «باران» است. اگر اسمِ پیشنهادی ≥۲ کلمه است و در عنوان نتیجه‌ها یک نسخهٔ کوتاه‌تر (که ابتدای همان اسم است) درست کنار
    اسم خواننده آمده («امید _ باران + متن»)، همان کوتاه‌تر برگردانده می‌شود؛ وگرنه اسم دست‌نخورده می‌ماند."""
    st = _song_norm(song).split()
    sg = set(_song_norm(singer).split())
    if len(st) < 2 or not sg:
        return song
    sj = "".join(st)
    best = ""
    for raw in titles or []:
        segs = [x.strip() for x in _SONG_SEG_SPLIT_RE.split(raw or "") if x and x.strip()]
        norms = [_song_norm(x).split() for x in segs]
        for i, toks in enumerate(norms):
            if not toks or not set(toks) <= (sg | _SONG_SEG_NOISE):
                continue                                 # این بخش اسم خواننده نیست
            for j in (i - 1, i + 1):
                if not (0 <= j < len(norms)):
                    continue
                cand = [w for w in norms[j] if w not in _SONG_SEG_NOISE]
                cj = "".join(cand)
                if cand and len(cand) < len(st) and cj and sj.startswith(cj) and set(cand).isdisjoint(sg):
                    if not best or len(cj) < len("".join(best.split())):
                        best = " ".join(cand)
    return best or song


def _song_title_is_lyric(phrase: str, title: str) -> bool:
    """مدل گاهی خودِ بیت را به‌جای اسم آهنگ می‌گذارد؛ اگر «اسم» تقریباً همان بیت بود یعنی اسم واقعی را پیدا نکرده."""
    np_, nt = _song_norm(phrase), _song_norm(title)
    return bool(nt) and difflib.SequenceMatcher(None, np_, nt).ratio() >= 0.8


def _song_ddg_eval(d, phrase: str, web_text: str, titles_norm: str, titles_raw=None):
    """جواب JSON جمینی → (متن نهایی یا None, خوانندهٔ معتبر یا \"\")."""
    if not isinstance(d, dict) or not d.get("found") or not _song_phrase_hit(phrase, _song_s(d.get("matched_text"))):
        return None, ""
    # بیتی که مدل ادعا می‌کند باید واقعاً در متن نتایج باشد، نه ساختهٔ مدل
    if not _song_phrase_hit(phrase, web_text) or not _song_phrase_hit(_song_s(d.get("matched_text")), web_text, 0.8):
        return None, ""
    d = dict(d)
    song = _song_s(d.get("song_title"))
    if song and titles_raw:
        _short = _song_shorten_title(song, _song_s(d.get("singer")), titles_raw)
        if _short != song:
            logger.info(f"[SONG-WEB] عنوان کوتاه شد: {song!r} → {_short!r}")
            song = d["song_title"] = _short
    if song and (_song_title_is_lyric(phrase, song) or _song_norm(song) not in titles_norm):
        d["song_title"] = None          # اسمی که در عنوان هیچ نتیجه‌ای نیست = قابل‌اعتماد نیست
    d = _song_verify_with_lyrics(d, phrase)     # تأیید/اصلاح اسم آهنگ با متن واقعی آهنگ‌های همان خواننده
    singer = _song_s(d.get("singer")) if _song_s(d.get("confidence")).lower() in ("high", "medium") else ""
    return _song_format(d, phrase), singer


def _song_query_variants(phrase: str) -> list:
    """چند شکل جستجو برای یک بیت: دقیق، بدون گیومه، فقط کلمه‌های مهم، و برای بیت بلند نیمهٔ اول."""
    p = re.sub(r"\s+", " ", phrase or "").strip()
    ws = p.split()
    qs = [f'"{p}" متن آهنگ', f"{p} آهنگ"]
    core = [w for w in ws if len(_song_norm(w)) >= 3]
    if len(core) >= 3:
        qs.append(" ".join(core[:7]) + " متن ترانه")
    if len(ws) >= 9:
        qs.append('"' + " ".join(ws[:len(ws) // 2 + 1]) + '" متن آهنگ')
    return list(dict.fromkeys(qs))[:4]


def _song_ddg_gemini(phrase: str):
    """روش اول (رایگان): پایتون در وب جستجو می‌کند (DuckDuckGo) و جمینی (بدون ابزار سرچ ← بدون ۴۲۹) فقط از نتایج
    JSON استخراج می‌کند. اگر خواننده پیدا شد ولی اسم آهنگ نه، دور دوم با «خواننده + بیت» دقیقاً برای اسم آهنگ می‌گردد.
    برمی‌گرداند: (جواب کامل یا None, جملهٔ جزئی دربارهٔ خواننده یا None)."""
    if not (_SONG_WEB_ON and _web_search_available() and _ai_keys_of("gemini")):
        return None, None
    res = []
    for q in _song_query_variants(phrase)[:3]:
        r = _search_web(q, 8, fresh=False)
        res = _web_merge(res, r)
        if r and _song_phrase_hit(phrase, _web_results_text(r)):
            break
    web = _web_results_text(res)
    if not (web and _song_phrase_hit(phrase, web)):
        logger.info(f"[SONG-WEB] بیت در نتایج وب دیده نشد: {phrase[:30]!r}")
        return None, None

    def _ask(results, hint=""):
        text = _web_results_text(results)
        raw = _song_gemini_ask(_SONG_SNIPPET_PROMPT.replace("{phrase}", phrase).replace("{hint}", hint)
                               .replace("{web}", text).replace("{{", "{").replace("}}", "}"), False, 700)
        titles_norm = _song_norm(" | ".join(x["title"] for x in results))
        return _song_ddg_eval(_song_json(raw or ""), phrase, text, titles_norm, [x["title"] for x in results])

    ans, singer = _ask(res)
    if ans:
        logger.info(f"[SONG-WEB] پیدا شد (ddg+gemini): {phrase[:30]!r}")
        return ans, None
    if singer:
        # خواننده معلوم است ولی اسم آهنگ نه → دور دوم با خواننده + بیت
        _f1 = _WEB_OUTER_POOL.submit(_search_web, f'{singer} "{phrase}"', 5)
        _f2 = _WEB_OUTER_POOL.submit(_search_web, f"متن آهنگ {singer} {phrase}", 4)
        more = _web_merge(_f1.result(), _f2.result())
        ans2, _ = _ask(_web_merge(res, more), f"HINT: the singer is reportedly {singer}. Find the song's exact title.\n")
        if ans2:
            logger.info(f"[SONG-WEB] اسم آهنگ در دور دوم پیدا شد: {phrase[:30]!r}")
            return ans2, None
        logger.info(f"[SONG-WEB] خواننده پیدا شد ولی اسم آهنگ نه: {singer!r}")
        return None, f"خواننده‌ش فکر کنم {singer} باشه، ولی اسم دقیق آهنگ رو پیدا نکردم."
    return None, None


def _song_gemini_search(phrase: str):
    """اختیاری (SONG_GEMINI_SEARCH=1): Google Search خودِ جمینی."""
    if not (_SONG_GEMINI_ON and _ai_keys_of("gemini")):
        return None
    return _song_clean_answer(_song_gemini_ask(_SONG_GEMINI_PROMPT.format(phrase=phrase.replace('"', "'")), True, 600))


_SONG_GROQ_BUDGET = 45.0
_SONG_BUSY = "الان نتونستم جستجو کنم (سرویس‌ها شلوغن). چند دقیقه دیگه دوباره بپرس."


def _song_groq_search(user_text: str, phrase: str):
    """فالبک آخر: جستجوی وب گروک. فقط مدل‌هایی که واقعاً وب دارند (compound های .env + gpt-oss با browser_search)؛
    مدل بدون وب هرگز استفاده نمی‌شود چون از حافظه حدس می‌زند.
    برمی‌گرداند: متن جواب (شامل «پیدا نشد» قابل‌کش) یا None اگر هیچ مدل وبی جواب نداد."""
    keys = _ai_keys_of("groq")
    if not keys:
        return None
    prompt = _SONG_PROMPT.format(msg=(user_text or "")[:400].replace("«", "").replace("»", ""),
                                 phrase=phrase.replace("«", "").replace("»", ""))
    messages = [{"role": "user", "content": prompt}]
    models = list(GROQ_WEB_MODELS)
    for m in ("openai/gpt-oss-120b", "openai/gpt-oss-20b"):
        if m not in models:
            models.append(m)
    deadline = time.time() + _SONG_GROQ_BUDGET
    _cdp = "groq-search"
    for _ in range(len(keys)):
        slot = _next_ai_slot("groq")
        if not slot:
            break
        _, key = slot
        if _AI_DEAD_KEYS.get(key, 0) > time.time():
            continue
        for model in models:
            if time.time() > deadline:
                logger.warning("[SONG-GROQ] بودجهٔ زمانی تمام شد")
                return None
            if max(_AI_MODEL_COOLDOWN.get((_cdp, model), 0), _AI_MODEL_COOLDOWN.get((_cdp, model, key), 0)) > time.time():
                continue
            try:
                r = _ai_http_post("groq", key, model, messages, 2000, 0.1, (10, 60), vision=False, search_web=True)
                if r.status_code == 200:
                    data = r.json() or {}
                    msg = ((data.get("choices") or [{}])[0].get("message") or {})
                    content = _ai_strip_think((msg.get("content") or "").strip())
                    d = _song_json(content)
                    if d is None:
                        logger.warning(f"[SONG-GROQ] {model}: JSON نامعتبر (len={len(content)})")
                        continue
                    if _song_title_is_lyric(phrase, _song_s(d.get("song_title"))):
                        d["song_title"] = None
                    ans = _song_format(d, phrase) or _SONG_NOT_FOUND
                    logger.info(f"[SONG-GROQ] {model} phrase={phrase[:40]!r} found={bool(d.get('found'))} "
                                f"conf={d.get('confidence')} tools_used={len(msg.get('executed_tools') or [])} "
                                f"-> {'answer' if ans != _SONG_NOT_FOUND else 'not-found'}")
                    return ans
                if r.status_code in (400, 401, 403) and _body_says_bad_key(r.text):
                    _AI_DEAD_KEYS[key] = time.time() + _AI_DEADKEY_SEC
                    logger.warning(f"[SONG-GROQ] key rejected ({_mask_key(key)}) — skipped for 1h")
                    break
                if r.status_code in (400, 404):
                    _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_MODELGONE_SEC
                elif r.status_code == 429:
                    _AI_MODEL_COOLDOWN[(_cdp, model, key)] = time.time() + _AI_RATELIMIT_SEC
                else:
                    _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_BUSY_SEC
                logger.warning(f"[SONG-GROQ] {model} {r.status_code} :: {_err_brief(r.text, 300)}")
            except requests.exceptions.ConnectionError as e:
                logger.warning(f"[SONG-GROQ] خطای شبکه :: {_err_cause(e)}")
                return None
            except requests.exceptions.Timeout:
                _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_BUSY_SEC
                logger.warning(f"[SONG-GROQ] {model} timeout")
            except Exception as e:
                logger.warning(f"[SONG-GROQ] خطا روی مدل {model}: {_err_cause(e)}")
    return None


# ============================================================
# lyricsify.com — پیدا کردن آهنگ و گرفتن متن آهنگ
# سایت API رسمی ندارد؛ همان صفحه‌های HTML که مرورگر می‌بیند خوانده می‌شود:
#   سرچ:   GET {BASE}{SEARCH_PATH}?q=...            ← HTML نتایج (لینک‌ها به {LYRICS_PATH}/خواننده/آهنگ)
#   متن:   GET {BASE}{LYRICS_PATH}/خواننده/آهنگ     ← HTML صفحهٔ آهنگ
# دو کار:
#   ۱) «این آهنگ از کیه؟» ← قبل از جستجوی وب، چند نتیجهٔ lyricsify چک می‌شود؛ فقط وقتی بیت واقعاً در متنِ همان صفحه باشد جواب می‌دهد
#   ۲) «متن آهنگ X» / «آهنگ X رو بخون» / «X lyrics» ← متن آهنگ (تا LYRICSIFY_MAX_LINES خط + لینک ادامه)
# هر خطا (شبکه، بلاک شدن، تغییر قالب سایت) ← None/پیام تمیز؛ ربات هرگز کرش نمی‌کند و مسیر قبلی ادامه پیدا می‌کند.
# .env (همه اختیاری):
#   LYRICSIFY=0                 خاموش (هر دو کار)
#   LYRICSIFY_IDENTIFY=0        فقط بخش «این آهنگ از کیه» خاموش
#   LYRICSIFY_BASE_URL          پیش‌فرض https://www.lyricsify.com
#   LYRICSIFY_SEARCH_PATH       پیش‌فرض /search
#   LYRICSIFY_LYRICS_PATH       پیش‌فرض /lyrics
#   LYRICSIFY_TIMEOUT_SEC       پیش‌فرض 8
#   LYRICSIFY_MAX_LINES         پیش‌فرض 0 = بدون سقف خط (فقط سقف پیام تلگرام: ۴۰۹۶ − ۱ = ۴۰۹۵ کاراکتر)
#   LYRICSIFY_USER_AGENT        پیش‌فرض یک UA معمولی مرورگر
# ============================================================
from html.parser import HTMLParser as _LysHTMLParser

_LYS_ON = os.environ.get("LYRICSIFY", "1").strip().lower() not in ("0", "false", "off", "no")
_LYS_IDENTIFY_ON = os.environ.get("LYRICSIFY_IDENTIFY", "1").strip().lower() not in ("0", "false", "off", "no")
# اسکرپ مستقیم lyricsify (کلودفلر ← تقریباً همیشه ۴۰۳). پیش‌فرض خاموش مگر LYRICSIFY_PROXY ست شده باشد.
# متن آهنگ حالا از lyrics_service.py (LRCLIB + lyrics.ovh) می‌آید؛ LYRICSIFY_LEGACY=1 این مسیر قدیمی را هم به‌عنوان فالبک روشن می‌کند.
_LYS_LEGACY = os.environ.get("LYRICSIFY_LEGACY",
                             "1" if (os.environ.get("LYRICSIFY_PROXY") or "").strip() else "0"
                             ).strip().lower() not in ("0", "false", "off", "no")
_LYS_BASE =(os.environ.get("LYRICSIFY_BASE_URL") or "https://www.lyricsify.com").strip().rstrip("/")
_LYS_SEARCH_PATH = "/" + (os.environ.get("LYRICSIFY_SEARCH_PATH") or "/search").strip().strip("/")
_LYS_LYRICS_PATH = "/" + (os.environ.get("LYRICSIFY_LYRICS_PATH") or "/lyrics").strip().strip("/")
_LYS_TIMEOUT = _env_float("LYRICSIFY_TIMEOUT_SEC", 8.0)
try:
    _LYS_MAX_LINES = max(0, int(os.environ.get("LYRICSIFY_MAX_LINES", "") or 0))      # 0 = بدون سقف خط؛ سقف = پیام تلگرام
except ValueError:
    _LYS_MAX_LINES = 0
_LYS_UA = (os.environ.get("LYRICSIFY_USER_AGENT") or
           "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 "
           "(KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1").strip()
_LYS_CACHE = TTLCache(maxsize=200, ttl=24 * 3600)      # متن آهنگ‌ها
_LYS_SEARCH_CACHE = TTLCache(maxsize=300, ttl=3 * 3600)
# --- جلوگیری از ۴۰۳: سایت اثر انگشت TLS کتابخونهٔ requests رو می‌شناسه و بلاک می‌کنه. ---
# curl_cffi هندشیک TLS یه مرورگر واقعی (Safari/Chrome) رو تقلید می‌کنه. نصب نبود ← فالبک به requests.
#   LYRICSIFY_IMPERSONATE   پیش‌فرض safari17_0 (فهرست پروفایل‌ها: chrome, safari, safari17_0, ...)
#   LYRICSIFY_PROXY         اختیاری؛ مثل http://user:pass@host:port (وقتی خود آی‌پی سرور بلاک باشه)
try:
    from curl_cffi import requests as _lys_cffi
except Exception:
    _lys_cffi = None
    # نصب خودکار: اگه curl_cffi توی ایمیج نیست، یک‌بار موقع استارت داخل /tmp نصبش می‌کنیم (پوشهٔ کد قابل نوشتن نیست).
    # خاموش‌کردن: LYRICSIFY_AUTO_PIP=0
    if (os.environ.get("LYRICSIFY_AUTO_PIP", "1").strip().lower() not in ("0", "false", "off", "no")
            and _LYS_ON and _LYS_LEGACY):
        _lys_libs = "/tmp/pylibs"
        try:
            logger.info("[LYS] curl_cffi نصب نیست ← نصب خودکار داخل /tmp/pylibs ...")
            _p = subprocess.run(
                [sys.executable, "-m", "pip", "install", "--no-input", "--no-cache-dir",
                 "--disable-pip-version-check", "--quiet", "--target", _lys_libs, "curl_cffi"],
                capture_output=True, text=True, timeout=120)
            if _p.returncode != 0:
                logger.warning(f"[LYS] نصب خودکار curl_cffi شکست خورد: {(_p.stderr or _p.stdout or '')[-300:]!r}")
            else:
                if _lys_libs not in sys.path:
                    sys.path.insert(0, _lys_libs)
                from curl_cffi import requests as _lys_cffi
                logger.info("[LYS] curl_cffi با موفقیت نصب و بارگذاری شد")
        except Exception as _e:
            _lys_cffi = None
            logger.warning(f"[LYS] نصب خودکار curl_cffi ممکن نشد :: {_err_cause(_e)}")
_LYS_IMPERSONATE = (os.environ.get("LYRICSIFY_IMPERSONATE") or "safari17_0").strip()
_LYS_PROXY = (os.environ.get("LYRICSIFY_PROXY") or "").strip()
_LYS_PROXIES = {"http": _LYS_PROXY, "https": _LYS_PROXY} if _LYS_PROXY else None
_lys_sessions: dict = {}
_lys_sessions_lock = threading.Lock()


def _lys_get_session(profile: str | None):
    """سشن مناسب پروفایل؛ profile=None یعنی requests معمولی. بار اول ساخته می‌شه و بعدش کش."""
    key = profile or "_requests"
    with _lys_sessions_lock:
        s = _lys_sessions.get(key)
        if s is None:
            if profile and _lys_cffi is not None:
                s = _lys_cffi.Session(impersonate=profile)
            else:
                s = requests.Session()
            _lys_sessions[key] = s
        return s


_lys_session = requests.Session()   # سازگاری با کد قدیمی (دیگه مستقیم استفاده نمی‌شه)
logger.info(f"[LYS] متن آهنگ {'فعال' if _LYS_ON else 'غیرفعال'} | lyrics_service={'بله' if _HAS_LYRSVC else 'نه (lyrics_service.py کنار bot.py نیست)'} "
            f"| lyricsify-legacy={'روشن' if _LYS_LEGACY else 'خاموش'} identify={_LYS_IDENTIFY_ON and _LYS_LEGACY} max_lines={_LYS_MAX_LINES}")
if _LYS_LEGACY:
    logger.info(f"[LYS] lyricsify base={_LYS_BASE} مرورگر-نما: {'curl_cffi/' + _LYS_IMPERSONATE if _lys_cffi is not None else 'غیرفعال (curl_cffi نصب نیست ← requests معمولی؛ احتمال ۴۰۳ زیاده)'}"
                f" proxy={'بله' if _LYS_PROXY else 'خیر'}")
_LYS_NOT_FOUND = "متن این آهنگ رو پیدا نکردم. اسم خواننده رو هم کنارش بنویس (ترجیحاً انگلیسی هم امتحان کن) تا دقیق‌تر بگردم."
_LYS_DOWN = "الان به سرویس متن آهنگ دسترسی نداشتم. چند دقیقه دیگه دوباره امتحان کن."


def _lys_get(path_or_url: str, params: dict | None = None):
    """GET با UA معمولی و timeout. متن HTML یا None (هر خطا/بلاک/وضعیت غیر ۲۰۰ ← None + لاگ)."""
    url = path_or_url if path_or_url.startswith("http") else _LYS_BASE + path_or_url
    # ترتیب تلاش: پروفایل اصلی ← کروم (اگه ۴۰۳/۴۲۹/۵۰۳ شد) ← requests معمولی (اگه curl_cffi نصب نیست)
    profiles: list = []
    if _lys_cffi is not None:
        profiles.append(_LYS_IMPERSONATE)
        if _LYS_IMPERSONATE != "chrome":
            profiles.append("chrome")
    else:
        profiles.append(None)
    last_status = None
    for prof in profiles:
        try:
            sess = _lys_get_session(prof)
            if prof:   # UA و بقیهٔ هدرها رو خودِ curl_cffi مطابق مرورگر می‌ذاره؛ دستکاری‌شون ناهمخوانی می‌سازه
                hdrs = {"Accept-Language": "fa,en;q=0.8"}
                tmo = _LYS_TIMEOUT + 4
            else:
                hdrs = {"User-Agent": _LYS_UA,
                        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                        "Accept-Language": "fa,en;q=0.8", "Accept-Encoding": "gzip, deflate",
                        "Upgrade-Insecure-Requests": "1"}
                tmo = (4, _LYS_TIMEOUT)
            r = sess.get(url, params=params, timeout=tmo, allow_redirects=True, headers=hdrs,
                         **({"proxies": _LYS_PROXIES} if _LYS_PROXIES else {}))
        except Exception as e:
            logger.warning(f"[LYS] خطای شبکه ({prof or 'requests'}) :: {_err_cause(e)}")
            continue
        last_status = r.status_code
        if r.status_code == 200:
            return r.text[:800_000]
        try:
            _h = r.headers
            _snip = re.sub(r"\s+", " ", (r.text or "")[:200])
            logger.warning(f"[LYS] وضعیت {r.status_code} ({prof or 'requests'}) برای {url[:120]} "
                           f"server={_h.get('server')} cf-mitigated={_h.get('cf-mitigated')} body={_snip!r}")
        except Exception:
            logger.warning(f"[LYS] وضعیت {r.status_code} ({prof or 'requests'}) برای {url[:120]}")
        if r.status_code not in (403, 429, 503):
            return None
    return None


def _lys_strip_tags(s: str) -> str:
    return re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", s or ""))).strip()


def _lys_alnum(s: str) -> str:
    return re.sub(r"[\W_]+", "", (s or "").lower(), flags=re.U)


def _lys_pretty(slug: str) -> str:
    s = urllib.parse.unquote(slug or "").replace("-", " ").replace("_", " ").strip()
    return " ".join(w[:1].upper() + w[1:] for w in s.split()) if s.isascii() else s


def _lys_pick_name(slug: str, *texts: str) -> str:
    """اسم قشنگ (با حروف بزرگ و کوچک درست) از متن صفحه؛ اگر پیدا نشد از خودِ اسلاگ."""
    key = _lys_alnum(urllib.parse.unquote(slug or ""))
    for t in texts:
        for part in re.split(r"\s+[-–—|:]\s+|\s+by\s+|\s*lyrics\s*", t or "", flags=re.I):
            if part.strip() and key and _lys_alnum(part) == key:
                return part.strip()
    return _lys_pretty(slug)


def _lys_parse_results(page: str) -> list:
    """لینک‌های {LYRICS_PATH}/خواننده/آهنگ از HTML سرچ (به ترتیب صفحه، بدون تکرار)."""
    out, seen = [], set()
    base_host = urllib.parse.urlparse(_LYS_BASE).netloc
    for m in re.finditer(r"<a\b[^>]*?href\s*=\s*[\"']([^\"']+)[\"'][^>]*>(.*?)</a>", page or "", re.S | re.I):
        href = html.unescape(m.group(1)).split("#")[0].split("?")[0]
        full = urllib.parse.urljoin(_LYS_BASE + "/", href)
        pu = urllib.parse.urlparse(full)
        if pu.netloc and pu.netloc != base_host:
            continue
        segs = [x for x in pu.path.split("/") if x]
        pref = [x for x in _LYS_LYRICS_PATH.split("/") if x]
        if len(segs) != len(pref) + 2 or segs[:len(pref)] != pref:
            continue
        if full in seen:
            continue
        seen.add(full)
        out.append({"url": full, "artist_slug": segs[-2], "song_slug": segs[-1], "text": _lys_strip_tags(m.group(1))})
    return out


class _LysPage(_LysHTMLParser):
    """استخراج متن آهنگ از HTML بدون نیاز به سلکتور ثابت: هر بلوک (div/p/article/pre…) یک «کاندید» است؛
    کاندیدی که بیشترین خط‌های کوتاهِ بدون لینک را دارد و از همه «تنگ‌تر» است برنده می‌شود
    (کلاس/آی‌دی دارای «lyric» یا تگ pre اولویت دارد)."""
    _SKIP = {"script", "style", "noscript", "svg", "nav", "header", "footer", "aside", "form", "button",
             "select", "iframe", "template", "head"}
    _BLOCK = {"div", "p", "article", "section", "pre", "main", "li", "ul", "ol", "blockquote", "td", "tr",
              "table", "h1", "h2", "h3", "h4"}
    _VOID = {"br", "hr", "img", "input", "meta", "link", "source", "wbr"}

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = [{"tag": "#root", "cls": "", "parts": [], "links": 0, "skip": False, "pre": False}]
        self.cands, self.title, self.h1 = [], [], []
        self._skip = self._pre = self._a = 0
        self._in_title = self._in_h1 = False

    def handle_starttag(self, tag, attrs):
        if tag == "br":
            self.stack[-1]["parts"].append("\n")
            return
        if tag in self._VOID:
            return
        if tag == "title":
            self._in_title = True
        if tag == "h1":
            self._in_h1 = True
        if tag == "a":
            self._a += 1
        if tag in self._SKIP or tag in self._BLOCK:
            ad = dict(attrs)
            cls = ((ad.get("class") or "") + " " + (ad.get("id") or "")).lower()
            is_pre = tag == "pre" or "lyric" in cls
            node = {"tag": tag, "cls": cls, "parts": [], "links": 0, "skip": tag in self._SKIP, "pre": is_pre}
            self.stack.append(node)
            if node["skip"]:
                self._skip += 1
            if is_pre:
                self._pre += 1

    def handle_endtag(self, tag):
        if tag == "title":
            self._in_title = False
        if tag == "h1":
            self._in_h1 = False
        if tag == "a" and self._a:
            self._a -= 1
        if not (tag in self._SKIP or tag in self._BLOCK):
            return
        idx = next((i for i in range(len(self.stack) - 1, 0, -1) if self.stack[i]["tag"] == tag), None)
        if idx is None:
            return
        while len(self.stack) > idx:
            self._close(self.stack.pop())

    def _close(self, node):
        if node["skip"]:
            self._skip -= 1
        if node["pre"]:
            self._pre -= 1
        text = "".join(node["parts"])
        parent = self.stack[-1]
        sep = "\n\n" if node["tag"] == "p" else "\n"
        if not node["skip"]:
            parent["parts"].append(sep + text + sep)
            parent["links"] += node["links"]
            self.cands.append((node["tag"], node["cls"], text, node["links"]))

    def handle_data(self, data):
        if self._in_title:
            self.title.append(data)
        if self._in_h1:
            self.h1.append(data)
        if self._skip:
            return
        if not self._pre:
            data = re.sub(r"\s+", " ", data)
        if self._a:
            self.stack[-1]["links"] += len(data.strip())
        self.stack[-1]["parts"].append(data)

    def close(self):
        super().close()
        while len(self.stack) > 1:
            self._close(self.stack.pop())


_LYS_TS_RE = re.compile(r"\[\d{1,3}:\d{2}(?:[.:]\d{1,3})?\]")
_LYS_META_RE = re.compile(r"^\[(?:ar|ti|al|au|by|length|offset|re|ve|id|la|lang):.*\]$", re.I)


def _lys_clean_lyrics(text: str) -> str:
    lines = []
    for ln in (text or "").replace("\r", "").split("\n"):
        ln = _LYS_TS_RE.sub("", ln).strip()
        if _LYS_META_RE.match(ln):
            continue
        lines.append(re.sub(r"[ \t]+", " ", ln))
    return re.sub(r"\n{3,}", "\n\n", "\n".join(lines)).strip()


def _lys_parse_page(page: str):
    """HTML صفحهٔ آهنگ ← (عنوان صفحه, h1, متن آهنگ یا ""). هر خطا ← ("", "", "")."""
    try:
        p = _LysPage()
        p.feed(page or "")
        p.close()
    except Exception as e:
        logger.warning(f"[LYS] پارس صفحه شکست خورد :: {_err_cause(e)}")
        return "", "", ""
    title = re.sub(r"\s+", " ", "".join(p.title)).strip()
    h1 = re.sub(r"\s+", " ", "".join(p.h1)).strip()
    scored = []
    for tag, cls, text, links in p.cands:
        if tag in ("h1", "h2", "h3", "h4", "li"):
            continue
        lines = [x.strip() for x in _lys_clean_lyrics(text).split("\n") if x.strip()]
        short = [x for x in lines if 2 <= len(x) <= 100]
        if len(short) < 4 or links > 0.2 * max(1, len(text)):
            continue
        scored.append((len(short), len(text), "lyric" in cls or tag == "pre", text))
    if not scored:
        return title, h1, ""
    pool = [c for c in scored if c[2]] or scored
    best_n = max(c[0] for c in pool)
    pool = [c for c in pool if c[0] >= 0.8 * best_n]
    return title, h1, _lys_clean_lyrics(min(pool, key=lambda c: c[1])[3])


def _lys_search(query: str):
    """لیست نتایج؛ [] = نتیجه‌ای نبود؛ None = سایت در دسترس نبود (خطای شبکه/بلاک)."""
    q = re.sub(r"\s+", " ", query or "").strip()
    if not q:
        return []
    key = _song_norm(q)
    if key in _LYS_SEARCH_CACHE:
        return _LYS_SEARCH_CACHE[key]
    page = _lys_get(_LYS_SEARCH_PATH, {"q": q})
    if page is None:
        return None                     # خطا کش نمی‌شود
    res = _lys_parse_results(page)
    _LYS_SEARCH_CACHE[key] = res
    logger.info(f"[LYS] سرچ {q[:40]!r} ← {len(res)} نتیجه")
    return res


def _lys_fetch_song(item: dict):
    """آیتم نتیجهٔ سرچ ← {song, artist, url, lyrics} یا None."""
    page = _lys_get(item["url"])
    if not page:
        return None
    title, h1, lyrics = _lys_parse_page(page)
    song = _lys_pick_name(item["song_slug"], h1, title, item.get("text", ""))
    artist = _lys_pick_name(item["artist_slug"], h1, title, item.get("text", ""))
    return {"song": song, "artist": artist, "url": item["url"], "lyrics": lyrics}


def _lyricsify_identify(phrase: str):
    """«این بیت از کدام آهنگ است؟» ← «آهنگ» از خواننده، فقط اگر بیت واقعاً در متن صفحهٔ lyricsify باشد؛ وگرنه None."""
    if not (_LYS_ON and _LYS_LEGACY and _LYS_IDENTIFY_ON and phrase):      # فقط با اسکرپ lyricsify ممکن است (LRCLIB در متن آهنگ جستجو نمی‌کند)
        return None
    deadline = time.time() + 2.5 * _LYS_TIMEOUT
    for item in (_lys_search(phrase) or [])[:2]:
        if time.time() > deadline:
            break
        s = _lys_fetch_song(item)
        if s and s["lyrics"] and _song_phrase_hit(phrase, s["lyrics"], 0.85):
            logger.info(f"[LYS] بیت پیدا شد: {phrase[:30]!r} ← {s['artist']} - {s['song']}")
            return _song_head(s["song"], s["artist"], True)
    return None


_LYS_QUICK_RE = re.compile(r"آهنگ|اهنگ|ترانه|لیریک|lyric", re.I)
_LYS_REQ_PATTERNS = [
    re.compile(r"(?:^|\s)(?:آهنگ|اهنگ|ترانه)\s+(?P<q>.+?)\s+(?:رو|را)\s+(?:(?:برام|بهم|واسم|برامون)\s+)?"
               r"(?:بخون|بخوان|بگو|بفرست|بده|بنویس)\w*"),
    re.compile(r"(?:^|\s)(?:بخون|بخوان|بفرست|بده|بگو)\s+(?:برام\s+|بهم\s+)?(?:متن\s+)?(?:آهنگ|اهنگ|ترانه)\s+(?P<q>.+)"),
    re.compile(r"(?:^|\s)(?:متن\s+(?:آهنگ|اهنگ|ترانه)|لیریک(?:س|ز)?)\s+(?:ی\s+)?(?P<q>.+)"),
    re.compile(r"(?:^|\s)lyrics?\s+(?:of|for)\s+(?P<q>.+)", re.I),
    re.compile(r"(?:^|\s)(?P<q>.+?)\s+lyrics?\s*$", re.I),
]
_LYS_TAIL_RE = re.compile(r"(?:\s+(?:رو|را|لطفا|لطفاً|پلیز|بده|بفرست|بگو|بخون|بخوان|بنویس|میخوام|می خوام|میخواستم|برام|بهم))+\s*$")
_LYS_BAD_RE = re.compile(r"معنی|معنا|ترجمه|یعنی|تحلیل|تفسیر|خلاصه|توضیح|تفاوت")
_LYS_CTX_RE = re.compile(r"^(?:این|اینو|اون|اونو|همین|همینو)(?:\s|$)")


_LYS_FILLER_RE = re.compile(r"(?:^|\s)(?:کامل(?:ش)?(?:\s+و\s+دقیق)?|دقیق(?:ش)?(?:\s+و\s+کامل)?|full|complete)(?=\s|$)", re.I)
_LYS_CLITIC_RE = re.compile(r"(آهنگ|اهنگ|ترانه)(?:و|رو|ُ)(?=\s|$)")
_LYS_CTX_REQ_RE = re.compile(
    r"(?:^|\s)(?:متن|لیریک(?:س|ز)?)\s+(?:این|همین|اون)\s+(?:آهنگ|اهنگ|ترانه)(?:\s+(?:رو|را))?"
    r"(?:\s+(?:رو|را|بده|بفرست|بگو|بنویس|میخوام|می خوام))*\s*$"
    r"|(?:^|\s)(?:این|همین|اون)\s+(?:آهنگ|اهنگ|ترانه)(?:\s+(?:رو|را))?\s+(?:بخون|بخوان|بفرست|بده)\w*\s*$")
_LYS_QUOTED_RE = re.compile(r"«([^»\n]{2,60})»(?:\s*(?:—|-|از)\s*([^\n.،,؛;(«]{2,40}))?")


_LYS_SONGWORD_RE = re.compile(r"آهنگ|اهنگ|ترانه|موزیک|سینگل|آلبوم|خواننده|«")
_LYS_CTX_SHORT_RE = re.compile(
    r"^(?:(?:نخود|نوید)\s*[،,]?\s+)?"
    r"(?:(?:خب|خوب|حالا|ببخشید|راستی|اگه|اگر|میشه|می\s?شه|میتونی|می\s?تونی|لطفا|پلیز|ممنون|یه\s?بار|یکم)\s+)*"
    # «متن / متنش / متنشو / متن آهنگ / متن آهنگو / متن اهنگشو / متن این آهنگ / لیریکشو / این آهنگ متنش»
    r"(?:(?:متن|لیریک(?:س|ز)?)(?:ش|شو|شُ|و|ه)?"
    r"(?:\s+(?:این|اینو|همین|همینو|اون|اونو))?"
    r"(?:\s+(?:آهنگ|اهنگ|ترانه)(?:ش|شو|و|ه)?)?"
    r"|(?:این|همین|اون)\s+(?:آهنگ|اهنگ|ترانه)(?:ش|شو|و)?\s+(?:متن|لیریک(?:س|ز)?)(?:ش|شو)?)"
    r"(?:\s+(?:رو|را))?(?:\s+(?:کامل(?:ش|شو)?|تمامش|تمام|همش))?"
    r"(?:\s+(?:رو|را))?"
    r"(?:\s+(?:میدی|می\s?دی|بدی|بده|بدید|میدید|می\s?دین|بدین|بفرست|بفرستی|بفرستید|بفرستین|بگو|بگی|بنویس|بنویسی"
    r"|بذار|بزار|بذاری|بزاری|میذاری|میزاری|میخوام|می\s?خوام|میخواستم|چیه|چی\s?بود)){0,2}"
    r"(?:\s+(?:لطفا|پلیز))?\s*[؟?!.]*$")
def _lys_is_ctx_short(tn: str) -> bool:
    """«متنشو بده» با حرف‌های اولِ اضافه («درسته متن اهنگشو میدی»، «دقیقا متنشو بده»، «آفرین حالا متنشو بفرست»):
    تا ۴ کلمهٔ اول را کنار می‌زند و بقیه باید دقیقاً یک درخواست کوتاهِ متن باشد (فعل‌های آخر جمله اجباری‌اند، پس
    «متن آهنگ بیست و پنج بده» یا جملهٔ بلند با کلمهٔ «متن» اشتباه گرفته نمی‌شود)."""
    w = (tn or "").split()
    if len(w) > 12:
        return False
    for i in range(0, min(5, len(w))):
        if _LYS_CTX_SHORT_RE.match(" ".join(w[i:])):
            return True
    return False


_LYS_HIST_SONG_RE = re.compile(r"آهنگ|اهنگ|ترانه|🎵|خواننده|«[^»\n]{2,60}»\s*(?:از|—|-)\s")
_LYS_NEED_SONG = "متن کدوم آهنگ رو میخوای؟ اسم آهنگ رو (با خواننده) بنویس یا روی پیام همون آهنگ ریپلای کن"


def _lys_hist_ctx(history) -> str:
    """آخرین جوابِ آهنگ‌یابِ خودِ ربات در چند پیام اخیر (««باران» از امید») ← برای «متنشو بده» بدون ریپلای؛ نبود ← ''."""
    try:
        for m in reversed(list(history or [])[-14:]):
            if isinstance(m, dict) and m.get("role") == "assistant":
                c = str(m.get("content") or "")
                if c and _LYS_HIST_SONG_RE.search(c):
                    return c[:400]
    except Exception:
        pass
    return ""


# ---- حافظهٔ آخرین آهنگِ شناسایی‌شده (برای «متنشو بده» بعد از «این آهنگ از کیه؟») ----
_LYS_FALLBACK_MIN = 0.9      # حداقل امتیازِ حضور بیت در متن، برای نشان‌دادن متنِ یک آهنگِ هم‌خوان وقتی اسم از زمینه متن نداشت
_SONG_LAST_BY_Q = TTLCache(maxsize=500, ttl=6 * 3600)     # norm("خواننده اسم") -> {title, artist, phrase, answer}
_SONG_LAST_BY_USER = TTLCache(maxsize=2000, ttl=3600)     # user_id -> همان
_SONG_TL = threading.local()                               # _song_lookup بیتِ استخراج‌شده را برای فراخواننده می‌گذارد

_LYS_JUNK = " \t«»\"'“”()[]*_،,.:؛;؟?!"
_LYS_ANS_RE = re.compile(r"«([^«»\n]{1,80})»\s*(?:از|—|–|-)\s*([^\n«»(،,؛;.؟?!]{2,60})")
_LYS_ANS_TITLE_RE = re.compile(r"(?:اسمش|اسم\s+آهنگ|عنوانش)\s*(?:رو\s*)?«([^«»\n]{1,80})»")
_LYS_ANS_SINGER_RE = re.compile(r"خواننده(?:‌|\s)?ش\s+(?:فکر\s+کنم\s+)?([^\n،,.«»]{2,40}?)\s+(?:باشه|هست)")
_LYS_ANS_TAIL_RE = re.compile(r"\s+(?:باشه|هست|هستش|بود|میباشه|می‌باشه)\s*$")


def _lys_unwrap_reply(ctx: str) -> str:
    """بلوک ریپلای گروه («پیام ریپلای‌شده — نویسنده: … » + «متن» + زنجیره) ← خودِ متن پیام ریپلای‌شده. بلوک نبود ← همان ورودی."""
    c = (ctx or "").strip()
    wrapped = c.startswith("پیام ریپلای‌شده")
    if not wrapped:
        return c
    c = c.split("\n\nزنجیرهٔ ریپلای", 1)[0]
    parts = c.split("\n", 1)
    c = parts[1].strip() if len(parts) > 1 else ""
    if len(c) >= 2 and c[0] == "«" and c[-1] == "»":
        c = c[1:-1].strip()          # گیومهٔ بیرونیِ بلوک؛ گیومه‌های داخلیِ خود پیام (اسم آهنگ) می‌مانند
    return c


def _lys_parse_answer(text: str):
    """جواب خودِ ربات یا پیام آهنگ ← (اسم آهنگ, خواننده)؛ هرکدام که پیدا نشد "".
    «اسم» از خواننده | 🎵 «اسم» — خواننده | فکر کنم «اسم» از خواننده باشه (مطمئن نیستم) | خواننده‌ش فکر کنم X باشه"""
    t = text or ""
    m = _LYS_ANS_RE.search(t)
    if m:
        title = m.group(1).strip(_LYS_JUNK)
        artist = _LYS_ANS_TAIL_RE.sub("", m.group(2).strip()).strip(_LYS_JUNK)
        if title and artist:
            return title, artist
    m = _LYS_ANS_TITLE_RE.search(t)
    if m:
        return m.group(1).strip(_LYS_JUNK), ""
    m = _LYS_ANS_SINGER_RE.search(t)
    if m:
        return "", m.group(1).strip(_LYS_JUNK)
    return "", ""


def _song_remember(ans: str, phrase: str = "", user_id=None):
    """جواب آهنگ‌یاب را (با بیتی که دنبالش بودیم) نگه می‌دارد تا «متنشو بده» بعدی هم اسم، هم بیت را داشته باشد."""
    try:
        title, artist = _lys_parse_answer(ans or "")
        if title and phrase and len(title.split()) >= 4 and _song_phrase_hit(phrase, title, 0.7):
            title = ""                  # «اسم» در واقع خودِ مصرع است (عنوان صفحه‌های فارسی) ← اسم آهنگ حساب نکن
        if not (title and artist) and not (phrase and (artist or title)):
            return
        info = {"title": title, "artist": artist, "phrase": phrase or "", "answer": (ans or "")[:400]}
        if title and artist:
            _SONG_LAST_BY_Q[_song_norm(f"{artist} {title}")] = info
        if user_id:                      # فقط خواننده + بیت (اسم آهنگ معلوم نیست) هم نگه داشته می‌شود تا «متنشو بده» از روی بیت برود
            _SONG_LAST_BY_USER[user_id] = info
    except Exception:
        pass


def _lys_ctx_query(reply_ctx: str) -> str:
    """«متن این آهنگ» / «متنشو میدی» ← «خواننده اسم» از پیام ریپلای‌شده یا جواب قبلیِ ربات؛ "" اگر نبود.
    اگر جواب فقط خواننده را می‌گفت (اسم آهنگ نه) هم "" برمی‌گردد تا ربات اسم آهنگ را بپرسد (به‌جای جستجوی اشتباه)."""
    ctx = _lys_unwrap_reply(reply_ctx)
    if not ctx or not (_LYS_SONGWORD_RE.search(ctx) or "🎵" in ctx):
        return ""
    title, artist = _lys_parse_answer(ctx)
    if title:
        return (f"{artist} {title}" if artist else title)[:120]
    if artist:
        return ""
    try:
        v = _lys_llm_variants(ctx[:160])
    except Exception:
        v = []
    return (v[0] if v else "")[:120]


_LYS_FILLER_WORDS = frozenset((
    "رو", "را", "بده", "بدی", "بدید", "بدین", "میدی", "میدید", "میدین", "بفرست", "بفرستی", "بفرستید", "بگو", "بگی", "بخون",
    "بخوان", "بنویس", "بنویسی", "میخوام", "میخواستم", "برام", "بهم", "واسم", "لطفا", "لطفاً", "پلیز", "کامل", "کاملش",
    "بذار", "بزار", "بذاری", "بزاری", "میذاری", "میزاری", "ممنون", "یه", "بار", "هم", "دیگه", "ببینم", "اینو", "اونو",
))


def _lys_strip_filler(q: str) -> str:
    """«رو بده» / «رو» / «رو بدی» ← "" ؛ فعل‌ها و حرف‌های اضافهٔ دو طرفِ اسم آهنگ حذف می‌شود (اسم واقعی دست‌نخورده می‌ماند)."""
    w = (q or "").split()
    norm = lambda x: x.replace("\u200c", "").strip("،,.؟?!")
    while w and norm(w[0]) in _LYS_FILLER_WORDS:
        w.pop(0)
    while w and norm(w[-1]) in _LYS_FILLER_WORDS:
        w.pop()
    return " ".join(w)


def _lys_extract_query(user_text: str, reply_ctx: str = "", hist_ctx: str = "") -> str:
    """اسم آهنگ/خوانندهٔ درخواست‌شده؛ "" اگر پیام درخواست متن آهنگ نیست.
    hist_ctx: آخرین جواب آهنگ‌یاب در تاریخچه؛ وقتی ریپلای نیست برای «میشه متنشو بدی» استفاده می‌شود."""
    t = _ai_norm_fa(user_text).replace("\u0654", "")        # «ترانهٔ» ← «ترانه»
    _ctx = reply_ctx or hist_ctx
    if _ctx and _lys_is_ctx_short(" ".join(t.replace("\u200c", " ").split())):
        return _lys_ctx_query(_ctx)                           # «متنشو میدی» روی پیام یک آهنگ (یا جواب قبلیِ ربات)
    if not _LYS_QUICK_RE.search(t) or _SONG_Q_RE.search(t) or _LYS_BAD_RE.search(t):
        return ""
    t = _LYS_CLITIC_RE.sub(r"\1 رو", t)                      # «آهنگو» ← «آهنگ رو»
    t = _LYS_FILLER_RE.sub(" ", t)                            # «متن کامل آهنگ …» / «… رو کامل بده»
    t = re.sub(r"\s+", " ", t).strip()
    if _LYS_CTX_REQ_RE.search(re.sub(r"(?:^|\s)نخود(?=\s|$|[،,:])", " ", t)):
        return _lys_ctx_query(_ctx)                           # «متن این آهنگ رو بده» ← از پیام ریپلای‌شده/جواب قبلی
    t = re.sub(r"@\w+", " ", t)
    t = re.sub(r"(?:^|\s)نخود(?=\s|$|[،,:])", " ", t)
    t = re.sub(r"\s+", " ", t).strip(" \t\n،,:؛;؟?!.-«»\"'")
    for pat in _LYS_REQ_PATTERNS:
        m = pat.search(t)
        if not m:
            continue
        q = m.group("q")
        for _ in range(3):
            q = _LYS_TAIL_RE.sub("", q)
        q = _lys_strip_filler(q.strip(" \t\n،,:؛;؟?!.-«»\"'"))
        if not q and _ctx:
            return _lys_ctx_query(_ctx)                       # «متن آهنگ رو بده» (فقط فعل و «رو») ← اسم آهنگ از زمینه
        if not q or _LYS_CTX_RE.match(q) or re.search(r"(?:چیه|چیست|کیه|کیست)$", q):
            return ""
        if not (1 <= len(q.split()) <= 8) or len(q) < 2:
            return ""
        return q[:120]
    return ""


def _lys_best_item(query: str, items: list):
    """نزدیک‌ترین نتیجه به عبارت کاربر (شباهت اسم خواننده+آهنگ). برمی‌گرداند (آیتم, امتیاز)."""
    nq = _song_norm(query)
    best, best_s = None, -1.0
    for it in items[:8]:
        cand = _song_norm(_lys_pretty(it["artist_slug"]) + " " + _lys_pretty(it["song_slug"]) + " " + it.get("text", ""))
        qs, cs = set(nq.split()), set(cand.split())
        overlap = len(qs & cs) / max(1, len(qs))
        s = max(overlap, difflib.SequenceMatcher(None, nq, cand).ratio())
        if s > best_s:
            best, best_s = it, s
    return best, best_s


_TG_MSG_LIMIT = 4096                     # سقف متن یک پیام در تلگرام
_LYS_TEXT_LIMIT = _TG_MSG_LIMIT - 1      # یک کاراکتر کمتر از سقف


def _lys_format(s: dict, approx: bool) -> str:
    lines = [x for x in s["lyrics"].split("\n")]
    head = f"🎵 «{s['song']}» — {s['artist']}"
    if approx:
        head += "\n(نزدیک‌ترین نتیجه‌ای بود که پیدا کردم؛ اگه این نبود اسم خواننده رو هم بنویس)"
    head += "\n\n"
    foot_full = f"\n\nمنبع: {s.get('source') or s['url']}"
    foot_cut = f"\n\n… (ادامهٔ متن: {s['url']})"

    def _take(limit_chars: int, max_lines: int):
        shown, count, size = [], 0, 0
        for ln in lines:
            if ln.strip():
                if max_lines and count >= max_lines:
                    return shown, False
                count += 1
            add = len(ln) + (1 if shown else 0)
            if size + add > limit_chars:
                return shown, False
            shown.append(ln)
            size += add
        return shown, True

    # اول با فوتر «منبع»؛ اگر کل متن جا نشد، با فوتر «ادامه» و حداکثر تا سقف پیام تلگرام
    shown, complete = _take(_LYS_TEXT_LIMIT - len(head) - len(foot_full), _LYS_MAX_LINES)
    if complete:
        return (head + "\n".join(shown).strip() + foot_full)[:_LYS_TEXT_LIMIT]
    shown, _ = _take(_LYS_TEXT_LIMIT - len(head) - len(foot_cut), _LYS_MAX_LINES)
    return (head + "\n".join(shown).strip() + foot_cut)[:_LYS_TEXT_LIMIT]


_LYS_VARIANTS_PROMPT = (
    "A user asked a Telegram bot for the lyrics of a song, using this request (may be Persian/Arabic/English, "
    "may contain a singer name and/or a song title, spelling may be rough):\n"
    "REQUEST: {q}\n\n"
    "Identify the most likely singer and song title and give up to 3 search strings for a lyrics database "
    "(like Spotify/LRCLIB would index it): 1) \"Artist Title\" in Latin/English spelling as commonly published, "
    "2) \"Artist Title\" in the original script (e.g. Persian) with standard spelling, 3) title only in Latin. "
    "Do NOT write any lyrics. Reply ONLY with JSON: {{\"queries\": [\"...\", \"...\"]}}"
)


def _lys_llm_variants(q: str) -> list:
    """هوک lyrics_service: وقتی با عبارت خام نتیجهٔ خوب نیامد، جمینی اسم خواننده/آهنگ را به نوشتار لاتین و استاندارد برمی‌گرداند
    (مثلاً «هایده ساقی» ← «Hayedeh Saghi»). خطا/نبودن کلید ← []."""
    if not _ai_keys_of("gemini"):
        return []
    try:
        raw = _song_gemini_ask(_LYS_VARIANTS_PROMPT.format(q=(q or "")[:160].replace("{", "").replace("}", "")), False, 220)
        d = _song_json(raw or "") or {}
        qs = d.get("queries") if isinstance(d.get("queries"), list) else []
        return [x.strip()[:100] for x in qs if isinstance(x, str) and x.strip()][:3]
    except Exception as _e:
        logger.warning(f"[LYS] variants (gemini) خطا :: {_err_cause(_e)}")
        return []


_LYS_NF_MARK = "متن این آهنگ رو پیدا نکردم"
_LYS_FU_CLOSERS = frozenset((
    "ممنون", "مرسی", "تشکر", "باشه", "اوکی", "ok", "okay", "نه", "نمیخوام", "نمی‌خوام", "لازم", "نیست", "هیچی",
    "سلام", "خداحافظ", "آره", "اره", "بله", "نخود", "ببخشید", "عجب", "حیف", "خب", "خوب", "مهم", "نیست",
))
_LYS_FU_QWORD_RE = re.compile(r"(?:^|\s)(?:چیه|چیست|کیه|کیست|چطور|چرا|چی|کی|کجا|چنده|چقدر|چرت|اشتباه)(?=\s|$)")


def _lys_followup_query(user_text: str, reply_ctx: str = "", history=None) -> str:
    """بعد از «متن این آهنگ رو پیدا نکردم. اسم خواننده رو هم بنویس…» کاربر معمولاً فقط می‌نویسد «دو پنجره از گوگوش».
    آن پیام کوتاه همان درخواست متن است ← کوئری («گوگوش دو پنجره»)؛ وگرنه \"\"."""
    marked = _LYS_NF_MARK in (reply_ctx or "")
    if not marked:
        try:
            for m in reversed(list(history or [])[-4:]):
                if isinstance(m, dict) and m.get("role") == "assistant":
                    marked = _LYS_NF_MARK in str(m.get("content") or "")
                    break                       # فقط آخرین جوابِ ربات؛ اگر چیز دیگری فرستاده بود دیگر ادامهٔ همان نیست
        except Exception:
            marked = False
    if not marked:
        return ""
    t = _ai_norm_fa(user_text or "").replace("\u200c", " ")
    t = re.sub(r"@\w+", " ", t)
    t = re.sub(r"(?:^|\s)نخود(?=\s|$|[،,:])", " ", t)
    t = re.sub(r"\s+", " ", t).strip(" \t\n،,:؛;؟?!.-«»\"'")
    words = t.split()
    if not (1 <= len(words) <= 8) or len(t) < 2 or len(t) > 80:
        return ""
    if all(w.lower() in _LYS_FU_CLOSERS for w in words) or _LYS_FU_QWORD_RE.search(t) or "؟" in (user_text or ""):
        return ""
    m = re.match(r"^(?P<t>.+?)\s+(?:از|by)\s+(?P<a>.+)$", t, re.I)
    if m:
        t = f"{m.group('a').strip()} {m.group('t').strip()}"      # «دو پنجره از گوگوش» ← «گوگوش دو پنجره»
    return t[:120]


def _lyrics_by_phrase(info: dict):
    """«متنشو بده» وقتی آهنگ‌یاب فقط بیت (و شاید خواننده) را می‌دانست: متن از شواهد وب، نه حدسِ مدل.
    اگر اسم آهنگ شناسایی شد، اول LRCLIB/lyrics.ovh (با تأیید بیت در متن)، بعد متنِ همان صفحهٔ وب. نبود ← None."""
    phrase = (info or {}).get("phrase") or ""
    if not (_HAS_LYRSVC and _ls_for_phrase and phrase):
        return None
    ck = "ph|" + _song_norm(phrase)
    if ck in _LYS_CACHE:
        return _LYS_CACHE[ck]
    try:
        r = _ls_for_phrase(phrase, artist=info.get("artist") or "")
    except Exception as _e:
        logger.warning(f"[LYS] lyrics_for_phrase خطا :: {_err_cause(_e)}")
        r = None
    if not r or not r.get("lyrics"):
        logger.info(f"[LYS] بیت {phrase[:30]!r} در هیچ صفحهٔ قابل‌دسترسی تأیید نشد")
        return None
    title, artist = r.get("title") or "", r.get("artist") or info.get("artist") or ""
    s = None
    if title and _ls_find:                                   # اسم معلوم شد ← اول LRCLIB (متنِ تمیز/زمان‌دار)، فقط اگر بیت در آن باشد
        try:
            r2 = _ls_find(f"{artist} {title}".strip(), variants_fn=_lys_llm_variants, phrase=phrase)
            if r2 and r2.get("lyrics") and _ls_pscore and _ls_pscore(phrase, r2["lyrics"]) >= 0.8:
                s = {"song": r2["song"], "artist": r2["artist"], "url": r2.get("more_url") or "",
                     "source": r2.get("source") or "", "lyrics": r2["lyrics"]}
        except Exception as _e:
            logger.warning(f"[LYS] LRCLIB بعد از شناسایی خطا :: {_err_cause(_e)}")
    if s is None:
        s = {"song": title or "این آهنگ", "artist": artist or "نامشخص", "url": r.get("url") or "",
             "source": r.get("source") or "", "lyrics": r["lyrics"]}
    if title:                                                # برای درخواست‌های بعدی (متن/لینک اسپاتیفای…)
        info["title"] = title
        if artist:
            info["artist"] = artist
            _SONG_LAST_BY_Q[_song_norm(f"{artist} {title}")] = info
    ans = _lys_format(s, approx=(r.get("confidence") not in ("high",) and not title))
    _LYS_CACHE[ck] = ans
    return ans


def _lyrics_request(user_text: str, reply_ctx: str = "", history=None, user_id=None):
    """درخواست متن آهنگ («متن آهنگ X»، «آهنگ X رو بخون»، «X lyrics») ← متن جواب؛ None = این پیام از این نوع نیست."""
    if not _LYS_ON:
        return None
    _hc = "" if reply_ctx else _lys_hist_ctx(history)
    if not reply_ctx and not _hc and user_id:
        _inf = _SONG_LAST_BY_USER.get(user_id)          # گروه شلوغ: جواب آهنگ‌یاب از ۴ پیام آخر بیرون افتاده؛ از حافظهٔ خودِ کاربر
        _hc = (_inf or {}).get("answer", "")
    # «متنشو بده» وقتی آهنگ‌یاب فقط بیت/خواننده را می‌دانست ← از روی بیت (شواهد وب)؛ نه اینکه مدل از خودش اسمِ آهنگ بسازد
    if _HAS_LYRSVC and user_id:
        _pinf = _SONG_LAST_BY_USER.get(user_id)
        if _pinf and _pinf.get("phrase") and not _pinf.get("title"):
            _tn0 = " ".join(_ai_norm_fa(user_text).replace("\u0654", "").replace("\u200c", " ").split())
            _same_msg = (not reply_ctx) or (_song_norm(_pinf.get("answer", ""))[:30] in _song_norm(reply_ctx))
            if _same_msg and _lys_is_ctx_short(_tn0):
                logger.info(f"[LYS] «متنشو بده» از روی بیت: {_pinf['phrase'][:30]!r} خواننده={_pinf.get('artist')!r}")
                _status_web_search()
                _pans = _lyrics_by_phrase(_pinf)
                return _pans or _LYS_NOT_FOUND
    q = _lys_extract_query(user_text, reply_ctx, _hc)
    if not q:
        q = _lys_followup_query(user_text, reply_ctx, history)
        if q:
            logger.info(f"[LYS] ادامهٔ «پیدا نکردم»: کاربر اسم آهنگ/خواننده را نوشت ← {q!r}")
    if not q:
        _tn = " ".join(_ai_norm_fa(user_text).replace("\u0654", "").replace("\u200c", " ").split())
        if _lys_is_ctx_short(_tn):
            _uw = _lys_unwrap_reply(reply_ctx)
            _say_song = bool(re.search(r"آهنگ|اهنگ|ترانه|لیریک", _tn))
            _bot_like = any(mk in _uw for mk in (_LYS_NF_MARK, "دقیق پیداش نکردم", "یه بیت از آهنگ رو بنویس", "الان نتونستم جستجو کنم"))
            # ریپلای روی پیامی که خودش بیت/شعر است + کاربر صراحتاً گفته «متن آهنگ/ترانه/لیریک» ← از روی همان بیت (LRCLIB/وب)
            if _HAS_LYRSVC and _uw and _say_song and not _bot_like and len(_uw.split()) >= 3 and "http" not in _uw:
                _ph = _song_extract_phrase("", "«" + _uw[:300] + "»") or _uw[:300]
                logger.info(f"[LYS] «متنشو بده» با ریپلای روی بیت: {_ph[:40]!r}")
                _status_web_search()
                _pans = _lyrics_by_phrase({"phrase": _ph, "artist": ""})
                return _pans or _LYS_NOT_FOUND
            if _LYS_SONGWORD_RE.search(_uw + " " + _hc) or _say_song:
                logger.info(f"[LYS] «متنشو بده» ولی اسم آهنگ از زمینه درنیامد: {(user_text or '')[:50]!r} "
                            f"reply={len(_uw)}ch hist={len(_hc)}ch mem={'بله' if (user_id and _SONG_LAST_BY_USER.get(user_id)) else 'نه'}")
                return _LYS_NEED_SONG          # به مسیر عادی نرو؛ آنجا مدل چند کلمه از خودش می‌نویسد
            logger.info(f"[LYS] «متنشو بده» بدون هیچ زمینهٔ آهنگ ← مسیر عادی: {(user_text or '')[:50]!r}")
        if _LYS_QUICK_RE.search(user_text or ""):
            logger.info(f"[LYS] درخواست متن آهنگ تشخیص داده نشد (مسیر عادی): {(user_text or '')[:70]!r}")
        return None
    logger.info(f"[LYS] درخواست متن آهنگ: {q!r}")
    ck = _song_norm(q)
    if ck in _LYS_CACHE:
        return _LYS_CACHE[ck]
    _status_web_search()
    answered = False        # آیا دست‌کم یک منبع واقعاً جواب داد (حتی «پیدا نشد»)؟ وگرنه «سرویس در دسترس نیست»

    # ۱) مسیر اصلی: lyrics_service.py (LRCLIB + lyrics.ovh) — بدون کلودفلر
    if _HAS_LYRSVC:
        _inf_ph = _SONG_LAST_BY_Q.get(ck) or {}
        if not _inf_ph.get("phrase") and user_id:
            _um = _SONG_LAST_BY_USER.get(user_id) or {}
            if _um.get("title") and _song_norm(f"{_um.get('artist', '')} {_um['title']}") == ck:
                _inf_ph = _um
        try:
            r = _ls_find(q, variants_fn=_lys_llm_variants, phrase=_inf_ph.get("phrase", ""))
            answered = True
        except _LsUnavailable:
            r = None
            logger.warning("[LYS] lyrics_service: هیچ منبعی جواب نداد")
        except Exception as _e:
            r = None
            logger.warning(f"[LYS] lyrics_service خطا :: {_err_cause(_e)}")
        if r and r.get("lyrics"):
            logger.info(f"[LYS] lyrics_service ← {r.get('artist')} - {r.get('song')} | منبع={r.get('source')} "
                        f"امتیاز={r.get('score', 0):.2f} phrase_miss={bool(r.get('phrase_miss'))}")
            if r.get("phrase_miss") and _inf_ph.get("phrase"):      # متن پیداشده بیتِ شناسایی‌شده را ندارد ← اول متنِ صفحهٔ تأییدشده با بیت
                try:
                    _pans0 = _lyrics_by_phrase(_inf_ph)
                except Exception as _e:
                    logger.warning(f"[LYS] متن با بیت (بعد از phrase_miss) خطا :: {_err_cause(_e)}")
                    _pans0 = None
                if _pans0:
                    _LYS_CACHE[ck] = _pans0
                    return _pans0
            s = {"song": r["song"], "artist": r["artist"], "url": r.get("more_url") or "",
                 "source": r.get("source") or "", "lyrics": r["lyrics"]}
            ans = _lys_format(s, approx=(r.get("score", 1.0) < 0.5 or bool(r.get("phrase_miss"))))
            _LYS_CACHE[ck] = ans
            return ans
        # اسمی که از جواب قبلی آمد ممکن است غلط/«مطمئن نیستم» باشد؛ با خودِ بیت، در متن آهنگ‌های همان خواننده می‌گردیم
        _inf = _SONG_LAST_BY_Q.get(ck)
        if _inf and _inf.get("phrase") and _ls_scan:
            try:
                _sc = _ls_scan(_inf["artist"], _inf["phrase"], titles=[_inf["title"]], name_fn=_lys_artist_names) or {}
                _b = _sc.get("best")
                if (_b and _b.get("score", 0) >= _LYS_FALLBACK_MIN
                        and _song_norm(_b.get("title", "")) != _song_norm(_inf["title"])):
                    logger.info(f"[LYS] اسم از زمینه {_inf['title']!r} متن نداشت؛ با بیت پیدا شد: {_b['title']!r} ({_b['score']:.2f})")
                    r2 = _ls_find(f"{_inf['artist']} {_b['title']}", variants_fn=_lys_llm_variants, phrase=_inf.get("phrase", ""))
                    if r2 and r2.get("lyrics"):
                        s = {"song": r2["song"], "artist": r2["artist"], "url": r2.get("more_url") or "",
                             "source": r2.get("source") or "", "lyrics": r2["lyrics"]}
                        ans = _lys_format(s, approx=(_b["score"] < _SONG_OVERRIDE_MIN))
                        _LYS_CACHE[ck] = ans
                        return ans
            except Exception as _e:
                logger.warning(f"[LYS] fallback با بیت شکست خورد :: {_err_cause(_e)}")
        if _inf and _inf.get("phrase"):                      # اسم معلوم بود ولی متنش با اسم پیدا نشد ← با خودِ بیت از صفحه‌های وب
            try:
                _pans = _lyrics_by_phrase(_inf)
                if _pans:
                    _LYS_CACHE[ck] = _pans
                    return _pans
            except Exception as _e:
                logger.warning(f"[LYS] fallback وب با بیت شکست خورد :: {_err_cause(_e)}")

    # ۲) فالبک قدیمی: اسکرپ lyricsify (فقط اگر LYRICSIFY_LEGACY=1 یا LYRICSIFY_PROXY ست باشد)
    if _LYS_LEGACY:
        items = _lys_search(q)
        if items:
            answered = True
            first, score = _lys_best_item(q, items)
            tried = [first] + [x for x in items[:3] if x is not first]
            for it in tried[:2]:
                s = _lys_fetch_song(it)
                if s and s["lyrics"]:
                    ans = _lys_format(s, approx=(score < 0.3 and it is first))
                    _LYS_CACHE[ck] = ans
                    return ans
        elif items is not None:
            answered = True
    if not answered:
        return _LYS_DOWN
    logger.info(f"[LYS] نتیجه‌ای برای {q[:40]!r} نبود")
    return _LYS_NOT_FOUND


_LATEST_STOP = {
    "اخرین", "جدیدترین", "جدید", "تازه", "تازهترین", "اهنگ", "البوم", "ترانه", "موزیک", "سینگل", "کار", "اثر",
    "اسمش", "اسم", "نامش", "نام", "چیه", "چیست", "کدومه", "کدوم", "بود", "هست", "چی", "امیر", "اقای", "خانم",
    "نخود", "رو", "را", "از", "ی", "های", "هاش", "آخرین",
}
_LATEST_ASK_RE = re.compile(r"چیه|چیست|کدوم|اسم|نام|چی بود|چی هست|[؟?]")
_LATEST_NOT_RE = re.compile(r"متن|لیریک|lyric|بخون|دانلود|آکورد|اکورد|ترجمه|معنی")
_LAT_VARIANTS_PROMPT = (
    "Give up to 3 spellings of this singer's/band's name as they appear on Spotify/Deezer/Apple Music "
    "(Latin script as commonly published, then the original script). Name: {q}\n"
    "Do NOT write any lyrics. Reply ONLY with JSON: {{\"queries\": [\"...\", \"...\"]}}"
)


def _lat_llm_variants(name: str) -> list:
    """«تتلو» ← ["Tataloo", "Amir Tataloo", ...] (فقط اسم خواننده، بدون اسم آهنگ)."""
    if not _ai_keys_of("gemini"):
        return []
    try:
        raw = _song_gemini_ask(_LAT_VARIANTS_PROMPT.format(q=(name or "")[:60].replace("{", "").replace("}", "")), False, 200)
        d = _song_json(raw or "") or {}
        qs = d.get("queries") if isinstance(d.get("queries"), list) else []
        return [x.strip()[:60] for x in qs if isinstance(x, str) and x.strip()][:3]
    except Exception as _e:
        logger.warning(f"[LATEST] variants خطا :: {_err_cause(_e)}")
        return []


def _latest_artist_from(text: str) -> str:
    """«نخود اخرین اهنگ تتلو چیه اسمش» ← «تتلو»؛ "" اگر خواننده‌ای جدا نشد یا طولانی بود."""
    t = re.sub(r"@\w+", " ", _ai_norm_fa(text or "")).replace("\u200c", "")
    keep = []
    for w in re.split(r"[\s؟?!.،,:؛;«»\"']+", t):
        wn = w.replace("آ", "ا").replace("ي", "ی").replace("ك", "ک")
        if w and wn not in _LATEST_STOP and w not in _LATEST_STOP:
            keep.append(w)
    return " ".join(keep) if 1 <= len(keep) <= 3 else ""


def _latest_release_answer(user_text: str):
    """«آخرین آهنگ X» ← از کاتالوگ Deezer (lyrics_service.latest_release)؛ None = پیدا نشد/ماژول نبود (مسیر وب ادامه دارد)."""
    if not (_HAS_LYRSVC and _ls_latest):
        return None
    artist = _latest_artist_from(user_text)
    if not artist:
        return None
    try:
        r = _ls_latest(artist, variants_fn=_lat_llm_variants)
    except Exception as _e:
        logger.warning(f"[LATEST] {artist!r} خطا :: {_err_cause(_e)}")
        return None
    if not r:
        logger.info(f"[LATEST] {artist!r}: در Deezer پیدا نشد؛ مسیر وب")
        return None
    logger.info(f"[LATEST] {artist!r} ← {r.get('artist')} / {r.get('title')} / {r.get('date')}")
    kind = {"single": "سینگل", "album": "آلبوم", "ep": "EP"}.get(r.get("type", ""), "اثر")
    _jdate = re.sub(r"\s*\(.*?\)\s*$", "", str(r.get("date") or "")).strip()     # فقط تاریخ شمسی؛ بدون پرانتز و تاریخ میلادی
    return f"آخرین {kind} ثبت‌شده از {r['artist']} در دیزر: «{r['title']}»\nتاریخ انتشار: {_jdate}"


def _song_bare_lyric_q(user_text: str) -> bool:
    """«این از کیه\\n<بیت>» — کلمهٔ آهنگ/شعر ندارد، ولی خط اول فقط سؤال است (≤۴ کلمه) و زیرش یک بیت (≥۴ کلمه) آمده.
    قبلاً چنین پیامی از دروازهٔ _SONG_TRIGGER_RE رد می‌شد و به مسیر عمومی وب می‌رفت؛ آنجا مدل عنوان صفحهٔ سایت
    («دانلود آهنگ <خودِ بیت>») را اسم آهنگ حساب می‌کرد و لینک‌یابی بعدی (Spotify/Apple/SoundCloud) هیچ‌چیز پیدا نمی‌کرد."""
    try:
        lines = [ln.strip(_SONG_STRIP) for ln in (user_text or "").replace("\r", "\n").split("\n")]
        lines = [ln for ln in lines if ln]
        if len(lines) < 2:
            return False
        head = _ai_norm_fa(lines[0])
        if len(head.split()) > 4 or not _SONG_Q_RE.search(head):
            return False
        return len(_ai_norm_fa(" ".join(lines[1:])).split()) >= 4
    except Exception:
        return False


def _song_lookup_impl(user_text: str, reply_ctx: str = ""):
    """شناسایی آهنگ/شعر (و فیلم، کتاب، دیالوگ): ۱) DuckDuckGo + تحلیل جمینی ← ۲) فالبک آخر: جستجوی وب گروک.
    None = این پیام از این نوع نیست (مسیر عادی ادامه پیدا کند)."""
    t = _ai_norm_fa(user_text)
    # «آخرین آهنگ فلانی چیه / اسمش چیه / چیه اسمش» ← اول کاتالوگ واقعی؛ قبل از شرط «کی خونده» (ترتیب کلمات مهم نیست)
    if (_SONG_LATEST_RE.search(t) and _LATEST_ASK_RE.search(t) and not _LATEST_NOT_RE.search(t)
            and len(t.split()) <= 8):
        _lat = _latest_release_answer(user_text)
        if _lat:
            return _lat
        logger.info(f"[SONG] «تازه‌ترین آهنگ فلانی» (کاتالوگ جواب نداد)؛ مسیر عادی وب: {t[:40]!r}")
        return None
    # فقط سؤال «کی خونده/از کیه/مال کیه» دربارهٔ اثر؛ نه هر پیامی که کلمهٔ «شعر» دارد (مثلاً «معنی این شعر چیه»)
    is_song = bool(_SONG_TRIGGER_RE.search(t))
    _bare_q = (not is_song) and _song_bare_lyric_q(user_text)      # «این از کیه\n<بیت>» بدون کلمهٔ آهنگ
    if not (_SONG_Q_RE.search(t) and (is_song or _bare_q or _SONG_WORK_RE.search(t))):
        return None
    phrase = _song_extract_phrase(user_text, reply_ctx)
    if _SONG_LATEST_RE.search(t) and len(phrase.split()) <= 5:
        logger.info(f"[SONG] «تازه‌ترین آهنگ فلانی» است، نه بیت شعر؛ مسیر عادی وب: {phrase[:30]!r}")
        return None
    if not is_song and len(phrase.split()) < 4:
        return None             # «بازیگر این فیلم کیه» و مشابه: مسیر عادی (با وب) جواب بدهد
    if not phrase:
        return _SONG_NEED_LINE if len(t.split()) <= 6 else None
    _SONG_TL.phrase = phrase
    ck = _song_norm(phrase)
    if ck in _SONG_CACHE:
        return _SONG_CACHE[ck]

    _status_web_search()
    try:
        _lys_ans = _song_lyrics_identify(phrase)            # روش صفرم: جستجوی تمام‌متن (Genius) — فقط با تأیید بیت در متن
    except Exception as _le:
        logger.warning(f"[SONG-LYR] identify failed: {_err_cause(_le)}")
        _lys_ans = None
    if not _lys_ans:
        try:
            _lys_ans = _lyricsify_identify(phrase)          # فالبک قدیمی lyricsify (فقط با LYRICSIFY_LEGACY=1)
        except Exception as _le:
            logger.warning(f"[LYS] identify failed: {_err_cause(_le)}")
            _lys_ans = None
    if _lys_ans:
        _SONG_CACHE[ck] = _lys_ans
        return _lys_ans
    ans, partial = _song_ddg_gemini(phrase)                 # روش اول: جستجوی پایتون + تحلیل جمینی
    ans = ans or _song_gemini_search(phrase)
    if ans:
        _SONG_CACHE[ck] = ans
        return ans

    g = _song_groq_search(user_text, phrase)                # پشتیبان آخر (جستجوی وب گروک)
    if g is None and not partial:
        return _SONG_BUSY       # هر دو سرویس در دسترس نبودند؛ به مسیر عادی نرو (آنجا از حافظه حدس می‌زند)
    if g is None or g == _SONG_NOT_FOUND:
        g = partial or _SONG_NOT_FOUND                      # حداقل چیزی که قطعی بود (خواننده) را بگو
    if g != _SONG_NOT_FOUND:                                # «پیدا نشد» کش نمی‌شود (قبلاً ۶ ساعت: ریت‌لیمیت لحظه‌ای = جواب منفیِ ۶ ساعته)
        _SONG_CACHE[ck] = g
    return g


def _song_lookup(user_text: str, reply_ctx: str = "", user_id=None):
    """_song_lookup_impl + حفظ آخرین آهنگ شناسایی‌شده (اسم/خواننده/بیت) برای «متنشو بده»ی بعدی."""
    _SONG_TL.phrase = ""
    ans = _song_lookup_impl(user_text, reply_ctx)
    if ans:
        _song_remember(ans, getattr(_SONG_TL, "phrase", "") or "", user_id)
    return ans


# ---------------------------------------------------------------------------
# لینک اسپاتیفای آهنگ — بدون کلید و بدون API: مثل چت‌جی‌پی‌تی، با جستجوی وبِ خودِ ربات (DuckDuckGo + بینگ)
#   «نخود لینک آهنگ خماری شایع رو بده»  یا  ریپلای روی جواب آهنگ‌یاب + «میشه لینک اسپاتیفایشو بدی»
#   فقط لینکی که عیناً در نتایج جستجو دیده شده و از دامنهٔ open.spotify.com/track/… باشد داده می‌شود (نه حدس مدل).
#   .env (اختیاری): SPOTIFY_LINKS=0 → خاموش
# ---------------------------------------------------------------------------
_SPOT_ON = os.environ.get("SPOTIFY_LINKS", "1").strip().lower() not in ("0", "false", "off", "no")
_SPOT_CACHE = TTLCache(maxsize=300, ttl=6 * 3600)

_SPOT_LINK_RE = re.compile(r"لینک|link|آدرس")
_SPOT_NAME_RE = re.compile(r"اسپاتیفای|اسپوتیفای|سپاتیفای|اسپاتیفی|spotify")
_SPOT_SONG_RE = re.compile(r"آهنگ|اهنگ|موزیک|ترانه|song|track|music")
_SPOT_OTHER_RE = re.compile(r"یوتیوب|یوتوب|youtube|youtu\.be|اینستا|instagram|پینترست|pinterest|ساندکلود|soundcloud|"
                            r"اپل ?موزیک|apple ?music|دیزر|deezer|دانلود|download|سایت|گروه|کانال")
_SPOT_DROP_PREFIX = ("لینک", "link", "اسپاتیفای", "اسپوتیفای", "سپاتیفای", "اسپاتیفی", "spotify",
                     "آهنگ", "اهنگ", "موزیک", "ترانه", "music", "song", "track",
                     "اپل", "apple", "itunes", "آیتونز", "ایتونز", "ساوندکلود", "ساندکلود", "ساوندک", "ساندک", "soundcloud",
                     "دیزر", "deezer", "میوزیک", "یوتیوب", "یوتوب")
_SPOT_VERB_RE = re.compile(r"می(?:ده|دی|دید|دین|دم|دن|دهید)|میید|بیید|بد(?:ه|ی|ید|ین|هید|م)|(?:می)?فرست\S*|بفرست\S*|"
                           r"(?:می)?تون(?:ی|م|ید|ین)|می?شه|ممنون\S*|مرسی\S*|لطفا\S*|سلام")
_SPOT_STOP = frozenset("""نخود لطفا لطفاً میشه می شه میتونی تونی ممنون مرسی بده بدی بدید بفرست بفرستی بفرستید
بزار بذار پیدا کن کنی برام برا یه یک رو را از اینو اونو همینو همین ببین بگیر میخوام خوام خواستم هم دوباره یکم
می شه خو خب خوب دیگه آخه بابا داداش
ایول آفرین عالی دمت حالا پس اها آها باشه اوکی آره اره این اون همون کدوم ساوند ساند اسپاتی
ببخشید راستی ولی اما یعنی اگه اگر اوکیه ممکنه امکانش هست""".split())


_SPOT_TRACK_RE = re.compile(r"https?://open\.spotify\.com/(?:intl-[a-z]{2}(?:-[a-z]{2})?/)?track/([A-Za-z0-9]{10,30})", re.I)
_SPOT_TITLE_RE = re.compile(r"^(.*?)\s+[-–—]\s+(?:song|single|track)\b.*?\bby\s+(.+?)\s*(?:\|\s*spotify)?\s*$", re.I)


def _spot_parse_result(r: dict):
    """نتیجهٔ وب → {title, artists, url, pop} اگر لینک ترک اسپاتیفای است؛ وگرنه None.
    عنوان صفحه‌های اسپاتیفای: «Khomari - song and lyrics by Shayea | Spotify»."""
    m = _SPOT_TRACK_RE.search(r.get("href") or "")
    if not m:
        return None
    raw = re.sub(r"\s+", " ", r.get("title") or "").strip()
    mt = _SPOT_TITLE_RE.match(re.sub(r"\s*\|\s*Spotify\s*$", "", raw, flags=re.I) + " | Spotify")
    if mt:
        title, artist = mt.group(1).strip(), mt.group(2).strip()
    else:
        title, artist = re.sub(r"\s*\|\s*Spotify\s*$", "", raw, flags=re.I).strip(), ""
    return {"title": title or "—", "artists": [artist] if artist else [],
            "url": f"https://open.spotify.com/track/{m.group(1)}", "pop": 0}


def _spot_search(q: str, limit: int = 5) -> list:
    """جستجوی وب برای لینک ترک اسپاتیفای ← [{title, artists, url, pop}] (بدون کلید/API)."""
    q = re.sub(r"\s+", " ", q or "").strip()[:120]
    if not q:
        return []
    ck = _song_norm(q)
    if ck in _SPOT_CACHE:
        return _SPOT_CACHE[ck]
    qs = [f"{q} site:open.spotify.com/track", f"{q} spotify song"]
    out, seen = [], set()
    for sq in qs:
        res = []
        try:
            futs = [_WEB_POOL.submit(_search_ddg, sq, 8), _WEB_POOL.submit(_search_bing_rss, _web_clean_q(sq), 8)]
            for f in futs:
                try:
                    res += f.result(timeout=9) or []
                except Exception:
                    pass
            if not res:
                res = _search_bing_html(sq, 8)
        except Exception as e:
            logger.warning(f"[SPOTIFY] جستجوی وب خطا :: {_err_cause(e)}")
        for r in res:
            it = _spot_parse_result(r)
            if it and it["url"] not in seen:
                seen.add(it["url"])
                out.append(it)
        if out:
            break
    out = out[:limit]
    if out:
        _SPOT_CACHE[ck] = out        # شکست را کش نکن
    return out


def _spot_sim(a: str, b: str) -> float:
    a, b = _song_norm(a), _song_norm(b)
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0
    r = difflib.SequenceMatcher(None, a, b).ratio()
    if len(a) >= 3 and (a in b or b in a):      # «خماری» داخل «خماری (Remix)»
        r = max(r, 0.85)
    return r


_SPOT_SPLIT_RE = re.compile(r"\s+و\s+|[,،&]|\bfeat\.?\b|\bft\.?\b|\bx\b", re.I)


def _spot_artist_keys(artist: str) -> set:
    """کلیدهای تطبیق خواننده، هم فارسی و هم لاتین (شایع ↔ Shayea) با املاهایی که جمینی می‌دهد."""
    keys = set()
    for part in _SPOT_SPLIT_RE.split(artist or ""):
        part = part.strip()
        if not part:
            continue
        names = [part]
        try:
            names += _lys_artist_names(part)
        except Exception:
            pass
        for n in names:
            for w in _song_norm(n).split():
                if len(w) >= 3:
                    keys.add(w)
    return keys


def _spot_artist_ok(it: dict, akeys: set) -> bool:
    toks = [w for w in _song_norm(" ".join(it["artists"])).split() if len(w) >= 2]
    for k in akeys:
        for w in toks:
            if k == w or difflib.SequenceMatcher(None, k, w).ratio() >= 0.8 or (len(k) >= 4 and len(w) >= 4 and (k in w or w in k)):
                return True
    return False


_SPOT_VER_RE = re.compile(r"\b(?:sped ?up|speed ?up|slowed|reverb|remix|nightcore|8d|instrumental|karaoke|cover|acoustic|"
                          r"live|lo-?fi|mashup|bass boosted|edit|rework|remaster(?:ed)?|extended|radio|version|ver)\b", re.I)


def _spot_deaccent(s: str) -> str:
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFKD", s or "") if not unicodedata.combining(c))


def _spot_version_ok(ref_title: str, q: str, cand_title: str) -> bool:
    """نتیجهٔ اسپاتیفای باید «همان نسخه» باشد: اسمش به اسم تأییدشده (مثلاً از اپل/دیزر) شبیه باشد و نشانهٔ نسخهٔ دیگر
    (Sped Up / Remix / Slowed / Live …) داشته باشد فقط اگر در اسم اصلی یا درخواست هم بوده."""
    ref = _spot_deaccent(ref_title).lower()
    cand = _spot_deaccent(cand_title).lower()
    ctx = ref + " " + _spot_deaccent(q).lower()
    for m in _SPOT_VER_RE.finditer(cand):
        if m.group(0) not in ctx:
            return False
    return _spot_sim(ref, cand) >= 0.8


def _spot_pick(items: list, title: str, artist: str, q: str, need=None, akeys=None, ref_title=None):
    """بهترین ترک از نتایج. اگر خواننده معلوم است (akeys) فقط ترک‌هایی که خواننده‌شان تأیید شود قبول می‌شوند —
    وگرنه «خماری» از هر خواننده‌ی دیگری جای آهنگ درست می‌نشست."""
    qt = set(_song_norm(q).split())
    best, best_s = None, 0.0
    for it in items:
        if akeys and not _spot_artist_ok(it, akeys):
            continue
        if ref_title and not _spot_version_ok(ref_title, q, it["title"]):
            continue
        if title:
            s = _spot_sim(title, it["title"])
        else:
            tt = set(_song_norm(it["title"] + " " + " ".join(it["artists"])).split())
            s = len(qt & tt) / max(1, len(qt))
        s += min(it.get("pop", 0), 100) / 1000.0       # بین دو نتیجهٔ هم‌امتیاز، محبوب‌تر
        if s > best_s:
            best, best_s = it, s
    if need is None:
        need = 0.75 if title else 0.5
    return (best, best_s) if best_s >= need else (None, best_s)


def _spot_resolve(title: str, artist: str, q: str, ref_title=None):
    """(آیتم|None, approx). فقط نتیجه‌ای که تأیید شده برمی‌گردد (خواننده + اسم)؛ حدس بی‌پشتوانه نمی‌دهیم.
    اول املای لاتین/استاندارد (اسپاتیفای بیشتر لاتین ایندکس شده)، بعد خودِ متن فارسی."""
    q0 = (f"{title} {artist}".strip() if title else q).strip()
    akeys = _spot_artist_keys(artist) if artist else None
    tried = set()
    for v in _lys_llm_variants(q0):
        if not v or _song_norm(v) in tried:
            continue
        tried.add(_song_norm(v))
        found = _spot_search(v)
        need = 0.7 if len(_song_norm(v).split()) >= 2 else 0.5
        best, s = _spot_pick(found, "", "", v, need=need, akeys=akeys, ref_title=ref_title)
        logger.info(f"[SPOTIFY] واریانت {v!r}: {len(found)} نتیجه ← {'OK ' + best['url'] if best else 'تأیید نشد'} ({s:.2f})")
        if best:
            return best, False
    for v in ([q0] + ([title] if (title and artist) else [])):
        if not v or _song_norm(v) in tried:
            continue
        tried.add(_song_norm(v))
        found = _spot_search(v)
        best, s = _spot_pick(found, title, artist, v, akeys=akeys, ref_title=ref_title)
        logger.info(f"[SPOTIFY] متن {v!r}: {len(found)} نتیجه ← {'OK ' + best['url'] if best else 'تأیید نشد'} ({s:.2f})")
        if best:
            return best, False
    return None, False


def _spot_query(t: str) -> str:
    """از متن نرمال‌شدهٔ کاربر، کلمات درخواست (لینک/اسپاتیفای/بده/…) را حذف می‌کند؛ باقی‌مانده = اسم آهنگ/خواننده."""
    t = re.sub(r"@\w+", " ", t)
    t = re.sub(r"[«»\"'“”()\[\]{}؟?!،,:؛;]", " ", t)
    keep = []
    for w in t.split():
        if w in _SPOT_STOP or w.startswith(_SPOT_DROP_PREFIX) or _SPOT_VERB_RE.fullmatch(w):
            continue
        keep.append(w)
    return " ".join(keep)[:120].strip()


def _spot_from_reply(reply_ctx: str):
    """از متن پیام ریپلای‌شده (جواب آهنگ‌یاب/متن‌آهنگ خودِ ربات) → (اسم آهنگ، خواننده)؛ نشد → ("","")."""
    if not reply_ctx:
        return "", ""
    m0 = re.search(r"«([^«»\n]{1,100})»\s+از\s+([^\n«»(]{1,80})", reply_ctx)       # «اسم» از خواننده  (جواب آهنگ‌یاب)
    if m0:
        t0 = m0.group(1).strip()
        if " - " in t0:                                   # «Hichkas - Oon Mesle ...» ← فقط اسم آهنگ
            t0 = t0.rsplit(" - ", 1)[1].strip()
        a0 = re.sub(r"\s+باشه\s*$", "", m0.group(2)).strip(" ،.…")
        return t0[:80], a0[:80]
    m = re.search(r"^«(.*?)»[ \t]*$", reply_ctx, re.M | re.S) or re.search(r"«(.+?)»", reply_ctx, re.S)
    if not m:
        return "", ""
    r = m.group(1).strip()
    m1 = re.match(r"\s*🎵\s*«(.+?)»\s*[—–-]\s*(.+?)\s*(?:\n|$)", r)                       # 🎵 «اسم» — خواننده
    if m1:
        return m1.group(1).strip()[:80], m1.group(2).strip()[:80]
    m2 = re.match(r"\s*(?:🎵\s*)?(?:آهنگ|ترانه)\s*[«\"]?(.+?)[»\"]?\s+از\s+(.+?)\s*(?:\n|$)", r)   # آهنگ X از Y
    if m2:
        return m2.group(1).strip()[:80], m2.group(2).strip()[:80]
    t3 = re.search(r"اثر\s*[:：]\s*\[?(.+?)\]?\s*(?:\n|$)", r)                              # 🎵 اثر: X / خواننده: Y
    if t3:
        a3 = re.search(r"(?:خواننده|صاحب اثر)[^:：\n]*[:：]\s*\[?(.+?)\]?\s*(?:\n|$)", r)
        return t3.group(1).strip()[:80], (a3.group(1).strip()[:80] if a3 else "")
    return "", ""


# ---------------------------------------------------------------------------
# لینک پلتفرم‌های موزیک — اسپاتیفای / اپل‌موزیک / ساوندکلود (+ دیزر / یوتیوب‌موزیک)        [r13]
#   «لینک اسپاتیفایشو بده» / «اپل موزیکشو میدی» / «لینک ساوندکلودشو بده» / «لینک آهنگ X از Y»
#   آهنگ از این‌ها مشخص می‌شود: متن پیام ← ریپلای ← آخرین آهنگ شناسایی‌شدهٔ کاربر ← گفتگوی اخیر (با جمینی).
#   روش پیدا کردن لینک (به‌جای جستجوی وب با site: که موتورها بلاک/۴۲۹ می‌دادند):
#     ۱) کاتالوگ iTunes (اپل‌موزیک) + Deezer — رایگان، بی‌کلید، JSON رسمی
#     ۲) Odesli/song.link — از همان لینک، بقیهٔ پلتفرم‌ها (اسپاتیفای/ساوندکلود/…) را می‌دهد (تطبیق با ISRC)
#     ۳) ساوندکلود: API داخلی با client_id که خودکار از صفحهٔ سایت خوانده می‌شود
#     ۴) اسپاتیفای: Odesli؛ اگر SPOTIFY_CLIENT_ID/SECRET در .env بود API رسمی؛ آخرین راه جستجوی وب قدیمی
#   فقط لینکی که «تأیید» شده (اسم + خواننده) داده می‌شود؛ وگرنه لینک جستجوی همان پلتفرم.
#   .env (همه اختیاری): SPOTIFY_LINKS=0 خاموش | SPOTIFY_CLIENT_ID / SPOTIFY_CLIENT_SECRET |
#                       SOUNDCLOUD_CLIENT_ID | SONGLINK_API_KEY | MLINK_DEBUG=1
# ---------------------------------------------------------------------------
_MLINK_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
             "Chrome/126.0.0.0 Safari/537.36")
_MLINK_CACHE = TTLCache(maxsize=400, ttl=6 * 3600)        # norm(متن) -> {links, meta, seed}
_MLINK_HIST_CACHE = TTLCache(maxsize=300, ttl=1800)       # امضای گفتگو -> (title, artist)
_MLINK_SC = {"id": "", "ts": 0.0}
_MLINK_SC_LOCK = threading.Lock()
_MLINK_SPOT_TOK = {"tok": "", "exp": 0.0}
_MLINK_ODESLI = {"until": 0.0}
_MLINK_AKEYS = TTLCache(maxsize=500, ttl=6 * 3600)

_MLINK_PLATS = (
    # کلید، شکلک، نام نمایشی، تشخیص در متن (بعد از _ai_norm_fa: حروف کوچک، نیم‌فاصله ← فاصله)
    ("spotify", "🟢", "Spotify", re.compile(r"اسپاتیفای|اسپوتیفای|سپاتیفای|اسپاتیفی|اسپاتی|spotify")),
    ("apple", "🍎", "Apple Music", re.compile(r"اپل ?(?:موزیک|میوزیک)|apple ?music|itunes|آیتونز|ایتونز")),
    ("soundcloud", "🟠", "SoundCloud", re.compile(r"ساوند ?ک[لب]ود|ساند ?ک[لب]ود|soundcloud")),
    ("deezer", "🟣", "Deezer", re.compile(r"دیزر|deezer")),
    ("ytmusic", "🔴", "YouTube Music", re.compile(r"(?:یوتیوب|یوتوب) ?(?:موزیک|میوزیک)|youtube ?music|yt ?music")),
)
_MLINK_DEFAULT = ("spotify", "apple", "soundcloud")
_MLINK_OTHER_RE = re.compile(r"یوتیوب|یوتوب|youtube|youtu\.be|اینستا|instagram|پینترست|pinterest|دانلود|download|سایت|گروه|کانال")
_MLINK_APPISH_RE = re.compile(r"نصب|اپلیکیشن|برنامه|اکانت|پریمیوم|premium|اشتراک|فیلتر|vpn|وی ?پی ?ان|کرک|ایمیل|رمز|"
                             r"دانلود|download|ویندوز|windows|اندروید|android|لپ ?تاپ")
_MLINK_ANS_RE = re.compile(r"🎧\s*«([^«»\n]{1,100})»\s*[—–-]\s*([^\n]{1,100})")
_MLINK_SEARCH_URL = {
    "spotify": "https://open.spotify.com/search/{q}",
    "apple": "https://music.apple.com/search?term={q}",
    "soundcloud": "https://soundcloud.com/search?q={q}",
    "deezer": "https://www.deezer.com/search/{q}",
    "ytmusic": "https://music.youtube.com/search?q={q}",
}
_MLINK_DEBUG = os.environ.get("MLINK_DEBUG", "").strip().lower() in ("1", "true", "on", "yes")


def _mlink_get(url: str, params=None, headers=None, timeout: float = 8.0):
    h = {"User-Agent": _MLINK_UA, "Accept": "application/json, text/plain, */*", "Accept-Language": "en-US,en;q=0.8"}
    if headers:
        h.update(headers)
    return _ai_session.get(url, params=params, headers=h, timeout=timeout)


def _mlink_clean_apple(u: str) -> str:
    u = re.sub(r"([?&])uo=\d+&?", r"\1", u or "")
    return u.rstrip("?&")


# ---- جستجو در کاتالوگ‌ها: همه → [{title, artists, url, pop, src}] --------------------------------
def _mlink_itunes(term: str, limit: int = 10) -> list:
    out = []
    try:
        r = _mlink_get("https://itunes.apple.com/search",
                       {"term": term[:120], "media": "music", "entity": "song", "limit": limit, "country": "US"}, timeout=8)
        if r.status_code != 200:
            logger.info(f"[MLINK] iTunes {r.status_code} برای {term[:40]!r}")
            return []
        for it in (r.json().get("results") or []):
            u = _mlink_clean_apple(it.get("trackViewUrl") or "")
            if u and it.get("trackName"):
                out.append({"title": it["trackName"], "artists": [it.get("artistName") or ""], "url": u,
                            "pop": 0, "src": "apple"})
    except Exception as e:
        logger.warning(f"[MLINK] iTunes خطا :: {_err_cause(e)}")
    return out


def _mlink_deezer(term: str, limit: int = 10) -> list:
    out = []
    try:
        r = _mlink_get("https://api.deezer.com/search", {"q": term[:120], "limit": limit}, timeout=8)
        if r.status_code != 200:
            logger.info(f"[MLINK] Deezer {r.status_code} برای {term[:40]!r}")
            return []
        for it in (r.json().get("data") or []):
            if it.get("link") and it.get("title"):
                out.append({"title": it["title"], "artists": [(it.get("artist") or {}).get("name") or ""],
                            "url": it["link"].split("?")[0], "pop": min(100, int(it.get("rank") or 0) // 10000),
                            "src": "deezer"})
    except Exception as e:
        logger.warning(f"[MLINK] Deezer خطا :: {_err_cause(e)}")
    return out


def _mlink_sc_client_id(force: bool = False) -> str:
    """client_id ساوندکلود: از .env یا خودکار از جاوااسکریپت صفحهٔ اصلی سایت (۶ ساعت کش)."""
    env = os.environ.get("SOUNDCLOUD_CLIENT_ID", "").strip()
    if env and not force:
        return env
    with _MLINK_SC_LOCK:
        if _MLINK_SC["id"] and not force and time.time() - _MLINK_SC["ts"] < 6 * 3600:
            return _MLINK_SC["id"]
        cid = ""
        try:
            r = _mlink_get("https://soundcloud.com/", headers={"Accept": "text/html,*/*"}, timeout=8)
            urls = re.findall(r'src="(https://a-v2\.sndcdn\.com/assets/[^"]+\.js)"', r.text or "")
            for u in reversed(urls[-8:]):
                try:
                    js = _mlink_get(u, headers={"Accept": "*/*"}, timeout=8).text or ""
                except Exception:
                    continue
                m = re.search(r'client_id\s*[:=]\s*"([0-9a-zA-Z]{32})"', js)
                if m:
                    cid = m.group(1)
                    break
        except Exception as e:
            logger.warning(f"[MLINK] خواندن client_id ساوندکلود خطا :: {_err_cause(e)}")
        if cid:
            _MLINK_SC.update(id=cid, ts=time.time())
            logger.info("[MLINK] client_id ساوندکلود به‌روز شد")
        else:
            logger.warning("[MLINK] client_id ساوندکلود پیدا نشد (SOUNDCLOUD_CLIENT_ID را در .env بگذار)")
        return cid


def _mlink_soundcloud(term: str, limit: int = 10) -> list:
    for attempt in (0, 1):
        cid = _mlink_sc_client_id(force=bool(attempt))
        if not cid:
            return []
        try:
            r = _mlink_get("https://api-v2.soundcloud.com/search/tracks",
                           {"q": term[:120], "client_id": cid, "limit": limit, "offset": 0,
                            "linked_partitioning": 1, "app_locale": "en"}, timeout=8)
        except Exception as e:
            logger.warning(f"[MLINK] SoundCloud خطا :: {_err_cause(e)}")
            return []
        if r.status_code in (401, 403):
            logger.info(f"[MLINK] SoundCloud {r.status_code} ← client_id تازه می‌گیرم")
            continue
        if r.status_code != 200:
            logger.info(f"[MLINK] SoundCloud {r.status_code}")
            return []
        out = []
        for it in (r.json().get("collection") or []):
            u, title = it.get("permalink_url"), it.get("title") or ""
            if not (u and title):
                continue
            pm = it.get("publisher_metadata") or {}
            who = [a for a in (pm.get("artist"), (it.get("user") or {}).get("username"), title) if a]
            out.append({"title": title, "artists": who, "url": u.split("?")[0],
                        "pop": min(100, int(it.get("playback_count") or 0) // 100000), "src": "soundcloud"})
        return out
    return []


def _mlink_spotify_token() -> str:
    cid, sec = os.environ.get("SPOTIFY_CLIENT_ID", "").strip(), os.environ.get("SPOTIFY_CLIENT_SECRET", "").strip()
    if not (cid and sec):
        return ""
    if _MLINK_SPOT_TOK["tok"] and _MLINK_SPOT_TOK["exp"] > time.time() + 30:
        return _MLINK_SPOT_TOK["tok"]
    try:
        r = _ai_session.post("https://accounts.spotify.com/api/token", data={"grant_type": "client_credentials"},
                             auth=(cid, sec), headers={"User-Agent": _MLINK_UA}, timeout=8)
        if r.status_code == 200:
            d = r.json()
            _MLINK_SPOT_TOK.update(tok=d.get("access_token") or "", exp=time.time() + int(d.get("expires_in") or 3000))
            return _MLINK_SPOT_TOK["tok"]
        logger.warning(f"[MLINK] توکن اسپاتیفای {r.status_code}")
    except Exception as e:
        logger.warning(f"[MLINK] توکن اسپاتیفای خطا :: {_err_cause(e)}")
    return ""


def _mlink_spotify_api(term: str, limit: int = 10) -> list:
    tok = _mlink_spotify_token()
    if not tok:
        return []
    try:
        r = _ai_session.get("https://api.spotify.com/v1/search",
                            params={"q": term[:120], "type": "track", "limit": limit, "market": "US"},
                            headers={"Authorization": f"Bearer {tok}", "User-Agent": _MLINK_UA}, timeout=8)
        if r.status_code == 401:
            _MLINK_SPOT_TOK["exp"] = 0.0
            return []
        if r.status_code != 200:
            logger.info(f"[MLINK] Spotify API {r.status_code}")
            return []
        out = []
        for it in ((r.json().get("tracks") or {}).get("items") or []):
            u = (it.get("external_urls") or {}).get("spotify")
            if u and it.get("name"):
                out.append({"title": it["name"], "artists": [a.get("name") or "" for a in (it.get("artists") or [])],
                            "url": u, "pop": int(it.get("popularity") or 0), "src": "spotify"})
        return out
    except Exception as e:
        logger.warning(f"[MLINK] Spotify API خطا :: {_err_cause(e)}")
        return []


_MLINK_ODESLI_MAP = {"spotify": "spotify", "appleMusic": "apple", "soundcloud": "soundcloud",
                     "deezer": "deezer", "youtubeMusic": "ytmusic"}


def _mlink_odesli(url: str) -> dict:
    """Odesli/song.link: یک لینک آهنگ ← لینک بقیهٔ پلتفرم‌ها {spotify, apple, soundcloud, deezer, ytmusic}.
    سقف رایگان ~۱۰ درخواست در دقیقه؛ ۴۲۹ ← یک دقیقه کنار می‌رود (SONGLINK_API_KEY سقف را برمی‌دارد)."""
    if not url or time.time() < _MLINK_ODESLI["until"]:
        return {}
    params = {"url": url, "userCountry": "US", "songIfSingle": "true"}
    key = os.environ.get("SONGLINK_API_KEY", "").strip()
    if key:
        params["key"] = key
    try:
        r = _mlink_get("https://api.song.link/v1-alpha.1/links", params, timeout=12)
        if r.status_code == 429:
            _MLINK_ODESLI["until"] = time.time() + 60
            logger.warning("[MLINK] Odesli ۴۲۹ (سقف درخواست) ← یک دقیقه کنار گذاشته شد")
            return {}
        if r.status_code in (401, 403):
            _MLINK_ODESLI["until"] = time.time() + 6 * 3600
            logger.warning(f"[MLINK] Odesli {r.status_code}: کلید لازم است (SONGLINK_API_KEY در .env) ← ۶ ساعت کنار گذاشته شد")
            return {}
        if r.status_code != 200:
            logger.info(f"[MLINK] Odesli {r.status_code} برای {url[:60]}")
            return {}
        lp = (r.json() or {}).get("linksByPlatform") or {}
        out = {}
        for k, v in _MLINK_ODESLI_MAP.items():
            u = (lp.get(k) or {}).get("url")
            if u:
                out[v] = _mlink_clean_apple(u) if v == "apple" else u
        return out
    except Exception as e:
        logger.warning(f"[MLINK] Odesli خطا :: {_err_cause(e)}")
        return {}


_MLINK_SEARCH_FN = {"apple": _mlink_itunes, "deezer": _mlink_deezer, "soundcloud": _mlink_soundcloud,
                    "spotify": _mlink_spotify_api}


def _mlink_akeys(artist: str):
    if not artist:
        return None
    k = _song_norm(artist)
    if k not in _MLINK_AKEYS:
        _MLINK_AKEYS[k] = _spot_artist_keys(artist)
    return _MLINK_AKEYS[k] or None


def _mlink_catalog(term: str) -> list:
    """iTunes + Deezer هم‌زمان (از ترد درخواست صدا بزن، نه از داخل خودِ _WEB_POOL)."""
    futs = [_WEB_POOL.submit(_mlink_itunes, term), _WEB_POOL.submit(_mlink_deezer, term)]
    out = []
    for f in futs:
        try:
            out += f.result(timeout=12) or []
        except Exception:
            pass
    return out


def _mlink_pick_seed(title: str, artist: str, q0: str, variants_fn):
    """اول متن خام، بعد املای لاتین/استاندارد جمینی، بعد فقط اسم آهنگ ← بهترین آهنگِ تأییدشده در iTunes/Deezer."""
    akeys = _mlink_akeys(artist)
    found = _mlink_catalog(q0)
    best, s = _spot_pick(found, title, artist, q0, akeys=akeys)
    logger.info(f"[MLINK] متن {q0!r}: {len(found)} نتیجه ← {'OK ' + best['url'] if best else 'تأیید نشد'} ({s:.2f})")
    if best:
        return best
    for v in variants_fn():
        found = _mlink_catalog(v)
        need = 0.7 if len(_song_norm(v).split()) >= 2 else 0.5
        best, s = _spot_pick(found, "", "", v, need=need, akeys=akeys)
        logger.info(f"[MLINK] واریانت {v!r}: {len(found)} نتیجه ← {'OK ' + best['url'] if best else 'تأیید نشد'} ({s:.2f})")
        if best:
            return best
    if title and artist:
        found = _mlink_catalog(title)
        best, s = _spot_pick(found, title, artist, title, akeys=akeys)
        logger.info(f"[MLINK] فقط اسم {title!r}: {len(found)} نتیجه ← {'OK ' + best['url'] if best else 'تأیید نشد'} ({s:.2f})")
        if best:
            return best
    return None


def _mlink_find(plat: str, seed, title: str, artist: str, q0: str, variants_fn):
    """لینک یک پلتفرم با جستجوی مستقیم در همان پلتفرم + تأیید. (بدون ترد داخلی؛ امن برای اجرا در ترد جدا)"""
    fn = _MLINK_SEARCH_FN.get(plat)
    if not fn:
        return None
    attempts = []
    if seed:
        a0 = next((a for a in seed["artists"] if a), "")
        attempts.append((f"{a0} {seed['title']}".strip(), seed["title"], a0))
    attempts.append((q0, title, artist))
    for term, ttl, art in attempts:
        found = fn(term)
        best, s = _spot_pick(found, ttl, art, term, akeys=_mlink_akeys(art))
        logger.info(f"[MLINK] {plat} {term!r}: {len(found)} نتیجه ← {'OK ' + best['url'] if best else 'تأیید نشد'} ({s:.2f})")
        if best:
            return best
    akeys = _mlink_akeys(artist)
    for v in variants_fn():
        found = fn(v)
        need = 0.7 if len(_song_norm(v).split()) >= 2 else 0.5
        best, s = _spot_pick(found, "", "", v, need=need, akeys=akeys)
        logger.info(f"[MLINK] {plat} واریانت {v!r}: {len(found)} نتیجه ← {'OK ' + best['url'] if best else 'تأیید نشد'} ({s:.2f})")
        if best:
            return best
    return None


def _mlink_resolve(title: str, artist: str, q: str, want):
    """→ (links {پلتفرم: url}, meta {title, artists}). فقط لینک‌های تأییدشده؛ نبود ← در links نیست."""
    q0 = (f"{artist} {title}".strip() if title else q).strip()
    ck = _song_norm(q0)
    cached = _MLINK_CACHE.get(ck) or {}
    links = dict(cached.get("links") or {})
    meta = dict(cached.get("meta") or {"title": title, "artists": [artist] if artist else []})
    seed = cached.get("seed")
    if all(p in links for p in want):
        return links, meta

    var_cache = []

    def variants_fn():
        if not var_cache:
            try:
                var_cache.append([v for v in (_lys_llm_variants(q0) or []) if v and v.strip()])
            except Exception:
                var_cache.append([])
        return var_cache[0]

    if not seed:
        seed = _mlink_pick_seed(title, artist, q0, variants_fn)
        if seed:
            links.setdefault(seed["src"], seed["url"])
            meta = {"title": seed["title"], "artists": [a for a in seed["artists"] if a][:2]}

    # بقیهٔ پلتفرم‌ها از روی همان آهنگِ تأییدشده (ISRC) — دقیق‌ترین راه
    if seed and any(p not in links for p in want):
        for p, u in _mlink_odesli(seed["url"]).items():
            links.setdefault(p, u)

    # هنوز نبود ← جستجوی مستقیم در همان پلتفرم (موازی)
    todo = [p for p in want if p not in links and p in _MLINK_SEARCH_FN
            and not (p == "spotify" and not _mlink_spotify_token())]
    if todo:
        with ThreadPoolExecutor(max_workers=len(todo), thread_name_prefix="mlink") as ex:
            futs = {p: ex.submit(_mlink_find, p, seed, title, artist, q0, variants_fn) for p in todo}
            for p, f in futs.items():
                try:
                    it = f.result(timeout=25)
                except Exception as e:
                    logger.warning(f"[MLINK] {p} خطا :: {_err_cause(e)}")
                    it = None
                if it:
                    links[p] = it["url"]
                    if not seed:
                        seed = it
                        meta = {"title": it["title"], "artists": [a for a in it["artists"] if a][:2]}

    # آخرین راهِ اسپاتیفای: جستجوی وبِ قدیمی (site:open.spotify.com)
    if "spotify" in want and "spotify" not in links:
        try:
            # اسم/خوانندهٔ تأییدشده از اپل/دیزر (seed) مرجع است؛ نسخهٔ دیگر آهنگ (Sped Up/Remix/…) قبول نمی‌شود
            _rt = (seed or {}).get("title") or title
            _ra = next((a for a in ((seed or {}).get("artists") or []) if a), "") or artist
            it, _ = _spot_resolve(_rt or title, _ra or artist, q, ref_title=(_rt or None))
            if it:
                links["spotify"] = it["url"]
                if not meta.get("title") or meta.get("title") == "—":
                    meta = {"title": it["title"], "artists": it["artists"]}
        except Exception as e:
            logger.warning(f"[MLINK] اسپاتیفای (وب) خطا :: {_err_cause(e)}")

    if links:                                  # شکست را کش نکن
        _MLINK_CACHE[ck] = {"links": links, "meta": meta, "seed": seed}
    return links, meta


def _mlink_format(links: dict, meta: dict, want, sq: str) -> str:
    esc = lambda s: html.escape(s or "", quote=False)
    names = {k: (e, n) for k, e, n, _ in _MLINK_PLATS}
    head = f"🎧 «{esc(meta.get('title') or sq)}»"
    arts = ", ".join(a for a in (meta.get("artists") or []) if a)
    if arts and links:
        head += f" — {esc(arts)}"
    lines = []
    if links:
        lines.append(head)
    qs = urllib.parse.quote((sq or "")[:100])
    miss = []
    for p in want:
        e, n = names[p]
        if p in links:
            lines.append(f"{e} {n}: {esc(links[p])}")
        else:
            miss.append(f"{e} {n}: {_MLINK_SEARCH_URL[p].format(q=qs)}")
    if miss:
        lines.append(("\n" if links else "") + ("لینک دقیق این‌ها رو پیدا نکردم و لینک اشتباه هم نمی‌دم؛ اینجا جستجو کن:"
                                                  if links else
                                                  "🎧 لینک دقیقش رو پیدا نکردم و لینک اشتباه هم نمی‌دم؛ اینجا جستجو کن:"))
        lines += miss
    return "\n".join(lines)


# ---- تشخیص آهنگ از گفتگو -------------------------------------------------------------------------
def _mlink_song_from_history(history):
    """آخرین آهنگی که در گفتگو مطرح شده → (title, artist) یا ("","").
    اول از جواب‌های خودِ ربات (قالب‌های شناخته‌شده)، بعد یک سؤال کوتاه از جمینی روی ۱۰ پیام آخر."""
    msgs = [m for m in list(history or [])[-14:] if isinstance(m, dict) and str(m.get("content") or "").strip()]
    if not msgs:
        return "", ""
    for m in reversed(msgs):
        if m.get("role") != "assistant":
            continue
        c = str(m.get("content") or "")
        mm = _MLINK_ANS_RE.search(c)
        if mm:
            return mm.group(1).strip(), re.split(r"\s*[,،]\s*", mm.group(2).strip())[0]
        t, a = _lys_parse_answer(c)
        if t and a:
            return t, a
        t, a = _spot_from_reply(c)
        if t and a:
            return t, a
    if not _ai_keys_of("gemini"):
        return "", ""
    chat = "\n".join(f"{'BOT' if m.get('role') == 'assistant' else 'USER'}: {str(m.get('content'))[:280]}"
                     for m in msgs[-10:])
    sig = hashlib.md5(chat.encode("utf-8", "ignore")).hexdigest()
    if sig in _MLINK_HIST_CACHE:
        return _MLINK_HIST_CACHE[sig]
    prompt = ("CHAT (oldest → newest):\n" + chat.replace("{", "(").replace("}", ")") + "\n\n"
              "Task: which ONE song is this conversation about right now — the song the newest messages refer to when "
              "the user asks for \"its link\"? Use ONLY what is written in the chat; never guess from memory. "
              "If the chat is about a specific version (remix / cover / live), keep that version in the title. "
              "If no specific song is clear, answer {\"title\": null}.\n"
              "Reply ONLY with JSON: {\"title\": \"...\", \"artist\": \"...\"} (copy the spelling used in the chat; "
              "artist may be empty).")
    res = ("", "")
    try:
        d = _song_json(_song_gemini_ask(prompt, False, 200) or "") or {}
        t, a = _song_s(d.get("title")), _song_s(d.get("artist"))
        if t:
            res = (t[:90], a[:80])
    except Exception as e:
        logger.warning(f"[MLINK] تشخیص آهنگ از گفتگو خطا :: {_err_cause(e)}")
    if res[0]:
        _MLINK_HIST_CACHE[sig] = res
    return res


_MLINK_VER_RE = re.compile(r"اصلیشو|اصلیش|اورجینال|اوریجینال|ورژن اصلی|نسخه اصلی|نسخه ی اصلی|original version|studio version")
_MLINK_QUESTION_RE = re.compile(r"چیه|چیست|چی هست|چطور|چجوری|چگونه|فرق|بهتره|کدوم|قیمت|رایگان")


def _mlink_ask_info(user_text: str):
    """درخواست لینک آهنگ را تشخیص می‌دهد. None = از این نوع نیست.
    kind: link («لینک … بده») | plat («دیزرشو بده» / «اسپاتیفای» / «ساوندکلودشو هم پیدا نکردی») | ver («ورژن اصلیشو بده»)."""
    t = _ai_norm_fa(user_text or "")
    if not t or "http" in t or len(t) > 300:
        return None
    plats = [k for k, _e, _n, rx in _MLINK_PLATS if rx.search(t)]
    words = t.split()
    has_link = bool(_SPOT_LINK_RE.search(t))
    has_verb = bool(_SPOT_VERB_RE.search(t))
    if has_link or (plats and len(words) <= 7 and has_verb):
        kind = "link"
    elif plats and len(words) <= 8 and not _MLINK_QUESTION_RE.search(t):
        kind = "plat"
    elif len(words) <= 9 and has_verb and _MLINK_VER_RE.search(t):
        kind = "ver"
    else:
        return None
    if _MLINK_APPISH_RE.search(t) or (not plats and _MLINK_OTHER_RE.search(t)):
        return None                                  # لینک دانلود برنامه/سایت/یوتیوب/… ← کار این بخش نیست
    return {"t": t, "plats": plats, "want": tuple(plats) or _MLINK_DEFAULT, "kind": kind,
            "explicit": has_link or bool(_SPOT_SONG_RE.search(t))}


def _mlink_remember(user_id, title: str, artists, ans: str = ""):
    """آهنگِ پیدا‌شده را برای پیام بعدی («ساوندکلودشو هم بده» / «ورژن اصلیش» / «متنشو بده») نگه می‌دارد."""
    try:
        if user_id and title:
            a0 = next((a for a in (artists or []) if a), "")
            if _SONG_FA_RE.search(f"{title} {a0}"):
                title, a0 = _song_latinize(title, a0)
            _SONG_LAST_BY_USER[user_id] = {"title": title, "artist": a0, "phrase": "", "answer": (ans or "")[:400]}
    except Exception:
        pass


_MLINK_REPLY_JUNK_RE = re.compile(r"^\s*$")      # ریپلای خالی = بدون زمینه


def _music_link_request(user_text: str, reply_ctx: str = "", user_id=None, history=None, with_image: bool = False):
    """«لینک اسپاتیفای/اپل‌موزیک/ساوندکلود (فلان آهنگ) رو بده» ← متن جواب (لینک واقعی)؛ None = از این نوع نیست.
    with_image=True: پیام روی عکس آمده؛ آهنگ را عکس مشخص می‌کند (نه حافظه) ← بدون اسم صریح None می‌دهد تا مسیر عکس/handoff برود."""
    if not _SPOT_ON:
        return None
    info = _mlink_ask_info(user_text)
    if not info:
        return None
    t, plats, want, kind, explicit = info["t"], info["plats"], info["want"], info["kind"], info["explicit"]
    r_title = r_artist = src = ""
    if not with_image:
        r_title, r_artist = _spot_from_reply(reply_ctx)
        if not r_title and reply_ctx:                # فرمت‌های دیگرِ جواب ربات («فکر کنم «X» از Y باشه» / «اسمش «X» ه»)
            r_title, r_artist = _lys_parse_answer(_lys_unwrap_reply(reply_ctx))
        if not r_title and reply_ctx and not _MLINK_REPLY_JUNK_RE.search(reply_ctx):
            r_title, r_artist = _mlink_song_from_history([{"role": "assistant", "content": _lys_unwrap_reply(reply_ctx)[:600]}])
        if r_title:
            r_title, r_artist = _song_latinize(r_title, r_artist)
        src = "reply" if r_title else ""
        if not r_title and user_id and not reply_ctx:  # فقط وقتی ریپلای نکرده: آخرین آهنگِ شناسایی‌شدهٔ همین کاربر (با ریپلای، حافظهٔ قدیمی آهنگ اشتباه می‌دهد)
            _um = _SONG_LAST_BY_USER.get(user_id) or {}
            if _um.get("title"):
                r_title, r_artist, src = _um["title"], _um.get("artist") or "", "user"
    if not (plats or _SPOT_SONG_RE.search(t) or r_title):
        return None
    if kind == "ver" and not r_title:
        _mh_t, _mh_a = ("", "") if with_image else _mlink_song_from_history(history)
        if not _mh_t:
            return None
        r_title, r_artist, src = _mh_t, _mh_a, "history"
    q = _spot_query(t)
    if kind == "ver":
        q = ""
    elif r_title and (not explicit or len(q.split()) <= 1):
        q = ""                                       # «دیزرشو بده» / «لینکشو میدی»؛ آهنگ همان است که ریپلای/حافظه می‌گوید
    elif not explicit and not (2 <= len(q.split()) <= 5):
        q = ""                                       # «خو … ساوندکلودشو هم پیدا نکردی اخه» ← حرف اضافه اسم آهنگ نیست
    if len(q.split()) == 1 and len(q) < 4:
        q = ""                                       # تک‌کلمهٔ خیلی کوتاه («یده»/«اگه») اسم آهنگ نیست
    if with_image and not (len(q.split()) >= 2 or len(q) >= 5):
        return None                                  # آهنگ را عکس مشخص می‌کند ← handoff (_img_music_link_answer)
    title = artist = ""
    if len(q) < 2:
        title, artist = r_title, r_artist
        if not title and not with_image:             # از گفتگوی اخیر بفهم (مثلاً بعد از چند پیام دربارهٔ یک آهنگ)
            title, artist = _mlink_song_from_history(history)
            src = "history" if title else ""
        if not title:
            if kind == "link" and not with_image:
                return ("🎧 اسم آهنگ رو بگو یا روی پیامِ آهنگ ریپلای کن؛ مثلاً:\n"
                        "«نخود لینک اسپاتیفای آهنگ خماری شایع رو بده»")
            return None
    logger.info(f"[MLINK] درخواست({kind}): پلتفرم={list(want)} title={title!r} artist={artist!r} q={q!r} منبع={src or 'متن'}")
    _status_web_search()
    links, meta = _mlink_resolve(title, artist, q, want)
    sq = (f"{artist} {title}".strip() if title else q) or (meta.get("title") or "")
    ans = _mlink_format(links, meta, want, sq)
    if links:
        _mlink_remember(user_id, meta.get("title") or title or q, meta.get("artists") or [artist], ans)
    return ans


# نام قدیمی (فراخوان‌های دیگر/سازگاری)
def _spotify_link_request(user_text: str, reply_ctx: str = "", user_id=None, history=None):
    return _music_link_request(user_text, reply_ctx, user_id, history)


def _song_text_phrase_ok(user_text: str) -> bool:
    """متنِ خودِ کاربر هم «سؤال آهنگ‌یاب» است و هم یک بیت (≥۳ کلمه) دارد؟"""
    try:
        t = _ai_norm_fa(user_text or "")
        if not (_SONG_Q_RE.search(t) and (_SONG_TRIGGER_RE.search(t) or _SONG_WORK_RE.search(t)
                                          or _song_bare_lyric_q(user_text))):
            return False
        return len((_song_extract_phrase(user_text, "") or "").split()) >= 3
    except Exception:
        return False


_AI_CTX_POOL = ThreadPoolExecutor(max_workers=16, thread_name_prefix="ai-ctx")
_AI_CTX_TIMEOUT = _env_float("AI_CTX_TIMEOUT_SEC", 40.0)

# ---- اسم مدل زیر جواب (AI_SHOW_MODEL=0 → خاموش) ----
# مدلی که واقعاً جواب داد (بعد از فالبک‌ها) در ترد-لوکال ذخیره می‌شود و هندلر ته جوابِ متنی می‌چسباند. به ویس/OCR اضافه نمی‌شود.
# برای عوض‌کردن اسم نمایشی، همین دیکشنری را ویرایش کن.
_AI_SHOW_MODEL = os.environ.get("AI_SHOW_MODEL", "1").strip().lower() not in ("0", "false", "off", "no")
_AI_PROVIDER_LABEL = {"groq": "Groq", "gemini": "Gemini", "openrouter": "OpenRouter"}
_AI_MODEL_TL = threading.local()
_AI_MODEL_TAG_RE = re.compile(
    r"\n+— (?:" + "|".join(re.escape(v) for v in _AI_PROVIDER_LABEL.values()) + r")(?: · [^\n<>]{1,60})?\s*$")
_AI_MODEL_TAG_NOTE = ("ربات خودش اسم مدل را ته جواب اضافه می‌کند؛ تو هرگز خطی مثل «— Groq» یا «— Gemini» ننویس "
                      "و اگر در پیام‌های قبلی چنین خطی دیدی تقلیدش نکن.")


# ---- لحن محاوره‌ای: قواعد پرامپت (برای همهٔ مسیرها از جمله عکس) + اصلاح‌گر کدیِ محافظه‌کار ----
# مدل‌ها گاهی «نشان می‌دهد / یک / آن» می‌نویسند حتی وقتی پرامپت می‌گوید خودمونی؛ پرامپتِ مسیر عکس هم قبلاً قاعدهٔ لحن نداشت.
# AI_COLLOQUIAL_FIX=0 → اصلاح‌گر کدی خاموش (قواعد پرامپت می‌مانند)
_AI_COLLOQ_ON = os.environ.get("AI_COLLOQUIAL_FIX", "1").strip().lower() not in ("0", "false", "off", "no")
_COLLOQUIAL_RULES = """
لحن واژه‌ها (برای همهٔ جواب‌ها، از جمله توضیح عکس):
فارسی محاوره‌ای واقعی بنویس، نه کتابی. مثلا:
«یه» نه «یک» | «نشون میده» نه «نشان می‌دهد» | «اون» نه «آن» | «اونا» نه «آن‌ها» | «داره» نه «دارد» | «میشه» نه «می‌شود»
«می‌تونه» نه «می‌تواند» | «می‌گه» نه «می‌گوید» | «اینجوری» نه «این‌گونه» | «پس» نه «بنابراین/لذا» | «هستن» نه «هستند» | «خوبه» نه «خوب است».
مثال درست: «این عکس یه اسکرین‌شات از یه پیام تلگرامیه که یه QR کد نشون میده».
نقل‌قول عینیِ متنِ داخل عکس، کد، لینک و اسم‌ها رو همون‌طور که هست بنویس و محاوره‌ای نکن.
"""
_COLLOQUIAL_FINAL = ("یادآوری لحن: فارسی محاوره‌ای و خودمونی بنویس (یه، نشون میده، اون، داره، میشه) نه کتابی (یک، نشان می‌دهد، آن، دارد، می‌شود).")

_FA_B_L = r"(?<![\u0600-\u06FF\u200c])"
_FA_B_R = r"(?![\u0621-\u065F\u0670-\u06D3\u200c])"
_AI_COLLOQ_MAP = (
    (r"می[\u200c ]?دهد", "میده"), (r"می[\u200c ]?دهند", "میدن"),
    (r"می[\u200c ]?کند", "می‌کنه"), (r"می[\u200c ]?کنند", "می‌کنن"),
    (r"می[\u200c ]?شود", "میشه"), (r"می[\u200c ]?شوند", "میشن"),
    (r"می[\u200c ]?تواند", "می‌تونه"), (r"می[\u200c ]?توانند", "می‌تونن"), (r"می[\u200c ]?توانید", "می‌تونی"),
    (r"می[\u200c ]?خواهد", "می‌خواد"), (r"می[\u200c ]?خواهند", "می‌خوان"), (r"می[\u200c ]?خواهید", "می‌خوای"),
    (r"می[\u200c ]?گوید", "می‌گه"), (r"می[\u200c ]?گویند", "می‌گن"),
    (r"می[\u200c ]?باشد", "هست"), (r"می[\u200c ]?باشند", "هستن"),
    (r"می[\u200c ]?بینید", "می‌بینی"),
    (r"نمی[\u200c ]?دانم", "نمی‌دونم"), (r"نمی[\u200c ]?توانم", "نمی‌تونم"), (r"نمی[\u200c ]?توانی", "نمی‌تونی"),
    (r"نمی[\u200c ]?شود", "نمیشه"), (r"نمی[\u200c ]?کند", "نمی‌کنه"), (r"نمی[\u200c ]?دهد", "نمیده"),
    (r"می[\u200c ]?توانی", "می‌تونی"), (r"می[\u200c ]?خواهی", "می‌خوای"), (r"می[\u200c ]?دانی", "می‌دونی"),
    (r"می[\u200c ]?دانم", "می‌دونم"), (r"می[\u200c ]?دانید", "می‌دونی"), (r"می[\u200c ]?توانم", "می‌تونم"),
    (r"دارد", "داره"), (r"دارند", "دارن"), (r"هستند", "هستن"), (r"هستید", "هستی"),
    (r"بنابراین", "پس"), (r"لذا", "پس"),
    (r"این[\u200c ]?گونه", "اینجوری"), (r"بدین[\u200c ]?گونه", "اینجوری"), (r"آن[\u200c ]?گونه", "اونجوری"),
    (r"آن[\u200c ]?ها", "اونا"), (r"آن", "اون"),
    (r"نشان(?=\s+(?:میده|میدن|داد|داده|بده|بدن)(?![\u0621-\u065F\u0670-\u06D3]))", "نشون"),
    # «یک» → «یه» فقط وقتی بعدش کلمهٔ فارسی می‌آید؛ «یک و نیم»، «ساعت یک …»، «شماره/عدد یک …» دست‌نخورده
    (r"(?<!ساعت )(?<!شماره )(?<!عدد )یک(?=\s+(?!و(?![\u0621-\u065F\u0670-\u06D3]))[\u0621-\u06D3])", "یه"),
)
_AI_COLLOQ_RX = tuple((re.compile(_FA_B_L + pat + _FA_B_R), to) for pat, to in _AI_COLLOQ_MAP)
# بخش‌هایی که هرگز تغییر نمی‌کنند: بلوک کد، تگ‌های HTML (آدرس لینک)، نقل‌قول داخل «» یا “” یا "…" (متن عینیِ عکس/منبع)
_AI_COLLOQ_SKIP_RE = re.compile(r'(<pre\b.*?</pre>|<code\b.*?</code>|<[^>]+>|«[^»]*»|“[^”]*”|"[^"\n]*")', re.S)


def _ai_colloquial_fix(text: str) -> str:
    """کلمه‌های کتابیِ پرتکرار را محاوره‌ای می‌کند (یک→یه، نشان می‌دهد→نشون میده، …)؛ کد، لینک و نقل‌قول‌ها دست‌نخورده."""
    if not (_AI_COLLOQ_ON and text):
        return text
    parts = _AI_COLLOQ_SKIP_RE.split(text)
    for i in range(0, len(parts), 2):
        seg = parts[i]
        for rx, to in _AI_COLLOQ_RX:
            seg = rx.sub(to, seg)
        parts[i] = seg
    return "".join(parts)


# ---- چسباندن نیم‌فاصله‌های «می‌ده / صبحانه‌م» در جواب مدل‌ها ----
# روی بعضی فونت/اپ‌ها نیم‌فاصله (ZWNJ) مثل فاصله دیده می‌شود («می ده»، «صبحانه م»).
# این اصلاح‌گر فقط دو الگوی پرتکرار را می‌چسباند: پیشوند «می/نمی» و ضمیرهای متصل (م ت ش مون تون شون ...).
# بقیهٔ نیم‌فاصله‌ها (خانه‌ها، آب‌وهوا، ...) دست‌نخورده می‌مانند. AI_HALFSPACE_JOIN=0 → خاموش.
_AI_HS_ON = os.environ.get("AI_HALFSPACE_JOIN", "1").strip().lower() not in ("0", "false", "off", "no")
_AI_HS_MI_RE = re.compile(r"(?<![\u0600-\u06FF\u200c])(ن?می)\u200c(?=[\u0621-\u06D3])")
_AI_HS_CLITIC_RE = re.compile(
    r"(?<=[\u0621-\u06D3])\u200c(?=(?:مان|تان|شان|مون|تون|شون|م|ت|ش)(?![\u0621-\u06D3\u200c]))")


def _ai_halfspace_join(text: str) -> str:
    """«می‌ده»→«میده»، «صبحانه‌م»→«صبحانهم»؛ کد، تگ HTML و نقل‌قول‌ها دست‌نخورده."""
    if not (_AI_HS_ON and text) or "\u200c" not in text:
        return text
    parts = _AI_COLLOQ_SKIP_RE.split(text)
    for i in range(0, len(parts), 2):
        seg = parts[i]
        seg = _AI_HS_MI_RE.sub(r"\1", seg)
        seg = _AI_HS_CLITIC_RE.sub("", seg)
        parts[i] = seg
    return "".join(parts)


def _ai_model_label(provider: str, model: str) -> str:
    p = _AI_PROVIDER_LABEL.get(provider) or (provider or "AI").capitalize()
    m = (model or "").strip().split("/")[-1].split(":")[0]
    if m.lower().startswith(p.lower()):
        m = m[len(p):].lstrip("-_ ")
    return f"{p} · {m}" if m else p


def _ai_add_model_tag(text: str) -> str:
    """«— Groq · compound» را بعد از یک خط فاصله ته جواب می‌گذارد (اگر مدلی جواب داده بود و قبلاً نگذاشته بودیم)."""
    label = getattr(_AI_MODEL_TL, "label", "") or ""
    if not (_AI_SHOW_MODEL and label and text):
        return text
    if _AI_MODEL_TAG_RE.search(text):
        return text
    return text.rstrip() + "\n\n— " + html.escape(label, quote=False)


def _ai_strip_model_tag(text: str) -> str:
    """برای حافظهٔ گروه: برچسب مدل از پیام‌های خودِ ربات حذف می‌شود تا مدل تقلیدش نکند."""
    return _AI_MODEL_TAG_RE.sub("", text or "")


def ask_chand_ai(
    user_text: str,
    cache_key: str | None = None,
    max_msgs: int = 10,
    max_tokens: int = 2500,
    route: str | None = None,
    web: bool = True,
    weather: bool = True,
    _retry: bool = False,
    _intent: dict | None = None,
    user_id: int | None = None,
    history_override: list | None = None,
    group_ctx: str = "",
    reply_ctx: str = "",
    images: list | None = None,
    _img_mode: str = "",
    _temperature: float | None = None,
) -> str:
    """پاسخ هوش مصنوعی با مسیریابی گروک/جمینی + فالبک کلید و مدل + کش مکالمه.
    route: "market" (گروک: اینترنت، بازار، دانش ربات) | "chat" (جمینی: گپ آزاد) | None = تشخیص نیت با مدل زبانی
    (_ai_resolve_intent: تصمیم می‌گیرد داده بازار / هوا / وب / دانش ربات لازم است یا نه؛ خطا → regex).
    web: در مسیر market اجازهٔ استفاده از مدل‌های جستجوی وب گروک (برای کارهای بدون نیاز به وب False بده).
    حالت گروه (حافظهٔ مشترک): history_override = چند پیام آخر برای تشخیص نیت (به مدل به‌صورت نوبت چت داده نمی‌شود)،
    group_ctx = بلوک «حافظهٔ گروه» که به پرامپت سیستم اضافه می‌شود، reply_ctx = پیام ریپلای‌شده + زنجیرهٔ ریپلای
    که قبل از حرف کاربر در پیام کاربر می‌آید.
    images: [{"mime","b64"}, …] عکس‌های ضمیمه — وقتی داده شود فقط جمینی (دارای بینایی) جواب می‌دهد، با مدل‌های دقیق‌تر،
    تفکر بیشتر و رزولوشن بالا (بخش «تحلیل تصویر»)؛ گروک عکس نمی‌بیند پس فالبک نمی‌شود."""
    images = list(images or [])
    _AI_MODEL_TL.label = ""
    reload_ai_keys()  # اگر .env عوض شده باشد، کلیدهای جدید بدون ری‌استارت وارد چرخه می‌شوند
    # «لینک (اسپاتیفای/اپل‌موزیک/ساوندکلود) فلان آهنگ رو بده» → لینک واقعی از کاتالوگ‌ها (None = از این نوع نیست؛ مسیر عادی)
    if not _retry and _SPOT_ON:
        try:
            _mh = history_override if history_override is not None else (_ai_get_history(cache_key) if cache_key else [])
            _sp_ans = _music_link_request(user_text, reply_ctx, user_id, _mh, with_image=bool(images))
        except Exception as _spe:
            logger.warning(f"[SPOTIFY] failed: {_err_cause(_spe)}")
            _sp_ans = None
        if _sp_ans:
            if cache_key:
                _ai_append(cache_key, "user", user_text[:600], max_msgs)
                _ai_append(cache_key, "assistant", _sp_ans[:1500], max_msgs)
            return _sp_ans
    # «این آهنگ/شعر از کیه؟» → مسیر تخصصی جستجوی آهنگ (جستجوی اجباری + اعتبارسنجی در کد)؛ None = مسیر عادی
    _uni_call = bool(_intent and _intent.get("source") == "unified")     # نیت را همین حالا مسیریابِ واحد داده (route/web هم پاس شده)
    _txt_song = bool(images) and _song_text_phrase_ok(user_text)         # «این آهنگ از کیه: <بیت>» روی عکس ← متن مهم‌تر از عکس
    if (not images or _txt_song) and ((route is None and _intent is None) or _uni_call or _txt_song) and not _retry and (_SONG_LOOKUP_ON or _LYS_ON):
        try:
            _lys_hist = history_override if history_override is not None else (_ai_get_history(cache_key) if cache_key else [])
            _song_ans = _lyrics_request(user_text, reply_ctx, _lys_hist, user_id) if _LYS_ON else None   # «متن آهنگ X» / «آهنگ X رو بخون» / «متنشو بده»
            if not _song_ans and _SONG_LOOKUP_ON:
                _song_ans = _song_lookup(user_text, reply_ctx, user_id)         # «این آهنگ از کیه؟»
        except Exception as _se:
            logger.warning(f"[SONG] lookup failed: {_err_cause(_se)}")
            _song_ans = None
        if _song_ans:
            if cache_key:
                _ai_append(cache_key, "user", user_text[:600], max_msgs)
                _ai_append(cache_key, "assistant", _song_ans[:1500], max_msgs)
            return _song_ans
    if history_override is not None:
        history = list(history_override)
    else:
        history = _ai_get_history(cache_key) if cache_key else []
    if images:
        # عکس: تشخیص نیت با مدل زبانی لازم نیست (سریع‌تر)؛ فقط regex برای هوا/داده زندهٔ بازار
        intent = dict(_intent) if _intent is not None else _ai_intent_regex(user_text)
        intent["route"] = route = "chat"
        web = False
    elif _intent is not None:
        intent = _intent
    elif route not in _AI_ROUTE_PROVIDERS:
        intent = _ai_resolve_intent(user_text, history)
        route = intent["route"]
        web = web and intent["web"]   # وب فقط وقتی لازم است (سریع‌تر و کم‌مصرف‌تر)
    else:
        # route را صدا‌زننده مشخص کرده (مثلاً خلاصهٔ خبر): بدون مسیریابی، همان رفتار قبلی
        intent = {"route": route, "market_data": route == "market", "weather": False,
                  "cities": [], "weather_future": False, "web": web, "source": "explicit"}
    # سؤال هوا بدون نام شهر («هوا فردا چطوره؟») → شهر ذخیره‌شدهٔ همان کاربر (اگر /هوا ثبتش کرده باشد)
    if user_id and _HAS_WEATHER and intent.get("weather") and not intent.get("cities"):
        _saved = get_user_weather_city(user_id)
        if _saved:
            intent = dict(intent)
            intent["cities"] = [_saved]       # dict با مختصات؛ _weather_block/_weather_direct_answer هر دو شکل را می‌فهمند
    providers = [
        p for p in _AI_ROUTE_PROVIDERS[route]
        if _ai_keys_of(p)
    ]
    _upref = None
    if user_id and len(providers) > 1 and intent.get("source") != "img-handoff":
        # /مدل: سرویس دلخواه کاربر اول امتحان می‌شود (هم گپ، هم قیمت/بازار/وب/هوا)؛ اگر از دسترس خارج بود بقیه (فالبک) جایگزین می‌شوند.
        # «خودکار» (پیش‌فرض) = ترتیب AI_CHAT_ORDER (گپ) یا AI_MARKET_ORDER (بازار/وب) بدون تغییر.
        # handoff عکس مستثناست: آن مسیر حتماً به مدلِ دارای جستجوی وب داخلی (گروک) نیاز دارد.
        _upref = get_user_ai_choice(user_id)
        if _upref and _upref in providers:
            providers = [_upref] + [p for p in providers if p != _upref]
        else:
            _upref = None
    if images:
        providers = [p for p in providers if p in ("gemini", "openrouter")]     # فقط این دو عکس را می‌فهمند
    # مسیر «market»/وب معمولاً فقط گروک دارد؛ اگر جمینی کلید دارد ممکن است پایین‌تر (با نتایج DDG/بینگ) اضافه شود
    _gem_web_possible = bool(_AI_GEMINI_WEB_ON and route == "market" and not images and _ai_keys_of("gemini"))
    if not providers and not _gem_web_possible:
        return render_text_or_default("ai_disabled_msg")

    live = ""
    _live_cache: dict = {}
    _focus_txt = (user_text or "") + "\n" + (reply_ctx or "")[:600]
    _hist_txt = " ".join(
        str(m.get("content") or "")[:300] for m in (history or [])[-4:]
        if isinstance(m, dict) and m.get("role") == "user"
    )

    # داده زندهٔ بازار / هواشناسی / ورزش / جستجوی وب مستقل از هم‌اند؛ قبلاً پشت‌سرهم اجرا می‌شدند (زمان‌ها جمع می‌شد).
    # حالا هر کدام که لازم باشد هم‌زمان شروع می‌شود و زمان کل = کندترینشان. شرط‌ها و خروجی‌ها دقیقاً مثل قبل است.
    web_ctx = ""
    _web_wanted = bool(not images and web and intent.get("web") and intent.get("source") not in ("img-handoff", "song"))
    _ctx_jobs: dict = {}
    _t_ctx = time.time()
    if (route == "market" or images) and intent["market_data"]:
        _ctx_jobs["live"] = _AI_CTX_POOL.submit(
            lambda: _build_live_market_context(_focus_txt, history_text=_hist_txt,
                                               analysis=_market_wants_analysis(user_text)))
    if weather and intent["weather"]:
        _ctx_jobs["weather"] = _AI_CTX_POOL.submit(
            lambda: _weather_block(intent["cities"], intent["weather_future"]))
    if _SPORTS_LIVE_ON and not images and _sports_wanted(user_text):
        _ctx_jobs["sports"] = _AI_CTX_POOL.submit(lambda: _sports_context(user_text))
    if _web_wanted:
        _status_web_search()      # پیام انتظار: «در حال جستجو در وب...» (از ترد اصلی صدا زده می‌شود چون ترد-لوکال است)
        _ctx_jobs["web"] = _AI_CTX_POOL.submit(
            lambda: _build_web_context(user_text, reply_ctx, q_hint=intent.get("web_q") or "",
                                       fresh=intent.get("fresh")))

    def _ctx_result(key: str, fail_default: str, log_tag: str) -> str:
        f = _ctx_jobs.get(key)
        if f is None:
            return ""
        try:
            return f.result(timeout=_AI_CTX_TIMEOUT) or ""
        except Exception as e:
            logger.warning(f"[{log_tag}] context failed: {_err_cause(e)}")
            return fail_default

    live = _ctx_result("live", "داده بازار زنده در دسترس نیست", "AI")
    weather_ctx = _ctx_result("weather", "", "AI-WEATHER")
    sports_ctx = _ctx_result("sports", "", "SPORTS")
    web_ctx = _ctx_result("web", "", "WEB-DDG")
    if len(_ctx_jobs) > 1:
        logger.info(f"[AI] منابع هم‌زمان: {','.join(_ctx_jobs)} took={time.time() - _t_ctx:.1f}s")

    # وب برای جمینی: جمینی ابزار جستجوی خودش را در چت ندارد، پس سؤال‌های «فقط وب» (خبر، ورزش، آدم‌ها، فناوری، …)
    # با نتایج DuckDuckGo+بینگ که بالا در web_ctx آمده به جمینی داده می‌شوند و گروک (compound با وب خودش) فالبک می‌ماند.
    # شرط‌ها: نتیجه‌ای از جستجو داریم (وگرنه جمینی بدون منبع حدس می‌زند → همان گروکِ دارای وب) و پیام قیمت/تحلیل بازار نیست
    # (آن‌ها با «داده بازار زنده» و قالب ۶بخشی روی گروک می‌مانند).
    _gem_web = bool(_gem_web_possible and web_ctx and not intent.get("market_data") and not _upref)   # انتخاب صریح کاربر را بهم نزن
    if _gem_web:
        providers = ["gemini"] + [p for p in providers if p != "gemini"]
        logger.info(f"[AI] وب → جمینی با نتایج DDG/بینگ (فالبک: {', '.join(providers[1:]) or 'ندارد'})")
    # وب لازم بود ولی DDG/بینگ چیزی نداد: جمینی با جستجوی گوگل (Grounding) و گروک با مدل‌های compound خودشان جستجو می‌کنند؛
    # اوپن‌روتر ابزار وب ندارد، پس اگر کاربر آن را انتخاب کرده بود در این حالت خاص یکی از آن دو جلو می‌افتد.
    _gem_native = bool(_web_wanted and not web_ctx and not images and route == "market")
    if _gem_native and providers and providers[0] == "openrouter":
        for _np in ("gemini", "groq"):
            if _np in providers and (_np == "gemini" or GROQ_WEB_MODELS):
                providers = [_np] + [p for p in providers if p != _np]
                logger.info(f"[AI] وب بدون نتیجهٔ DDG؛ اوپن‌روتر ابزار وب ندارد → {_np} جلو افتاد")
                break
    if not providers and not images and _ai_keys_of("gemini"):
        # مسیر وب/بازار هیچ ارائه‌دهنده‌ای نداشت و جستجو هم نتیجه‌ای نداد (یا گروک کلید ندارد): به‌جای «هوش مصنوعی غیرفعال است»
        # با جمینی در حالت گپ جواب بده؛ _WEB_FAIL_NOTE پایین به مدل می‌گوید حدس نزند و صادقانه بگوید پیدا نشد.
        providers = ["gemini"]
        route = "chat"
        logger.info("[AI] مسیر وب بدون ارائه‌دهنده/نتیجه → فالبک جمینی (گپ)")
    if not providers:
        return render_text_or_default("ai_disabled_msg")

    # شخصیت/هویت از تنظیمات قابل‌ویرایش پنل ادمین می‌آید (adm:edit:ai_personality / ai_personality_openrouter = پرامپت گپ جمینی)؛
    # قوانین داده/اعداد و دانش ربات در _BOT_KNOWLEDGE ثابت می‌مانند (فقط مسیر بازار).
    _utl = 4000 if intent.get("source") == "img-handoff" else 1000     # شرح عکس در handoff بلندتر است

    def _messages_for(provider: str, compact: bool = False) -> list:
        if images and _img_mode == "ocr":
            return [{"role": "system", "content": _OCR_SYSTEM},
                    {"role": "user", "content": _OCR_PROMPT, "images": images}]
        _gem_web_now = bool(_gem_web and provider == "gemini")    # جمینی روی مسیر وب (با نتایج DDG/بینگ)
        use_chat_persona = route == "chat" or _gem_web_now or (route == "market" and provider != "groq")
        pkey = "ai_personality_openrouter" if use_chat_persona else "ai_personality"
        personality = render_text(pkey) or _AI_PERSONALITY_DEFAULT
        if images:
            system = personality + "\n\n" + _VISION_RULES
            if _img_mode == "nosearch":
                system += "\n\n" + _VISION_NOSEARCH_NOTE
            elif _img_handoff_active():
                system += "\n\n" + _VISION_HANDOFF_RULES
            if live:
                system += ("\n\nداده بازار زنده (فقط اگر به عکس یا سؤال کاربر ربط دارد استفاده کن؛ "
                           "عددها را از همین داده بگو، نه از حدس):\n" + live)
        elif _gem_web_now:
            system = personality + "\n\n" + _GEMINI_WEB_RULES + _WEB_TONE_RULES + _STYLE_CASUAL_RULES
        elif route == "market":
            _lv = live
            if compact and live:
                if "c" not in _live_cache:
                    try:
                        _live_cache["c"] = _build_live_market_context(_focus_txt, compact=True, history_text=_hist_txt)
                    except Exception:
                        _live_cache["c"] = live
                _lv = _live_cache["c"]
            # قالب ۶بخشی تحلیل فقط وقتی کاربر تحلیل/پیش‌بینی/خرید و فروش خواسته؛ قوانین جستجوی وب فقط وقتی وب لازم است
            _kn = _BOT_KNOWLEDGE if (not compact and _market_wants_analysis(user_text)) else _BOT_KNOWLEDGE_LITE
            if provider == "groq":
                _wr = _GROQ_WEB_RULES if (_web_wanted or (web and GROQ_WEB_MODELS)) and not compact else ""
            else:
                # جمینی/اوپن‌روتر: جستجوی داخلی ندارند؛ منبع وبشان بلوک «نتایج جستجوی زنده» است که ته پرامپت می‌آید
                _wr = _GEMINI_WEB_RULES if (web_ctx and not compact) else ""
                if _wr and live:
                    _wr += ("\nاگر «داده بازار زنده» هم در پرامپت هست، برای نمادهای داخل آن همان عددها را بگو، "
                            "نه نتیجهٔ جستجو.\n")
            _wt = _WEB_TONE_RULES if _wr else ""
            system = personality + "\n\n" + _kn + "\n\n" + _wr + _wt + _STYLE_CASUAL_RULES + "\n\n" + _lv
        else:
            system = personality + "\n\n" + _CHAT_RULES + _STYLE_CASUAL_RULES
        system += "\n\n" + _AI_SCOPE_RULE
        if _AI_SHOW_MODEL:
            system += "\n\n" + _AI_MODEL_TAG_NOTE
        system += "\n\n" + _COLLOQUIAL_RULES
        if not compact and not images and _asks_about_bot(user_text):
            system += "\n\n" + _AI_SELF_FEATURES
        if not compact:
            system += "\n\n" + _AI_CODE_RULE
        if _HAS_PINTEREST and not images and not compact:
            system += "\n\n" + _AI_IMAGE_RULE
        system += "\n\n" + calendar_context(user_text)   # تاریخ شمسی/میلادی از ساعت سرور (هر سال خودکار)
        if weather_ctx:
            system += "\n\n" + weather_ctx
        if sports_ctx:
            system += "\n\n" + (sports_ctx[:3500] if compact else sports_ctx)
        if web_ctx:
            system += "\n\n" + (web_ctx[:3500] if compact else web_ctx)
        elif _web_wanted and not sports_ctx:
            system += "\n\n" + _WEB_FAIL_NOTE
        if group_ctx:
            system += "\n\n" + (group_ctx[:1500] if compact else group_ctx)
        if not images and (web_ctx or route == "market" or _gem_web_now):
            system += "\n\n" + _WEB_TONE_FINAL           # آخرین چیزی که مدل می‌بیند، نه متن رسمی نتایج جستجو
        system += "\n\n" + _COLLOQUIAL_FINAL
        msgs = [{"role": "system", "content": system}]
        if history_override is None:
            msgs.extend(history[-4:] if compact else history)
        if reply_ctx:
            user_content = reply_ctx + "\n\nپیام کاربر:\n" + user_text[:_utl]
        else:
            user_content = user_text[:_utl]
        _um = {"role": "user", "content": user_content}
        if images:
            _um["images"] = images
        msgs.append(_um)
        return msgs

    last_err = None
    try:
        _total_budget = float(os.environ.get("AI_TOTAL_TIMEOUT_SEC", "50") or 50)
    except ValueError:
        _total_budget = 50.0
    if images:
        _total_budget = max(_total_budget, IMG_TOTAL_BUDGET)
    _deadline = time.time() + _total_budget
    _t_start = time.time()
    _tries = 0
    _skipped_cd = False
    for provider in providers:
        if time.time() > _deadline:
            break
        n_keys = len(_ai_keys_of(provider))
        messages = _messages_for(provider)
        models = ((list(OPENROUTER_VISION_MODELS) if provider == "openrouter" else _img_models())
                  or _ai_models_for(provider, route, web)) if images \
            else list(_ai_models_for(provider, route, web))
        _compact_on = False
        _mt_now = max_tokens
        if route == "market" and provider == "groq" and not images:
            # گروک «توکن ورودی + max_tokens» را با سقف دقیقه‌ای (TPM) مقایسه می‌کند؛ پس max_tokens بزرگ خودش باعث 413 می‌شود
            _mt_now = min(max_tokens, _GROQ_MARKET_MAXTOK)
        try:
            logger.info(f"[AI] prompt route={route} provider={provider} chars="
                        f"{sum(len(str(m.get('content') or '')) for m in messages)} max_tok={_mt_now}")
        except Exception:
            pass
        _conn_fail = False
        logger.info(f"[AI] start route={route} provider={provider} keys={n_keys} order={models} "
                    f"budget={_total_budget:.0f}s gem_timeout={_AI_GEMINI_TIMEOUT:.0f}s build={AI_BUILD}")
        for _ in range(n_keys):
            if time.time() > _deadline:
                break
            slot = _next_ai_slot(provider)
            if not slot:
                break
            _, key = slot
            if _AI_DEAD_KEYS.get(key, 0) > time.time():
                continue
            for model in models:
                if time.time() > _deadline:
                    break
                _cdp = f"{provider}-img" if images else provider      # کول‌داون عکس، چت متنی را خراب نکند
                _cd = max(_AI_MODEL_COOLDOWN.get((_cdp, model), 0),
                          _AI_MODEL_COOLDOWN.get((_cdp, model, key), 0))
                if _cd > time.time():
                    _skipped_cd = True
                    logger.info(f"[AI] skip {provider}/{model} (cooldown {_cd - time.time():.0f}s left)")
                    continue
                try:
                    _t_call = time.time()
                    _tries += 1
                    r = _ai_http_post(
                        provider, key, model, messages, _mt_now,
                        (0.0 if _img_mode == "ocr" else 0.3) if images else (_temperature if _temperature is not None else (0.62 if (route == "market" and provider == "groq") else 0.40)),
                        (15, IMG_HTTP_TIMEOUT) if images else (
                            (5, max(3.0, min(_GROQ_WEB_TIMEOUT if model in GROQ_WEB_MODELS else
                                             ((max(_AI_GEMINI_TIMEOUT, 20.0) if _gem_native else _AI_GEMINI_TIMEOUT)
                                              if provider == "gemini" else 45),
                                             _deadline - time.time())))),
                        vision=bool(images),
                        search_web=bool(_gem_native and provider == "gemini"),
                        think=("minimal" if _compact_on else None),
                    )
                    if r.status_code == 200:
                        data = r.json()
                        choice0 = (data.get("choices") or [{}])[0]
                        content = (
                            ((choice0.get("message") or {}).get("content") or "")
                            .strip()
                        )
                        content = _ai_strip_think(content)
                        if images and _img_mode == "ocr":
                            if content:
                                logger.info(f"[OCR] provider={provider} model={model} took={time.time() - _t_call:.1f}s "
                                            f"chars={len(content)}")
                                return _ocr_format_reply(content)
                            continue
                        if images and not _img_mode and _IMG_WEB_MARK in content[:60]:
                            # جمینی: «این سؤال اینترنت می‌خواهد» → گروک (جستجوی وب) با شرح دقیق عکس
                            return _img_web_handoff(user_text, content, images, intent, user_id,
                                                    history_override, group_ctx, reply_ctx, max_tokens)
                        if images:
                            content = content.replace(_IMG_WEB_MARK, "").strip()
                        content = _ai_leak_guard(
                            _ai_strip_markdown(_force_latin_digits(content), code_html=True), relaxed=bool(images)
                        )
                        content = _scrub_unverified_spotify(content)       # لینک اسپاتیفای ساختگیِ مدل ← حذف
                        finish = choice0.get("finish_reason") or ""
                        if content:
                            if finish == "length":
                                logger.warning(
                                    "[AI] response truncated by max_tokens "
                                    f"(len={len(content)}) — consider higher limit"
                                )
                                # اگر جمع‌بندی بریده شده یک جمله پایانی اضافه کن
                                if route == "market" and "جمع‌بندی" in content and not content.rstrip().endswith(
                                    ("تضمینی", ".", "۔", "!")
                                ):
                                    content = (
                                        content.rstrip()
                                        + _ai_disclaimer_suffix()
                                    )
                            if cache_key:
                                _ai_append(cache_key, "user", user_text[:600], max_msgs)
                                _ai_append(cache_key, "assistant", _ai_code_html_to_md(content)[:1500], max_msgs)
                            _u = (data.get("_usage") or {}) if isinstance(data, dict) else {}
                            _extra = (f" think_tokens={_u.get('think')} out_tokens={_u.get('out')} in_tokens={_u.get('in')}"
                                      if _u else "")
                            logger.info(
                                f"[AI] route={route} provider={provider} model={model} "
                                f"took={time.time() - _t_call:.1f}s total={time.time() - _t_start:.1f}s tries={_tries}{_extra}"
                            )
                            _AI_MODEL_TL.label = _ai_model_label(provider, model)
                            return _ai_prettify_spacing(_ai_strip_opener(_ai_halfspace_join(_ai_colloquial_fix(content))))
                    elif r.status_code in (400, 401, 403) and _body_says_bad_key(r.text):
                        # کلید مرده/لو‌رفته (گوگل 400 یا 403 می‌دهد) — تا یک ساعت کنار بگذار و برو کلید بعدی
                        last_err = "bad key"
                        _AI_DEAD_KEYS[key] = time.time() + _AI_DEADKEY_SEC
                        logger.warning(f"[AI] {provider} key rejected ({_mask_key(key)}) — skipped for 1h")
                        break
                    elif r.status_code in (400, 404):
                        last_err = f"model {model} {r.status_code}"
                        _gone = 6 * 3600 if (model in GROQ_WEB_MODELS and r.status_code == 404) else _AI_MODELGONE_SEC   # compound بدون دسترسی: ۶ ساعت کنار
                        _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _gone
                        logger.warning(
                            f"[AI] model unavailable/rejected: {provider}/{model} {r.status_code} "
                            f"— skipped for {_gone}s :: {_err_brief(r.text)}"
                        )
                        continue
                    elif r.status_code == 413:
                        # «Request too large»: پرامپت (+max_tokens) از سقف توکن/دقیقهٔ مدل بیشتر است. کلید یا مدل مشکل ندارد،
                        # پس کولدان نمی‌گذاریم؛ یک بار با پرامپت فشرده (نمادهای کمتر، بدون قالب تحلیل، تاریخچهٔ کوتاه) دوباره همان مدل را امتحان می‌کنیم.
                        last_err = f"model {model} 413"
                        logger.warning(f"[AI] {provider}/{model} 413 request too large — compact={_compact_on}")
                        if not _compact_on and not images:
                            _compact_on = True
                            messages = _messages_for(provider, compact=True)
                            _mt_now = min(_mt_now, 1000)
                            try:
                                logger.info(f"[AI] retry compact chars="
                                            f"{sum(len(str(m.get('content') or '')) for m in messages)} max_tok={_mt_now}")
                            except Exception:
                                pass
                            models.insert(models.index(model) + 1, model)
                        continue
                    elif r.status_code == 429:
                        # سقف نرخ معمولاً «به‌ازای هر مدل» است؛ مدل بعدی همین کلید را امتحان کن
                        last_err = f"model {model} 429"
                        _AI_MODEL_COOLDOWN[(_cdp, model, key)] = time.time() + _AI_RATELIMIT_SEC
                        logger.warning(f"[AI] rate-limited: {provider}/{model} — trying next model :: {_err_brief(r.text)}")
                        continue
                    elif r.status_code in (500, 502, 503, 504):
                        # «مدل شلوغ است» مشکل خودِ مدل است نه کلید: مدل بعدی را امتحان کن (قبلاً break می‌شد
                        # و مدل‌های جایگزین هیچ‌وقت امتحان نمی‌شدند)، و مدل شلوغ را چند ثانیه کنار بگذار
                        last_err = f"model {model} {r.status_code}"
                        _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_BUSY_SEC
                        logger.warning(f"[AI] {provider}/{model} busy {r.status_code} — next model")
                        continue
                    else:
                        last_err = f"status {r.status_code}"
                        logger.warning(f"[AI] {provider} fail: {r.status_code} {r.text[:120]}")
                        break
                except requests.exceptions.ConnectionError as e:
                    # خطای شبکه (نه کلید/مدل): امتحان باقی کلیدها همین سرویس فقط ۵۰ ثانیه بودجه را می‌سوزاند
                    # → سرویس بعدی (فالبک) را امتحان کن
                    last_err = f"{provider} network: {_err_cause(e, 80)}"
                    logger.warning(f"[AI] {provider} connection failed — switching provider :: {_err_cause(e)}")
                    _conn_fail = True
                    break
                except requests.exceptions.Timeout:
                    last_err = f"model {model} timeout"
                    _AI_MODEL_COOLDOWN[(_cdp, model)] = time.time() + _AI_BUSY_SEC
                    logger.warning(f"[AI] {provider}/{model} timeout — next model")
                    continue
                except Exception as e:
                    last_err = str(e)
                    logger.warning(f"[AI] {provider} request failed: {_err_cause(e)}")
                    break
            if _conn_fail:
                break
    if _skipped_cd and _tries == 0 and not _retry:
        # همهٔ مدل‌ها در کول‌داون بودند و هیچ درخواستی نرفت — یک بار کول‌داون‌ها را پاک کن و دوباره امتحان کن
        _AI_MODEL_COOLDOWN.clear()
        return ask_chand_ai(user_text, cache_key, max_msgs, max_tokens, route, web, weather, _retry=True, _intent=intent,
                             user_id=user_id, history_override=history_override,
                             group_ctx=group_ctx, reply_ctx=reply_ctx, images=images, _img_mode=_img_mode)
    logger.warning(
        f"[AI] all keys/models failed route={route} last_err={last_err} "
        f"total={time.time() - _t_start:.1f}s tries={_tries}"
    )
    if intent.get("weather"):
        # همهٔ AIها از دسترس خارج‌اند ولی هواشناسی (The Weather Channel) مستقل از آن‌هاست؛ جواب را مستقیم بده
        try:
            direct = _weather_direct_answer(intent.get("cities") or [], bool(intent.get("weather_future")))
        except Exception as e:
            logger.warning(f"[AI] direct weather fallback failed: {e}")
            direct = ""
        if direct:
            return direct
    return render_text_or_default("ai_fail_msg")


def ask_ai_raw(messages: list, max_tokens: int = 3000, temperature: float = 0.2, route: str = "chat"):
    """تماس خام و یک‌باره با هوش مصنوعی برای کارهای پس‌زمینه (مثل استخراج شهر از پرامپت شخصی): بدون تشخیص نیت، بدون حافظهٔ مکالمه،
    بدون ذخیرهٔ متن. چرخش کلید/مدل و کول‌داون‌ها مثل ask_chand_ai است. خروجی: متن پاسخ یا None."""
    reload_ai_keys()
    try:
        budget = float(os.environ.get("AI_RAW_TIMEOUT_SEC", "120") or 120)
    except ValueError:
        budget = 120.0
    deadline = time.time() + budget
    for provider in [p for p in _AI_ROUTE_PROVIDERS.get(route, ()) if _ai_keys_of(p)]:
        models = _ai_models_for(provider, route, False)
        conn_fail = False
        for _ in range(len(_ai_keys_of(provider))):
            if conn_fail or time.time() > deadline:
                break
            slot = _next_ai_slot(provider)
            if not slot:
                break
            _, key = slot
            if _AI_DEAD_KEYS.get(key, 0) > time.time():
                continue
            for model in models:
                if time.time() > deadline:
                    break
                _cd = max(_AI_MODEL_COOLDOWN.get((provider, model), 0),
                          _AI_MODEL_COOLDOWN.get((provider, model, key), 0))
                if _cd > time.time():
                    continue
                try:
                    r = _ai_http_post(provider, key, model, messages, max_tokens, temperature, 60)
                except requests.exceptions.ConnectionError:
                    conn_fail = True            # مشکل شبکه: سرویس بعدی
                    break
                except requests.exceptions.Timeout:
                    _AI_MODEL_COOLDOWN[(provider, model)] = time.time() + _AI_BUSY_SEC
                    continue
                except Exception as e:
                    logger.warning(f"[AI-RAW] {provider} request failed: {_err_cause(e)}")
                    break
                sc = r.status_code
                if sc == 200:
                    try:
                        content = (((r.json().get("choices") or [{}])[0].get("message") or {})
                                   .get("content") or "").strip()
                    except Exception:
                        content = ""
                    content = _ai_strip_think(content)
                    if content:
                        return content
                    continue
                if sc in (400, 401, 403) and _body_says_bad_key(r.text):
                    _AI_DEAD_KEYS[key] = time.time() + _AI_DEADKEY_SEC
                    break
                if sc in (400, 404):
                    _AI_MODEL_COOLDOWN[(provider, model)] = time.time() + _AI_MODELGONE_SEC
                    continue
                if sc == 429:
                    _AI_MODEL_COOLDOWN[(provider, model, key)] = time.time() + _AI_RATELIMIT_SEC
                    continue
                if sc in (500, 502, 503, 504):
                    _AI_MODEL_COOLDOWN[(provider, model)] = time.time() + _AI_BUSY_SEC
                    continue
                break
    logger.warning("[AI-RAW] all keys/models failed")
    return None


# آخرین نتیجهٔ تست — برای دکمهٔ «حذف مرده‌ها» (اگر تازه باشد دوباره تست نمی‌گیرد)
_LAST_AI_TEST: dict | None = None
_AI_TEST_FRESH_SEC = 600


def _probe_completion(provider: str, key: str, model: str):
    r = _ai_http_post(
        provider, key, model, [{"role": "user", "content": "hi"}],
        32 if provider == "gemini" else 5, 0.3, 25,
    )
    body = (r.text or "")[:300].replace("<", "").replace("\n", " ")
    return r.status_code, body


def _test_eleven_key(key: str, res: dict) -> dict:
    """تست کلید ElevenLabs بدون خرج‌کردن کاراکتر: GET /v1/user/subscription (مصرف/سقف ماهانه را هم نشان می‌دهد).
    dead فقط برای invalid_api_key؛ تمام‌شدن سهمیه (ماهانه ریست می‌شود) مرده نیست → limit."""
    try:
        r = _ai_session.get(API_SERVICES["elevenlabs"]["sub_url"], headers={"xi-api-key": key}, timeout=12)
    except Exception as e:
        res.update(detail=_err_cause(e, 140))
        return res
    st = r.status_code
    status, msg = _eleven_detail(r)
    if st == 200:
        try:
            d = r.json()
            used = int(d.get("character_count") or 0)
            limit = int(d.get("character_limit") or 0)
            tier = d.get("tier") or "?"
        except Exception:
            res.update(status="ok", detail="سالم")
            return res
        if limit:
            res["extra"] = f"باقی‌مانده {max(0, limit - used):,} کاراکتر"
            if used >= limit:
                res.update(status="limit", detail=f"سهمیه تمام شد ({used:,}/{limit:,}) — {tier}")
                return res
            res.update(status="ok", detail=f"سالم — {tier} | مصرف {used:,}/{limit:,}")
        else:
            res.update(status="ok", detail=f"سالم — {tier}")
        return res
    if st in (400, 401, 403) and status == "invalid_api_key":
        res.update(status="dead", detail=f"{st} نامعتبر")
        return res
    if st in (401, 403) and status == "missing_permissions":
        # کلید معتبر ولی محدودشده (بدون دسترسی user_read) — مصرف قابل‌نمایش نیست
        res.update(status="ok", detail="معتبر (کلید محدود؛ مصرف قابل‌نمایش نیست)")
        return res
    if st == 429:
        res.update(status="limit", detail="429 محدودیت نرخ")
        return res
    if st == 402 or status == "quota_exceeded":
        res.update(status="limit", detail=f"{st} سهمیه/پرداخت — {msg[:80]}")
        return res
    res.update(detail=f"{st} {status} {msg[:90]}".strip())
    return res


def _test_one_key(provider: str, key: str) -> dict:
    """تست یک کلید. status: ok | limit | dead | error
    dead فقط برای پاسخ‌های قطعی 401 (نامعتبر) یا 402 (اعتبار تمام) — خطای شبکه/429/5xx هرگز dead نیست."""
    res = {"provider": provider, "key": key, "status": "error", "detail": "", "extra": ""}
    if provider == "elevenlabs":
        return _test_eleven_key(key, res)
    models = _ai_models_for(provider, "chat", False)
    try:
        if provider == "groq":
            r = _ai_session.get(
                AI_PROVIDERS["groq"]["ping_url"],
                headers={"Authorization": f"Bearer {key}"}, timeout=12,
            )
            if r.status_code == 401:
                res.update(status="dead", detail="401 نامعتبر")
                return res
            if r.status_code == 429:
                res.update(status="limit", detail="429 محدودیت نرخ")
                return res
            if r.status_code == 404:
                res.update(detail="404 پروکسی/فیلتر")
                return res
            if r.status_code != 200:
                res.update(detail=f"models {r.status_code}")
                return res
        elif provider == "openrouter":
            r = _ai_session.get(
                AI_PROVIDERS["openrouter"]["key_url"],
                headers={"Authorization": f"Bearer {key}"}, timeout=12,
            )
            if r.status_code == 401:
                res.update(status="dead", detail=f"401 نامعتبر :: {_err_brief(r.text)}")
                return res
            if r.status_code == 429:
                res.update(status="limit", detail="429 محدودیت نرخ")
                return res
            if r.status_code == 200:
                _lim = ""
                try:
                    _d = (r.json() or {}).get("data") or {}
                    _free = _d.get("is_free_tier")
                    _lim = " | رایگان (۵۰ درخواست/روز)" if _free else " | شارژدار"
                except Exception:
                    pass
                res.update(status="ok", detail=f"معتبر{_lim}")
                return res
            # 404 و … (واسطه‌ای که /key ندارد): با یک درخواست آزمایشی ادامه می‌دهیم
        elif provider == "gemini":
            r = _ai_session.get(
                AI_PROVIDERS["gemini"]["ping_url"],
                headers={"x-goog-api-key": key}, timeout=12,
            )
            body = (r.text or "")[:400]
            brief = _err_brief(body)
            # «مرده» فقط وقتی خود گوگل صریحاً بگوید کلید نامعتبر/منقضی/لو‌رفته است.
            # 401/403 به‌تنهایی مرده نیست (مثلاً نوع توکن، منطقه، پروژهٔ معلق) — دلیلش نمایش داده می‌شود.
            if r.status_code in (400, 401, 403) and _body_says_bad_key(body):
                res.update(status="dead", detail=f"{r.status_code} {brief}")
                return res
            if r.status_code == 429:
                res.update(status="limit", detail="429 محدودیت نرخ")
                return res
            if r.status_code != 200:
                res.update(detail=f"{r.status_code} {brief}")
                return res
        saw_402 = False
        saw_429 = False
        saw_busy = False
        net_errs = 0
        last_body = ""
        for model in models:
            try:
                code, last_body = _probe_completion(provider, key, model)
            except Exception as e:
                last_body = _err_cause(e, 90)
                net_errs += 1
                continue
            if code == 200:
                res.update(status="ok", detail=f"سالم ({model})")
                return res
            if code == 401 and provider != "gemini":
                res.update(status="dead", detail="401 نامعتبر")
                return res
            if code in (400, 403) and _body_says_bad_key(last_body):
                res.update(status="dead", detail=f"{code} {_err_brief(last_body)}")
                return res
            if provider == "gemini" and code in (401, 403):
                res.update(detail=f"{code} {_err_brief(last_body)}")
                return res
            if code == 402:
                saw_402 = True
                continue
            if code == 429:
                saw_429 = True
                continue
            if code in (404, 400):
                continue
            if code in (500, 502, 503, 504):
                saw_busy = True
                continue
            res.update(detail=f"completion {code} :: {_err_brief(last_body)}")   # دلیل واقعی (مثلاً مدل/اعتبار/دسترسی) در پنل دیده شود
            return res
        if saw_429:
            res.update(status="limit", detail="429 محدودیت نرخ (همهٔ مدل‌ها)")
            return res
        if saw_busy:
            res.update(status="limit", detail="کلید معتبر است ولی مدل‌ها شلوغ‌اند (503 موقت)")
            return res
        if saw_402:
            res.update(status="dead", detail="402 اعتبار/شارژ تمام شده")
        elif net_errs and net_errs == len(models):
            # کلید ممکن است سالم باشد؛ مشکل اتصال به سرور مدل است نه خود مدل/کلید
            res.update(detail=f"کلید پذیرفته شد ولی اتصال به سرور مدل برقرار نشد — {last_body[:140]}")
        else:
            res.update(detail=f"auth اوکی، مدل نه — {last_body[:100]}")
        return res
    except Exception as e:
        res.update(detail=_err_cause(e, 140))
        return res


def _svc_en(p: str) -> str:
    m = re.search(r"\(([^)]+)\)", API_SERVICES[p]["label"])
    return m.group(1) if m else API_SERVICES[p]["short"]


def _svc_info_lines(p: str) -> list:
    """خطوط اطلاعاتی مخصوص هر سرویس (مدل‌ها و …) — داخل بخش خودش نمایش داده می‌شود."""
    if p == "groq":
        return [f"مدل: <code>{', '.join(GROQ_MODEL_FALLBACKS)}</code>",
                f"مدل با جستجوی وب: <code>{', '.join(GROQ_WEB_MODELS)}</code>"]
    if p == "gemini":
        return [f"مدل: <code>{', '.join(GEMINI_MODELS)}</code>"]
    if p == "openrouter":
        return [f"مدل: <code>{', '.join(OPENROUTER_MODELS)}</code>",
                f"مدل تحلیل عکس: <code>{', '.join(OPENROUTER_VISION_MODELS)}</code>"]
    if p == "elevenlabs":
        model, _voices, _fmt = _eleven_cfg()
        state = "روشن" if ELEVEN_ENABLED else "خاموش (ELEVENLABS_TTS=0)"
        fb = "edge-tts ✅" if _HAS_EDGE_TTS else "edge-tts ❌ نصب نیست"
        return [f"مدل: <code>{model}</code> | وضعیت: {state}", f"فالبک ویس: {fb}"]
    return []


def test_all_ai_keys():
    """تست سلامت همهٔ کلیدها (Groq، Gemini، ElevenLabs و هر سرویس آیندهٔ API_SERVICES) — برای پنل ادمین.
    هر سرویس بخش جدا و شمارهٔ جدا (#1/N) دارد. خروجی: (متن HTML, لیست نتایج)."""
    global _LAST_AI_TEST
    reload_ai_keys(force=True)  # همیشه تازه از .env بخوان

    providers = [p for p in API_SERVICES if p != "openrouter"]   # اوپن‌روتر حذف شد
    rep_by_provider = {p: _extract_ai_keys(p, with_report=True) for p in providers}
    counts = {p: len(rep_by_provider[p][0]) for p in providers}
    total = sum(counts.values())

    if not total:
        ex = "\n".join(
            f"<code>{API_SERVICES[p]['env']}={API_SERVICES[p].get('example', '…')}</code>" for p in providers
        )
        return (
            "❌ هیچ کلید معتبری پیدا نشد.\n\n"
            "با دکمهٔ «➕ افزودن» کلید اضافه کن، یا در .env بنویس (چند کلید با ویرگول):\n" + ex
        ), []

    # شبکه: به‌ازای هر سرویسی که کلید دارد
    net_ok, net_line = {}, {}
    for p in providers:
        if not counts[p]:
            continue
        try:
            ping = _ai_session.get(API_SERVICES[p]["ping_url"], timeout=10)
            net_ok[p] = True
            net_line[p] = f"شبکه: <code>{ping.status_code}</code>"
        except Exception as e:
            net_ok[p] = False
            net_line[p] = f"شبکه: ❌ وصل نشد — {_err_cause(e, 120)}"

    jobs = [(p, k) for p in providers for k in rep_by_provider[p][0]]

    def _run(job):
        p, k = job
        if not net_ok.get(p):
            return {"provider": p, "key": k, "status": "error", "detail": "شبکه در دسترس نیست", "extra": ""}
        return _test_one_key(p, k)

    # هم‌زمانی کم: روی شبکهٔ ناپایدار ۶ هندشیک TLS هم‌زمان خودش باعث قطع شدن اتصال‌ها می‌شد
    with ThreadPoolExecutor(max_workers=3) as ex:
        results = list(ex.map(_run, jobs))

    icons = {"ok": "✅", "limit": "⚠️", "dead": "💀", "error": "❌"}
    sep = "━━━━━━━━━━━━━━"

    # هدر: شمارش هر سرویس جدا
    lines = [
        "🔑 <b>تست کلیدهای API</b>",
        "  ".join(f"{API_SERVICES[p].get('icon', '🔑')} {API_SERVICES[p]['short']}: <b>{counts[p]}</b>" for p in providers)
        + f"  |  جمع: <b>{total}</b>",
        "",
    ]

    # یک بخش جدا برای هر سرویس؛ شماره‌گذاری هر سرویس از ۱
    for p in providers:
        svc = API_SERVICES[p]
        rs = [r for r in results if r["provider"] == p]
        lines.append(sep)
        lines.append(f"{svc.get('icon', '🔑')} <b>{svc['label']}</b> — {counts[p]} کلید")
        if not counts[p]:
            lines.append(f"بدون کلید — در .env: <code>{svc['env']}=…</code> یا دکمهٔ «➕ افزودن»")
            if svc.get("no_key_note"):
                lines.append(svc["no_key_note"])
            for m, why in rep_by_provider[p][1]:
                lines.append(f"⚠️ ردشد: <code>{m}</code> — {why}")
            lines.append("")
            continue
        lines.extend(_svc_info_lines(p))
        lines.append(net_line[p])
        for m, why in rep_by_provider[p][1]:
            lines.append(f"⚠️ ردشد: <code>{m}</code> — {why}")
        for i, r in enumerate(rs, 1):
            extra = f" — {r['extra']}" if r.get("extra") else ""
            lines.append(
                f"{icons[r['status']]} #{i}/{len(rs)} <code>{_mask_key(r['key'])}</code> — {r['detail']}{extra}"
            )
        ns = {st_: sum(1 for r in rs if r["status"] == st_) for st_ in icons}
        lines.append(f"↳ ✅{ns['ok']}  💀{ns['dead']}  ⚠️{ns['limit']}  ❌{ns['error']}")
        lines.append("")

    lines.append(sep)
    n = {st_: sum(1 for r in results if r["status"] == st_) for st_ in icons}
    lines.append(
        f"جمع کل: ✅{n['ok']}  💀{n['dead']}  ⚠️{n['limit']}  ❌{n['error']}  از {len(results)} کلید"
    )
    if n["dead"]:
        lines.append("💀 = مرده (نامعتبر یا شارژ تمام) → با «🗑 حذف مرده‌ها» پاک می‌شود.")
    if n["error"] and not (n["ok"] or n["limit"]):
        hosts = " / ".join(
            re.sub(r"^https?://([^/]+).*$", r"\1", API_SERVICES[p]["ping_url"]) for p in providers
        )
        lines.append("⚠️ همهٔ خطاها از نوع شبکه‌اند، نه کلید: سرور ربات به "
                     f"{hosts} دسترسی پایدار ندارد. راه‌حل: در .env مقدار AI_PROXY را بگذار (یا سرور/VPN با دسترسی آزاد).")
    lines.append(
        "💡 کلید جدید: "
        + " | ".join(f'<a href="{API_SERVICES[p]["console"]}">{_svc_en(p)}</a>' for p in providers)
    )
    _LAST_AI_TEST = {"ts": time.time(), "results": results}
    return "\n".join(lines), results


def delete_dead_ai_keys() -> str:
    """کلیدهای مردهٔ آخرین تست را حذف می‌کند (اگر تست تازه نبود، اول تست می‌گیرد)."""
    global _LAST_AI_TEST
    last = _LAST_AI_TEST
    if not last or time.time() - last["ts"] > _AI_TEST_FRESH_SEC:
        test_all_ai_keys()
        last = _LAST_AI_TEST
    results = (last or {}).get("results") or []
    if not results:
        return "❌ کلیدی برای بررسی نبود."
    dead = [r for r in results if r["status"] == "dead"]
    if not dead:
        return (
            "✅ کلید مرده‌ای پیدا نشد؛ چیزی حذف نشد.\n"
            f"کلیدهای فعال در چرخه: <b>{_ai_total_keys()}</b>"
        )
    remove_ai_keys([r["key"] for r in dead])
    _LAST_AI_TEST = None
    logger.info(f"[AI] dead keys removed: {len(dead)}")
    out = [f"🗑 <b>{len(dead)}</b> کلید مرده حذف شد:"]
    for r in dead:
        out.append(f"• [{API_SERVICES[r['provider']]['short']}] <code>{_mask_key(r['key'])}</code> — {r['detail']}")
    out.append("")
    out.append(f"باقی‌مانده در چرخه: {_ai_counts_inline()}")
    out.append("بدون ری‌استارت اعمال شد.")
    return "\n".join(out)


def _split_telegram_html(text: str, limit: int = 3900) -> list:
    """تقسیم متن طولانی برای سقف پیام تلگرام (~4096)."""
    if len(text) <= limit:
        return [text]
    chunks = []
    cur = []
    cur_len = 0
    for line in text.split("\n"):
        add = len(line) + 1
        if cur and cur_len + add > limit:
            chunks.append("\n".join(cur))
            cur = [line]
            cur_len = add
        else:
            cur.append(line)
            cur_len += add
    if cur:
        chunks.append("\n".join(cur))
    return chunks or [text]


