BOT_USERNAME = None


class _StyledInlineButton(types.InlineKeyboardButton):
    """برای نسخه‌های telebot که پارامتر style ندارند: فیلد style (primary/success/danger) را خودمان
    در JSON دکمه می‌گذاریم تا رنگ دکمه گم نشود (قبلاً در این حالت بی‌صدا حذف می‌شد)."""

    _style = None

    def to_dict(self):
        d = super().to_dict()
        if self._style:
            d["style"] = self._style
        return d


def btn(text, callback_data=None, url=None, style=None):
    kw = {}
    if callback_data is not None:
        kw["callback_data"] = callback_data
    if url is not None:
        kw["url"] = url
    if style:
        kw["style"] = style
    try:
        return types.InlineKeyboardButton(text, **kw)
    except TypeError:
        kw.pop("style", None)
        b = _StyledInlineButton(text, **kw)
        if style:
            b._style = style
        return b


# ============================================================
# دکمهٔ شیشه‌ای برای همهٔ لینک‌های جواب ربات
#   لینک از متن برداشته می‌شود و به‌صورت دکمهٔ URL با «اسم پلتفرم» (بدون ایموجی) زیر پیام می‌آید.
#   تلگرام برای دکمه فقط سه رنگ می‌دهد: primary (آبی) / success (سبز) / danger (قرمز)؛ رنگ دلخواه (hex) ممکن نیست.
#   پس نزدیک‌ترین رنگ به رنگ آیکون هر پلتفرم انتخاب می‌شود. None = رنگ پیش‌فرض (خاکستریِ شیشه‌ای).
# ============================================================
_LB_PLATFORMS = (
    # (regex روی hostname، اسم دکمه، style)
    (r"(?:^|\.)spotify\.com$|^spoti\.fi$",                 "Spotify",       "success"),   # سبز
    (r"^(?:music|itunes|geo\.music)\.apple\.com$",         "Apple Music",   "danger"),    # قرمز/صورتی
    (r"(?:^|\.)soundcloud\.com$|^snd\.sc$",                "SoundCloud",    "danger"),    # نارنجی ← نزدیک‌ترین قرمز
    (r"(?:^|\.)deezer\.com$|^deezer\.page\.link$",         "Deezer",        "primary"),   # بنفش ← نزدیک‌ترین آبی
    (r"^music\.youtube\.com$",                             "YouTube Music", "danger"),
    (r"(?:^|\.)youtube\.com$|^youtu\.be$",                 "YouTube",       "danger"),
    (r"(?:^|\.)instagram\.com$",                           "Instagram",     "danger"),    # صورتی/بنفش
    (r"(?:^|\.)pinterest\.[a-z.]+$|^pin\.it$",             "Pinterest",     "danger"),
    (r"^(?:t\.me|telegram\.me|telegram\.org)$",            "Telegram",      "primary"),
    (r"(?:^|\.)(?:facebook|fb)\.com$",                     "Facebook",      "primary"),
    (r"(?:^|\.)linkedin\.com$",                            "LinkedIn",      "primary"),
    (r"(?:^|\.)(?:twitter|x)\.com$",                       "X",             None),        # مشکی
    (r"(?:^|\.)tiktok\.com$",                              "TikTok",        None),        # مشکی
    (r"(?:^|\.)(?:whatsapp\.com|wa\.me)$",                 "WhatsApp",      "success"),
    (r"(?:^|\.)aparat\.com$",                              "Aparat",        "danger"),
    (r"(?:^|\.)wikipedia\.org$",                           "Wikipedia",     None),
    (r"(?:^|\.)genius\.com$",                              "Genius",        None),
    (r"(?:^|\.)github\.com$",                              "GitHub",        None),
    (r"(?:^|\.)google\.[a-z.]+$",                          "Google",        "primary"),
)
_LB_PLATFORMS = tuple((re.compile(rx, re.I), name, st) for rx, name, st in _LB_PLATFORMS)
_LB_URL_RE = re.compile(r"https?://[^\s<>\"']+", re.I)
_LB_A_RE = re.compile(r"<a\s+[^>]*?href=[\"'](https?://[^\"']+)[\"'][^>]*>(.*?)</a>", re.I | re.S)
_LB_SEARCH_RE = re.compile(r"/search|[?&](?:q|term|query|search)=", re.I)
_LB_SLD = {"co", "com", "org", "net", "gov", "ac", "edu", "ir"}
_LB_MAX = 8


def _lb_platform(url: str):
    """url → (اسم دکمه، style). پلتفرم ناشناس: اسم دامنه با حرف اول بزرگ، بدون رنگ."""
    try:
        host = (urlparse(url).hostname or "").lower()
    except Exception:
        host = ""
    for rx, name, st in _LB_PLATFORMS:
        if rx.search(host):
            return name, st
    parts = [x for x in host.split(".") if x and x != "www"]
    if len(parts) >= 3 and parts[-2] in _LB_SLD:
        base = parts[-3]
    elif len(parts) >= 2:
        base = parts[-2]
    else:
        base = parts[0] if parts else "Link"
    return base[:1].upper() + base[1:], None


def _lb_strip_tail(raw: str) -> str:
    """علامت‌های انتهای جمله که چسبیده به URL‌اند (نقطه، ویرگول، «، پرانتز بی‌جفت، ...) را کم می‌کند."""
    while raw:
        c = raw[-1]
        if c in ".,،؛:!؟?»…]\"'":
            raw = raw[:-1]
        elif c == ";" and not re.search(r"&#?\w+;$", raw):
            raw = raw[:-1]
        elif c == ")" and "(" not in raw:
            raw = raw[:-1]
        else:
            break
    return raw


def _lb_clean_url(raw: str) -> str:
    u = html.unescape(raw).strip()
    return urllib.parse.quote(u, safe="%/:?#[]@!$&'()*+,;=~-._")


def link_buttons_for(text: str):
    """متن جواب (HTML تلگرام) → (متن بدون لینک، InlineKeyboardMarkup | None).
    اگر لینکی نبود یا متن بلوک کد داشت، متن دست‌نخورده برمی‌گردد."""
    if not text or "http" not in text or "<pre" in text or "<code" in text:
        return text, None
    found = []                                   # [(url)] به ترتیب ظهور

    def _add(u):
        if u and u not in found:
            found.append(u)

    # ۱) <a href="…">متن</a> ← فقط متن لینک می‌ماند (اگر خودِ متن URL بود حذف می‌شود)
    def _a_sub(m):
        _add(_lb_clean_url(_lb_strip_tail(m.group(1))))
        inner = m.group(2).strip()
        return "" if _LB_URL_RE.fullmatch(html.unescape(inner)) else inner
    t = _LB_A_RE.sub(_a_sub, text)

    # ۲) URL خام ← از خط برداشته می‌شود؛ خطی که فقط «برچسب + لینک» بود («Spotify: …») کلاً حذف می‌شود
    out_lines = []
    for line in t.split("\n"):
        if "http" not in line:
            out_lines.append(line)
            continue
        new = line
        for m in list(_LB_URL_RE.finditer(line)):
            raw = _lb_strip_tail(m.group(0))
            _add(_lb_clean_url(raw))
            new = new.replace(raw, "", 1)
        words = re.sub(r"[\W_]+", " ", re.sub(r"<[^>]+>", "", new)).split()
        if len(words) <= 3:
            continue
        new = re.sub(r"[(\[«]\s*[)\]»]", "", new)              # «(لینک)» که لینکش رفت ← پرانتز خالی نماند
        out_lines.append(re.sub(r"[ \t]{2,}", " ", new).rstrip())
    if not found:
        return text, None
    clean = re.sub(r"\n{3,}", "\n\n", "\n".join(out_lines)).strip()
    if not clean:
        clean = "👇"

    # ۳) ساخت دکمه‌ها
    seen_names = {}
    buttons = []
    for u in found[:_LB_MAX]:
        name, st = _lb_platform(u)
        if _LB_SEARCH_RE.search(u):
            name += " (جستجو)"
        seen_names[name] = seen_names.get(name, 0) + 1
        label = name if seen_names[name] == 1 else f"{name} {seen_names[name]}"
        try:
            buttons.append(btn(label, url=u, style=st))
        except Exception:
            buttons.append(btn(label, url=u))
    kb = InlineKeyboardMarkup()
    for i in range(0, len(buttons), 2):
        kb.row(*buttons[i:i + 2])
    return clean, kb


def _get_bot_username():
    global BOT_USERNAME, _BOT_ID
    if not BOT_USERNAME:
        try:
            me = bot.get_me()
            BOT_USERNAME = me.username
            _BOT_ID = me.id
        except Exception:
            pass
    return BOT_USERNAME or ""


