import secrets as _api_secrets

def _gen_api_key() -> str:
    return "ch_" + _api_secrets.token_urlsafe(24)


def create_api_client(name: str, days: int = 30, note: str | None = None) -> dict | None:
    """ایجاد کلاینت جدید + کلید یکتا + تاریخ انقضا."""
    name = (name or "").strip()[:100]
    if not name:
        return None
    days = max(1, min(int(days), 3650))
    key = _gen_api_key()
    expire = _now_tehran() + timedelta(days=days)
    # بدون tz برای ستون TIMESTAMP
    expire_naive = expire.replace(tzinfo=None)
    try:
        with db_cursor() as c:
            c.execute(
                """INSERT INTO api_clients (client_name, api_key, expire_at, is_active, note)
                   VALUES (%s, %s, %s, 1, %s) RETURNING id""",
                (name, key, expire_naive, note),
            )
            cid = c.fetchone()["id"]
        return {
            "id": cid,
            "client_name": name,
            "api_key": key,
            "expire_at": expire_naive,
            "is_active": 1,
            "days": days,
        }
    except Exception as e:
        logger.error(f"[API] create failed: {e}")
        return None


def get_api_client_by_name(name: str) -> dict | None:
    try:
        with db_cursor() as c:
            c.execute(
                "SELECT * FROM api_clients WHERE client_name=%s LIMIT 1",
                (name.strip(),),
            )
            return c.fetchone()
    except Exception as e:
        logger.error(f"[API] get by name: {e}")
        return None


def get_api_client_by_key(api_key: str) -> dict | None:
    try:
        with db_cursor() as c:
            c.execute(
                "SELECT * FROM api_clients WHERE api_key=%s LIMIT 1",
                (api_key.strip(),),
            )
            return c.fetchone()
    except Exception as e:
        logger.error(f"[API] get by key: {e}")
        return None


def list_api_clients() -> list:
    try:
        with db_cursor() as c:
            c.execute(
                "SELECT * FROM api_clients ORDER BY id ASC"
            )
            return list(c.fetchall() or [])
    except Exception as e:
        logger.error(f"[API] list: {e}")
        return []


def extend_api_client(name: str, days: int = 30) -> dict | None:
    """تمدید از max(الان, expire فعلی) + days روز."""
    days = max(1, min(int(days), 3650))
    try:
        with db_cursor() as c:
            c.execute(
                """UPDATE api_clients
                   SET expire_at = GREATEST(expire_at, LOCALTIMESTAMP) + make_interval(days => %s),
                       is_active = 1
                   WHERE client_name = %s""",
                (days, name.strip()),
            )
            if c.rowcount == 0:
                return None
            c.execute(
                "SELECT * FROM api_clients WHERE client_name=%s LIMIT 1",
                (name.strip(),),
            )
            return c.fetchone()
    except Exception as e:
        logger.error(f"[API] extend failed: {e}")
        return None


def set_api_client_active(name: str, active: bool) -> bool:
    try:
        with db_cursor() as c:
            c.execute(
                "UPDATE api_clients SET is_active=%s WHERE client_name=%s",
                (1 if active else 0, name.strip()),
            )
            return c.rowcount > 0
    except Exception as e:
        logger.error(f"[API] set active: {e}")
        return False


def set_api_allowed_symbols(name: str, symbols: str | None) -> bool:
    """symbols=None یا 'all' → همه نمادها؛ وگرنه رشتهٔ کاما جدا مثل usd,eur"""
    try:
        with db_cursor() as c:
            c.execute(
                "UPDATE api_clients SET allowed_symbols=%s WHERE client_name=%s",
                (symbols, name.strip()),
            )
            return c.rowcount > 0
    except Exception as e:
        logger.error(f"[API] set allowed: {e}")
        return False

def delete_api_client(name: str) -> bool:
    try:
        with db_cursor() as c:
            c.execute(
                "DELETE FROM api_clients WHERE client_name=%s",
                (name.strip(),),
            )
            return c.rowcount > 0
    except Exception as e:
        logger.error(f"[API] delete: {e}")
        return False


def check_api_client_access(api_key: str) -> tuple[bool, str, list | None]:
    """
    (True, name, allowed_list|None) اگر مجاز.
    allowed_list=None یعنی همه نمادها؛ لیست یعنی فقط همان‌ها.
    """
    if not api_key:
        return False, "missing_key", None
    row = get_api_client_by_key(api_key)
    if not row:
        return False, "invalid_key", None
    if not row.get("is_active"):
        return False, "disabled", None
    exp = row.get("expire_at")
    if exp is None:
        return False, "no_expire", None
    now = _now_tehran().replace(tzinfo=None)
    if isinstance(exp, str):
        try:
            exp = datetime.strptime(exp[:19], "%Y-%m-%d %H:%M:%S")
        except Exception:
            return False, "bad_expire", None
    if now > exp:
        return False, "expired", None

    allowed = row.get("allowed_symbols")
    allowed_list = None
    if allowed and str(allowed).strip():
        allowed_list = [s.strip().lower() for s in str(allowed).split(",") if s.strip()]

    return True, row.get("client_name") or "", allowed_list


def build_api_rates_payload(abs_filter: list[str] | None = None) -> dict:
    """پاسخ استاندارد JSON برای وب‌سرویس."""
    fetch_prices()
    items_out = {}
    # ترتیب پیشنهادی + بقیه
    preferred = [
        "usd", "eur", "gbp", "aed", "try", "cny",
        "usdt", "btc", "eth",
        "emami", "azadi", "half", "quarter", "gerami", "gram", "mithqal",
        "brent", "wti", "ng",
    ]
    seen = set()
    order = []
    if abs_filter:
        order = []
        for a in abs_filter:
            a_norm = (a or "").strip().lower()
            if not a_norm:
                continue
            order.append(a_norm)
    else:
        order = preferred[:]
        # بقیه از کش قیمت (کلاینت بدون فیلتر = دسترسی به همه)
        try:
            for ab in list(_price_by_ab.keys()):
                if ab not in seen and ab not in order:
                    order.append(ab)
        except Exception:
            pass

    updated = "—"
    for ab in order:
        if ab in seen:
            continue
        seen.add(ab)
        it = get_item_by_ab(ab)
        if not it:
            continue
        p = item_current_price(it)
        d, pct = item_fluctuation(it)
        if updated == "—":
            try:
                updated = item_last_update_str(it)
            except Exception:
                pass
        items_out[ab] = {
            "ab": ab,
            "fa": item_display_fa(it),
            "emoji": it.get("av") or "",
            "price": p,
            "change": d,
            "change_pct": round(pct, 4) if pct is not None else None,
            "unit": item_price_unit(it),
        }

    return {
        "status": "success",
        "updated_at": updated,
        "count": len(items_out),
        "data": items_out,
    }


def _fmt_api_client_row(r: dict) -> str:
    now = _now_tehran().replace(tzinfo=None)
    exp = r.get("expire_at")
    if isinstance(exp, str):
        try:
            exp = datetime.strptime(exp[:19], "%Y-%m-%d %H:%M:%S")
        except Exception:
            exp = None
    active = bool(r.get("is_active"))
    expired = bool(exp and now > exp)
    if not active:
        st = "🔴 غیرفعال"
    elif expired:
        st = "⏰ منقضی"
    else:
        st = "🟢 فعال"
    exp_s = exp.strftime("%Y-%m-%d %H:%M") if exp else "—"
    key = r.get("api_key") or ""
    key_short = (key[:10] + "…") if len(key) > 12 else key
    allowed = r.get("allowed_symbols")
    allow_s = "همه" if not allowed else str(allowed)
    return (
        f"• <b>{r.get('client_name')}</b> {st}\n"
        f"  کلید: <code>{key_short}</code>\n"
        f"  انقضا: <code>{exp_s}</code>\n"
        f"  نمادها: <code>{allow_s}</code>"
    )


