def _api_symbols_status_text(name: str) -> str:
    return (
        f"📊 نمادهای مجاز برای <b>{name}</b>\n\n"
        f"برای <b>افزودن</b>: همین‌جا عدد(های) آیتم رو بفرست — تکی (مثل <code>3</code>) یا با کاما/فاصله "
        f"(مثل <code>1,4,9</code>). همون عددیه که تو منوی اصلی ربات کنار اسم هر آیتم می‌بینی.\n"
        f"برای <b>حذف</b>: دکمهٔ 🗑 کنار همون آیتم رو بزن."
    )


def _api_symbols_keyboard(name: str) -> InlineKeyboardMarkup:
    """کیبورد نمادهای مجاز یک کلاینت — فقط آیتم‌های *الان مجاز* را با یک دکمهٔ
    حذف کنار هرکدام نشان می‌دهد؛ افزودن با ارسال شمارهٔ آیتم (همان عددی که
    کنار اسم هر آیتم در منوی اصلی خود ادمین دیده می‌شود) انجام می‌شود، نه با
    مرور یک کاتالوگ تیک‌دار طولانی."""
    row = get_api_client_by_name(name)
    allowed_raw = (row or {}).get("allowed_symbols")
    if not allowed_raw or not str(allowed_raw).strip():
        selected = []
        all_mode = True
    else:
        selected = [s.strip().lower() for s in str(allowed_raw).split(",") if s.strip()]
        all_mode = False

    catalog = _api_catalog_build()
    by_ab = {c["ab"]: c for c in catalog}

    kb = InlineKeyboardMarkup(row_width=1)
    kb.row(btn(
        ("✅ " if all_mode else "◻️ ") + "همهٔ نمادها (بدون محدودیت)",
        callback_data=f"adm:api:symall:{name}",
        style="success" if all_mode else None,
    ))

    if not all_mode:
        for ab in sorted(selected):
            c = by_ab.get(ab)
            label = f"{c['num']}. {c['emoji']} {c['label']}".strip() if c else ab
            label = _wrap_long_button_name(label, hard_cap=56, wrap_from=56)
            kb.row(btn(label, callback_data="noop"))
            kb.row(btn("🗑 حذف", callback_data=f"adm:api:symdel:{name}:{ab}", style="danger"))

    kb.row(btn("📋 فهرست کامل با شماره", callback_data=f"adm:api:symlist:{name}:all", style="primary"))
    kb.row(btn("✔️ تایید و بازگشت", callback_data="adm:api_menu", style="success"))
    return kb


def _api_symbols_reference_keyboard(name: str, cat_key: str) -> InlineKeyboardMarkup:
    kb = InlineKeyboardMarkup(row_width=3)
    tabs = [("all", "همه")] + [(ck, ct.split(" ", 1)[-1]) for ck, ct in API_CAT_DEFS]
    tab_btns = [
        btn(("• " if cat_key == ck else "") + label, callback_data=f"adm:api:symlist:{name}:{ck}")
        for ck, label in tabs
    ]
    for i in range(0, len(tab_btns), 3):
        kb.row(*tab_btns[i:i + 3])
    kb.row(btn("◄ بازگشت", callback_data=f"adm:api:symmenu:{name}", style="danger"))
    return kb


def _api_symbols_send_reference_list(chat_id: int, name: str, cat_key: str):
    """فهرست مرجعِ فقط-نمایشیِ شمارهٔ همهٔ آیتم‌ها (بدون تیک‌زدن) — تیک ✅/◻️
    فقط برای این است که مشخص شود این کلاینت الان کدام‌ها را دارد. افزودن از
    همین صفحه ممکن نیست، عمداً: عدد را بخوان و توی صفحهٔ نمادهای کلاینت بفرست."""
    row = get_api_client_by_name(name)
    allowed_raw = (row or {}).get("allowed_symbols")
    if not allowed_raw or not str(allowed_raw).strip():
        selected = set()
        all_mode = True
    else:
        selected = {s.strip().lower() for s in str(allowed_raw).split(",") if s.strip()}
        all_mode = False

    catalog = _api_catalog_build()
    items = _api_catalog_filtered(catalog, cat_key)
    cat_label = "همهٔ دسته‌ها" if cat_key == "all" else API_CAT_TITLE_BY_KEY.get(cat_key, cat_key)

    lines = [f"📋 آیتم‌های <b>{cat_label}</b> — برای افزودن، عدد رو تو صفحهٔ نمادهای «{name}» بفرست:"]
    last_cat = None
    for c in items:
        if cat_key == "all" and c["cat_key"] != last_cat:
            last_cat = c["cat_key"]
            lines.append(f"\n<b>{c['cat_title']}</b>")
        mark = "✅" if (not all_mode and c["ab"] in selected) else "◻️"
        lines.append(f"{mark} <b>{c['num']}</b>. {c['emoji']} {c['label']}")

    kb = _api_symbols_reference_keyboard(name, cat_key)
    _send_html_chunks(chat_id, lines, final_markup=kb)


def _handle_admin_api_sym_numbers(msg: types.Message):
    """گیرندهٔ عدد(های) تایپ‌شده برای *افزودن* نماد — نه تیک‌زدن/برداشتن؛ حذف
    فقط با دکمهٔ 🗑 انجام می‌شود تا فرستادن دوبارهٔ یک عدد به‌اشتباه چیزی را
    حذف نکند. این حالت بعد از هر افزودن باز نگه داشته می‌شود تا بشود پشت‌سرهم
    چند بار عدد فرستاد بدون نیاز به باز کردن دوبارهٔ منو."""
    state = get_admin_state()
    data = state.get("data") or {}
    name = data.get("name")
    raw = (msg.text or "").strip()
    try:
        bot.delete_message(msg.chat.id, msg.message_id)
    except Exception:
        pass

    nums = re.findall(r"\d+", raw)
    if not nums or not name:
        bot.send_message(ADMIN_ID, "❌ فرمت نامعتبره. عدد(ها) رو با فاصله یا کاما بفرست، مثل: 1 3 7")
        return

    catalog = _api_catalog_build()
    row = get_api_client_by_name(name)
    allowed_raw = (row or {}).get("allowed_symbols")
    selected = {s.strip().lower() for s in str(allowed_raw).split(",") if s.strip()} if allowed_raw else set()

    added = []
    already = []
    invalid = []
    for n_s in nums:
        n = int(n_s)
        item = _api_catalog_by_num(catalog, n)
        if not item:
            invalid.append(n_s)
            continue
        ab = item["ab"]
        if ab in selected:
            already.append(f"{n}.{item['label']}")
        else:
            selected.add(ab)
            added.append(f"{n}.{item['label']}")

    symbols_val = ",".join(sorted(selected)) if selected else ""
    set_api_allowed_symbols(name, symbols_val if symbols_val else None)
    # حالت را عمداً باز نگه می‌داریم — عدد بعدی هم بدون کار اضافه اضافه می‌شود
    set_admin_state("api_sym_numbers", {"name": name})

    bot.send_message(ADMIN_ID, _api_symbols_status_text(name), reply_markup=_api_symbols_keyboard(name), parse_mode="HTML")

    note_parts = []
    if added:
        note_parts.append(f"✅ اضافه شد: {', '.join(added)}")
    if already:
        note_parts.append(f"ℹ️ از قبل بود: {', '.join(already)}")
    if invalid:
        note_parts.append(f"⚠️ عدد نامعتبر: {', '.join(invalid)}")
    if note_parts:
        bot.send_message(ADMIN_ID, "\n".join(note_parts))


def _handle_admin_api_new_name(msg: types.Message):
    """گام اول ساخت کلاینت جدید: دریافت اسم به‌صورت متن، بقیهٔ فلو با دکمه است."""
    state = get_admin_state()
    data = state.get("data") or {}
    name = (msg.text or "").strip()
    try:
        bot.delete_message(msg.chat.id, msg.message_id)
    except Exception:
        pass
    if not name or len(name) > 100:
        bot.send_message(ADMIN_ID, "❌ اسم نامعتبره. یه اسم کوتاه بفرست:")
        return
    if get_api_client_by_name(name):
        bot.send_message(ADMIN_ID, f"❌ کلاینت «{name}» از قبل وجود داره. یه اسم دیگه بفرست:")
        return
    mid = data.get("mid")
    text = f"➕ کلاینت <b>{name}</b>\n\nچند روز اعتبار داشته باشه؟"
    kb = _api_days_keyboard(name, "new")
    try:
        if mid:
            bot.edit_message_text(text, ADMIN_ID, mid, reply_markup=kb, parse_mode="HTML")
        else:
            bot.send_message(ADMIN_ID, text, reply_markup=kb, parse_mode="HTML")
    except Exception:
        bot.send_message(ADMIN_ID, text, reply_markup=kb, parse_mode="HTML")
    clear_admin_state()


# ============================================================
# پیش‌نمایش نمودار داخل پیام (LinkPreviewOptions)
# ============================================================
# آدرس عمومی HTTPS همان سروری که وب‌سرویس قیمت (start_price_api_server) رویش
# اجرا می‌شود — یعنی دامنه‌ای که با ریورس‌پراکسی (nginx و مشابه) به
# API_HOST:API_PORT وصل است. تلگرام برای پیش‌نمایش لینک (show_above_text +
# prefer_large_media) باید بتواند تصویر نمودار را از یک URL عمومی HTTPS بخواند؛
# این آدرس همان دامنه است، مثلاً:  CHART_PREVIEW_BASE_URL=https://your-domain.com
# اگر خالی بماند، دکمهٔ نمودار در نتایج اینلاین و پیام زمان‌بندی‌شدهٔ گروه با
# پیام خطای کوتاه پاسخ می‌دهد (بدون کرش) — نه پیام موجود خراب می‌شود و نه ربات.
#
# نکته: این قابلیت به pyTelegramBotAPI نسخهٔ ۴.۱۴ به بالا نیاز دارد (کلاس
# types.LinkPreviewOptions و پارامتر link_preview_options در edit_message_text).
# روی Render خودِ پلتفرم آدرس عمومی HTTPS سرویس را در RENDER_EXTERNAL_URL می‌گذارد و پورت API قیمت (همان /chart/...) از
# همان‌جا در دسترس است؛ پس دیگر به تونل رایگان و ناپایدار کلودفلر نیازی نیست (تونل کند بود و با هر ری‌استارت آدرسش عوض می‌شد).
# برای اجبار تونل: CHART_PREVIEW_BASE_URL را خودت بگذار یا RENDER_EXTERNAL_URL را خالی کن.
CHART_PREVIEW_BASE_URL = (os.environ.get("CHART_PREVIEW_BASE_URL") or os.environ.get("RENDER_EXTERNAL_URL") or "").strip().rstrip("/")
if CHART_PREVIEW_BASE_URL and not CHART_PREVIEW_BASE_URL.lower().startswith("https://"):
    logger.warning(
        "[CHART-PREVIEW] CHART_PREVIEW_BASE_URL='%s' با https:// شروع نمی‌شود — "
        "تلگرام پیش‌نمایش لینک را فقط از آدرس HTTPS می‌پذیرد.",
        CHART_PREVIEW_BASE_URL,
    )
elif not CHART_PREVIEW_BASE_URL:
    logger.info(
        "[CHART-PREVIEW] CHART_PREVIEW_BASE_URL تنظیم نشده — ربات به‌صورت خودکار "
        "تونل رایگان کلودفلر را اجرا و این مقدار را در حافظه پر می‌کند "
        "(نگاه کن به start_cloudflare_tunnel). تا وقتی خط "
        "'[TUNNEL] ✅ آدرس اختصاصی کلودفلر فعال شد' در لاگ ظاهر نشده، دکمهٔ "
        "نمودار در نتایج اینلاین و پیام زمان‌بندی‌شدهٔ گروه پیام خطای کوتاه می‌دهد."
    )

_CHART_PREVIEW_AB_RE = re.compile(r"[A-Za-z0-9_.\-]+")


def _chart_preview_url(ab: str, theme: str = "dark") -> str | None:
    """آدرس عمومی PNG نمودار برای LinkPreviewOptions؛ اگر دامنه ست نشده یا ab نامعتبر
    باشد None برمی‌گرداند (فراخوان باید این حالت را جدا مدیریت کند)."""
    if not CHART_PREVIEW_BASE_URL:
        return None
    ab_clean = (ab or "").strip().lower()
    if not ab_clean or not _CHART_PREVIEW_AB_RE.fullmatch(ab_clean):
        return None
    theme = "light" if (theme or "").lower() == "light" else "dark"
    # timestamp فقط برای شکستن کش پیش‌نمایش لینک تلگرام روی همین URL
    return f"{CHART_PREVIEW_BASE_URL}/chart/{ab_clean}.png?theme={theme}&t={int(time.time())}"


_CF_TUNNEL_URL_RE = re.compile(r"https://[a-zA-Z0-9-]+\.trycloudflare\.com")
# رفرنس پروسه‌ی جدای cloudflared — این یک پروسه‌ی سیستم‌عاملی جداست (نه ترد
# پایتون)، پس daemon=True روی تردها کمکی به بسته‌شدنش نمی‌کند و باید صریحاً
# موقع خاموشی ربات kill شود، وگرنه یتیم می‌ماند و بعضی هاست‌ها (که موقع Stop
# منتظر صفر شدن کل پروسه‌های زیرمجموعه می‌مانند) در وضعیت Stopping گیر می‌کنند.
_CF_TUNNEL_PROC = None


def _cloudflared_bin_path() -> Path:
    """مسیر فایل cloudflared: اگر قبلاً جایی دانلود شده همان؛ وگرنه اولین پوشهٔ قابل‌نوشتن
    (کنار bot.py ، LOCAL_SERVER_DIR ، /tmp). با CLOUDFLARED_BIN هم می‌شود مسیر را دستی داد."""
    import tempfile as _tf
    forced = (os.environ.get("CLOUDFLARED_BIN") or "").strip()
    if forced:
        return Path(forced)
    name = "cloudflared"
    dirs = [Path(__file__).resolve().parent,
            Path(os.environ.get("LOCAL_SERVER_DIR") or "/tmp/tgapi"),
            Path(_tf.gettempdir())]
    for d in dirs:
        if (d / name).is_file():
            return d / name
    for d in dirs:
        try:
            d.mkdir(parents=True, exist_ok=True)
            if os.access(str(d), os.W_OK):
                return d / name
        except Exception:
            continue
    return dirs[-1] / name


def start_cloudflare_tunnel(port: int):
    """دانلود خودکار و اجرای تونل رایگان کلودفلر در پس‌زمینه — برای هاست‌هایی مثل
    Raven/Pterodactyl که تب Console یک Bash واقعی نیست و امکان اجرای دستی
    cloudflared یا ست‌کردن دامنه/DuckDNS راحت نیست.
    اگر CHART_PREVIEW_BASE_URL از قبل در .env مقداردهی شده باشد، این تابع اصلاً
    فراخوانی/اجرا نمی‌شود (دامنهٔ دستی همیشه اولویت دارد) — نگاه کن به انتهای
    start_price_api_server().
    آدرس https://...trycloudflare.com ساخته‌شده مستقیم در CHART_PREVIEW_BASE_URL
    نوشته می‌شود؛ چون هندلرهای نمودار (ichart:/gschart:) این متغیر را در لحظهٔ
    کلیک می‌خوانند، نیازی به ریستارت یا اطلاع‌رسانی جداگانه نیست.
    نکته: این آدرس رایگان کلودفلر موقتی است و با هر ریستارت ربات عوض می‌شود —
    برای استفادهٔ جدی/دائمی، دامنهٔ خودت را در CHART_PREVIEW_BASE_URL بگذار.
    """
    global CHART_PREVIEW_BASE_URL
    bin_path = _cloudflared_bin_path()

    # ۱. اگر فایل اجرایی کلودفلر نبود، خودکار دانلود شود (در پوشه‌ای که قابل نوشتن است؛ روی Knative پوشهٔ /app فقط‌خواندنی است)
    if not bin_path.is_file():
        logger.info(f"[TUNNEL] در حال دانلود فایل ابزار کلودفلر به {bin_path} ...")
        url = "https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64"
        tmp_path = bin_path.with_name(bin_path.name + ".part")
        try:
            urllib.request.urlretrieve(url, str(tmp_path))
            tmp_path.chmod(tmp_path.stat().st_mode | stat.S_IEXEC)
            tmp_path.replace(bin_path)
            logger.info("[TUNNEL] دانلود با موفقیت انجام شد.")
        except Exception as e:
            logger.error(f"[TUNNEL] خطا در دریافت فایل کلودفلر: {e}")
            try:
                tmp_path.unlink()
            except Exception:
                pass
            return

    # ۲. اجرای پروسه تونل در پس‌زمینه و خواندن آدرس HTTPS از خروجی آن — فقط
    # برای پیش‌نمایش نمودار (CHART_PREVIEW_BASE_URL) استفاده می‌شود؛ ربات
    # همیشه با polling کار می‌کند و این تونل هیچ ارتباطی به دریافت آپدیت‌های
    # تلگرام ندارد.
    def _set_pdeathsig():
        """اجرا در پروسهٔ فرزند (قبل از exec): اگر پروسهٔ پدر (ربات) به هر شکلی
        مرد — حتی با os._exit یا SIGKILL از سمت پنل — کرنل خودش cloudflared را
        SIGKILL می‌کند تا یتیم نماند و هاست در وضعیت Stopping گیر نکند."""
        try:
            libc = ctypes.CDLL(ctypes.util.find_library("c") or "libc.so.6", use_errno=True)
            libc.prctl(1, int(signal.SIGKILL))  # PR_SET_PDEATHSIG = 1
        except Exception:
            pass

    def _worker():
        global CHART_PREVIEW_BASE_URL, _CF_TUNNEL_PROC
        try:
            cmd = [str(bin_path), "tunnel", "--url", f"http://127.0.0.1:{port}"]
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
                preexec_fn=_set_pdeathsig if os.name == "posix" else None,
            )
            _CF_TUNNEL_PROC = proc
            _url_found = False
            for line in proc.stdout:
                if _url_found:
                    continue  # خروجی را تا آخر بخوان و دور بریز؛ وگرنه پایپ پر می‌شود و cloudflared قفل می‌کند
                match = _CF_TUNNEL_URL_RE.search(line)
                if match:
                    CHART_PREVIEW_BASE_URL = match.group(0)
                    _url_found = True
                    logger.info(f"[TUNNEL] ✅ آدرس اختصاصی کلودفلر فعال شد: {CHART_PREVIEW_BASE_URL}")
            proc.wait()
        except Exception as ex:
            logger.error(f"[TUNNEL] خطا در اجرای تونل: {ex}")

    threading.Thread(target=_worker, name="cf-tunnel", daemon=True).start()


def stop_cloudflare_tunnel():
    """موقع خاموشی ربات صدا زده می‌شود — پروسه‌ی جدای cloudflared (اگر بالا
    آمده باشد) را می‌بندد تا یتیم نماند و هاست بتواند کانتینر را کامل Stop کند."""
    global _CF_TUNNEL_PROC
    proc = _CF_TUNNEL_PROC
    if proc is None:
        return
    try:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=2)
            except subprocess.TimeoutExpired:
                proc.kill()
            logger.info("[TUNNEL] پروسه‌ی cloudflared بسته شد.")
    except Exception as ex:
        logger.warning(f"[TUNNEL] خطا در بستن پروسه‌ی cloudflared: {ex}")


import atexit as _atexit
_atexit.register(lambda: stop_cloudflare_tunnel())


def _discover_knative_public_url(port: int) -> None:
    """روی Knative/OpenShift Serverless: آدرس عمومی همین سرویس را خودکار از API کوبرنتیز می‌خواند
    (status.url از Knative Service) و فقط در حافظه (CHART_PREVIEW_BASE_URL) نگه می‌دارد — چیزی در YAML نوشته نمی‌شود.
    نیازمند Role/RoleBinding خواندنِ services برای ServiceAccount پیش‌فرض (در deploy.yaml هست).
    اگر دسترسی نبود (403) یا آدرس دیر پر شد:
      • متن کامل خطای API در لاگ چاپ می‌شود (نام ServiceAccount و namespace دقیقاً در آن هست)،
      • بعد از حدود نیم‌دقیقه تونل کلودفلر به‌عنوان جایگزین بالا می‌آید تا نمودار کار کند،
      • خواندن Knative هر ۳۰ ثانیه تکرار می‌شود؛ هر وقت دسترسی درست شد (بدون ری‌استارت) آدرس ثابت جایگزین تونل می‌شود."""
    global CHART_PREVIEW_BASE_URL
    import ssl
    import urllib.error
    sa = "/var/run/secrets/kubernetes.io/serviceaccount"
    svc = os.environ.get("K_SERVICE", "").strip()
    host = os.environ.get("KUBERNETES_SERVICE_HOST", "kubernetes.default.svc")
    kport = os.environ.get("KUBERNETES_SERVICE_PORT", "443")
    found = ""
    tunnel_started = False
    denied_logged = False
    try:
        ns = Path(f"{sa}/namespace").read_text().strip()
        ctx = ssl.create_default_context(cafile=f"{sa}/ca.crt")
    except Exception as e:
        logger.warning(f"[CHART-URL] کشف خودکار آدرس ممکن نشد (فایل‌های ServiceAccount): {type(e).__name__}: {e}")
        ns, ctx = "", None
    if ctx is not None:
        api = f"https://{host}:{kport}/apis/serving.knative.dev/v1/namespaces/{ns}/services/{svc}"
        logger.info(f"[CHART-URL] خواندن آدرس عمومی از Knative: ns={ns} service={svc}")
        for attempt in range(240):                              # حدود ۱ تا ۲ ساعت؛ ترد daemon است و هزینه‌ای ندارد
            wait = 6
            try:
                token = Path(f"{sa}/token").read_text().strip()   # توکن ممکن است چرخش کند؛ هر بار تازه بخوان
                req = urllib.request.Request(api, headers={"Authorization": f"Bearer {token}"})
                with urllib.request.urlopen(req, timeout=10, context=ctx) as r:
                    data = _json_loads(r.read().decode("utf-8"))
                u = ((data.get("status") or {}).get("url") or "").strip().rstrip("/")
                if u:
                    found = "https://" + u.split("://", 1)[-1]
                    break
                logger.info(f"[CHART-URL] تلاش {attempt + 1}: status.url هنوز خالی است")
            except urllib.error.HTTPError as e:
                if e.code in (401, 403):
                    wait = 30
                    if not denied_logged:
                        denied_logged = True
                        try:
                            body = e.read().decode("utf-8", "replace")[:500]
                        except Exception:
                            body = ""
                        logger.warning(
                            "[CHART-URL] دسترسی خواندن Knative Service رد شد (%s). پاسخ کلاستر: %s — "
                            "یعنی Role/RoleBinding آخر deploy.yaml روی کلاستر apply نشده، یا برای ServiceAccount دیگری است. "
                            "تا اصلاح شود، تونل کلودفلر جایگزین می‌شود و هر ۳۰ ثانیه دوباره امتحان می‌کنم.",
                            e.code, body)
                else:
                    logger.info(f"[CHART-URL] تلاش {attempt + 1}: HTTP {e.code}")
            except Exception as e:
                logger.info(f"[CHART-URL] تلاش {attempt + 1}: {type(e).__name__}: {e}")
            # جایگزین: تونل کلودفلر، اگر بعد از چند تلاش هنوز آدرسی نداریم
            if not tunnel_started and attempt >= 4 and not CHART_PREVIEW_BASE_URL:
                tunnel_started = True
                logger.warning("[CHART-URL] آدرس Knative هنوز پیدا نشد؛ تونل کلودفلر به‌عنوان جایگزین بالا می‌آید...")
                try:
                    start_cloudflare_tunnel(port)
                except Exception as e:
                    logger.warning(f"[CHART-URL] راه‌اندازی تونل ناموفق: {e}")
            time.sleep(wait)
    if found:
        CHART_PREVIEW_BASE_URL = found
        logger.info(f"[CHART-URL] ✅ آدرس عمومی خودکار پیدا شد: {CHART_PREVIEW_BASE_URL}")
        if tunnel_started:
            stop_cloudflare_tunnel()                           # آدرس ثابت Knative بهتر از تونل موقتی است
    elif not CHART_PREVIEW_BASE_URL and not tunnel_started:
        logger.warning("[CHART-URL] آدرس پیدا نشد؛ تلاش با تونل کلودفلر...")
        start_cloudflare_tunnel(port)


_PUBLIC_HOST_IP_RE = re.compile(r"^\d{1,3}(\.\d{1,3}){3}$")


def _learn_public_base_url(headers) -> None:
    """آخرین راه: اگر تا الان آدرس عمومی نداریم و درخواستی از بیرون (از طریق همان آدرس عمومی) به API رسید،
    هدر Host/X-Forwarded-Host را به‌عنوان آدرس عمومی یاد می‌گیرد. هاست‌های داخلی/IP/خوشه‌ای رد می‌شوند.
    (کافی است یک بار آدرس سرویس را در مرورگر باز کنی، مثلاً https://آدرس-سرویس/api/v1/health)"""
    global CHART_PREVIEW_BASE_URL
    if CHART_PREVIEW_BASE_URL:
        return
    h = (headers.get("x-forwarded-host") or headers.get("host") or "").split(",")[0].strip().lower()
    h = h.split(":")[0]
    if (not h or h.count(".") < 2 or _PUBLIC_HOST_IP_RE.match(h) or ".svc" in h
            or h.endswith((".local", ".internal", ".localhost"))):
        return
    svc = os.environ.get("K_SERVICE", "").strip().lower()
    if svc and svc not in h and not h.endswith(".trycloudflare.com"):
        return
    CHART_PREVIEW_BASE_URL = "https://" + h
    logger.info(f"[CHART-URL] ✅ آدرس عمومی از هدر درخواست یاد گرفته شد: {CHART_PREVIEW_BASE_URL}")


def start_price_api_server():
    """FastAPI سبک روی ترد جدا — اگر fastapi/uvicorn نبود فقط لاگ هشدار."""
    try:
        from fastapi import FastAPI, Header, HTTPException, Query
        from fastapi.responses import JSONResponse, Response
        import uvicorn
    except ImportError:
        logger.warning(
            "[API] fastapi/uvicorn نصب نیست — وب‌سرویس قیمت غیرفعال. "
            "نصب: pip install fastapi uvicorn"
        )
        return

    app = FastAPI(title="Nokhod Price API", version="1.0")

    @app.middleware("http")
    async def _learn_public_url_mw(request, call_next):
        try:
            _learn_public_base_url(request.headers)
        except Exception:
            pass
        return await call_next(request)

    @app.get("/api/v1/rates")
    def get_rates(
        x_api_key: str | None = Header(default=None, alias="x-api-key"),
        abs: str | None = Query(default=None, description="لیست ab جدا با کاما مثلا usd,eur,emami"),
    ):
        ok, reason, client_allowed = check_api_client_access(x_api_key or "")
        if not ok:
            detail = {
                "missing_key": "کلید API ارسال نشده است.",
                "invalid_key": "کلید نامعتبر است.",
                "disabled": "اشتراک شما غیرفعال شده است.",
                "expired": "اشتراک شما به پایان رسیده است.",
            }.get(reason, "دسترسی مجاز نیست.")
            raise HTTPException(status_code=403, detail=detail)

        requested = (
            [x.strip().lower() for x in abs.split(",") if x.strip()]
            if abs else None
        )
        if client_allowed is not None:
            if requested:
                allowed_expanded = set(client_allowed)
                final_symbols = [s for s in requested if s in allowed_expanded]
            else:
                final_symbols = list(client_allowed)
        else:
            final_symbols = requested  # None = همه

        payload = build_api_rates_payload(final_symbols)
        payload["client"] = reason
        if client_allowed is not None:
            payload["allowed_symbols"] = client_allowed
        return JSONResponse(payload)

    @app.get("/api/v1/health")
    def health():
        return {"status": "ok", "service": "chand-price-api"}

    @app.get("/chart/{ab}.png")
    def get_chart_preview_image(ab: str, theme: str = "dark"):
        """PNG نمودار — فقط برای پیش‌نمایش لینک تلگرام (LinkPreviewOptions) در
        نتایج اینلاین و پیام زمان‌بندی‌شدهٔ گروه. عمداً بدون نیاز به x-api-key،
        چون سرورهای تلگرام باید بتوانند مستقیم این آدرس را بخوانند."""
        _t0 = time.time()
        logger.info(f"[CHART-HTTP] request {ab}")
        fetch_prices()
        item = get_item_by_ab((ab or "").strip().lower())
        if not item:
            raise HTTPException(status_code=404, detail="item not found")
        buf = get_cached_chart_image(item, theme=theme, strict=False)
        logger.info(f"[CHART-HTTP] served {ab} ok={bool(buf)} in {time.time() - _t0:.2f}s")
        if not buf:
            raise HTTPException(status_code=404, detail="no chart data")
        return Response(
            content=buf.getvalue(),
            media_type="image/png",
            headers={"Cache-Control": "public, max-age=60"},
        )

    def _run():
        logger.info(f"[API] price API listening on {API_HOST}:{API_PORT}")
        uvicorn.run(app, host=API_HOST, port=API_PORT, log_level="warning")

    threading.Thread(target=_run, name="price-api", daemon=True).start()

    # اگر دامنهٔ دستی در .env ست شده باشد، همان اولویت دارد و تونل رایگان
    # کلودفلر اصلاً اجرا نمی‌شود (برای هاست‌هایی مثل Raven/Pterodactyl که
    # اجرای دستی/تنظیم دامنه راحت نیست، بدون این مقدار خالی بمانَد کافی است).
    if not CHART_PREVIEW_BASE_URL:
        if os.environ.get("K_SERVICE"):      # Knative / OpenShift Serverless: آدرس را از خود کلاستر بخوان
            threading.Thread(target=_discover_knative_public_url, args=(API_PORT,),
                             name="chart-url-discover", daemon=True).start()
        else:
            start_cloudflare_tunnel(API_PORT)


# ============================================================
# حافظه دیتابیس — پنل ادمین
# PostgreSQL خودش عدد «ظرفیت کل» را گزارش نمی‌دهد (بسته به هاست فرق دارد)، پس
# فقط حجم واقعی مصرف‌شده از pg_class خوانده می‌شود؛ ظرفیت کل یک
# عدد دستی است که ادمین از همین پنل تنظیم می‌کند تا درصد پر شدن محاسبه شود.
# ============================================================
DB_QUOTA_SETTING_KEY = "db_quota_mb"


def get_db_quota_mb() -> float | None:
    raw = (get_setting(DB_QUOTA_SETTING_KEY, "") or "").strip()
    if not raw:
        return None
    try:
        v = float(raw)
        return v if v > 0 else None
    except Exception:
        return None


def set_db_quota_mb(mb: float):
    set_setting(DB_QUOTA_SETTING_KEY, str(mb))


def _get_db_size_info() -> dict:
    """حجم واقعی جدول‌ها (داده + ایندکس) در اسکیمای جاری PostgreSQL."""
    try:
        with db_cursor() as c:
            c.execute(
                "SELECT "
                "ROUND((COALESCE(SUM(pg_total_relation_size(c.oid)), 0) / 1024.0 / 1024.0)::numeric, 2) AS mb, "
                "COUNT(*) AS n_tables, "
                "COALESCE(SUM(GREATEST(c.reltuples, 0)), 0)::bigint AS n_rows "
                "FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace "
                "WHERE n.nspname = current_schema() AND c.relkind = 'r'"
            )
            row = c.fetchone() or {}
        return {
            "mb": float(row.get("mb") or 0),
            "n_tables": int(row.get("n_tables") or 0),
            "n_rows": int(row.get("n_rows") or 0),
        }
    except Exception as e:
        logger.error(f"[DBMEM] size query failed: {e}")
        return {"mb": 0.0, "n_tables": 0, "n_rows": 0}


def _progress_bar(pct: float, length: int = 10) -> str:
    pct = max(0.0, min(100.0, pct))
    filled = max(0, min(length, int(round(pct / 100 * length))))
    return "█" * filled + "░" * (length - filled)


def build_dbmem_text() -> str:
    info = _get_db_size_info()
    mb = info["mb"]
    quota = get_db_quota_mb()
    lines = [
        "🗄 <b>حافظه دیتابیس</b>",
        "",
        f"حجم فعلی: <b>{mb:.2f}</b> مگابایت",
        f"تعداد جدول‌ها: <b>{info['n_tables']}</b>",
    ]
    if quota:
        pct = (mb / quota * 100) if quota else 0.0
        bar = _progress_bar(pct)
        icon = "🔴" if pct >= 90 else ("🟡" if pct >= 70 else "🟢")
        lines.append(f"ظرفیت تنظیم‌شده: <b>{quota:.0f}</b> مگابایت")
        lines.append("")
        lines.append(f"{icon} {bar} <b>{pct:.1f}%</b> پر")
    else:
        lines.append("")
        lines.append(
            "⚠️ ظرفیت کل تنظیم نشده — روی «✎ تنظیم ظرفیت» بزن و عدد مگابایتی "
            "که هاست بهت داده رو بفرست تا درصد پر شدن نشون داده بشه."
        )
    return "\n".join(lines)


def admin_dbmem_keyboard() -> InlineKeyboardMarkup:
    kb = InlineKeyboardMarkup(row_width=2)
    kb.row(
        btn("🔄 بروزرسانی", callback_data="adm:dbmem", style="primary"),
        btn("✎ تنظیم ظرفیت", callback_data="adm:dbmem_setquota", style="primary"),
    )
    if get_db_quota_mb():
        kb.row(btn("🗑 حذف ظرفیت", callback_data="adm:dbmem_clearquota", style="danger"))
    kb.add(btn("◄ برگشت", callback_data="adm:main", style="danger"))
    return kb


