def _extract_retry_after(exc) -> int:
    try:
        params = getattr(exc, "result_json", {}).get("parameters", {}) or {}
        ra = params.get("retry_after")
        if ra:
            return int(ra)
    except Exception:
        pass
    try:
        m = re.search(r"retry after (\d+)", str(exc))
        if m:
            return int(m.group(1))
    except Exception:
        pass
    return 5


_PERMANENT_FAILURE_MARKERS = (
    "bot was blocked",
    "user is deactivated",
    "chat not found",
    "kicked",
    "bot was kicked",
    "user not found",
    "forbidden",
    "group chat was deactivated",
    "bot is not a member",
    "not enough rights",
    "peer_id_invalid",
)


def _auto_mark_user_blocked(chat_id, desc: str):
    """هر ارسال (پیام همگانی، هشدار قیمت، نتیجهٔ پیش‌بینی، ...) که با «بلاک/حذف‌شدن» رد شود، کاربر را
    همان لحظه در دیتابیس علامت می‌زند تا شمارش کاربران فعال درست بماند. فقط چت خصوصی (id مثبت)."""
    try:
        if isinstance(chat_id, int) and chat_id > 0 and (
            "blocked by the user" in desc or "user is deactivated" in desc
        ):
            with db_cursor() as c:
                c.execute("UPDATE users SET is_blocked=1 WHERE user_id=%s AND is_blocked=0", (chat_id,))
    except Exception as ex:
        logger.warning(f"[BLOCK] auto-mark failed for {chat_id}: {ex}")


class SendResult:
    __slots__ = ("ok", "permanent", "message", "error")

    def __init__(self, ok: bool, permanent: bool = False, message=None, error=None):
        self.ok = ok
        self.permanent = permanent
        self.message = message
        self.error = error

    def __bool__(self):
        return self.ok


# —— ارسال مدیا برای پیام همگانی ——
_BC_MEDIA_SENDERS = {
    "photo": "send_photo", "video": "send_video", "animation": "send_animation",
    "document": "send_document", "audio": "send_audio", "voice": "send_voice",
    "video_note": "send_video_note", "sticker": "send_sticker",
}
_BC_MEDIA_LABELS = {
    "photo": "عکس", "video": "ویدیو", "animation": "گیف", "document": "فایل",
    "audio": "آهنگ", "voice": "ویس", "video_note": "ویدیو‌مسیج", "sticker": "استیکر",
}
_BC_NO_CAPTION_TYPES = ("video_note", "sticker")   # تلگرام برای این‌ها کپشن نمی‌پذیرد
_BC_CAPTION_MAX = 1024                              # سقف کپشن تلگرام


def _send_media_message(chat_id, text, media: dict, kwargs: dict):
    """مدیا + کپشن (+ دکمه شیشه‌ای). اگر متن بلندتر از ۱۰۲۴ یا مدیا بدون کپشن بود،
    مدیا جدا و متن (همراه دکمه) به‌صورت پیام بعدی فرستاده می‌شود."""
    ctype = media.get("type")
    fn = getattr(bot, _BC_MEDIA_SENDERS[ctype])
    text = text or ""
    markup = kwargs.get("reply_markup")
    pm = kwargs.get("parse_mode")
    inline_caption = bool(text) and ctype not in _BC_NO_CAPTION_TYPES and len(text) <= _BC_CAPTION_MAX
    media_kw = {}
    if inline_caption:
        media_kw["caption"] = text
        if pm:
            media_kw["parse_mode"] = pm
    if markup is not None and (inline_caption or not text):
        media_kw["reply_markup"] = markup      # دکمه روی خودِ مدیا
    sent = fn(chat_id, media["file_id"], **media_kw)
    if text and not inline_caption:
        try:
            sent = bot.send_message(chat_id, text, **kwargs)   # دکمه روی پیام متنی
        except telebot.apihelper.ApiTelegramException as e:
            if "parse" in (getattr(e, "description", "") or str(e)).lower() and pm:
                # مدیا رفته؛ فقط متن را ساده بفرست (وگرنه تلاش مجدد مدیا را دوباره می‌فرستاد)
                sent = bot.send_message(chat_id, text, **dict(kwargs, parse_mode=None))
            else:
                raise
    return sent


def safe_send_message(chat_id, text, retries: int = 3, _media: dict | None = None, **kwargs) -> SendResult:
    attempt = 0
    current_kwargs = dict(kwargs)

    while attempt <= retries:
        try:
            if _media and _media.get("file_id") and _media.get("type") in _BC_MEDIA_SENDERS:
                sent = _send_media_message(chat_id, text, _media, current_kwargs)
            else:
                sent = bot.send_message(chat_id, text, **current_kwargs)
            return SendResult(ok=True, message=sent)

        except telebot.apihelper.ApiTelegramException as e:
            err_code = getattr(e, "error_code", None)
            desc = (getattr(e, "description", "") or str(e)).lower()

            if err_code == 429:
                wait = _extract_retry_after(e)
                logger.warning(f"[FLOOD] 429 on {chat_id}, sleeping {wait}s")
                time.sleep(wait)
                attempt += 1
                continue

            if "can't parse entities" in desc or ("parse" in desc and "entit" in desc):
                if current_kwargs.get("parse_mode") is not None:
                    logger.warning(f"[HTML] parse error for {chat_id}, retrying as plain text")
                    current_kwargs["parse_mode"] = None
                    attempt += 1
                    continue
                logger.warning(f"[SEND] persistent parse error for {chat_id}: {e}")
                return SendResult(ok=False, permanent=False, error=e)

            if any(marker in desc for marker in _PERMANENT_FAILURE_MARKERS):
                logger.info(f"[SEND] permanent failure for {chat_id}: {desc}")
                _auto_mark_user_blocked(chat_id, desc)
                return SendResult(ok=False, permanent=True, error=e)

            logger.warning(f"[SEND] transient/unrecognized API error for {chat_id}: {e}")
            return SendResult(ok=False, permanent=False, error=e)

        except (requests.exceptions.RequestException, ConnectionError, TimeoutError, OSError) as e:
            logger.warning(f"[SEND] network error for {chat_id}: {e}")
            return SendResult(ok=False, permanent=False, error=e)

        except Exception as e:
            logger.warning(f"[SEND] unexpected failure for {chat_id}: {e}")
            return SendResult(ok=False, permanent=False, error=e)

    logger.warning(f"[SEND] retries exhausted for {chat_id}")
    return SendResult(ok=False, permanent=False, error=None)


