def _handle_admin_db_quota_input(msg: types.Message):
    clear_admin_state()
    raw = (msg.text or "").strip()
    trans = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
    raw_norm = raw.translate(trans).replace(",", "").strip()
    if raw_norm in ("حذف", "خالی", "0"):
        set_setting(DB_QUOTA_SETTING_KEY, "")
        bot.reply_to(msg, "✅ ظرفیت حذف شد.")
        _open_admin_panel(ADMIN_ID)
        return
    try:
        mb = float(raw_norm)
        if mb <= 0:
            raise ValueError
    except Exception:
        bot.reply_to(msg, "❌ فرمت اشتباه. یک عدد مثبت به مگابایت بفرست، مثلاً <code>1024</code>", parse_mode="HTML")
        return
    set_db_quota_mb(mb)
    bot.reply_to(msg, f"✅ ظرفیت دیتابیس روی {mb:.0f} مگابایت تنظیم شد.")
    _open_admin_panel(ADMIN_ID)


