def _ai_think_panel():
    """متن و کیبورد صفحهٔ «سطح تفکر» — (text, kb)"""
    names = {"gemini": "جمینی (Gemini)", "groq": "گروک (Groq)"}
    lines = ["🧠 <b>سطح تفکر هوش مصنوعی</b>", ""]
    for p in _AI_THINK_PROVIDERS:
        lines.append(f"• {names[p]}: <b>{_AI_THINK_LABELS[_ai_think_level(p)]}</b>")
    lines.append("")
    lines.append("هرچه تفکر کمتر باشد جواب سریع‌تر می‌رسد؛ هرچه بیشتر باشد دقیق‌تر ولی کندتر است.")
    lines.append("")
    for p in _AI_THINK_PROVIDERS:
        lines.append(_AI_THINK_HINTS[p])
    lines.append("بدون ری‌استارت اعمال می‌شود.")
    kb = InlineKeyboardMarkup()
    for p in _AI_THINK_PROVIDERS:
        cur = _ai_think_level(p)
        kb.add(btn(f"— {names[p]} —", callback_data="adm:ai_think", style="primary"))
        row = []
        for lv in _AI_THINK_LEVELS:
            mark = "✅ " if lv == cur else ""
            row.append(btn(f"{mark}{_AI_THINK_LABELS[lv]}", callback_data=f"adm:ai_think:{p}:{lv}",
                           style="success" if lv == cur else "primary"))
            if len(row) == 3:
                kb.row(*row)
                row = []
        if row:
            kb.row(*row)
    kb.add(btn("◄ برگشت", callback_data="adm:test_groq", style="danger"))
    return "\n".join(lines), kb


def _handle_admin_ai_add_key(msg: types.Message):
    """ادمین کلید (یا چند کلید) گروک/جمینی فرستاده — تست، ذخیره در .env و ورود به چرخه."""
    state = get_admin_state()
    data = state.get("data") or {}
    provider = data.get("provider")
    mid = data.get("mid")
    if provider not in API_SERVICES:
        clear_admin_state()
        return
    prefix = _ai_prefixes(provider)
    label = API_SERVICES[provider]["label"]

    # پیام حاوی کلید را از چت پاک کن
    try:
        bot.delete_message(msg.chat.id, msg.message_id)
    except Exception:
        pass

    cands, seen = [], set()
    for part in _split_env_list(msg.text or ""):
        k = _clean_groq_key(part.split("=")[-1] if "=" in part and not part.startswith(prefix) else part)
        if k and k not in seen:
            seen.add(k)
            cands.append(k)
    if not cands:
        bot.send_message(ADMIN_ID, "❌ کلیدی در پیام پیدا نشد. دوباره بفرست (یا لغو کن).")
        return
    clear_admin_state()

    def _show(text, kb=None):
        try:
            if mid:
                bot.edit_message_text(text, msg.chat.id, mid, reply_markup=kb,
                                      parse_mode="HTML", disable_web_page_preview=True)
                return
        except Exception:
            pass
        bot.send_message(ADMIN_ID, text, reply_markup=kb, parse_mode="HTML",
                         disable_web_page_preview=True)

    _show(f"⏳ در حال بررسی {len(cands)} کلید {label}...")
    lines = []
    added = 0
    for k in cands:
        m = _mask_key(k)
        if not _ai_key_ok(provider, k):
            lines.append(f"❌ <code>{m}</code> — قالب کلید {label} درست نیست: <code>{_ai_prefix_label(provider)}</code>")
            continue
        if k in _extract_ai_keys(provider):
            lines.append(f"⚠️ <code>{m}</code> — از قبل در لیست هست")
            continue
        r = _test_one_key(provider, k)
        if r["status"] == "dead":
            lines.append(f"❌ <code>{m}</code> — رد شد: {r['detail']}")
            continue
        try:
            ok = add_ai_key(provider, k)
        except Exception as e:
            logger.warning(f"[ADMIN] add_ai_key failed: {e}")
            lines.append(f"❌ <code>{m}</code> — نوشتن در .env ناموفق: {str(e)[:80]}")
            continue
        if ok:
            added += 1
            note = "سالم" if r["status"] == "ok" else f"اضافه شد ولی تأیید نشد ({r['detail']})"
            lines.append(f"✅ <code>{m}</code> — {note}")
        else:
            lines.append(f"⚠️ <code>{m}</code> — از قبل در لیست هست")

    lines.append("")
    lines.append(f"اضافه‌شده: <b>{added}</b> | در چرخه الان: {_ai_counts_inline()}")
    if added:
        lines.append("بدون ری‌استارت وارد چرخه شد.")
    _show("\n".join(lines), _ai_keys_keyboard())


@bot.message_handler(commands=["api_create", "api_extend", "api_list", "api_key", "api_off", "api_on", "api_del", "api_allow", "api_catalog", "extend_site"], chat_types=["private"])
def handle_api_admin_cmds(msg: types.Message):
    if msg.from_user.id != ADMIN_ID:
        return
    text = (msg.text or "").strip()
    parts = text.split()
    cmd = parts[0].lstrip("/").split("@")[0].lower()

    if cmd == "api_list":
        bot.reply_to(msg, build_api_admin_text(), parse_mode="HTML")
        return

    if cmd == "api_catalog":
        # فهرست کامل و شماره‌دار همهٔ آیتم‌ها (ارز/رمزارز/طلا و سکه/نفت)
        # فقط برای ادمین — برای این‌که بدون رفتن توی منوی کلاینت هم شماره‌ها
        # را ببیند و با /api_allow نام عدد۱,عدد۲ سریع تنظیم کند.
        catalog = _api_catalog_build()
        lines = ["📊 <b>کاتالوگ کامل آیتم‌ها</b> (فقط ادمین می‌بیند):"]
        last_cat = None
        for c in catalog:
            if c["cat_key"] != last_cat:
                last_cat = c["cat_key"]
                lines.append(f"\n<b>{c['cat_title']}</b>")
            lines.append(f"◻️ <b>{c['num']}</b>. {c['emoji']} {c['label']}")
        _send_html_chunks(msg.chat.id, lines)
        return

    if cmd == "api_create":
        if len(parts) < 2:
            bot.reply_to(
                msg,
                "فرمت: <code>/api_create نام [روز]</code>\nمثال: <code>/api_create site1 30</code>",
                parse_mode="HTML",
            )
            return
        name = parts[1]
        days = 30
        if len(parts) > 2:
            try:
                days = int(parts[2])
            except ValueError:
                bot.reply_to(msg, "❌ تعداد روز نامعتبر")
                return
        if get_api_client_by_name(name):
            bot.reply_to(msg, f"❌ کلاینت <b>{name}</b> از قبل وجود دارد. از /api_extend استفاده کن.", parse_mode="HTML")
            return
        row = create_api_client(name, days)
        if not row:
            bot.reply_to(msg, "❌ ساخت ناموفق (نام تکراری یا خطای دیتابیس)")
            return
        bot.reply_to(
            msg,
            f"✅ کلاینت ساخته شد\n\n"
            f"نام: <b>{row['client_name']}</b>\n"
            f"مدت: <b>{days}</b> روز\n"
            f"انقضا: <code>{row['expire_at']}</code>\n\n"
            f"🔑 کلید (فقط یک‌بار کامل نشان داده می‌شود):\n"
            f"<code>{row['api_key']}</code>\n\n"
            f"آدرس:\n<code>http://SERVER:{API_PORT}/api/v1/rates</code>\n"
            f"هدر: <code>x-api-key: {row['api_key']}</code>",
            parse_mode="HTML",
        )
        return

    if cmd in ("api_extend", "extend_site"):
        if len(parts) < 2:
            bot.reply_to(
                msg,
                "فرمت: <code>/api_extend نام [روز]</code>\nمثال: <code>/api_extend site1 30</code>",
                parse_mode="HTML",
            )
            return
        name = parts[1]
        days = 30
        if len(parts) > 2:
            try:
                days = int(parts[2])
            except ValueError:
                bot.reply_to(msg, "❌ تعداد روز نامعتبر")
                return
        row = extend_api_client(name, days)
        if not row:
            bot.reply_to(msg, "❌ کلاینت پیدا نشد")
            return
        bot.reply_to(
            msg,
            f"✅ اشتراک <b>{name}</b> به مدت <b>{days}</b> روز تمدید شد.\n"
            f"انقضای جدید: <code>{row.get('expire_at')}</code>\n"
            f"وضعیت: فعال",
            parse_mode="HTML",
        )
        return

    if cmd == "api_key":
        if len(parts) < 2:
            bot.reply_to(msg, "فرمت: <code>/api_key نام</code>", parse_mode="HTML")
            return
        row = get_api_client_by_name(parts[1])
        if not row:
            bot.reply_to(msg, "❌ پیدا نشد")
            return
        bot.reply_to(
            msg,
            f"🔑 <b>{row['client_name']}</b>\n"
            f"<code>{row['api_key']}</code>\n"
            f"انقضا: <code>{row.get('expire_at')}</code>\n"
            f"فعال: <b>{'بله' if row.get('is_active') else 'خیر'}</b>",
            parse_mode="HTML",
        )
        return

    if cmd == "api_off":
        if len(parts) < 2:
            bot.reply_to(msg, "فرمت: <code>/api_off نام</code>", parse_mode="HTML")
            return
        ok = set_api_client_active(parts[1], False)
        bot.reply_to(msg, "✅ قطع شد" if ok else "❌ پیدا نشد")
        return

    if cmd == "api_on":
        if len(parts) < 2:
            bot.reply_to(msg, "فرمت: <code>/api_on نام</code>", parse_mode="HTML")
            return
        ok = set_api_client_active(parts[1], True)
        bot.reply_to(msg, "✅ فعال شد" if ok else "❌ پیدا نشد")
        return


    if cmd == "api_allow":
        parts2 = text.split(maxsplit=2)
        if len(parts2) < 3:
            bot.reply_to(
                msg,
                "فرمت:\n<code>/api_allow نام 1,5,12</code> (عدد کنار هر آیتم از /api_catalog یا منوی «📊 نمادها»)\n"
                "یا با اسم مثل قبل: <code>/api_allow نام usd,eur,emami</code>\n"
                "همه نمادها: <code>/api_allow نام all</code>",
                parse_mode="HTML",
            )
            return
        name = parts2[1].strip()
        symbols_raw = parts2[2].strip()
        symbols_low = symbols_raw.lower()
        if not get_api_client_by_name(name):
            bot.reply_to(msg, "❌ کلاینت پیدا نشد")
            return
        if symbols_low in ("all", "*", "همه"):
            symbols_val = None
        else:
            nums = re.findall(r"\d+", symbols_raw)
            # اگر ورودی فقط عدد(ها) بود (با فاصله/کاما جدا)، بر اساس همان شمارهٔ
            # ثابت کاتالوگ (کنار هر آیتم در /api_catalog یا منوی «📊 نمادها») به
            # نماد واقعی تبدیل می‌شود؛ وگرنه مثل قبل به‌عنوان اسم مستقیم خوانده می‌شود.
            is_numeric_only = bool(nums) and not re.search(r"[a-zA-Zء-ی]", symbols_raw)
            if is_numeric_only:
                catalog = _api_catalog_build()
                picked, invalid_nums = [], []
                for n_s in nums:
                    item = _api_catalog_by_num(catalog, int(n_s))
                    if item:
                        picked.append(item["ab"])
                    else:
                        invalid_nums.append(n_s)
                if invalid_nums:
                    bot.reply_to(msg, f"⚠️ عدد نامعتبر: {', '.join(invalid_nums)}")
                if not picked:
                    bot.reply_to(msg, "❌ هیچ عدد معتبری پیدا نشد.")
                    return
                symbols_val = ",".join(sorted(set(picked)))
            else:
                symbols_val = symbols_low.replace(" ", "")
        ok = set_api_allowed_symbols(name, symbols_val)
        if ok:
            label = "همه نمادها" if symbols_val is None else f"<code>{symbols_val}</code>"
            bot.reply_to(
                msg,
                f"✅ نمادهای مجاز برای <b>{name}</b> روی {label} تنظیم شد.",
                parse_mode="HTML",
            )
        else:
            bot.reply_to(msg, "❌ خطا در ذخیره")
        return

    if cmd == "api_del":
        if len(parts) < 2:
            bot.reply_to(msg, "فرمت: <code>/api_del نام</code>", parse_mode="HTML")
            return
        ok = delete_api_client(parts[1])
        bot.reply_to(msg, "✅ حذف شد" if ok else "❌ پیدا نشد")
        return


# ============================================================
# دستور /هوا و /weather (و /hava) — در پیوی و گروه
# باید قبل از هندلرهای عمومی پیوی/گروه ثبت شود (telebot اولین هندلر منطبق را اجرا می‌کند).
# با is_spam خود ربات محدودیت اسپم هم اعمال می‌شود. اگر weather_service نبود، فقط این دستور غیرفعال می‌ماند.
# ============================================================
def get_user_weather_location(uid: int) -> dict | None:
    """شهر و مختصات ذخیره‌شدهٔ کاربر از جدول users → {"city","lat","lon"} یا None
    (کاربر شهری ذخیره نکرده، یا خطای دیتابیس)."""
    try:
        with db_cursor() as c:
            c.execute(
                "SELECT weather_city, weather_lat, weather_lon FROM users WHERE user_id=%s",
                (int(uid),),
            )
            row = c.fetchone()
        if row and row.get("weather_city") and row.get("weather_lat") is not None \
                and row.get("weather_lon") is not None:
            return {
                "city": row["weather_city"],
                "lat": float(row["weather_lat"]),
                "lon": float(row["weather_lon"]),
            }
    except Exception as e:
        logger.warning(f"[WEATHER] get_user_weather_location failed: {type(e).__name__}")
    return None


def save_user_weather_location(uid: int, city: str, lat: float, lon: float) -> bool:
    """شهر و مختصات کاربر را ذخیره/آپدیت می‌کند. اگر کاربر هنوز ردیفی در users ندارد
    (مثلاً فقط داخل گروه از ربات استفاده کرده) ردیف جدید ساخته می‌شود."""
    try:
        uid = int(uid)
        city = str(city or "").strip()[:64]
        lat, lon = float(lat), float(lon)
        if not city or not (-90.0 <= lat <= 90.0) or not (-180.0 <= lon <= 180.0):
            return False
        with db_cursor() as c:
            c.execute(
                """INSERT INTO users (user_id, weather_city, weather_lat, weather_lon)
                   VALUES (%s, %s, %s, %s)
                   ON CONFLICT (user_id) DO UPDATE SET
                       weather_city=%s, weather_lat=%s, weather_lon=%s""",
                (uid, city, lat, lon, city, lat, lon),
            )
        return True
    except Exception as e:
        logger.warning(f"[WEATHER] save_user_weather_location failed: {type(e).__name__}")
        return False


# نام‌های قدیمی (استفاده‌شده در مسیر هوش مصنوعی) به همین دو تابع وصل‌اند
get_user_weather_city = get_user_weather_location


# ---- پیوی: کمکی‌های مشترک قیمت و هوا (برای همهٔ کاربران، نه فقط ادمین) ----
def _pv_fj_blocked(user) -> bool:
    """جوین اجباری در پیوی: True = کاربر عضو نیست، گیت نشان داده شد و دستور نباید اجرا شود."""
    try:
        if user is None or not _fj_enforced() or user.id == ADMIN_ID:
            return False
        ok, missing, _unc = fj_check_user(user.id)
        if ok:
            _fj_note_ok(user.id)
            return False
        _fj_show_gate_pv(user, missing)
        return True
    except Exception as e:
        logger.warning(f"[FJ] pv_blocked: {e}")
        return False


def _pv_admin_busy(user) -> bool:
    """ادمین وسط وارد کردن یک ورودی مرحله‌ای (پنل) است؛ متنش نباید به‌عنوان دستور قیمت/هوا گرفته شود."""
    try:
        return bool(user is not None and user.id == ADMIN_ID and (get_admin_state() or {}).get("state"))
    except Exception:
        return False


def _pv_autodel(cmd_msg, sent=None) -> None:
    """مکانیزم حذف مثل گروه: پیام دستور و جواب ربات بعد از GROUP_CMD_REPLY_AUTO_DELETE_SEC ثانیه پاک می‌شوند
    (کلیک روی نمودار یک‌بار مهلت هر دو را تمدید می‌کند). sent=None → فقط پیام دستور؛ sent → جواب (linked به دستور)."""
    try:
        d = GROUP_CMD_REPLY_AUTO_DELETE_SEC
        if sent is None:
            _auto_delete_message(cmd_msg.chat.id, cmd_msg.message_id, delay=d)
        else:
            _auto_delete_message(cmd_msg.chat.id, sent.message_id, delay=d, linked=(cmd_msg.message_id,))
    except Exception as e:
        logger.debug(f"[PV-AUTODEL] {e}")


_PV_WX_CMDS = ("هوا", "weather", "hava")


def _pv_wx_parse(text: str):
    """(منطبق؟، نام شهر) برای «/هوا» ، «/هوا تهران» ، «/weather@ربات مشهد»."""
    t = (text or "").strip()
    if not t.startswith("/"):
        return False, ""
    parts = t[1:].split(None, 1)
    if not parts:
        return False, ""
    cmd, _, mention = parts[0].partition("@")
    if cmd.lower() not in _PV_WX_CMDS:
        return False, ""
    if mention:
        uname = _get_bot_username()
        if uname and mention.lower() != uname.lower():
            return False, ""
    return True, (parts[1].strip() if len(parts) > 1 else "")


def _pv_wx_filter(m) -> bool:
    try:
        return bool(m.from_user) and _pv_wx_parse(m.text or "")[0] and not _pv_admin_busy(m.from_user)
    except Exception:
        return False


def handle_pv_weather(msg: types.Message):
    """/هوا در پیوی برای همهٔ کاربران: «/هوا تهران» یا «/هوا» (شهر ذخیره‌شدهٔ خود کاربر)."""
    u = msg.from_user
    if u is None or is_spam(msg.chat.id) or _pv_fj_blocked(u):
        return
    _pv_autodel(msg)
    _ok, arg = _pv_wx_parse(msg.text or "")
    item = None
    if arg:
        arg = arg[:60]
        canon = _weather_canon_city(arg)
        if canon in PREDEFINED_CITIES:
            item = canon
        else:
            hit = _pp_geocode(arg)
            if hit:
                item = {"city": hit[0], "lat": hit[1], "lon": hit[2]}
        if not item:
            _pv_autodel(msg, bot.reply_to(msg, "این شهر رو پیدا نکردم؛ اسمش رو درست‌تر بنویس.\nمثال: <code>/هوا تهران</code>",
                                          parse_mode="HTML"))
            return
    else:
        item = get_user_weather_location(u.id)
        if not item:
            _pv_autodel(msg, bot.reply_to(msg, "اسم شهر رو هم بنویس.\nمثال: <code>/هوا تهران</code>", parse_mode="HTML"))
            return
    try:
        _, data = _weather_fetch_item(item)
    except Exception as e:
        logger.warning(f"[WEATHER] PV fetch failed: {type(e).__name__}: {e}")
        data = None
    txt = ""
    if data:
        try:
            txt = (format_weather_for_user(data, future=False) if format_weather_for_user
                   else format_weather_for_ai(data)) or ""
        except Exception as e:
            logger.warning(f"[WEATHER] PV format failed: {type(e).__name__}: {e}")
    if not txt.strip():
        _pv_autodel(msg, bot.reply_to(msg, "الان نتونستم اطلاعات هوا رو بگیرم؛ چند لحظهٔ دیگه دوباره امتحان کن."))
        return
    try:
        _sent = _html_retry(lambda t: bot.reply_to(msg, t, parse_mode="HTML", link_preview_options=_lp_off()), txt)
        _pv_autodel(msg, _sent)
    except Exception as e:
        logger.warning(f"[WEATHER] PV send failed: {e}")


if _HAS_WEATHER:
    # قبل از ثبت هندلرهای خود ماژول و هندلر عمومی پیوی ثبت می‌شود تا در پیوی قطعاً جواب بدهد (گروه دست‌نخورده می‌ماند)
    bot.message_handler(func=_pv_wx_filter, content_types=["text"], chat_types=["private"])(handle_pv_weather)
