_INTRO_HANDLE_RE = re.compile(r"@\w{3,}")
_INTRO_DATE_RE = re.compile(r"(?<!\d)\d{2,4}\s*[/\-.]\s*\d{1,2}\s*[/\-.]\s*\d{1,4}(?!\d)")
_INTRO_NUM_RE = re.compile(r"\+?\d(?:[\s\-().]?\d){5,}")                 # ۶ رقم یا بیشتر: تلفن، کد ملی، کارت، ...
_INTRO_ADDR_RE = re.compile(r"خیابان|کوچه|پلاک|بلوار|محله|آدرس|کد ?پستی|street|avenue|postal|\bzip\b", re.I)

