def admin_fj_text() -> str:
    on = _fj_enabled()
    chs = _fj_channels(force=True)
    lines = [
        "🔒 <b>جوین اجباری</b>",
        "",
        f"وضعیت: <b>{'🟢 روشن' if on else '🔴 خاموش'}</b>",
        f"کانال‌ها: <b>{len(chs)}</b>",
    ]
    for i, ch in enumerate(chs, 1):
        lines.append(f"{i}. {html.escape(str(ch['title']))} — <code>{ch['key']}</code>")
    if on and not chs:
        lines.append("⚠️ هیچ کانالی تنظیم نشده؛ تا کانال اضافه نکنی گیت اعمال نمی‌شود.")
    lines += [
        "",
        "• ربات باید در همهٔ این کانال‌ها <b>ادمین</b> باشد (برای چک عضویت و تشخیص خروج).",
        "• متن‌ها و برچسب دکمه‌ها از «ویرایش پیام‌ها» (کلیدهای <code>fj_</code>) قابل‌تغییرند.",
    ]
    return "\n".join(lines)


def admin_fj_menu() -> InlineKeyboardMarkup:
    on = _fj_enabled()
    kb = InlineKeyboardMarkup(row_width=1)
    kb.add(btn(
        "🟢 جوین اجباری: روشن (برای خاموش‌کردن بزن)" if on else "🔴 جوین اجباری: خاموش (برای روشن‌کردن بزن)",
        callback_data="adm:fj_toggle", style="success" if on else "danger",
    ))
    for ch in _fj_channels():
        kb.add(btn(f"🗑 حذف: {ch['title']}"[:60], callback_data=f"adm:fj_del:{ch['key']}", style="danger"))
    kb.add(btn("➕ افزودن کانال", callback_data="adm:fj_add", style="primary"))
    kb.add(btn("◄ برگشت", callback_data="adm:main", style="danger"))
    return kb


def _fj_admin_show_menu(mid=None):
    text, kb = admin_fj_text(), admin_fj_menu()
    if mid:
        try:
            bot.edit_message_text(text, ADMIN_ID, mid, reply_markup=kb, parse_mode="HTML")
            return
        except Exception as e:
            if "message is not modified" in str(e).lower():
                return
    bot.send_message(ADMIN_ID, text, reply_markup=kb, parse_mode="HTML")


def _fj_parse_channel_ref(msg):
    fo = getattr(msg, "forward_origin", None)
    chat = getattr(fo, "chat", None) if fo else None
    if chat is None:
        chat = getattr(msg, "forward_from_chat", None)
    if chat is not None:
        return chat.id
    raw = (msg.text or "").strip().translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789"))
    m = re.search(r"t\.me/c/(\d+)", raw)
    if m:
        return int("-100" + m.group(1))
    if re.fullmatch(r"-?\d{5,}", raw):
        return int(raw)
    m = re.search(r"t\.me/([A-Za-z][A-Za-z0-9_]{3,})", raw)
    if m:
        return "@" + m.group(1)
    if re.fullmatch(r"@?[A-Za-z][A-Za-z0-9_]{3,}", raw):
        return "@" + raw.lstrip("@")
    return None


def _fj_save_channel(cid, title: str, link: str):
    first = not _fj_channels(force=True)
    with db_cursor() as c:
        c.execute(
            "INSERT INTO force_join_channels (channel_id, channel_title, channel_link) VALUES (%s, %s, %s) "
            "ON CONFLICT (channel_id) DO UPDATE SET channel_title=%s, channel_link=%s",
            (str(cid), title, link, title, link),
        )
    _fj_channels_invalidate()
    if first:
        set_fj_enabled(True)
    return first


def _handle_admin_fj_channel_input(msg: types.Message):
    data = (get_admin_state().get("data") or {})
    mid = data.get("mid")
    raw = (msg.text or "").strip()
    if raw in ("/cancel", "لغو", "بازگشت", "انصراف"):
        clear_admin_state()
        _fj_admin_show_menu(mid)
        return
    ref = _fj_parse_channel_ref(msg)
    if ref is None:
        bot.reply_to(
            msg,
            "❌ نفهمیدم. یوزرنیم (<code>@my_channel</code>)، آیدی عددی (<code>-100…</code>) یا "
            "یک پست متنیِ فوروارد‌شده از کانال بفرست. (برای انصراف: <b>لغو</b>)",
        )
        return
    try:
        chat = bot.get_chat(ref)
    except Exception as e:
        bot.reply_to(msg, f"❌ کانال پیدا نشد: <code>{html.escape(str(e)[:150])}</code>")
        return
    if chat.type not in ("channel", "supergroup", "group"):
        bot.reply_to(msg, "❌ این یک کانال/گروه نیست.")
        return
    try:
        me_id = _get_bot_id() or bot.get_me().id
        st = bot.get_chat_member(chat.id, me_id).status
    except Exception as e:
        bot.reply_to(msg, f"❌ نتونستم وضعیت ربات رو توی کانال چک کنم: <code>{html.escape(str(e)[:150])}</code>")
        return
    if st not in ("administrator", "creator"):
        bot.reply_to(msg, "⚠️ ربات توی این کانال ادمین نیست. اول ادمینش کن، بعد دوباره بفرست.")
        return
    title = chat.title or str(chat.id)
    uname = getattr(chat, "username", None)
    link = f"https://t.me/{uname}" if uname else (getattr(chat, "invite_link", None) or "")
    if not link:
        try:
            link = bot.export_chat_invite_link(chat.id) or ""
        except Exception:
            link = ""
    if not link:
        set_admin_state("fj_waiting_link", {"cid": chat.id, "title": title, "mid": mid})
        bot.reply_to(
            msg,
            "کانال خصوصیه و نتونستم لینک دعوتش رو خودم بسازم.\n"
            "لینک دعوت کانال رو بفرست (مثل <code>https://t.me/+AbCd...</code>):",
        )
        return
    clear_admin_state()
    first = _fj_save_channel(chat.id, title, link)
    note = "\n🟢 جوین اجباری هم روشن شد." if first else ""
    bot.reply_to(msg, f"✅ کانال «{html.escape(title)}» اضافه شد.{note}")
    _fj_admin_show_menu()


def _handle_admin_fj_link_input(msg: types.Message):
    data = (get_admin_state().get("data") or {})
    raw = (msg.text or "").strip()
    if raw in ("/cancel", "لغو", "بازگشت", "انصراف"):
        clear_admin_state()
        _fj_admin_show_menu(data.get("mid"))
        return
    if not re.match(r"^https?://t\.me/\S+$", raw):
        bot.reply_to(msg, "❌ لینک باید با <code>https://t.me/</code> شروع بشه. دوباره بفرست (یا <b>لغو</b>).")
        return
    cid, title = data.get("cid"), data.get("title") or str(data.get("cid"))
    clear_admin_state()
    first = _fj_save_channel(cid, title, raw)
    note = "\n🟢 جوین اجباری هم روشن شد." if first else ""
    bot.reply_to(msg, f"✅ کانال «{html.escape(title)}» اضافه شد.{note}")
    _fj_admin_show_menu()


def fj_admin_callback(call, data: str) -> bool:
    """شاخه‌های adm:fj_* پنل ادمین. True = کالبک کامل جواب داده شد (دیگر answer نزن)."""
    cid, mid = call.message.chat.id, call.message.message_id
    if data == "adm:fj_menu":
        clear_admin_state()
        bot.edit_message_text(admin_fj_text(), cid, mid, reply_markup=admin_fj_menu(), parse_mode="HTML")
        return False
    if data == "adm:fj_toggle":
        if not _fj_enabled() and not _fj_channels(force=True):
            bot.answer_callback_query(call.id, "اول حداقل یک کانال اضافه کن ➕", show_alert=True)
            return True
        new_state = not _fj_enabled()
        set_fj_enabled(new_state)
        bot.answer_callback_query(
            call.id,
            "جوین اجباری روشن شد ✅" if new_state else "جوین اجباری خاموش شد ⛔️",
            show_alert=True,
        )
        _fj_admin_show_menu(mid)
        return True
    if data == "adm:fj_add":
        set_admin_state("fj_waiting_channel", {"mid": mid})
        kb = InlineKeyboardMarkup()
        kb.add(btn("◄ بازگشت / لغو", callback_data="adm:fj_menu", style="danger"))
        bot.edit_message_text(
            "➕ <b>افزودن کانال</b>\n\n"
            "یوزرنیم کانال (<code>@my_channel</code>)، آیدی عددی (<code>-100…</code>) یا یک پست متنیِ "
            "فوروارد‌شده از کانال رو بفرست.\n"
            "⚠️ ربات باید توی اون کانال <b>ادمین</b> باشه.",
            cid, mid, reply_markup=kb, parse_mode="HTML",
        )
        return False
    if data.startswith("adm:fj_del:"):
        key = data[len("adm:fj_del:"):]
        with db_cursor() as c:
            c.execute("DELETE FROM force_join_channels WHERE channel_id=%s", (key,))
        _fj_channels_invalidate()
        bot.answer_callback_query(call.id, "کانال حذف شد")
        _fj_admin_show_menu(mid)
        return True
    return False


