@bot.message_handler(commands=["start"], chat_types=["group", "supergroup"])
def handle_group_start_payload(msg: types.Message):
    """وقتی ربات با لینک «افزودن به گروه» اضافه می‌شود، تلگرام یک «/start addgroup» داخل گروه
    می‌گذارد؛ آن را بی‌صدا پاک می‌کنیم تا گروه شلوغ نشود."""
    toks = (msg.text or "").split()
    if not toks:
        return
    _, _, mention = toks[0].partition("@")
    if mention:
        uname = _get_bot_username()
        if uname and mention.lower() != uname.lower():
            return
    if len(toks) > 1 and toks[1] == ADD_GROUP_PAYLOAD:
        _delete_message_async(msg.chat.id, msg.message_id)


@bot.callback_query_handler(func=lambda c: bool(c.data) and c.data.startswith("grpx:"))
def handle_group_close(call: types.CallbackQuery):
    if call.message is None:
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return
    try:
        owner = int(call.data.split(":", 1)[1])
    except (IndexError, ValueError):
        owner = 0
    uid = call.from_user.id
    cid, mid = call.message.chat.id, call.message.message_id
    allowed = uid == ADMIN_ID or (owner != 0 and uid == owner)
    if not allowed:
        try:
            allowed = bot.get_chat_member(cid, uid).status in ("administrator", "creator")
        except Exception:
            allowed = False
    if not allowed:
        try:
            bot.answer_callback_query(call.id, render_text("group_close_denied") or None)
        except Exception:
            pass
        return
    try:
        bot.delete_message(cid, mid)
    except Exception:
        pass
    # اگر پیام ریپلای روی خود دستور /راهنما بود، دستور هم پاک شود
    try:
        rt = call.message.reply_to_message
        if rt is not None and _is_group_help_cmd(rt.text or ""):
            bot.delete_message(cid, rt.message_id)
    except Exception:
        pass
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass


