@bot.callback_query_handler(func=lambda c: c.data and c.data.startswith("ichart:"))
def handle_inline_chart_toggle(call: types.CallbackQuery):
    """دکمهٔ ▸ نمودار روی نتیجهٔ اینلاین — تلگرام اجازه نمی‌دهد پیام متنی اینلاین
    مستقیم به عکس تبدیل شود، پس با فعال‌کردن show_above_text + prefer_large_media
    روی link_preview_options همان پیام را ادیت می‌کنیم تا نمودار درست بالای متن
    باز شود، بدون پرش به پیوی و بدون پاک/ارسال مجدد پیام.
    طبق درخواست: بعد از نمایش، کیبورد کاملاً حذف می‌شود (بدون دکمهٔ آپدیت/بستن)."""
    if not call.inline_message_id:
        bot.answer_callback_query(call.id, render_text("toast_inline_only") or None)
        return
    if fj_guard_callback(call):
        return

    ab = call.data.split(":", 1)[1]

    if is_chart_spam(call.from_user.id, is_group=False):
        bot.answer_callback_query(call.id, render_text("chart_spam_msg"), show_alert=False)
        return

    chart_url = _chart_preview_url(ab, theme="dark")
    if not chart_url:
        bot.answer_callback_query(
            call.id, (render_text("toast_chart_unavailable") or None), show_alert=True,
        )
        return

    fetch_prices()
    item = get_item_by_ab(ab)
    if not item:
        bot.answer_callback_query(call.id, render_text("toast_not_found") or None)
        return
    answered = _chart_building_toast(call, ab)
    if not _chart_prewarm(ab):
        if not answered:
            _cb_answer(call, render_text("toast_chart_error") or None)
        else:
            logger.warning(f"[ICHART] prewarm failed after toast for {ab}")
        return

    uname = _get_bot_username() or "thechandbot"
    msg_text = _build_inline_item_text(item, uname)
    preview = types.LinkPreviewOptions(
        is_disabled=False,
        url=chart_url,
        prefer_large_media=True,
        show_above_text=True,
    )
    try:
        bot.edit_message_text(
            msg_text,
            inline_message_id=call.inline_message_id,
            parse_mode="HTML",
            link_preview_options=preview,
            reply_markup=None,
        )
        if not answered:
            _cb_answer(call)
    except Exception as e:
        logger.warning(f"[ICHART] inline edit failed for {ab}: {e}")
        if not answered:
            _cb_answer(call, render_text("toast_chart_error") or None)


