@bot.my_chat_member_handler()
def handle_bot_member(update: types.ChatMemberUpdated):
    # پیوی: kicked = کاربر ربات را بلاک کرد | member = آنبلاک/استارت
    if update.chat.type == "private":
        try:
            _pv_member_update(update)
        except Exception as e:
            logger.warning(f"[BLOCK] my_chat_member پیوی: {e}")
        return
    if update.chat.type not in ("group", "supergroup"):
        return

    new_status = update.new_chat_member.status
    old_status = getattr(update.old_chat_member, "status", "")

    if new_status in ("administrator", "creator", "member"):
        register_group(update.chat)
    elif new_status in ("left", "kicked", "banned") or (
        new_status == "restricted" and not getattr(update.new_chat_member, "is_member", True)
    ):
        deactivate_group(update.chat.id)

    # جوین اجباری: اضافه‌کنندهٔ ربات را بررسی کن؛ اگر عضو کانال نبود گروه قفل می‌شود
    gate_sent = False
    try:
        gate_sent = fj_on_bot_status_change(update, old_status, new_status)
    except Exception as e:
        logger.warning(f"[FJ] بررسی اضافه‌کنندهٔ ربات در {update.chat.id}: {e}", exc_info=True)

    # تازه ادمین شده (نه فقط تغییر دسترسی‌ها) → پیام ادمین‌شدن + دکمهٔ بستن قرمز
    if new_status == "administrator" and old_status != "administrator":
        locked = False
        try:
            locked = _fj_enforced() and _fj_group_status(update.chat.id) == 0
        except Exception:
            pass
        if not gate_sent and not locked:
            _send_group_admin_welcome(update.chat)


