# ---------------------------------------------------------------------------
# محدودکنندهٔ نرخ: پنجرهٔ لغزان ۱ ثانیه‌ای، حداکثر TTS_RATE_PER_SEC شروع در هر پنجره
# ---------------------------------------------------------------------------
_TTS_SLOTS = _deque()
_TTS_SLOTS_LOCK = threading.Lock()


def _tts_try_acquire() -> float:
    """0 = جا گرفته شد؛ در غیر این‌صورت تعداد ثانیه‌ای که باید صبر کرد."""
    now = time.monotonic()
    with _TTS_SLOTS_LOCK:
        while _TTS_SLOTS and now - _TTS_SLOTS[0] >= 1.0:
            _TTS_SLOTS.popleft()
        if len(_TTS_SLOTS) < TTS_RATE_PER_SEC:
            _TTS_SLOTS.append(now)
            return 0.0
        return max(0.02, 1.0 - (now - _TTS_SLOTS[0]))


def _tts_acquire(on_busy=None, timeout: float = None) -> bool:
    """منتظر می‌ماند تا جا خالی شود. اولین باری که سقف پر بود on_busy صدا زده می‌شود. False = مهلت تمام شد."""
    deadline = time.monotonic() + (TTS_WAIT_TIMEOUT if timeout is None else timeout)
    notified = False
    while True:
        wait = _tts_try_acquire()
        if wait <= 0:
            return True
        if not notified:
            notified = True
            if on_busy:
                try:
                    on_busy()
                except Exception:
                    pass
        if time.monotonic() + wait > deadline:
            return False
        time.sleep(wait)


# ---------------------------------------------------------------------------
# تولید صدا
# ---------------------------------------------------------------------------
_TTS_EMOJI_RE = re.compile("[\U0001F000-\U0001FAFF\u2190-\u21FF\u2300-\u23FF\u2600-\u27BF\u2B00-\u2BFF\uFE00-\uFE0F\u200d]+")


def _tts_clean(text: str) -> str:
    """متن جواب → متن قابل‌خواندن برای صدا (بدون تگ، مارک‌داون، لینک و ایموجی)."""
    t = re.sub(r"<pre\b.*?</pre>", " ", text or "", flags=re.S | re.I)   # بلوک کد را نخوان
    t = re.sub(r"<[^>]+>", " ", t)
    t = html.unescape(t)
    t = _ai_strip_markdown(t)
    t = re.sub(r"https?://\S+|www\.\S+", " ", t)
    t = _TTS_EMOJI_RE.sub(" ", t)
    t = re.sub(r"[*_#`~|<>\[\]{}^\\]+", " ", t)
    t = re.sub(r"[ \t]+", " ", t)
    t = re.sub(r"\s*\n\s*", "\n", t)
    return t.strip()


# ---------------------------------------------------------------------------
# آماده‌سازی متن برای تلفظ بهتر فارسی
# edge-tts اعراب و تلفظ فارسی را خودش حدس می‌زند و برای عددها/کسرهٔ اضافه/کلمه‌های مبهم زیاد اشتباه می‌کند.
# پس: ۱) عدد و نماد (٪ $ …) به حروف ۲) اعراب‌گذاری با هوش مصنوعی خودِ ربات (کسرهٔ اضافه، فتحه/ضمه، تشدید).
# ---------------------------------------------------------------------------
_FA_ONES = ["صفر", "یک", "دو", "سه", "چهار", "پنج", "شش", "هفت", "هشت", "نه", "ده", "یازده", "دوازده",
            "سیزده", "چهارده", "پانزده", "شانزده", "هفده", "هجده", "نوزده"]
_FA_TENS = ["", "", "بیست", "سی", "چهل", "پنجاه", "شصت", "هفتاد", "هشتاد", "نود"]
_FA_HUND = ["", "صد", "دویست", "سیصد", "چهارصد", "پانصد", "ششصد", "هفتصد", "هشتصد", "نهصد"]
_FA_SCALES = ["", "هزار", "میلیون", "میلیارد", "تریلیون", "کوادریلیون"]
_FA_DIGITS_TR = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
_TTS_LATIN = {"usd": "دلار", "usdt": "تتر", "btc": "بیت کوین", "eth": "اتریوم", "eur": "یورو", "gbp": "پوند",
              "ai": "ای آی", "ok": "اوکی"}
_DIAC_MARKS_RE = re.compile("[\u064B-\u0652\u0670]")


def _fa_below_1000(n: int) -> str:
    h, r = divmod(n, 100)
    parts = []
    if h:
        parts.append(_FA_HUND[h])
    if r:
        if r < 20:
            parts.append(_FA_ONES[r])
        else:
            t, o = divmod(r, 10)
            parts.append(_FA_TENS[t])
            if o:
                parts.append(_FA_ONES[o])
    return " و ".join(parts)


def _fa_int_words(n: int) -> str:
    if n == 0:
        return "صفر"
    parts, i = [], 0
    while n > 0:
        n, grp = divmod(n, 1000)
        if grp:
            w = _fa_below_1000(grp)
            if i == 1 and grp == 1:
                w = ""                      # «هزار» نه «یک هزار»
            parts.append(f"{w} {_FA_SCALES[i]}".strip())
        i += 1
    return " و ".join(reversed(parts))


def _fa_digit_by_digit(d: str) -> str:
    return " ".join(_FA_ONES[int(c)] for c in d if c.isdigit())


def _tts_numbers_to_words(t: str) -> str:
    t = t.translate(_FA_DIGITS_TR)
    t = re.sub(r"\$\s*(\d[\d,٬]*(?:[.٫]\d+)?)", r"\1 دلار", t)
    t = t.replace("$", " دلار ").replace("€", " یورو ").replace("£", " پوند ")
    t = re.sub(r"\s*[%٪]", " درصد ", t)
    t = re.sub(r"(?<![\w.])-(?=\d)", "منفی ", t)

    def _num(m):
        ip = re.sub(r"[,٬]", "", m.group(1))
        fp = m.group(2)
        if len(ip) > 17 or (len(ip) > 1 and ip.startswith("0") and not fp):
            return _fa_digit_by_digit(ip)           # شماره تلفن/کد: رقم‌به‌رقم
        out = _fa_int_words(int(ip))
        if fp:
            if len(fp) <= 3:
                out += " ممیز " + _fa_int_words(int(fp)) + " " + {1: "دهم", 2: "صدم", 3: "هزارم"}[len(fp)]
            else:
                out += " ممیز " + _fa_digit_by_digit(fp)
        return out

    return re.sub(r"(?<![\w.])(\d{1,3}(?:[,٬]\d{3})+|\d+)(?:[.٫](\d+))?", _num, t)


def _tts_diac_ok(src: str, out: str) -> bool:
    base = re.sub(r"\s+", " ", _DIAC_MARKS_RE.sub("", out)).strip()
    ref = re.sub(r"\s+", " ", _DIAC_MARKS_RE.sub("", src)).strip()
    if not base or abs(len(base) - len(ref)) > max(12, len(ref) * 0.08):
        return False
    return difflib.SequenceMatcher(None, ref, base).ratio() >= 0.93


_TTS_DIAC_SYSTEM = (
    "تو ویراستار تلفظِ متن فارسی برای موتور تبدیل متن به گفتار هستی. وظیفه‌ات فقط اعراب‌گذاری است تا خوانندهٔ ماشینی "
    "درست و روان بخواند.\n"
    "قواعد:\n"
    "- متن را با همان کلمه‌ها، همان ترتیب، همان نشانه‌گذاری و همان نیم‌فاصله‌ها برگردان؛ هیچ کلمه‌ای اضافه، حذف یا عوض نشود.\n"
    "- روی حرف‌هایی که تلفظشان مبهم است فتحه (َ)، کسره (ِ)، ضمه (ُ) و تشدید (ّ) بگذار.\n"
    "- کسرهٔ اضافه را حتماً بگذار: «قیمتِ دلار»، «بازارِ طلا»، «ربعِ سکه». برای کلمه‌ای که به «ا/و/ی» ختم می‌شود: «خانه‌یِ من»، «دلارِ آمریکا».\n"
    "- تلفظ فارسیِ ایرانی را بنویس، نه عربی: تنوین، سکون و «ال» عربی نگذار.\n"
    "- کلمه‌های محاوره‌ای (مثل «میخوام»، «تومن») را همان‌طور که هستند نگه دار و فقط همان‌ها را اعراب بزن.\n"
    "- خروجی فقط خودِ متن اعراب‌دار باشد؛ بدون توضیح، بدون مارک‌داون، بدون گیومهٔ اضافه."
)


_TTS_PREP_EXECUTOR = ThreadPoolExecutor(max_workers=3, thread_name_prefix="tts-prep")


def _tts_diacritize(text: str) -> str:
    """اعراب‌گذاری با AI؛ هر مشکلی (خطا/تایم‌اوت/دست‌کاری متن) → همان متن بدون اعراب."""
    if not TTS_DIACRITICS or len(text) < 3:
        return text
    msgs = [{"role": "system", "content": _TTS_DIAC_SYSTEM}, {"role": "user", "content": text}]
    try:
        fut = _TTS_PREP_EXECUTOR.submit(ask_ai_raw, msgs, 4000, 0.1, "chat")
        out = fut.result(timeout=TTS_DIAC_TIMEOUT)
    except Exception as e:
        logger.warning(f"[TTS] اعراب‌گذاری ناموفق ({type(e).__name__}) — متن ساده خوانده می‌شود")
        return text
    out = (out or "").replace("```", "").strip()
    if out and _DIAC_MARKS_RE.search(out) and _tts_diac_ok(text, out):
        return out
    logger.warning("[TTS] خروجی اعراب‌گذاری نامعتبر بود — متن ساده خوانده می‌شود")
    return text


def _tts_prepare(text: str, diacritize: bool = True) -> str:
    t = _tts_numbers_to_words(text)
    t = re.sub(r"[A-Za-z]{2,5}", lambda m: _TTS_LATIN.get(m.group(0).lower(), m.group(0)), t)
    t = re.sub(r"[ \t]+", " ", t).strip()
    return _tts_diacritize(t) if diacritize else t


async def _tts_save_async(text: str, voice: str, path: str):
    await asyncio.wait_for(edge_tts.Communicate(text, voice, rate=TTS_RATE).save(path), timeout=TTS_GEN_TIMEOUT)


# ---------------------------------------------------------------------------
# ElevenLabs (منبع اصلی ویس) — کلیدها چرخشی‌اند و خطای هر کلید جداگانه مدیریت می‌شود
# ---------------------------------------------------------------------------
ELEVEN_ENABLED = os.environ.get("ELEVENLABS_TTS", "1").strip().lower() not in ("0", "false", "off", "no")
ELEVEN_DEFAULT_VOICES = {"female": "EXAVITQu4vr4xnSDxMaL", "male": "pNInz6obpgDQGcFmaJgB"}  # Sarah / Adam (premade)
ELEVEN_TIMEOUT = _tts_env("ELEVENLABS_TIMEOUT", 40, float)            # مهلت هر درخواست به ElevenLabs
ELEVEN_QUOTA_COOLDOWN_SEC = 1800     # quota_exceeded/402: این کلید ۳۰ دقیقه کنار می‌رود
ELEVEN_RATE_COOLDOWN_SEC = 20        # 429 / concurrent: این کلید ۲۰ ثانیه کنار می‌رود
_ELEVEN_COOLDOWN: dict = {}          # key → تا چه زمانی کنار باشد (برای quota/rate؛ کلید مرده در _AI_DEAD_KEYS)


def _eleven_available() -> bool:
    """ElevenLabs روشن است و حداقل یک کلید دارد؟ (کلیدها تازه از .env خوانده می‌شوند)"""
    if not ELEVEN_ENABLED:
        return False
    try:
        reload_ai_keys()
    except Exception:
        pass
    return bool(ELEVENLABS_API_KEYS)


def _tts_available() -> bool:
    """ویس ممکن است؟ (ElevenLabs یا edge-tts)"""
    return _HAS_EDGE_TTS or _eleven_available()


def _eleven_lang_ok(lang) -> bool:
    """مدل v3 فارسی و اغلب زبان‌های ترجمه را می‌خواند؛ کردی سورانی را نه."""
    return lang in (None, "fa") or (lang in _TR_LANGS and lang != "ku")


def _eleven_cfg():
    model = (_env_get("ELEVENLABS_MODEL") or "eleven_v3").strip().strip('"').strip("'") or "eleven_v3"
    voices = {
        "female": (_env_get("ELEVENLABS_VOICE_FEMALE") or ELEVEN_DEFAULT_VOICES["female"]).strip(),
        "male": (_env_get("ELEVENLABS_VOICE_MALE") or ELEVEN_DEFAULT_VOICES["male"]).strip(),
    }
    fmt = (_env_get("ELEVENLABS_FORMAT") or "mp3_44100_128").strip()
    return model, voices, fmt


def _eleven_detail(r) -> tuple:
    """(status, message) از بدنهٔ خطای ElevenLabs: {"detail": {"status": "...", "message": "..."}}"""
    try:
        d = r.json().get("detail")
        if isinstance(d, dict):
            return str(d.get("status") or ""), str(d.get("message") or "")
        if isinstance(d, str):
            return "", d
    except Exception:
        pass
    return "", (r.text or "")[:120].replace("\n", " ")


def _eleven_tts_bytes(text: str, gender: str, voice_override: str = None):
    """متن → بایت‌های mp3 با ElevenLabs. بین کلیدها می‌چرخد؛ None = شکست (صدا زننده به edge-tts فالبک می‌کند)."""
    if not _eleven_available():
        return None
    model, voices, fmt = _eleven_cfg()
    voice_id = voice_override or voices.get(gender) or voices["female"]
    url = API_SERVICES["elevenlabs"]["url"].format(voice_id=voice_id)
    body = {
        "text": text,
        "model_id": model,
        "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
    }
    deadline = time.time() + TTS_GEN_TIMEOUT
    n_keys = len(ELEVENLABS_API_KEYS)
    tried = 0
    for _ in range(n_keys):
        left = deadline - time.time()
        if left < 3:
            break
        slot = _next_ai_slot("elevenlabs")
        if not slot:
            break
        key = slot[1]
        now = time.time()
        if _AI_DEAD_KEYS.get(key, 0) > now or _ELEVEN_COOLDOWN.get(key, 0) > now:
            continue
        tried += 1
        try:
            r = _ai_session.post(
                url, params={"output_format": fmt},
                headers={"xi-api-key": key, "Content-Type": "application/json", "Accept": "audio/mpeg"},
                json=body, timeout=(10, min(ELEVEN_TIMEOUT, max(3.0, left))),
            )
        except Exception as e:
            # خطای شبکه ربطی به کلید ندارد؛ چرخاندن بقیهٔ کلیدها فقط وقت می‌سوزاند → فالبک
            logger.warning(f"[TTS] elevenlabs اتصال ناموفق: {_err_cause(e)}")
            return None
        st = r.status_code
        if st == 200 and len(r.content or b"") >= 500:
            return r.content
        status, msg = _eleven_detail(r)
        if st in (401, 403) and status in ("invalid_api_key", "missing_permissions", "detected_unusual_activity"):
            _AI_DEAD_KEYS[key] = time.time() + _AI_DEADKEY_SEC
            logger.warning(f"[TTS] elevenlabs کلید رد شد ({_mask_key(key)}) [{status}] — ۱ ساعت کنار گذاشته شد")
            continue
        # صدای کتابخانه‌ای (library) روی پلن رایگان از API کار نمی‌کند (402 paid_plan_required) یا voice_id وجود ندارد (404).
        # این مشکل «صدا» است نه «کلید»؛ پس کلید را کنار نگذار و یک بار با صدای پیش‌فرض همان جنسیت امتحان کن.
        if (status in ("paid_plan_required", "voice_not_found", "invalid_voice_id")
                or (st == 404 and "voice" in (msg or "").lower())
                or (st == 402 and "voice" in (msg or "").lower())):
            default_vid = ELEVEN_DEFAULT_VOICES.get(gender) or ELEVEN_DEFAULT_VOICES["female"]
            logger.warning(f"[TTS] elevenlabs صدای «{voice_id}» قابل‌استفاده نیست [{st} {status}] {msg[:100]} "
                           f"— ELEVENLABS_VOICE_{gender.upper()} را در .env عوض کن")
            if voice_override is None and default_vid != voice_id:
                return _eleven_tts_bytes(text, gender, voice_override=default_vid)
            return None
        if st == 402 or status == "quota_exceeded" or (st == 401 and "quota" in (msg or "").lower()):
            _ELEVEN_COOLDOWN[key] = time.time() + ELEVEN_QUOTA_COOLDOWN_SEC
            logger.warning(f"[TTS] elevenlabs سهمیه/اعتبار تمام ({_mask_key(key)}) — {ELEVEN_QUOTA_COOLDOWN_SEC // 60} دقیقه کنار")
            continue
        if st == 429 or status in ("too_many_concurrent_requests", "rate_limit_exceeded", "system_busy"):
            _ELEVEN_COOLDOWN[key] = time.time() + ELEVEN_RATE_COOLDOWN_SEC
            logger.warning(f"[TTS] elevenlabs 429/شلوغ ({_mask_key(key)}) [{status}] — کلید بعدی")
            continue
        if st >= 500:
            logger.warning(f"[TTS] elevenlabs {st} (سمت سرویس) — کلید بعدی")
            if tried >= 2:
                return None
            continue
        # 400/404/422: مشکل درخواست است (voice_id، مدل، طول متن …) نه کلید → بقیهٔ کلیدها هم همین را می‌گیرند
        logger.warning(f"[TTS] elevenlabs {st} [{status}] {msg[:140]} (voice={voice_id} model={model}) — فالبک")
        return None
    return None


def _tts_generate(text: str, gender: str, lang: str = "fa", diacritized: bool = True):
    """تبدیل متن به فایل mp3 موقت؛ مسیر فایل یا None. اول ElevenLabs، اگر نشد edge-tts (فالبک).
    هر فراخوانی لوپ asyncio مستقل خودش را دارد (امن برای تردها).
    lang: کد زبان (پیش‌فرض fa)؛ برای زبان‌های دیگر (مثلاً ویس ترجمه) صداهای _TR_LANGS استفاده می‌شود.
    diacritized: متن قبلاً اعراب‌گذاری شده؟ اگر نه و به edge-tts فالبک شدیم، همین‌جا اعراب‌گذاری می‌شود."""
    if not text.strip():
        return None

    # ۱) ElevenLabs
    if _eleven_available() and _eleven_lang_ok(lang):
        audio = _eleven_tts_bytes(text, gender)
        if audio:
            fd, path = tempfile.mkstemp(prefix="voice_", suffix=".mp3")
            try:
                with os.fdopen(fd, "wb") as f:
                    f.write(audio)
                return path
            except Exception as e:
                logger.warning(f"[TTS] نوشتن فایل ElevenLabs ناموفق: {_err_cause(e)}")
                try:
                    os.remove(path)
                except OSError:
                    pass
        if _HAS_EDGE_TTS:
            logger.warning("[TTS] ElevenLabs جواب نداد — فالبک به edge-tts")

    # ۲) فالبک: edge-tts
    if not _HAS_EDGE_TTS:
        return None
    voice = _tts_voice_for(lang, gender)
    if not voice:
        return None
    if lang == "fa" and not diacritized:
        text = _tts_diacritize(text)
    fd, path = tempfile.mkstemp(prefix="voice_", suffix=".mp3")
    os.close(fd)
    try:
        asyncio.run(_tts_save_async(text, voice, path))
        if os.path.getsize(path) < 500:
            raise RuntimeError("فایل صوتی خالی بود")
        return path
    except Exception as e:
        logger.warning(f"[TTS] تولید صدا ناموفق: {_err_cause(e)}")
        try:
            os.remove(path)
        except OSError:
            pass
        return None


# ویس‌هایی که خودِ ربات فرستاده: (chat_id, message_id) → gender؛ برای «ریپلای با ویس روی ویس ربات → جواب خودکار با ویس»
_BOT_VOICE_SENT = TTLCache(maxsize=5000, ttl=24 * 3600)


def _is_reply_to_bot_voice(msg) -> bool:
    """ریپلای روی یک «ویسِ» خودِ ربات؟ (بدون وابستگی به حافظه؛ بعد از ریستارت هم کار می‌کند)"""
    r = getattr(msg, "reply_to_message", None)
    return bool(r is not None and getattr(r, "voice", None) is not None and _is_reply_to_bot(msg))


def _tts_reply_voice(msg: types.Message, wait_msg, reply: str, gender: str, read_mode: bool = False,
                     lang: str = "fa") -> list:
    """جواب (یا متنِ خوانده‌شده) را به ویس تبدیل و روی پیام کاربر ریپلای می‌کند. خروجی: message_id ویس‌های ارسال‌شده.
    لیست خالی = شکست کامل (صدا زننده خودش جواب متنی می‌فرستد). اگر فقط بخشی ویس شد، باقی‌مانده متنی ارسال می‌شود.
    read_mode: خواندن متن یک پیام (ریپلای) — بیشتر از سقف تکه‌ها فقط بریده می‌شود و متنی فرستاده نمی‌شود."""
    clean = _tts_clean(reply)
    if len(clean) < 2:
        return []
    all_parts = _vx_split(clean, TTS_PART_CHARS)
    if read_mode:
        all_parts = all_parts[:TTS_MAX_PARTS]
    chat_id = msg.chat.id
    notice = {"id": None, "own": False}

    def _on_busy():
        # سقف پر است: پیام «چند ثانیه وایسا» (روی همان پیام ⏳ یا یک ریپلای جدید)
        if wait_msg is not None:
            bot.edit_message_text(TTS_BUSY_TEXT, chat_id, wait_msg.message_id)
            notice["id"] = wait_msg.message_id
        else:
            m = bot.reply_to(msg, TTS_BUSY_TEXT)
            notice["id"], notice["own"] = m.message_id, True

    sent_ids = []
    try:
        for part in all_parts[:TTS_MAX_PARTS]:
            try:
                bot.send_chat_action(chat_id, "record_voice")
            except Exception:
                pass
            # عدد→حروف + اعراب فقط برای فارسی است؛ زبان‌های دیگر (ویس ترجمه) متن را همان‌طور می‌خوانند
            # با ElevenLabs اعراب‌گذاری پیش‌فرض خاموش است (فقط اگر به edge-tts فالبک شد انجام می‌شود)
            _diac = (not _eleven_available()) or _tts_env("ELEVENLABS_DIACRITICS", 0, int) == 1
            spoken = _tts_prepare(part, diacritize=_diac) if lang == "fa" else part
            if not _tts_acquire(_on_busy):
                logger.warning("[TTS] مهلت انتظار برای سقف نرخ تمام شد")
                break
            path = _tts_generate(spoken, gender, lang, diacritized=_diac)
            if not path:
                break
            try:
                with open(path, "rb") as f:
                    sent = bot.send_voice(chat_id, f, reply_to_message_id=msg.message_id,
                                          allow_sending_without_reply=True)
                sent_ids.append(sent.message_id)
                try:
                    _BOT_VOICE_SENT[(chat_id, sent.message_id)] = gender
                except Exception:
                    pass
            except Exception as e:
                logger.warning(f"[TTS] ارسال ویس ناموفق: {_err_cause(e)}")
                break
            finally:
                try:
                    os.remove(path)
                except OSError:
                    pass
        if sent_ids:
            # ویس رسید → پیام «سقف پره» / ⏳ پاک شود
            for mid in {notice["id"], getattr(wait_msg, "message_id", None)} - {None}:
                try:
                    bot.delete_message(chat_id, mid)
                except Exception:
                    pass
            # بخشی که ویس نشد (بیشتر از سقف تکه‌ها یا خطا) متنی فرستاده شود تا چیزی گم نشود
            for left in ([] if (read_mode and len(sent_ids) >= len(all_parts)) else all_parts[len(sent_ids):]):
                try:
                    bot.reply_to(msg, left)
                except Exception:
                    pass
        elif notice["own"] and notice["id"]:
            try:
                bot.delete_message(chat_id, notice["id"])
            except Exception:
                pass
    except Exception as e:
        logger.error(f"[TTS] خطا: {_err_cause(e)}", exc_info=True)
    return sent_ids


# ---------------------------------------------------------------------------
# تشخیص درخواست ویس از متن کاربر
# ---------------------------------------------------------------------------
_VR_B = r"(?<![\u0600-\u06FF])"   # مرز چپ کلمهٔ فارسی
_VR_E = r"(?![\u0600-\u06FF])"    # مرز راست کلمهٔ فارسی

_VR_OFF_RE = re.compile(
    _VR_B + r"(?:ویس|وویس|صوتی)\s*(?:رو\s*|را\s*)?(?:نده|نفرست|نخوام|نمیخوام|نمی\s*خوام|نمیخواد|نمی\s*خواد|نکن|نزن|نباشه|خاموش|غیرفعال|قطع)" + _VR_E
    + r"|" + _VR_B + r"بدون\s*(?:ویس|صدا)" + _VR_E
    + r"|" + _VR_B + r"(?:جواب|پاسخ)\s*(?:رو\s*)?متنی" + _VR_E
    + r"|" + _VR_B + r"متنی\s*(?:جواب|پاسخ)" + _VR_E
)
_VR_ON_RE = re.compile(
    _VR_B + r"(?:با|به)\s*(?:یه\s*|یک\s*)?(?:ویس|وویس|صدا|پیام\s*صوتی|صورت\s*(?:صوتی|ویس)|فرمت\s*صوتی)(?:ی)?" + _VR_E
    + r"|" + _VR_B + r"(?:ویس|وویس)\s*(?:ی\s*)?(?:بده|بدی|بفرست|بگو|بزن|کن|بذار|بزار|جواب|پاسخ)" + _VR_E
    + r"|" + _VR_B + r"صوتی\s*(?:جواب|پاسخ|بده|بگو|بفرست)" + _VR_E
    + r"|" + _VR_B + r"(?:جواب|پاسخ)(?:م|مو|مرو)?\s*(?:رو\s*|را\s*)?(?:ویس|صوتی)" + _VR_E
)
_VR_VW = r"(?:ویس|وویس|صدا|صوتی|گوینده|لحن)(?:ی|ش)?"
_VR_M_WORDS = r"(?:مرد|مردونه|مردانه|آقا|آقایون|آقایی|پسر|پسرونه|پسرانه)"
_VR_F_WORDS = r"(?:زن|زنونه|زنانه|خانم|خانوم|دختر|دخترونه|دخترانه|بانو)"
# «ویس آقا»، «با صدای مرد»، «مردونه ویس بده»، «فرید» — «آقا» تنها (خطاب: «آقا قیمت دلار؟») جنسیت حساب نمی‌شود
_VR_M_RE = re.compile(
    _VR_B + _VR_VW + r"\s*(?:یه\s+|یک\s+|ی\s+)?" + _VR_M_WORDS + _VR_E
    + r"|" + _VR_B + r"(?:مرد|مردونه|مردانه|پسر|پسرونه|پسرانه)\s+" + _VR_VW + _VR_E
    + r"|" + _VR_B + r"فرید" + _VR_E
)
_VR_F_RE = re.compile(
    _VR_B + _VR_VW + r"\s*(?:یه\s+|یک\s+|ی\s+)?" + _VR_F_WORDS + _VR_E
    + r"|" + _VR_B + r"(?:زن|زنونه|زنانه|خانم|خانوم|دختر|دخترونه|دخترانه)\s+" + _VR_VW + _VR_E
    + r"|" + _VR_B + r"دیلارا" + _VR_E
)
_VR_READ_VERB_RE = re.compile(_VR_B + r"(?:بخون(?:ش|ه|ید|ین)?|بخوان)" + _VR_E)
_VR_READ_VOCAB = frozenset((
    "این", "اینو", "اینم", "اینه", "همین", "همینو", "همینم", "اون", "اونو", "اونم", "متن", "متنش", "پیام", "پیامو",
    "پیامش", "بالا", "بالایی", "ویس", "ویسش", "صوتی", "صدا", "بگو", "بگین", "بگید", "بفرست", "بکن", "ش", "با", "به",
    "فقط", "جواب", "پاسخ",
))
_VR_ALWAYS_RE = re.compile(r"از\s*این\s*به\s*بعد|همیشه|همیشگی|دائم|دایم|همه\s*(?:ی\s*)?(?:جواب|پاسخ)")
_VR_BLIND_RE = re.compile(
    _VR_B + r"(?:کورم|کور\s*هستم|کور\s*ام|نابینام|نابینا\s*هستم|نابینا\s*ام|نابینایم|کم\s*بینام|کم\s*بینا\s*هستم)" + _VR_E
    + r"|" + _VR_B + r"نمی\s*بینم" + _VR_E
    + r"|" + _VR_B + r"چشم(?:ام|م)?\s*(?:ها)?\s*(?:نمی\s*بینه|نمی\s*بینن|ضعیفه|ضعیفن|کار\s*نمی\s*کنه)" + _VR_E
    + r"|" + _VR_B + r"(?:مشکل|ضعف)\s*(?:در\s*)?بینایی" + _VR_E
    + r"|" + _VR_B + r"(?:بینایی|دید)(?:م)?\s*(?:ندارم|ضعیفه|ضعیف)" + _VR_E
)
_VR_FILLER = frozenset((
    "لطفا", "کن", "بکن", "بده", "بدی", "باش", "دیگه", "ممنون", "مرسی", "باشه", "از", "این", "به", "بعد", "من", "رو", "را", "هم", "ها", "خب", "نخود",
))

_VR_MODE_FILE = Path(__file__).resolve().parent / "voice_mode.json"
_VR_MODE: dict = {}          # str(user_id) -> "female" | "male"  (حالت دائمی ویس)
_VR_MODE_LOCK = threading.Lock()


def _vr_mode_load():
    try:
        with open(_VR_MODE_FILE, "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict):
            _VR_MODE.update({str(k): v for k, v in d.items() if v in TTS_VOICES})
    except FileNotFoundError:
        pass
    except Exception as e:
        logger.warning(f"[TTS] خواندن voice_mode.json ناموفق: {e}")


def _vr_mode_get(uid: int):
    with _VR_MODE_LOCK:
        return _VR_MODE.get(str(uid))


def _vr_mode_set(uid: int, gender):
    """gender=None → حالت دائمی ویس برای این کاربر خاموش می‌شود."""
    if not uid:
        return
    with _VR_MODE_LOCK:
        if gender is None:
            _VR_MODE.pop(str(uid), None)
        else:
            _VR_MODE[str(uid)] = gender
        try:
            tmp = _VR_MODE_FILE.with_suffix(".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(_VR_MODE, f, ensure_ascii=False)
            os.replace(tmp, _VR_MODE_FILE)
        except Exception as e:
            logger.warning(f"[TTS] ذخیرهٔ voice_mode.json ناموفق: {e}")


_vr_mode_load()


# غلط‌های املایی رایج در درخواست ویس: «وبس/ویز» به‌جای «ویس»، «اقا/اقایون» به‌جای «آقا/آقایون» (بدون مدّ)
_VR_TYPO_VOICE_RE = re.compile(_VR_B + r"(?:وبس|ویز|ویث|وییس|ویسس)" + _VR_E)
_VR_TYPO_AGHA_RE = re.compile(_VR_B + r"اقا(?=(?:ی|یون|یی)?" + _VR_E + r")")


def _vr_fix_typos(t: str) -> str:
    t = _VR_TYPO_VOICE_RE.sub("ویس", t)
    return _VR_TYPO_AGHA_RE.sub("آقا", t)


# «تبدیل به ویس»: کاربر خودش متن را می‌دهد و فقط می‌خواهد همان متنِ عینی خوانده شود (بدون هوش مصنوعی و بدون حرف اضافه).
#   ۱) متن در همان پیام: «این متنی که میدم رو تبدیل به ویس کن» + خط بعد متن  /  «…تبدیل به ویس کن: متن»  /  متن + خط آخر دستور
#   ۲) بدون متن در پیام ولی ریپلای روی یک پیام: همان پیام ریپلای‌شده خوانده می‌شود
_VRL_VOICE = r"(?:ویس|وایس|وویس|وبس|ویز|ویث|صدا|صوت|صوتی|پیام\s*صوتی|فایل\s*صوتی)(?:ش|شو|شون|ی)?"
_VRL_TO_VOICE_RE = re.compile(_VR_B + r"(?:به|با|توی|تو|در)\s*(?:یه\s*|یک\s*)?" + _VRL_VOICE + _VR_E)
_VRL_VOICE_VERB_RE = re.compile(
    _VR_B + _VRL_VOICE + _VR_E + r"\s*(?:رو\s*|را\s*)?"
    + _VR_B + r"(?:کن|بکن|کنی|کنید|بساز|بسازی|بسازید|بگو|بگین|بگید|بده|بدی|بفرست|بفرستی)" + _VR_E)
_VRL_VERB_RE = re.compile(
    _VR_B + r"(?:تبدیل\w*|بدل\w*|تغییر\w*|کن|بکن|کنی|کنید|بساز|بسازی|بسازید|درست\s*کن\w*|بگو|بگین|بگید|"
    r"بخون\w*|بخوان|بفرست|بفرستی|بده|بدی|ضبط\w*)" + _VR_E)
_VRL_CONVERT_RE = re.compile(_VR_B + r"(?:تبدیل\w*|بدل\w*|تغییر\w*|ضبط\w*)")
_VRL_MAX_INSTR_LEN = 110


def _vrl_is_instr(line: str) -> bool:
    """این خط (کوتاه) یک دستور «تبدیل به ویس» است؟"""
    ln = _vr_fix_typos(_ai_norm_fa(line)).strip()
    if not ln or len(ln) > _VRL_MAX_INSTR_LEN or _VR_OFF_RE.search(ln):
        return False
    if not (_VRL_TO_VOICE_RE.search(ln) or _VRL_VOICE_VERB_RE.search(ln)):
        return False
    if not _VRL_VERB_RE.search(ln):
        return False
    if _VRL_CONVERT_RE.search(ln):
        return True
    # بدون فعل «تبدیل»: فقط اگر خط تقریباً خالص دستور باشد («اینو ویس کن») و سؤالی داخلش نباشد («با ویس بگو قیمت دلار چنده»)
    rest = ln
    for rx in (_VRL_TO_VOICE_RE, _VRL_VOICE_VERB_RE, _VRL_VERB_RE):
        rest = rx.sub(" ", rest)
    return len([w for w in re.sub(r"[\W_]+", " ", rest).split()]) <= 2


def _vr_literal_split(question: str):
    """(is_convert, body, instr_text). is_convert=True اگر پیام دستور «تبدیل به ویس» است؛
    body = متنِ خودِ پیام که باید خوانده شود (خالی اگر متنی همراه پیام نیست)."""
    lines = (question or "").strip().split("\n")
    nonempty = [i for i, l in enumerate(lines) if l.strip()]
    if not nonempty:
        return False, "", ""
    first, last = nonempty[0], nonempty[-1]
    # حالت ۱: دستور در خط اول (بدنه خط‌های بعد؛ یا بعد از «:» همان خط)
    head = lines[first]
    mc = re.search(r"[:：]", head)
    if mc and _vrl_is_instr(head[:mc.start()]):
        body = (head[mc.end():] + "\n" + "\n".join(lines[first + 1:])).strip()
        return True, body, head[:mc.start()]
    if _vrl_is_instr(head):
        return True, "\n".join(lines[first + 1:]).strip(), head
    # حالت ۲: متن اول، دستور در خط آخر
    if last != first and _vrl_is_instr(lines[last]):
        return True, "\n".join(lines[:last]).strip(), lines[last]
    return False, "", ""


def _vr_plan(uid: int, question: str, has_reply: bool = False) -> dict:
    """از متن کاربر تصمیم می‌گیرد: voice (جواب ویس شود؟)، gender، mode ('on' / 'off' / None = حالت دائمی عوض شود؟)،
    off_only (فقط خواسته ویس خاموش شود)، read (روی یک پیام ریپلای کرده و فقط می‌خواهد همان متن خوانده شود)."""
    t = _vr_fix_typos(_ai_norm_fa(question))
    sticky = _vr_mode_get(uid) if uid else None
    ms = [m.start() for m in _VR_M_RE.finditer(t)]
    fs = [m.start() for m in _VR_F_RE.finditer(t)]
    asked_gender = None
    if ms or fs:
        asked_gender = "male" if (ms and (not fs or max(ms) > max(fs))) else "female"
    _conv, _lit, _instr = _vr_literal_split(question)
    if _conv and (len(_lit) >= 2 or (has_reply and _VRL_CONVERT_RE.search(_vr_fix_typos(_ai_norm_fa(_instr))))):
        # «تبدیل به ویس»: فقط خودِ متن (همراه پیام، یا پیام ریپلای‌شده) عیناً خوانده می‌شود
        _it = _vr_fix_typos(_ai_norm_fa(_instr))
        _ms = [m.start() for m in _VR_M_RE.finditer(_it)]
        _fs = [m.start() for m in _VR_F_RE.finditer(_it)]
        _g = None
        if _ms or _fs:
            _g = "male" if (_ms and (not _fs or max(_ms) > max(_fs))) else "female"
        return {"voice": True, "gender": _g or sticky or TTS_DEFAULT_GENDER, "mode": None, "off_only": False,
                "read": True, "literal": _lit if len(_lit) >= 2 else "", "clean_q": ""}
    if _VR_OFF_RE.search(t):
        rest = re.sub(r"[\W_]+", " ", _VR_OFF_RE.sub(" ", t))
        left = [w for w in rest.split() if w not in _VR_FILLER]
        return {"voice": False, "gender": sticky or TTS_DEFAULT_GENDER, "mode": "off", "off_only": not left, "read": False}
    read_verb = has_reply and bool(_VR_READ_VERB_RE.search(t))
    explicit = bool(_VR_ON_RE.search(t) or ms or fs or read_verb)
    blind = bool(_VR_BLIND_RE.search(t))
    always = explicit and bool(_VR_ALWAYS_RE.search(t))
    gender = asked_gender or sticky or TTS_DEFAULT_GENDER
    mode = None
    if blind or always or (asked_gender and sticky is not None):
        mode = "on"
    read = False
    if has_reply and explicit:
        rest = t
        for rx in (_VR_M_RE, _VR_F_RE, _VR_ON_RE, _VR_READ_VERB_RE):   # جنسیت قبل از ON تا «با صدای مرد» کامل پاک شود
            rest = rx.sub(" ", rest)
        rest = re.sub(r"[\W_]+", " ", rest)
        read = not [w for w in rest.split() if w not in _VR_FILLER and w not in _VR_READ_VOCAB]
    # سؤال تمیز: عبارت‌های انتخاب صدا («با ویس خانم»، «صدای آقا» …) از متن حذف می‌شود تا قاطی سؤالِ هوش مصنوعی نشود
    clean_q = ""
    if explicit:
        clean_q = t
        for rx in (_VR_M_RE, _VR_F_RE, _VR_ON_RE) + ((_VR_READ_VERB_RE,) if has_reply else ()):
            # «با/به» چسبیده به عبارت هم حذف شود تا «با» تنها در سؤال نماند
            clean_q = re.sub(r"(?:" + _VR_B + r"(?:با|به)\s+)?(?:" + rx.pattern + r")", " ", clean_q)
        clean_q = re.sub(r"\s+", " ", clean_q).strip(" ،,:؛-")
    return {"voice": explicit or blind or sticky is not None, "gender": gender, "mode": mode,
            "off_only": False, "read": read, "clean_q": clean_q}


if TTS_ENABLED:
    logger.info(
        f"[TTS] پاسخ صوتی فعال — elevenlabs={len(ELEVENLABS_API_KEYS) if ELEVEN_ENABLED else 'خاموش'} کلید | "
        f"edge-tts={'نصب (فالبک)' if _HAS_EDGE_TTS else 'نصب نیست (pip install edge-tts)'} | "
        f"سقف {TTS_RATE_PER_SEC} درخواست در ثانیه | کاربران با حالت دائمی: {len(_VR_MODE)}"
    )


