def _handle_admin_edit_input(msg: types.Message):
    state = get_admin_state()
    data = state.get("data") or {}
    key = data.get("key")
    mid = data.get("mid")
    if not key:
        clear_admin_state()
        return

    new_val = msg.text or msg.caption or ""
    # دستورات لغو متنی
    if new_val.strip() in ("/cancel", "لغو", "بازگشت", "انصراف"):
        clear_admin_state()
        try:
            bot.delete_message(msg.chat.id, msg.message_id)
        except Exception:
            pass
        try:
            bot.send_message(
                ADMIN_ID,
                "❌ ویرایش لغو شد.",
                reply_markup=admin_edit_menu(),
                parse_mode="HTML",
            )
        except Exception:
            pass
        return

    set_setting(key, new_val)
    clear_admin_state()

    try:
        bot.delete_message(msg.chat.id, msg.message_id)
    except Exception:
        pass

    # پیام ویرایش را هم به منوی ویرایش برگردان
    done = (
        f"✅ <b>{key}</b> ذخیره شد.\n\n"
        f"مقدار جدید:\n<code>{html.escape(new_val[:500])}</code>"
    )
    try:
        if mid:
            bot.edit_message_text(
                done, ADMIN_ID, mid,
                reply_markup=admin_edit_menu(), parse_mode="HTML",
            )
        else:
            bot.send_message(
                ADMIN_ID, done,
                reply_markup=admin_edit_menu(), parse_mode="HTML",
            )
    except Exception:
        try:
            bot.send_message(
                ADMIN_ID, done,
                reply_markup=admin_edit_menu(), parse_mode="HTML",
            )
        except Exception:
            pass


# اجرای واقعی پیام همگانی ادمین روی یک ترد اختصاصی — همان الگوی
# _scheduled_send_executor برای send_scheduled_to_groups؛ وگرنه حلقهٔ
# for + time.sleep(0.05) با ۱۰۰۰ کاربر حدود ۱ دقیقه ترد پردازش پیام‌های
# پنل ادمین (و در نتیجه کل polling) را قفل می‌کند.
_admin_bc_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="admin-broadcast")


def _bc_yes_no_keyboard(prefix: str) -> InlineKeyboardMarkup:
    """prefix مثل adm:bc:want یا adm:bc:more → yes/no callbacks."""
    kb = InlineKeyboardMarkup(row_width=2)
    kb.row(
        btn("بله ✓", callback_data=f"{prefix}:yes", style="success"),
        btn("خیر ×", callback_data=f"{prefix}:no", style="danger"),
    )
    kb.row(btn("لغو", callback_data="adm:bc:cancel", style="danger"))
    return kb


def _bc_color_keyboard() -> InlineKeyboardMarkup:
    kb = InlineKeyboardMarkup(row_width=3)
    kb.row(
        btn("سبز", callback_data="adm:bc:color:success", style="success"),
        btn("آبی", callback_data="adm:bc:color:primary", style="primary"),
        btn("قرمز", callback_data="adm:bc:color:danger", style="danger"),
    )
    kb.row(btn("لغو", callback_data="adm:bc:cancel", style="danger"))
    return kb


def _bc_placement_keyboard() -> InlineKeyboardMarkup:
    kb = InlineKeyboardMarkup(row_width=2)
    kb.row(
        btn("↓ زیر دکمه قبلی", callback_data="adm:bc:place:below", style="primary"),
        btn("→ کنار دکمه قبلی", callback_data="adm:bc:place:beside", style="primary"),
    )
    kb.row(btn("لغو", callback_data="adm:bc:cancel", style="danger"))
    return kb


def _bc_normalize_url(url: str) -> str | None:
    url = (url or "").strip()
    if not url:
        return None
    if url.startswith("@"):
        return "https://t.me/" + url[1:]
    if url.startswith("t.me/"):
        return "https://" + url
    if url.startswith("http://") or url.startswith("https://") or url.startswith("tg://"):
        return url
    return None


def _bc_rows_to_markup(rows: list) -> InlineKeyboardMarkup | None:
    """rows = [[{label,url,style}, ...], ...]"""
    if not rows:
        return None
    kb = InlineKeyboardMarkup()
    for row in rows:
        if not row:
            continue
        buttons = []
        for b in row:
            label = (b.get("label") or "")[:64]
            url = b.get("url") or ""
            style = b.get("style") or "primary"
            if label and url:
                buttons.append(btn(label, url=url, style=style))
        if buttons:
            kb.row(*buttons)
    if not kb.keyboard:
        return None
    return kb


# آخرین پیام همگانی که بعضی مقصدها «موقتاً» ناموفق مانده‌اند — برای دکمهٔ «🔁 ارسال مجدد»
_BC_LAST_RETRY: dict = {}
# فاصلهٔ تلاش‌های مجدد خودکار (ثانیه) — سه دور
_BC_RETRY_DELAYS = (5, 15, 30)


def _bc_reason(res) -> str:
    """دلیل خوانا برای شکست ارسال (برای گزارش ادمین)."""
    err = getattr(res, "error", None)
    desc = (getattr(err, "description", "") or str(err or "")).lower()
    if "blocked" in desc:
        return "ربات را بلاک کرده"
    if "deactivated" in desc:
        return "حساب حذف/غیرفعال"
    if "chat not found" in desc or "peer_id_invalid" in desc or "user not found" in desc:
        return "چت پیدا نشد"
    if "kicked" in desc or "not a member" in desc or "not enough rights" in desc or "forbidden" in desc:
        return "ربات اخراج شده / دسترسی ندارد"
    if err is None:
        return "محدودیت تلگرام (فلود)"
    if isinstance(err, (requests.exceptions.RequestException, ConnectionError, TimeoutError, OSError)):
        return "خطای شبکه"
    return "خطای موقت تلگرام"


def _run_admin_broadcast(target: str, bc_text: str, reply_markup=None, only_ids=None, media: dict | None = None):
    """ارسال همگانی — متن + کیبورد شیشه‌ای اختیاری.
    شکست‌های «دائمی» (بلاک‌کرده/حذف‌شده/اخراج) دیگر تلاش نمی‌شوند و علامت می‌خورند؛
    شکست‌های «موقتی» (شبکه، فلود، خطای تلگرام) در چند دور خودکار دوباره فرستاده می‌شوند و
    اگر بعد از آن هم مانده بودند، دکمهٔ «ارسال مجدد» می‌آید. only_ids = فقط همین مقصدها."""
    success = 0
    permanent_fail = {}   # دلیل -> تعداد
    transient = []        # [(cid, reason)]

    body = (bc_text or "").strip()
    if not body and not (media and media.get("file_id")):
        try:
            bot.send_message(ADMIN_ID, "❌ متن پیام خالی بود.")
        except Exception:
            pass
        return

    if only_ids is not None:
        targets = list(only_ids)
    elif target == "users":
        targets = [u["user_id"] for u in get_all_users()]
    else:
        targets = [g["group_id"] for g in get_all_groups()]

    status_msg = bot.send_message(
        ADMIN_ID, f"⏳ در حال ارسال به {len(targets)} مقصد...", parse_mode="HTML"
    )

    send_kwargs = {"parse_mode": "HTML"}
    if reply_markup is not None:
        send_kwargs["reply_markup"] = reply_markup

    def _mark_permanent(cid, res):
        reason = _bc_reason(res)
        permanent_fail[reason] = permanent_fail.get(reason, 0) + 1
        try:
            if target == "users":
                set_user_blocked(cid, True)
            else:
                deactivate_group(cid)
        except Exception:
            pass

    def _send_round(ids, retries):
        """یک دور ارسال؛ برمی‌گرداند: لیست شکست‌های موقتی [(cid, reason)]"""
        nonlocal success
        still = []
        for cid in ids:
            result = safe_send_message(cid, body, retries=retries, _media=media, **send_kwargs)
            if result.ok:
                success += 1
            elif result.permanent:
                _mark_permanent(cid, result)
            else:
                still.append((cid, _bc_reason(result)))
            time.sleep(0.05)
        return still

    transient = _send_round(targets, retries=3)

    # دورهای تلاش مجدد خودکار برای شکست‌های موقتی
    for rnd, delay in enumerate(_BC_RETRY_DELAYS, 1):
        if not transient:
            break
        try:
            bot.edit_message_text(
                f"⏳ ارسال اول تمام شد — موفق: {success}\n"
                f"🔁 تلاش مجدد {rnd}/{len(_BC_RETRY_DELAYS)} برای {len(transient)} مقصد ناموفق (بعد از {delay} ثانیه)...",
                ADMIN_ID, status_msg.message_id, parse_mode="HTML",
            )
        except Exception:
            pass
        time.sleep(delay)
        transient = _send_round([c for c, _ in transient], retries=5)

    n_btns = 0
    if reply_markup and getattr(reply_markup, "keyboard", None):
        n_btns = sum(len(r) for r in reply_markup.keyboard)
    perm_total = sum(permanent_fail.values())
    lines = [
        "✅ پیام همگانی تمام شد",
        "",
        f"موفق: <b>{success}</b> از <b>{len(targets)}</b>",
    ]
    if perm_total:
        det = "، ".join(f"{k}: {v}" for k, v in permanent_fail.items())
        lines.append(f"غیرقابل‌ارسال (دائمی): <b>{perm_total}</b> — {det}")
        lines.append("<i>این‌ها از لیست ارسال کنار رفتند و دفعهٔ بعد حساب نمی‌شوند.</i>")
    kb = admin_keyboard()
    if transient:
        reasons = {}
        for _, r in transient:
            reasons[r] = reasons.get(r, 0) + 1
        det = "، ".join(f"{k}: {v}" for k, v in reasons.items())
        lines.append(f"⚠️ هنوز نرسیده (بعد از {len(_BC_RETRY_DELAYS)} تلاش مجدد): <b>{len(transient)}</b> — {det}")
        _BC_LAST_RETRY.clear()
        _BC_LAST_RETRY.update({
            "target": target, "text": body, "markup": reply_markup, "media": media,
            "ids": [c for c, _ in transient],
        })
        try:
            kb.row(btn(f"🔁 ارسال مجدد به {len(transient)} ناموفق", callback_data="adm:bc:retry", style="primary"))
        except Exception:
            pass
    else:
        _BC_LAST_RETRY.clear()
        lines.append("هیچ ارسال موقتی ناموفقی نمانده ✔️")
    lines.append(f"دکمه: <b>{n_btns or '—'}</b>")
    if media:
        lines.append(f"مدیا: <b>{_BC_MEDIA_LABELS.get(media.get('type'), media.get('type'))}</b>")
    result_text = "\n".join(lines)
    logger.info(f"[BC] target={target} total={len(targets)} ok={success} permanent={perm_total} left={len(transient)}")
    try:
        bot.edit_message_text(
            result_text, ADMIN_ID, status_msg.message_id,
            reply_markup=kb, parse_mode="HTML",
        )
    except Exception:
        bot.send_message(ADMIN_ID, result_text, reply_markup=kb, parse_mode="HTML")


def _handle_admin_bc_input(msg: types.Message):
    """مرحله ۱: دریافت متن پیام → سؤال درباره دکمه شیشه‌ای."""
    state = get_admin_state()
    data = dict(state.get("data") or {})
    target = data.get("target")
    if not target:
        clear_admin_state()
        return

    bc_text = (msg.text or msg.caption or "").strip()
    media = _bc_extract_media(msg)
    try:
        bot.delete_message(msg.chat.id, msg.message_id)
    except Exception:
        pass

    if not bc_text and not media:
        try:
            bot.send_message(ADMIN_ID, "❌ متن خالی بود. دوباره از پنل شروع کن.")
        except Exception:
            pass
        clear_admin_state()
        return

    data["text"] = bc_text
    data["media"] = media
    data["rows"] = []
    data["draft"] = {}
    set_admin_state("bc_ask_buttons", data)

    mid = data.get("mid")
    if media:
        label = _BC_MEDIA_LABELS.get(media["type"], media["type"])
        extra = ""
        if getattr(msg, "media_group_id", None):
            extra += "\n⚠️ آلبوم بود؛ فقط یک مدیا در هر پیام همگانی پشتیبانی می‌شود."
        if media["type"] in _BC_NO_CAPTION_TYPES and bc_text:
            extra += "\nℹ️ این نوع مدیا کپشن ندارد؛ متن جدا بعد از آن فرستاده می‌شود."
        elif len(bc_text) > _BC_CAPTION_MAX:
            extra += f"\nℹ️ کپشن بیشتر از {_BC_CAPTION_MAX} کاراکتر است؛ مدیا و متن در دو پیام پشت‌سرهم می‌روند."
        if not bc_text:
            extra += "\nℹ️ بدون کپشن."
        ask = (
            f"✅ مدیا ({label}) ذخیره شد.{extra}\n\n"
            "می‌خوای زیر این پیام <b>دکمه شیشه‌ای</b> داشته باشی؟"
        )
    else:
        ask = (
            "✅ متن ذخیره شد.\n\n"
            "می‌خوای زیر این پیام <b>دکمه شیشه‌ای</b> داشته باشی؟"
        )
    kb = _bc_yes_no_keyboard("adm:bc:want")
    try:
        if mid:
            bot.edit_message_text(ask, ADMIN_ID, mid, reply_markup=kb, parse_mode="HTML")
        else:
            bot.send_message(ADMIN_ID, ask, reply_markup=kb, parse_mode="HTML")
    except Exception:
        bot.send_message(ADMIN_ID, ask, reply_markup=kb, parse_mode="HTML")


def _bc_extract_media(msg: types.Message) -> dict | None:
    """از پیام ادمین نوع و file_id مدیا را درمی‌آورد (None = پیام متنی ساده)."""
    ct = getattr(msg, "content_type", "text")
    if ct == "photo" and msg.photo:
        return {"type": "photo", "file_id": msg.photo[-1].file_id}   # بزرگ‌ترین سایز
    if ct in _BC_MEDIA_SENDERS and ct != "photo":
        obj = getattr(msg, ct, None)
        if obj is not None and getattr(obj, "file_id", None):
            return {"type": ct, "file_id": obj.file_id}
    return None


# بدون content_types هندلرها فقط «text» می‌گیرند؛ برای همین عکس/ویدیو/فایلِ ادمین هیچ‌وقت به
# مرحلهٔ پیام همگانی نمی‌رسید. این هندلر فقط وقتی ادمین در مرحلهٔ «waiting_bc» است فعال می‌شود.
