# ============================================================
# ۱) اعلان «عضو جدید» به صاحب ربات (بعد از گذراندن جوین اجباری)
# ۲) فقط یک منو در پیوی: منوی بازِ قبلی پاک و منوی جدید فرستاده می‌شود
# ۳) ریاکشن ❤️ روی پیام اولین /start هر کاربر
# ============================================================
_PV_MENU_LOCKS = [threading.Lock() for _ in range(64)]


def _pv_menu_lock(uid: int):
    return _PV_MENU_LOCKS[uid % len(_PV_MENU_LOCKS)]


def _pv_menu_get(uid: int):
    try:
        with db_cursor() as c:
            c.execute("SELECT active_mid FROM users WHERE user_id=%s", (uid,))
            row = c.fetchone()
        return int(row["active_mid"]) if row and row.get("active_mid") else None
    except Exception as e:
        logger.warning(f"[PVMENU] خواندن منوی باز ناموفق: {e}")
        return None


def _pv_menu_set(uid: int, mid):
    try:
        with db_cursor() as c:
            c.execute("UPDATE users SET active_mid=%s WHERE user_id=%s", (mid, uid))
    except Exception as e:
        logger.warning(f"[PVMENU] ثبت منوی باز ناموفق: {e}")


def _pv_send_menu(chat_id, text: str, kb, delete_old: bool = True):
    """منوی تازه را در پیوی می‌فرستد و منوی بازِ قبلیِ همان کاربر را پاک می‌کند
    (همیشه فقط یک منو در پیوی می‌ماند). اول منوی جدید فرستاده می‌شود تا لحظه‌ای بدون منو نماند."""
    with _pv_menu_lock(int(chat_id)):
        old = _pv_menu_get(int(chat_id))
        sent = _html_retry(
            lambda t: bot.send_message(
                chat_id, t, parse_mode="HTML", reply_markup=kb, link_preview_options=_lp_off()
            ),
            text,
        )
        new_mid = getattr(sent, "message_id", None)
        if new_mid:
            _pv_menu_set(int(chat_id), new_mid)
        if delete_old and old and old != new_mid:
            _fj_safe_delete(chat_id, old)
    return sent


def _react_heart(chat_id, message_id):
    """ریاکشن ❤️ روی پیام. (تلگرام ایموجی ❤ را بدون variation-selector می‌پذیرد.)"""
    try:
        if hasattr(bot, "set_message_reaction") and hasattr(types, "ReactionTypeEmoji"):
            bot.set_message_reaction(chat_id, message_id, [types.ReactionTypeEmoji("\u2764")])
        else:
            telebot.apihelper._make_request(
                TOKEN, "setMessageReaction", method="post",
                params={"chat_id": chat_id, "message_id": message_id,
                        "reaction": json.dumps([{"type": "emoji", "emoji": "\u2764"}])},
            )
    except Exception as e:
        logger.debug(f"[REACT] ریاکشن ❤️ ثبت نشد: {e}")


def _notify_owner_new_member(u):
    """بعد از گذراندن جوین اجباری (یا اگر جوین اجباری خاموش است، همان اولین استارت)
    یک‌بار به صاحب ربات خبر می‌دهد. با UPDATE اتمیک، حتی با چند /start پشت‌سرهم فقط یک اعلان می‌رود."""
    uid = int(u.id)
    with db_cursor() as c:
        c.execute("UPDATE users SET owner_notified=1 WHERE user_id=%s AND owner_notified=0", (uid,))
        first = (c.rowcount or 0) > 0
    if not first or uid == ADMIN_ID:
        return
    full = ((getattr(u, "first_name", "") or "") + " " + (getattr(u, "last_name", "") or "")).strip()
    name = html.escape(full)[:64] or "بدون‌نام"
    uname = getattr(u, "username", None)
    text = (
        "🆕 <b>عضو جدید ربات</b>\n\n"
        f'👤 <a href="tg://user?id={uid}">{name}</a>\n'
        f"🔖 یوزرنیم: {('@' + uname) if uname else 'ندارد'}\n"
        f"🆔 <code>{uid}</code>\n"
        f"🕐 {_now_tehran().strftime('%Y-%m-%d %H:%M')}\n\n"
        f"👥 مجموع کاربران فعال: <b>{get_user_count()}</b>"
    )
    res = safe_send_message(ADMIN_ID, text, parse_mode="HTML")
    if not res.ok:
        # اعلان نرسید → علامت برداشته شود تا /start بعدیِ همین کاربر دوباره تلاش کند
        try:
            with db_cursor() as c:
                c.execute("UPDATE users SET owner_notified=0 WHERE user_id=%s", (uid,))
        except Exception:
            pass


# ============================================================
# تشخیص دقیق‌تر بلاک/حذف — پیوی و گروه
#   • رویداد my_chat_member در پیوی (بلاک/آنبلاک لحظه‌ای)
#   • هوک مرکزی روی همهٔ تماس‌های API: هر خطای «بلاک‌شده/حذف‌شده/اخراج‌شده» از هر
#     جای کد (نه فقط ارسال همگانی) همان لحظه ثبت می‌شود
#   • جاروی دوره‌ای بی‌صدا (sendChatAction / getChatMember) برای چیزی که رویدادش نرسید
# ============================================================
_SEND_METHODS = frozenset({
    "sendMessage", "sendPhoto", "sendDocument", "sendVideo", "sendAnimation", "sendAudio",
    "sendVoice", "sendVideoNote", "sendSticker", "sendChatAction", "sendMediaGroup",
    "sendPoll", "copyMessage", "forwardMessage",
})
_USER_GONE_ALWAYS = ("blocked by the user", "user is deactivated")
_USER_GONE_SEND = ("chat not found", "peer_id_invalid", "user not found")
_GROUP_GONE_ALWAYS = (
    "bot was kicked", "bot is not a member", "group chat was deactivated",
    "group chat was deleted", "supergroup chat was deleted",
)
_GROUP_GONE_SEND = ("chat not found",)
_GONE_SEEN = TTLCache(maxsize=20000, ttl=300)


def _groups_list_migrate(old_id: int, new_id: int):
    """گروه به سوپرگروه ارتقا یافته: ردیف گروه (با همهٔ تنظیماتش) به آیدی جدید منتقل می‌شود."""
    try:
        with db_cursor() as c:
            c.execute("SELECT 1 FROM groups_list WHERE group_id=%s", (new_id,))
            exists = c.fetchone()
            if exists:
                c.execute("UPDATE groups_list SET is_active=0 WHERE group_id=%s", (old_id,))
            else:
                c.execute("UPDATE groups_list SET group_id=%s, is_active=1 WHERE group_id=%s", (new_id, old_id))
            c.execute("UPDATE IGNORE group_seen_users SET group_id=%s WHERE group_id=%s", (new_id, old_id))
    except Exception as e:
        logger.warning(f"[MIGRATE] انتقال گروه {old_id} → {new_id}: {e}")


def _api_failure_watch(method_name, params, exc):
    try:
        if not isinstance(params, dict):
            return
        try:
            cid = int(params.get("chat_id"))
        except (TypeError, ValueError):
            return
        if getattr(exc, "error_code", None) not in (400, 403):
            return
        desc = (getattr(exc, "description", "") or str(exc)).lower()
        is_send = method_name in _SEND_METHODS
        if cid > 0:
            hit = any(m in desc for m in _USER_GONE_ALWAYS) or (
                is_send and any(m in desc for m in _USER_GONE_SEND))
            if hit and (cid, "u") not in _GONE_SEEN:
                _GONE_SEEN[(cid, "u")] = 1
                with db_cursor() as c:
                    c.execute(
                        "UPDATE users SET is_blocked=1, active_mid=NULL "
                        "WHERE user_id=%s AND is_blocked=0 AND captcha_ok=1", (cid,))
                    if c.rowcount:
                        logger.info(f"[BLOCK] کاربر {cid} ربات را بلاک کرده/حسابش حذف شده ({method_name})")
        else:
            if "upgraded to a supergroup" in desc:
                new_id = ((getattr(exc, "result_json", None) or {}).get("parameters") or {}).get("migrate_to_chat_id")
                if new_id:
                    _groups_list_migrate(cid, int(new_id))
                return
            hit = any(m in desc for m in _GROUP_GONE_ALWAYS) or (
                is_send and any(m in desc for m in _GROUP_GONE_SEND))
            if hit and (cid, "g") not in _GONE_SEEN:
                _GONE_SEEN[(cid, "g")] = 1
                deactivate_group(cid)
                logger.info(f"[GROUP] ربات از گروه {cid} حذف شده ({method_name}) → غیرفعال شد")
    except Exception:
        pass


try:
    _orig_make_request = telebot.apihelper._make_request

    def _make_request_watched(*args, **kwargs):
        try:
            return _orig_make_request(*args, **kwargs)
        except telebot.apihelper.ApiTelegramException as e:
            try:
                mname = args[1] if len(args) > 1 else kwargs.get("method_name", "")
                params = kwargs.get("params")
                if params is None and len(args) > 3:
                    params = args[3]
                _api_failure_watch(mname, params, e)
            except Exception:
                pass
            raise

    telebot.apihelper._make_request = _make_request_watched
except Exception as _watch_err:  # pragma: no cover
    logger.warning(f"[BLOCK] هوک تشخیص بلاک نصب نشد (فقط جاروی دوره‌ای کار می‌کند): {_watch_err}")


def _pv_member_update(upd):
    """my_chat_member در پیوی: kicked = کاربر ربات را بلاک کرد | member = آنبلاک/استارت."""
    uid = int(upd.chat.id)
    st = upd.new_chat_member.status
    if st == "kicked":
        with db_cursor() as c:
            c.execute("UPDATE users SET is_blocked=1, active_mid=NULL WHERE user_id=%s", (uid,))
        logger.info(f"[BLOCK] کاربر {uid} ربات را بلاک کرد")
    elif st == "member":
        with db_cursor() as c:
            c.execute("UPDATE users SET is_blocked=0 WHERE user_id=%s AND is_blocked=1", (uid,))


_ALIVE_USER_BATCH = 100
_ALIVE_GROUP_BATCH = 40


def _alive_sweep_users():
    """کاربرانِ واقعی (که ربات را استارت کرده‌اند) را به‌نوبت با sendChatAction بی‌صدا چک می‌کند.
    شکستِ بلاک/حذف را هوک API ثبت می‌کند؛ موفقیتِ کسی که بلاک‌شده علامت خورده بود = آنبلاک."""
    with db_cursor() as c:
        c.execute(
            "SELECT user_id, is_blocked FROM users WHERE captcha_ok=1 "
            "ORDER BY (alive_checked_at IS NULL) DESC, alive_checked_at ASC LIMIT %s",
            (_ALIVE_USER_BATCH,),
        )
        rows = list(c.fetchall())
    for r in rows:
        uid = int(r["user_id"])
        try:
            with db_cursor() as c:
                c.execute("UPDATE users SET alive_checked_at=NOW() WHERE user_id=%s", (uid,))
            bot.send_chat_action(uid, "typing")
            if r.get("is_blocked"):
                set_user_blocked(uid, False)
                logger.info(f"[BLOCK] کاربر {uid} دوباره در دسترس است → آنبلاک شد")
        except telebot.apihelper.ApiTelegramException as e:
            if getattr(e, "error_code", None) == 429:
                time.sleep(min(30, _extract_retry_after(e)))
                break
        except Exception:
            pass
        time.sleep(0.08)


def _alive_sweep_groups():
    """وضعیت ربات در گروه‌های فعال را چک می‌کند؛ اگر اخراج/خارج شده باشد، گروه غیرفعال می‌شود."""
    bid = _get_bot_id()
    if not bid:
        return
    with db_cursor() as c:
        c.execute(
            "SELECT group_id FROM groups_list WHERE is_active=1 "
            "ORDER BY (alive_checked_at IS NULL) DESC, alive_checked_at ASC LIMIT %s",
            (_ALIVE_GROUP_BATCH,),
        )
        gids = [int(r["group_id"]) for r in c.fetchall()]
    for gid in gids:
        try:
            with db_cursor() as c:
                c.execute("UPDATE groups_list SET alive_checked_at=NOW() WHERE group_id=%s", (gid,))
            cm = bot.get_chat_member(gid, bid)
            st = getattr(cm, "status", "")
            if st in ("left", "kicked") or (st == "restricted" and not getattr(cm, "is_member", True)):
                deactivate_group(gid)
                logger.info(f"[GROUP] ربات دیگر عضو گروه {gid} نیست → غیرفعال شد")
        except telebot.apihelper.ApiTelegramException as e:
            if getattr(e, "error_code", None) == 429:
                time.sleep(min(30, _extract_retry_after(e)))
                break
            desc = (getattr(e, "description", "") or str(e)).lower()
            if "upgraded to a supergroup" in desc:
                new_id = ((getattr(e, "result_json", None) or {}).get("parameters") or {}).get("migrate_to_chat_id")
                if new_id:
                    _groups_list_migrate(gid, int(new_id))
            elif "chat not found" in desc or any(m in desc for m in _GROUP_GONE_ALWAYS):
                deactivate_group(gid)
                logger.info(f"[GROUP] گروه {gid} در دسترس نیست ({desc[:60]}) → غیرفعال شد")
        except Exception:
            pass
        time.sleep(0.1)


def alive_sweep_job():
    try:
        _alive_sweep_users()
    except Exception as e:
        logger.warning(f"[ALIVE] users sweep: {e}")
    try:
        _alive_sweep_groups()
    except Exception as e:
        logger.warning(f"[ALIVE] groups sweep: {e}")


