_NUDGE_SEEN_DAYS = 14
_NUDGE_COOLDOWN_DAYS = 7
_NUDGE_HOUR_FROM = 10
_NUDGE_HOUR_TO = 22
_NUDGE_CATCHUP_MIN = 180

