def _seen_note(m) -> None:
    """هر کاربرِ غیررباتی که در گروه پیام می‌دهد/اضافه می‌شود ثبت می‌شود (با کش ۳۰ دقیقه‌ای؛ سبک)."""
    chat = getattr(m, "chat", None)
    if chat is None or getattr(chat, "type", "") not in ("group", "supergroup"):
        return
    lc = getattr(m, "left_chat_member", None)
    if lc is not None:
        try:
            with db_cursor() as c:
                c.execute("DELETE FROM group_seen_users WHERE group_id=%s AND user_id=%s", (chat.id, lc.id))
            _SEEN_CACHE.pop((chat.id, lc.id), None)
        except Exception:
            pass
    users = []
    fu = getattr(m, "from_user", None)
    if fu is not None and not getattr(fu, "is_bot", False) and getattr(m, "sender_chat", None) is None:
        users.append(fu)
    for nu in (getattr(m, "new_chat_members", None) or []):
        if not getattr(nu, "is_bot", False):
            users.append(nu)
    now = time.time()
    for u in users:
        key = (chat.id, u.id)
        if key in _SEEN_CACHE:
            continue
        _SEEN_CACHE[key] = 1
        try:
            fn = (getattr(u, "first_name", "") or "")[:64]
            un = getattr(u, "username", None)
            with db_cursor() as c:
                c.execute(
                    "INSERT INTO group_seen_users (group_id, user_id, first_name, username, last_seen) "
                    "VALUES (%s, %s, %s, %s, %s) "
                    "ON CONFLICT (group_id, user_id) DO UPDATE SET first_name=%s, username=%s, last_seen=%s",
                    (chat.id, u.id, fn, un, now, fn, un, now),
                )
        except Exception as e:
            logger.debug(f"[SEEN] ثبت عضو ناموفق: {e}")


def _nudge_slot_minute(gid: int, day: str) -> int:
    """دقیقهٔ ارسال امروزِ این گروه (از نیمه‌شب) — برای هر گروه و هر روز متفاوت، ولی ثابت (با ری‌استارت عوض نمی‌شود)."""
    h = int(hashlib.sha256(f"ppnudge:{gid}:{day}".encode()).hexdigest()[:8], 16)
    return _NUDGE_HOUR_FROM * 60 + h % ((_NUDGE_HOUR_TO - _NUDGE_HOUR_FROM) * 60)


def _nudge_pick_candidate(gid: int):
    now = time.time()
    with db_cursor() as c:
        c.execute(
            "SELECT s.user_id, s.first_name FROM group_seen_users s "
            "LEFT JOIN user_ai_profile p ON p.user_id = s.user_id "
            "WHERE s.group_id=%s AND s.last_seen>=%s AND p.user_id IS NULL AND s.user_id<>%s "
            "AND (s.last_nudged IS NULL OR s.last_nudged<%s) "
            "ORDER BY RANDOM() LIMIT 10",
            (gid, now - _NUDGE_SEEN_DAYS * 86400, ADMIN_ID, now - _NUDGE_COOLDOWN_DAYS * 86400),
        )
        rows = list(c.fetchall())
    for r in rows:
        uid = int(r["user_id"])
        try:
            cm = bot.get_chat_member(gid, uid)
            st = getattr(cm, "status", "")
            if st in ("left", "kicked") or (st == "restricted" and not getattr(cm, "is_member", True)):
                with db_cursor() as c:
                    c.execute("DELETE FROM group_seen_users WHERE group_id=%s AND user_id=%s", (gid, uid))
                continue
        except telebot.apihelper.ApiTelegramException as e:
            desc = (getattr(e, "description", "") or str(e)).lower()
            if "user not found" in desc or "participant_id_invalid" in desc:
                with db_cursor() as c:
                    c.execute("DELETE FROM group_seen_users WHERE group_id=%s AND user_id=%s", (gid, uid))
                continue
            return None            # مشکل از سمت گروه/دسترسی ربات است؛ بعداً دوباره
        except Exception:
            return None
        return uid, (r.get("first_name") or "").strip()
    return None


def _nudge_send(gid: int) -> str:
    """'sent' | 'none' (کاندیدایی نبود) | 'fail'"""
    cand = _nudge_pick_candidate(gid)
    if not cand:
        return "none"
    uid, name = cand
    mention = f'<a href="tg://user?id={uid}">{html.escape(name[:32] or "دوست")}</a>'
    text = _rnd.choice(_NUDGE_TEXTS).replace("{m}", mention)
    kb = InlineKeyboardMarkup()
    kb.row(btn("تنظیم", url=f"https://t.me/{_get_bot_username()}?start=ppnudge", style="primary"))
    res = safe_send_message(gid, text, parse_mode="HTML", reply_markup=kb, link_preview_options=_lp_off())
    if not res.ok:
        return "fail"
    try:
        with db_cursor() as c:
            c.execute(
                "UPDATE group_seen_users SET last_nudged=%s WHERE group_id=%s AND user_id=%s",
                (time.time(), gid, uid),
            )
    except Exception:
        pass
    return "sent"


def group_pp_nudge_job():
    """هر ۳ دقیقه اجرا می‌شود؛ گروهی که زمان امروزش رسیده و هنوز امروز پیامی نگرفته، یک منشن می‌گیرد."""
    now = _now_tehran()
    today = now.strftime("%Y-%m-%d")
    nowm = now.hour * 60 + now.minute
    if nowm < _NUDGE_HOUR_FROM * 60:
        return
    try:
        with db_cursor() as c:
            c.execute("SELECT group_id FROM group_pp_nudge WHERE last_date=%s", (today,))
            done = {int(r["group_id"]) for r in c.fetchall()}
    except Exception as e:
        logger.warning(f"[NUDGE] خواندن وضعیت امروز: {e}")
        return
    for g in get_all_groups():
        gid = int(g["group_id"])
        if gid in done:
            continue
        slot = _nudge_slot_minute(gid, today)
        if not (slot <= nowm < slot + _NUDGE_CATCHUP_MIN):
            continue
        try:
            if _fj_enforced() and _fj_group_status(gid) == 0:
                continue                      # گروه قفلِ جوین اجباری است
        except Exception:
            pass
        try:
            r = _nudge_send(gid)
        except Exception as e:
            logger.warning(f"[NUDGE] گروه {gid}: {e}")
            continue
        if r == "sent":
            try:
                with db_cursor() as c:
                    c.execute(
                        "INSERT INTO group_pp_nudge (group_id, last_date) VALUES (%s, %s) "
                        "ON CONFLICT (group_id) DO UPDATE SET last_date=%s", (gid, today, today))
            except Exception as e:
                logger.warning(f"[NUDGE] ثبت ارسال امروز: {e}")
            logger.info(f"[NUDGE] منشن روزانه در گروه {gid} ارسال شد")
        time.sleep(0.4)


# ============================================================
# Scheduled jobs
# ============================================================


# ---------- جلوگیری از خوابِ هاست (Render رایگان بعد از ~۱۵ دقیقه بدون ترافیک می‌خوابد) ----------
# هر KEEPALIVE_MINUTES دقیقه (پیش‌فرض ۱۰) یک درخواست GET از بیرون به آدرس عمومیِ خودِ سرویس می‌زند.
# آدرس را Render خودش در RENDER_EXTERNAL_URL می‌گذارد؛ روی هاست دیگر KEEPALIVE_URL را در .env بگذار.
_KEEPALIVE_URL = (os.environ.get("KEEPALIVE_URL") or os.environ.get("RENDER_EXTERNAL_URL") or "").strip().rstrip("/")
_KEEPALIVE_MINUTES = max(1, int(os.environ.get("KEEPALIVE_MINUTES") or 10))


def keepalive_ping():
    try:
        r = requests.get(_KEEPALIVE_URL + "/api/v1/health", timeout=20)
        logger.debug(f"[KEEPALIVE] ping {r.status_code}")
    except Exception as e:
        logger.warning(f"[KEEPALIVE] ping ناموفق: {type(e).__name__}")


def setup_scheduler():
    # timezone ثابت UTC+3:30 — بدون وابستگی به tzdata سیستم
    scheduler = BackgroundScheduler(timezone=TEHRAN_TZ)

    # دریافت خودکار قیمت‌های جدید هر ۳۰ ثانیه از API برنامهٔ چند (و بارگذاری مجدد ارز.txt)
    # max_instances=1 + coalesce: اگر یک دور طول کشید، دورهای عقب‌افتاده روی هم انباشته نمی‌شوند
    scheduler.add_job(
        update_prices_from_api, "interval", seconds=PRICE_API_REFRESH_SEC,
        id="price_api_refresh", replace_existing=True,
        max_instances=1, coalesce=True, misfire_grace_time=20,
    )
    # نفت فقط در پس‌زمینه — هر OIL_REFRESH_SEC ثانیه (پیش‌فرض ۶۰؛ داده‌ی API حدود هر ۱ دقیقه تازه می‌شود)
    scheduler.add_job(
        background_update_oil, "interval", seconds=OIL_REFRESH_SEC,
        id="oil_refresh", replace_existing=True,
        max_instances=1, coalesce=True, misfire_grace_time=30,
    )

    if _HAS_CARS:
        scheduler.add_job(
            car_refresh_job, "interval", seconds=car_prices.CAR_REFRESH_SEC,
            id="car_refresh", replace_existing=True, max_instances=1, coalesce=True,
            misfire_grace_time=60, next_run_time=datetime.now(timezone.utc) + timedelta(seconds=20),
        )

    scheduler.add_job(cleanup_spam_tracker, "interval", minutes=5)
    if _KEEPALIVE_URL:
        scheduler.add_job(
            keepalive_ping, "interval", minutes=_KEEPALIVE_MINUTES,
            id="keepalive", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=60,
        )
        logger.info(f"[KEEPALIVE] هر {_KEEPALIVE_MINUTES} دقیقه به {_KEEPALIVE_URL} پینگ می‌شود")
    else:
        logger.info("[KEEPALIVE] غیرفعال (RENDER_EXTERNAL_URL / KEEPALIVE_URL تنظیم نشده)")
    # تعطیلات رسمی: همگام‌سازی خودکار با تقویم رسمی (۳۰ ثانیه بعد از استارت، بعد هر ۳ ساعت)
    if _HOLIDAY_SYNC_ON:
        scheduler.add_job(
            holiday_sync_job, "interval", hours=3,
            id="holiday_sync", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=600,
            next_run_time=datetime.now(timezone.utc) + timedelta(seconds=30),
        )
    # جوین اجباری: شبکهٔ اطمینان برای تشخیص خروج از کانال (اگر رویداد chat_member نرسید)
    scheduler.add_job(
        fj_sweep_job, "interval", minutes=5,
        id="fj_sweep", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=60,
    )
    scheduler.add_job(memory_housekeeping, "interval", hours=1)
    # روزنامهٔ شبانه: هر دقیقه بررسی زمان انتشار گروه‌ها؛ هر ساعت پاکسازی لاگ قدیمی
    if _HAS_NEWS:
        try:
            newspaper_service.init(
                db_cursor, _news_llm, _news_send_photo, None, get_all_groups,
                lambda c, u: u == ADMIN_ID or bool(_enf_is_admin(c, u)), gregorian_to_jalali, GROUP_AI_BOT_NAME,
            )
            newspaper_service.set_owner_id(ADMIN_ID)             # «روزنامه الان» فقط برای مالک ربات
            newspaper_service.set_bot_id_getter(_get_bot_id)
            scheduler.add_job(
                newspaper_service.job, "interval", minutes=1,
                id="news_job", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=60,
            )
            scheduler.add_job(
                newspaper_service.cleanup, "interval", hours=1,
                id="news_cleanup", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=300,
            )
            logger.info("[NEWS] روزنامهٔ شبانه فعال شد")
        except Exception as _ne:
            logger.warning(f"[NEWS] راه‌اندازی ناموفق: {_ne}")
    # منشن روزانهٔ «تنظیم پرامپت شخصی» در گروه‌ها (ساعت هر گروه هر روز تصادفی است)
    scheduler.add_job(
        group_pp_nudge_job, "interval", minutes=3,
        id="group_pp_nudge", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=60,
    )
    # جاروی بی‌صدای بلاک/حذف: کاربران (sendChatAction) و گروه‌ها (getChatMember)
    scheduler.add_job(
        alive_sweep_job, "interval", minutes=10,
        id="alive_sweep", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=120,
    )
    # نمودارهای پرمصرف را از قبل آماده نگه می‌دارد تا کلیک روی «نمودار» لودینگ ۱۰ثانیه‌ای نداشته باشد
    if _CHART_HOT_MAX > 0:
        scheduler.add_job(
            chart_hot_refresh_job, "interval", seconds=40,
            id="chart_hot_refresh", replace_existing=True, max_instances=1, coalesce=True, misfire_grace_time=30,
        )


    scheduler.start()
    logger.info(
        f"[SCHED] scheduler started (TEHRAN_TZ fixed offset) — price API every {PRICE_API_REFRESH_SEC}s"
    )
    return scheduler


